INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35563, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "商品の売買や取引を目的として組織された団体や企業。", "primary_collocate": null, "pronunciation": "かいしゃ", "ipa": "kaiɕa", "syllable_count": 3, "sentences": [{"text": "この会社は海外の商品を輸入して売っています。", "target_word": "会社", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]は海外[かいがい]の商品[しょうひん]を輸入[ゆにゅう]して売[う]っています。", "sentence_source": "generated"}, {"text": "会社の名前を変えることが、先月決まりました。", "target_word": "会社", "complexity_tier": "T3", "furigana": "会社[かいしゃ]の名前[なまえ]を変[か]えることが、先月[せんげつ]決[き]まりました。", "sentence_source": "generated"}, {"text": "小さな会社でも、よい商品を作れば人気が出ます。", "target_word": "会社", "complexity_tier": "T3", "furigana": "小[ちい]さな会社[かいしゃ]でも、よい商品[しょうひん]を作[つく]れば人気[にんき]が出[で]ます。", "sentence_source": "generated"}, {"text": "会社が新しい店を出すので、働く人を探しています。", "target_word": "会社", "complexity_tier": "T3", "furigana": "会社[かいしゃ]が新[あたら]しい店[みせ]を出[だ]すので、働[はたら]く人[ひと]を探[さが]しています。", "sentence_source": "generated"}, {"text": "その会社は百年前に作られた、古い貿易の会社です。", "target_word": "会社", "complexity_tier": "T3", "furigana": "その会社[かいしゃ]は百年前[ひゃくねんまえ]に作[つく]られた、古[ふる]い貿易[ぼうえき]の会社[かいしゃ]です。", "sentence_source": "generated"}, {"text": "会社の売り上げが増えて、社員のお給料も上がりました。", "target_word": "会社", "complexity_tier": "T3", "furigana": "会社[かいしゃ]の売[う]り上[あ]げが増[ふ]えて、社員[しゃいん]のお給料[きゅうりょう]も上[あ]がりました。", "sentence_source": "generated"}, {"text": "取引先の会社に、見積書を送りました。", "target_word": "会社", "complexity_tier": "T3", "furigana": "取引先[とりひきさき]の会社[かいしゃ]に、見積書[みつもりしょ]を送[おく]りました。", "sentence_source": "generated"}, {"text": "商品の仕入れ先として、この会社と契約することにしました。", "target_word": "会社", "complexity_tier": "T3", "furigana": "商品[しょうひん]の仕入[しい]れ先[さき]として、この会社[かいしゃ]と契約[けいやく]することにしました。", "sentence_source": "generated"}, {"text": "兄の会社は去年、東京から大阪へ引っ越しました。", "target_word": "会社", "complexity_tier": "T3", "furigana": "兄[あに]の会社[かいしゃ]は去年[きょねん]、東京[とうきょう]から大阪[おおさか]へ引[ひ]っ越[こ]しました。", "sentence_source": "generated"}, {"text": "この会社の商品は、品質がよいことで知られています。", "target_word": "会社", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]の商品[しょうひん]は、品質[ひんしつ]がよいことで知[し]られています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "会社", "label": "基本形"}], "register": "標準（丁寧体）", "sense_fingerprint": "商売を目的に組織された企業という団体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88ab33ea-5a2d-4337-99fd-ffa844ac1d2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35563, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "会社", "is_correct": true, "explanation": "商品を輸入して売る主体として、会社が文に合う。"}, {"text": "本", "is_correct": false, "explanation": "本は輸入や販売の主体にならず、文が不自然になる。"}, {"text": "花", "is_correct": false, "explanation": "花は輸入して売る主体にならず、文が成り立たない。"}, {"text": "空", "is_correct": false, "explanation": "空は商品を売る主体にはならず、文が成り立たない。"}], "explanations": {"会社": "商品を輸入して売る主体として、会社が文に合う。", "本": "本は輸入や販売の主体にならず、文が不自然になる。", "花": "花は輸入して売る主体にならず、文が成り立たない。", "空": "空は商品を売る主体にはならず、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "会社"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会社を着て、外へ出かけた。", "explanation": "ここは〈服〉の意味。会社は身につけるものではないので、〈会社〉は合わない。"}, {"text": "会社が悲しくなって、涙を流した。", "explanation": "ここは〈感情〉の意味。会社は悲しむ人ではないので、〈会社〉は合わない。"}, {"text": "会社と手をつないで、駅まで歩いた。", "explanation": "ここは〈友達〉の意味。会社は手をつなぐ相手ではないので、〈会社〉は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e7f3f6-6c39-43b2-adbf-bdba1f8fbe51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35563, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "会社", "is_correct": true, "explanation": "見積書を送る相手として、会社が文に合う。"}, {"text": "傘", "is_correct": false, "explanation": "傘に見積書を送ることはできず、文が成り立たない。"}, {"text": "紅茶", "is_correct": false, "explanation": "紅茶は受け取り手にならず、不自然な文になる。"}, {"text": "雨", "is_correct": false, "explanation": "雨に見積書を送ることは成り立たない。"}], "explanations": {"会社": "見積書を送る相手として、会社が文に合う。", "傘": "傘に見積書を送ることはできず、文が成り立たない。", "紅茶": "紅茶は受け取り手にならず、不自然な文になる。", "雨": "雨に見積書を送ることは成り立たない。"}, "sentence_index": 6, "correct_answer": "会社"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夜空の会社が、きらきら光っている。", "explanation": "ここは〈星〉の意味。会社は光るものではないので、〈会社〉は合わない。"}, {"text": "庭の会社が、春に咲いた。", "explanation": "ここは〈花〉の意味。会社は咲く（開花する）ものではないので合わない。"}, {"text": "会社の境内には、大きな木がある。", "explanation": "〈会社〉は神社や寺の敷地の意味にはならず、境内の文には合わないので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e7f3f6-6c39-43b2-adbf-bdba1f8fbe51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35563, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その会社を名前を変えることが、先月決まりました。", "corrected_sentence": "その会社の名前を変えることが、先月決まりました。", "error_description": "誤りは「会社を」。名前の所有を表すには「の」を使うので、「を」は誤り。「を」が二つ重なる形になっている。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e7f3f6-6c39-43b2-adbf-bdba1f8fbe51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35563, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明日、取引先の会社と見積書を送ります。", "corrected_sentence": "明日、取引先の会社に見積書を送ります。", "error_description": "誤りは「会社と」。見積書を送る相手は「に」で示すので、「と」は誤り。正しくは「会社に」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e7f3f6-6c39-43b2-adbf-bdba1f8fbe51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35564, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「安い値段で」の「で」は条件や手段を表し、取り引きの仕方を示すので合う。"}, {"text": "が", "is_correct": false, "explanation": "「安い値段が取り引きしました」は値段を主語にすることになり、意味が通らない。"}, {"text": "に", "is_correct": false, "explanation": "「安い値段に取り引きしました」は相手や位置を表すことになり、取り引きの条件として不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「安い値段へ取り引きしました」は方向を表すが、値段は方向にならないので不自然。"}], "correct_answer": "で", "explanations": {"で": "「安い値段で」の「で」は条件や手段を表し、取り引きの仕方を示すので合う。", "が": "「安い値段が取り引きしました」は値段を主語にすることになり、意味が通らない。", "に": "「安い値段に取り引きしました」は相手や位置を表すことになり、取り引きの条件として不自然。", "へ": "「安い値段へ取り引きしました」は方向を表すが、値段は方向にならないので不自然。"}, "error_tags": {"が": "主語", "に": "相手・位置", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e7f3f6-6c39-43b2-adbf-bdba1f8fbe51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35564, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「本を取り引きする」の「を」は、取り引きの対象を示すので合う。"}, {"text": "より", "is_correct": false, "explanation": "「本より取り引きする人」は比較の意味になり、文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「本から取り引きする人」は起点を表すが、本を対象とする取り引きの説明にならない。"}, {"text": "が", "is_correct": false, "explanation": "「本が取り引きする人」は本を主語にすることになり、意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「本を取り引きする」の「を」は、取り引きの対象を示すので合う。", "より": "「本より取り引きする人」は比較の意味になり、文が成り立たない。", "から": "「本から取り引きする人」は起点を表すが、本を対象とする取り引きの説明にならない。", "が": "「本が取り引きする人」は本を主語にすることになり、意味が通らない。"}, "error_tags": {"より": "比較", "から": "起点", "が": "主語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e7f3f6-6c39-43b2-adbf-bdba1f8fbe51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35564, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "お金を出して、ものを買ったり売ったりすること。", "primary_collocate": null, "pronunciation": "とりひき", "ipa": "toɾihiki", "syllable_count": 4, "sentences": [{"text": "市場では、朝から魚の取り引きが始まります。", "target_word": "取り引き", "complexity_tier": "T3", "furigana": "市場[いちば]では、朝[あさ]から魚[さかな]の取[と]り引[ひ]きが始[はじ]まります。", "sentence_source": "generated"}, {"text": "店の人と話して、安い値段で取り引きしました。", "target_word": "取り引き", "complexity_tier": "T3", "furigana": "店[みせ]の人[ひと]と話[はな]して、安[やす]い値段[ねだん]で取[と]り引[ひ]きしました。", "sentence_source": "generated"}, {"text": "知らない人との取り引きは、少しこわいです。", "target_word": "取り引き", "complexity_tier": "T3", "furigana": "知[し]らない人[ひと]との取[と]り引[ひ]きは、少[すこ]しこわいです。", "sentence_source": "generated"}, {"text": "取り引きが終わったあと、二人は握手をしました。", "target_word": "取り引き", "complexity_tier": "T3", "furigana": "取[と]り引[ひ]きが終[お]わったあと、二人[ふたり]は握手[あくしゅ]をしました。", "sentence_source": "generated"}, {"text": "祖父は昔、米の取り引きをする仕事をしていました。", "target_word": "取り引き", "complexity_tier": "T3", "furigana": "祖父[そふ]は昔[むかし]、米[こめ]の取[と]り引[ひ]きをする仕事[しごと]をしていました。", "sentence_source": "generated"}, {"text": "この店とは、十年前から取り引きがあります。", "target_word": "取り引き", "complexity_tier": "T3", "furigana": "この店[みせ]とは、十年前[じゅうねんまえ]から取[と]り引[ひ]きがあります。", "sentence_source": "generated"}, {"text": "お金が足りなかったので、その取り引きはやめました。", "target_word": "取り引き", "complexity_tier": "T3", "furigana": "お金[かね]が足[た]りなかったので、その取[と]り引[ひ]きはやめました。", "sentence_source": "generated"}, {"text": "インターネットで中古の本を取り引きする人が増えています。", "target_word": "取り引き", "complexity_tier": "T3", "furigana": "インターネットで中古[ちゅうこ]の本[ほん]を取[と]り引[ひ]きする人[ひと]が増[ふ]えています。", "sentence_source": "generated"}, {"text": "取り引きの前に、品物をよく見ておきましょう。", "target_word": "取り引き", "complexity_tier": "T3", "furigana": "取[と]り引[ひ]きの前[まえ]に、品物[しなもの]をよく見[み]ておきましょう。", "sentence_source": "generated"}, {"text": "毎日の取り引きを、ノートに書いて残しています。", "target_word": "取り引き", "complexity_tier": "T3", "furigana": "毎日[まいにち]の取[と]り引[ひ]きを、ノートに書[か]いて残[のこ]しています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "取り引き", "label": "基本形"}, {"form": "取り引きする", "label": "する動詞の辞書形"}, {"form": "取り引きした", "label": "過去形"}], "register": "標準（丁寧体）", "sense_fingerprint": "お金とものを交換する売り買いの行為", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88ab33ea-5a2d-4337-99fd-ffa844ac1d2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35564, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "取り引き", "is_correct": true, "explanation": "「魚の取り引き」は魚の売り買いのことで、市場の場面に合う。"}, {"text": "授業", "is_correct": false, "explanation": "「魚の授業」は教えを受ける場で、市場の売り買いには合わない。"}, {"text": "試験", "is_correct": false, "explanation": "「魚の試験」は意味が通らず、市場の場面とも合わない。"}, {"text": "工事", "is_correct": false, "explanation": "「魚の工事」は建設作業を指し、魚の売買とは関係がない。"}], "explanations": {"取り引き": "「魚の取り引き」は魚の売り買いのことで、市場の場面に合う。", "授業": "「魚の授業」は教えを受ける場で、市場の売り買いには合わない。", "試験": "「魚の試験」は意味が通らず、市場の場面とも合わない。", "工事": "「魚の工事」は建設作業を指し、魚の売買とは関係がない。"}, "sentence_index": 0, "correct_answer": "取り引き"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "二人は意見を取り引きして、仲良くなりました。", "explanation": "ここは〈意見を交換する〉の意味。取り引きはお金で商品を売り買いすることなので、意見には使わない。"}, {"text": "この機械は取り引きがむずかしいので、説明書をよく読みましょう。", "explanation": "ここは〈扱い〉の意味。取り引きは売買のことなので、機械の使い方を表すのには使わない。"}, {"text": "見事な取り引きを見せて、会場が沸きました。", "explanation": "ここは〈試合でのプレー〉の意味。取り引きは商品の売買なので、競技の動きには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e7f3f6-6c39-43b2-adbf-bdba1f8fbe51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35564, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "取り引き", "is_correct": true, "explanation": "お金が足りず、その売り買いをやめたという文脈に合う。"}, {"text": "天気", "is_correct": false, "explanation": "「その天気はやめました」は意味が通らない。"}, {"text": "寝顔", "is_correct": false, "explanation": "「その寝顔はやめました」は不自然で、お金の不足とも結びつかない。"}, {"text": "食器", "is_correct": false, "explanation": "「その食器はやめました」はやめる対象にならず、文脈にも合わない。"}], "explanations": {"取り引き": "お金が足りず、その売り買いをやめたという文脈に合う。", "天気": "「その天気はやめました」は意味が通らない。", "寝顔": "「その寝顔はやめました」は不自然で、お金の不足とも結びつかない。", "食器": "「その食器はやめました」はやめる対象にならず、文脈にも合わない。"}, "sentence_index": 6, "correct_answer": "取り引き"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女の気持ちを取り引きして、やっと分かり合えました。", "explanation": "ここは〈理解する〉の意味。取り引きは商品の売買のことで、気持ちには使わない。"}, {"text": "先生が生徒に漢字を取り引きしました。", "explanation": "ここは〈教える〉の意味。取り引きはお金での売買なので、知識を教える場面には使わない。"}, {"text": "相手の話を取り引きして、考えを変えました。", "explanation": "ここは〈話を聞く〉の意味。取り引きは売買のことで、話を聞く行為には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e7f3f6-6c39-43b2-adbf-bdba1f8fbe51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35564, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "魚の取り引きが、朝早く始めます。", "corrected_sentence": "魚の取り引きを、朝早く始めます。", "error_description": "「取り引きを始める」の「を」が「が」になっている。「始める」は他動詞なので、目的語の「取り引き」に「を」が必要。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e7f3f6-6c39-43b2-adbf-bdba1f8fbe51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35564, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "毎月、商社と取り引きを食べています。", "corrected_sentence": "毎月、商社と取り引きをしています。", "error_description": "「取り引きをする」の動詞が誤り。取り引きには「する・続ける」が合い、「食べる」は合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e7f3f6-6c39-43b2-adbf-bdba1f8fbe51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35565, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「取り引きの条件」の「の」は、条件が取り引きに属することを示すので合う。"}, {"text": "が", "is_correct": false, "explanation": "「取り引きが条件について話し合う」は主語の関係が合わず、不自然。"}, {"text": "から", "is_correct": false, "explanation": "「取り引きから条件について」は起点を示すが、話し合いの対象として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「取り引きへ条件について」は方向を表すが、話し合う相手にならない。"}], "correct_answer": "の", "explanations": {"の": "「取り引きの条件」の「の」は、条件が取り引きに属することを示すので合う。", "が": "「取り引きが条件について話し合う」は主語の関係が合わず、不自然。", "から": "「取り引きから条件について」は起点を示すが、話し合いの対象として成り立たない。", "へ": "「取り引きへ条件について」は方向を表すが、話し合う相手にならない。"}, "error_tags": {"が": "主語", "から": "起点", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e7f3f6-6c39-43b2-adbf-bdba1f8fbe51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35565, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「取り引きに必要な」の「に」は、〜に必要だという関係を示すので合う。"}, {"text": "から", "is_correct": false, "explanation": "「取り引きから必要な書類」は起点を示すが、必要の対象にならない。"}, {"text": "で", "is_correct": false, "explanation": "「取り引きで必要な書類」は手段になり、必要の関係を表さない。"}, {"text": "を", "is_correct": false, "explanation": "「取り引きを必要な書類を」は目的語が二つ重なり、文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「取り引きに必要な」の「に」は、〜に必要だという関係を示すので合う。", "から": "「取り引きから必要な書類」は起点を示すが、必要の対象にならない。", "で": "「取り引きで必要な書類」は手段になり、必要の関係を表さない。", "を": "「取り引きを必要な書類を」は目的語が二つ重なり、文が成り立たない。"}, "error_tags": {"から": "起点", "で": "手段", "を": "目的語の重複"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e7f3f6-6c39-43b2-adbf-bdba1f8fbe51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35565, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "商品やサービスを売買すること。商売のやりとり。", "primary_collocate": null, "pronunciation": "とりひき", "ipa": "toɾihiki", "syllable_count": 4, "sentences": [{"text": "この会社とは、長く取り引きを続けています。", "target_word": "取り引き", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]とは、長[なが]く取[と]り引[ひ]きを続[つづ]けています。", "sentence_source": "generated"}, {"text": "取り引きの条件について、来週話し合います。", "target_word": "取り引き", "complexity_tier": "T3", "furigana": "取[と]り引[ひ]きの条件[じょうけん]について、来週[らいしゅう]話[はな]し合[あ]います。", "sentence_source": "generated"}, {"text": "二つの会社は、新しい取り引きを始めることにしました。", "target_word": "取り引き", "complexity_tier": "T3", "furigana": "二[ふた]つの会社[かいしゃ]は、新[あたら]しい取[と]り引[ひ]きを始[はじ]めることにしました。", "sentence_source": "generated"}, {"text": "取り引きを断ったので、あの店とはもう仕事をしません。", "target_word": "取り引き", "complexity_tier": "T3", "furigana": "取[と]り引[ひ]きを断[ことわ]ったので、あの店[みせ]とはもう仕事[しごと]をしません。", "sentence_source": "generated"}, {"text": "大きな取り引きが決まって、社員はみんな喜びました。", "target_word": "取り引き", "complexity_tier": "T3", "furigana": "大[おお]きな取[と]り引[ひ]きが決[き]まって、社員[しゃいん]はみんな喜[よろこ]びました。", "sentence_source": "generated"}, {"text": "海外との取り引きでは、言葉の違いが問題になります。", "target_word": "取り引き", "complexity_tier": "T3", "furigana": "海外[かいがい]との取[と]り引[ひ]きでは、言葉[ことば]の違[ちが]いが問題[もんだい]になります。", "sentence_source": "generated"}, {"text": "取り引きの記録は、五年間保管しなければなりません。", "target_word": "取り引き", "complexity_tier": "T3", "furigana": "取[と]り引[ひ]きの記録[きろく]は、五年間[ごねんかん]保管[ほかん]しなければなりません。", "sentence_source": "generated"}, {"text": "彼は取り引きに必要な書類を、急いで届けました。", "target_word": "取り引き", "complexity_tier": "T3", "furigana": "彼[かれ]は取[と]り引[ひ]きに必要[ひつよう]な書類[しょるい]を、急[いそ]いで届[とど]けました。", "sentence_source": "generated"}, {"text": "景気が悪くなって、取り引きが少なくなりました。", "target_word": "取り引き", "complexity_tier": "T3", "furigana": "景気[けいき]が悪[わる]くなって、取[と]り引[ひ]きが少[すく]なくなりました。", "sentence_source": "generated"}, {"text": "取り引きの相手を選ぶときは、信用を大切にします。", "target_word": "取り引き", "complexity_tier": "T3", "furigana": "取[と]り引[ひ]きの相手[あいて]を選[えら]ぶときは、信用[しんよう]を大切[たいせつ]にします。", "sentence_source": "generated"}], "morphological_forms": [{"form": "取り引き", "label": "基本形"}, {"form": "取り引きする", "label": "する動詞の辞書形"}, {"form": "取り引きした", "label": "過去形"}], "register": "標準（丁寧体）", "sense_fingerprint": "会社や店の間で行う商売上のやりとり", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88ab33ea-5a2d-4337-99fd-ffa844ac1d2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35565, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "取り引き", "is_correct": true, "explanation": "「会社と長く取り引きを続けている」は商売上のやりとりとして自然に合う。"}, {"text": "天気", "is_correct": false, "explanation": "「天気を続けています」は意味が通らない。"}, {"text": "寝顔", "is_correct": false, "explanation": "「寝顔を続けています」は意味が通らず、会社との関係とも合わない。"}, {"text": "食器", "is_correct": false, "explanation": "「食器を続けています」は不自然で、会社との関係を表せない。"}], "explanations": {"取り引き": "「会社と長く取り引きを続けている」は商売上のやりとりとして自然に合う。", "天気": "「天気を続けています」は意味が通らない。", "寝顔": "「寝顔を続けています」は意味が通らず、会社との関係とも合わない。", "食器": "「食器を続けています」は不自然で、会社との関係を表せない。"}, "sentence_index": 0, "correct_answer": "取り引き"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "友達に、悩みを取り引きしました。", "explanation": "ここは〈相談する〉の意味。取り引きは商売上の売り買いのことで、悩みには使わない。"}, {"text": "パーティーに、友達を取り引きしました。", "explanation": "ここは〈招待する〉の意味。取り引きは商品の売買で、人を誘う場面には使わない。"}, {"text": "玄関をきれいに取り引きしました。", "explanation": "ここは〈掃除する〉の意味。取り引きは売買のことで、場所の手入れには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e7f3f6-6c39-43b2-adbf-bdba1f8fbe51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35565, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "取り引き", "is_correct": true, "explanation": "「取り引きの記録」は商売の記録を指し、五年間の保管義務に合う。"}, {"text": "寝息", "is_correct": false, "explanation": "「寝息の記録」は保管の対象にならず、文脈に合わない。"}, {"text": "雨音", "is_correct": false, "explanation": "「雨音の記録」は商売の書類とは関係がなく、保管義務と合わない。"}, {"text": "落ち葉", "is_correct": false, "explanation": "「落ち葉の記録」は商売上の保管義務と結びつかず、不自然。"}], "explanations": {"取り引き": "「取り引きの記録」は商売の記録を指し、五年間の保管義務に合う。", "寝息": "「寝息の記録」は保管の対象にならず、文脈に合わない。", "雨音": "「雨音の記録」は商売の書類とは関係がなく、保管義務と合わない。", "落ち葉": "「落ち葉の記録」は商売上の保管義務と結びつかず、不自然。"}, "sentence_index": 6, "correct_answer": "取り引き"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は毎晩、大好きな歌を取り引きしています。", "explanation": "ここは〈歌を歌う〉の意味。取り引きは売買のことで、歌を歌う行為には使わない。"}, {"text": "毎日、英語を取り引きしています。", "explanation": "ここは〈英語を勉強する〉の意味。取り引きは商品の売買なので、学習には使わない。"}, {"text": "薬で病気を取り引きしました。", "explanation": "ここは〈病気を治す〉の意味。取り引きは売買のことで、病気の治療には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e7f3f6-6c39-43b2-adbf-bdba1f8fbe51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35565, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しい会社と、来月から取り引きが始めます。", "corrected_sentence": "新しい会社と、来月から取り引きを始めます。", "error_description": "「取り引きを始める」の「を」が「が」になっている。「始める」は他動詞なので、目的語の「取り引き」に「を」が必要。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e7f3f6-6c39-43b2-adbf-bdba1f8fbe51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35565, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先月の取り引きを、すべて飲みました。", "corrected_sentence": "先月の取り引きを、すべて確認しました。", "error_description": "取り引きに合う動詞は「確認する」などで、「飲む」は取り引きと結びつかない。動詞の選び方が誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e7f3f6-6c39-43b2-adbf-bdba1f8fbe51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
