INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35566, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "物事が、止まったり困ったりしないで、うまく進むこと。", "primary_collocate": null, "pronunciation": "すむーず", "ipa": "sɯmɯːzɯ", "syllable_count": 4, "sentences": [{"text": "道がすいていたので、スムーズに家へ着いた。", "target_word": "スムーズ", "complexity_tier": "T3", "furigana": "道[みち]がすいていたので、スムーズに家[いえ]へ着[つ]いた。", "sentence_source": "generated"}, {"text": "準備をしっかりしたから、発表はスムーズに進んだ。", "target_word": "スムーズ", "complexity_tier": "T3", "furigana": "準備[じゅんび]をしっかりしたから、発表[はっぴょう]はスムーズに進[すす]んだ。", "sentence_source": "generated"}, {"text": "手続きがスムーズにできて、とても助かりました。", "target_word": "スムーズ", "complexity_tier": "T3", "furigana": "手続[てつづ]きがスムーズにできて、とても助[たす]かりました。", "sentence_source": "generated"}, {"text": "彼女の説明のおかげで、話し合いがスムーズになった。", "target_word": "スムーズ", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の説明[せつめい]のおかげで、話[はな]し合[あ]いがスムーズになった。", "sentence_source": "generated"}, {"text": "駅の改札が広くて、人の流れがスムーズだ。", "target_word": "スムーズ", "complexity_tier": "T3", "furigana": "駅[えき]の改札[かいさつ]が広[ひろ]くて、人[ひと]の流[なが]れがスムーズだ。", "sentence_source": "generated"}, {"text": "引っ越しの作業は、みんなで協力したのでスムーズに終わった。", "target_word": "スムーズ", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]しの作業[さぎょう]は、みんなで協力[きょうりょく]したのでスムーズに終[お]わった。", "sentence_source": "generated"}, {"text": "練習すれば、会話もスムーズにできるようになる。", "target_word": "スムーズ", "complexity_tier": "T3", "furigana": "練習[れんしゅう]すれば、会話[かいわ]もスムーズにできるようになる。", "sentence_source": "generated"}, {"text": "前の日に道具をそろえておくと、朝の準備がスムーズだ。", "target_word": "スムーズ", "complexity_tier": "T3", "furigana": "前[まえ]の日[ひ]に道具[どうぐ]をそろえておくと、朝[あさ]の準備[じゅんび]がスムーズだ。", "sentence_source": "generated"}, {"text": "古い機械は動きがスムーズではなく、よく止まってしまう。", "target_word": "スムーズ", "complexity_tier": "T3", "furigana": "古[ふる]い機械[きかい]は動[うご]きがスムーズではなく、よく止[と]まってしまう。", "sentence_source": "generated"}, {"text": "質問に答える流れがスムーズで、聞きやすい授業だった。", "target_word": "スムーズ", "complexity_tier": "T3", "furigana": "質問[しつもん]に答[こた]える流[なが]れがスムーズで、聞[き]きやすい授業[じゅぎょう]だった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "スムーズだ", "label": "断定形"}, {"form": "スムーズな", "label": "連体形"}, {"form": "スムーズに", "label": "連用形"}], "register": "neutral", "sense_fingerprint": "止まらず困らず、うまく進むさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e60ae888-bad4-41d8-9618-5085bc76d610') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35566, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "スムーズ", "is_correct": true, "explanation": "道がすいていた状況で、支障なく進んで着いたという意味になる。"}, {"text": "豪華", "is_correct": false, "explanation": "豪華では道の状況と合わず、着き方の様子を表さない。"}, {"text": "上品", "is_correct": false, "explanation": "上品は態度への評価で、道の状況に続かない。"}, {"text": "陽気", "is_correct": false, "explanation": "陽気は気分を表し、家へ着いた様子の説明に合わない。"}], "explanations": {"スムーズ": "道がすいていた状況で、支障なく進んで着いたという意味になる。", "豪華": "豪華では道の状況と合わず、着き方の様子を表さない。", "上品": "上品は態度への評価で、道の状況に続かない。", "陽気": "陽気は気分を表し、家へ着いた様子の説明に合わない。"}, "sentence_index": 0, "correct_answer": "スムーズ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "台風が去って、海はスムーズになった。", "explanation": "ここは〈穏やか〉の意味。スムーズは進み具合の形容で、海の波の静けさは表さない。"}, {"text": "この荷物はスムーズで、持ちやすい。", "explanation": "ここは〈軽い〉の意味。スムーズは進み方の形容で、荷物の重さは表さない。"}, {"text": "部屋の大きさがスムーズで、広く感じる。", "explanation": "ここは〈大きい〉の意味。スムーズは進み方の形容で、部屋の寸法には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c8b42d-f3e7-4b88-90bd-76c3f6398d22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35566, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "スムーズ", "is_correct": true, "explanation": "会話が支障なく進むようになる、という意味になる。"}, {"text": "派手", "is_correct": false, "explanation": "派手では会話の進み具合を表せない。"}, {"text": "静粛", "is_correct": false, "explanation": "静粛は静かなさまで、会話ができるようになる文には合わない。"}, {"text": "不自由", "is_correct": false, "explanation": "不自由は困る状態を表し、できるようになるという文と逆になる。"}], "explanations": {"スムーズ": "会話が支障なく進むようになる、という意味になる。", "派手": "派手では会話の進み具合を表せない。", "静粛": "静粛は静かなさまで、会話ができるようになる文には合わない。", "不自由": "不自由は困る状態を表し、できるようになるという文と逆になる。"}, "sentence_index": 6, "correct_answer": "スムーズ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このお茶は苦みがスムーズだ。", "explanation": "ここは〈苦い〉の意味。スムーズは進み具合の形容で、味の強さには使わない。"}, {"text": "この果物はスムーズで、とても甘い。", "explanation": "ここは〈甘い〉の意味。スムーズは進み具合の形容で、味の甘さは表さない。"}, {"text": "この肉はスムーズで、噛み切りやすい。", "explanation": "ここは〈柔らかい〉の意味。スムーズは進み具合の形容で、肉の柔らかさは表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c8b42d-f3e7-4b88-90bd-76c3f6398d22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35566, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "手続きがスムーズな進んで、すぐに終わった。", "corrected_sentence": "手続きがスムーズに進んで、すぐに終わった。", "error_description": "「進んで」を修飾するには連用形の「に」が必要。「な」は名詞の前に置く形で、動詞の前には使えない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "スムーズ", "is_correct": true, "explanation": "「スムーズに」の語幹にあたる形。「に」を付けて「進んだ」を修飾する。"}, {"text": "スムーズだ", "is_correct": false, "explanation": "断定形。「進んだ」を修飾する副詞の位置には入らない。"}, {"text": "スムーズな", "is_correct": false, "explanation": "連体形。名詞を修飾する形で、動詞「進んだ」には続かない。"}, {"text": "スムーズさ", "is_correct": false, "explanation": "名詞化した形。進み方を修飾する位置には入らない。"}], "correct_form": "スムーズ", "base_form": "スムーズだ", "form_label": "連用形", "sentence_index": 1, "explanations": {"スムーズ": "「スムーズに」の語幹にあたる形。「に」を付けて「進んだ」を修飾する。", "スムーズだ": "断定形。「進んだ」を修飾する副詞の位置には入らない。", "スムーズな": "連体形。名詞を修飾する形で、動詞「進んだ」には続かない。", "スムーズさ": "名詞化した形。進み方を修飾する位置には入らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c8b42d-f3e7-4b88-90bd-76c3f6398d22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35566, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "作業はスムーズに進みので、夕方に終わった。", "corrected_sentence": "作業はスムーズに進んだので、夕方に終わった。", "error_description": "「進んだので」が正しい。「進みので」は「進む」の活用が誤りで、「進み」は「ので」に続かない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "スムーズ", "is_correct": true, "explanation": "「スムーズだ」の語幹。「準備がスムーズだ」と文末で言い切る形を作る。"}, {"text": "スムーズに", "is_correct": false, "explanation": "連用形。「準備が」の述語としては続かない。"}, {"text": "スムーズな", "is_correct": false, "explanation": "連体形。名詞の前に置く形で、「だ」と続けると文末を閉じられない。"}, {"text": "スムーズではない", "is_correct": false, "explanation": "否定形。「準備がスムーズだ」という肯定の意味と合わない。"}], "correct_form": "スムーズ", "base_form": "スムーズだ", "form_label": "断定形", "sentence_index": 7, "explanations": {"スムーズ": "「スムーズだ」の語幹。「準備がスムーズだ」と文末で言い切る形を作る。", "スムーズに": "連用形。「準備が」の述語としては続かない。", "スムーズな": "連体形。名詞の前に置く形で、「だ」と続けると文末を閉じられない。", "スムーズではない": "否定形。「準備がスムーズだ」という肯定の意味と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c8b42d-f3e7-4b88-90bd-76c3f6398d22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
