INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35567, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "問題や遅れがなく、順調に物事が進む様子。", "primary_collocate": null, "pronunciation": "すむーず", "ipa": "sɯmɯːzɯ", "syllable_count": 4, "sentences": [{"text": "工事は問題なく、スムーズに進んでいる。", "target_word": "スムーズ", "complexity_tier": "T3", "furigana": "工事[こうじ]は問題[もんだい]なく、スムーズに進[すす]んでいる。", "sentence_source": "generated"}, {"text": "交渉がスムーズに進み、契約は一日で決まった。", "target_word": "スムーズ", "complexity_tier": "T4", "furigana": "交渉[こうしょう]がスムーズに進[すす]み、契約[けいやく]は一日[いちにち]で決[き]まった。", "sentence_source": "generated"}, {"text": "事前に連絡したおかげで、入国の手続きはスムーズだった。", "target_word": "スムーズ", "complexity_tier": "T4", "furigana": "事前[じぜん]に連絡[れんらく]したおかげで、入国[にゅうこく]の手続[てつづ]きはスムーズだった。", "sentence_source": "generated"}, {"text": "電車が遅れず、通勤がスムーズにできた。", "target_word": "スムーズ", "complexity_tier": "T3", "furigana": "電車[でんしゃ]が遅[おく]れず、通勤[つうきん]がスムーズにできた。", "sentence_source": "generated"}, {"text": "新しいシステムのおかげで、受付の流れがスムーズになった。", "target_word": "スムーズ", "complexity_tier": "T3", "furigana": "新[あたら]しいシステムのおかげで、受付[うけつけ]の流[なが]れがスムーズになった。", "sentence_source": "generated"}, {"text": "引き継ぎが十分だったので、仕事はスムーズに回り始めた。", "target_word": "スムーズ", "complexity_tier": "T4", "furigana": "引[ひ]き継[つ]ぎが十分[じゅうぶん]だったので、仕事[しごと]はスムーズに回[まわ]り始[はじ]めた。", "sentence_source": "generated"}, {"text": "会議はスムーズに終わり、予定より早く帰れた。", "target_word": "スムーズ", "complexity_tier": "T3", "furigana": "会議[かいぎ]はスムーズに終[お]わり、予定[よてい]より早[はや]く帰[かえ]れた。", "sentence_source": "generated"}, {"text": "書類にまちがいが多く、審査はスムーズにいかなかった。", "target_word": "スムーズ", "complexity_tier": "T4", "furigana": "書類[しょるい]にまちがいが多[おお]く、審査[しんさ]はスムーズにいかなかった。", "sentence_source": "generated"}, {"text": "彼は段取りがうまく、プロジェクトがスムーズに運んだ。", "target_word": "スムーズ", "complexity_tier": "T4", "furigana": "彼[かれ]は段取[だんど]りがうまく、プロジェクトがスムーズに運[はこ]んだ。", "sentence_source": "generated"}, {"text": "ネットの接続が安定していて、オンライン授業もスムーズだ。", "target_word": "スムーズ", "complexity_tier": "T3", "furigana": "ネットの接続[せつぞく]が安定[あんてい]していて、オンライン授業[じゅぎょう]もスムーズだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "スムーズだ", "label": "断定形"}, {"form": "スムーズな", "label": "連体形"}, {"form": "スムーズに", "label": "連用形"}], "register": "neutral", "sense_fingerprint": "問題や遅れなく順調に運ぶ様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e60ae888-bad4-41d8-9618-5085bc76d610') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35567, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "スムーズ", "is_correct": true, "explanation": "問題なく順調に進んでいる、という意味になる。"}, {"text": "寡黙", "is_correct": false, "explanation": "寡黙は口数が少ないさまで、工事の進み方を表さない。"}, {"text": "粗末", "is_correct": false, "explanation": "粗末は質の低さを表し、順調な進行の説明に合わない。"}, {"text": "陰気", "is_correct": false, "explanation": "陰気は雰囲気を表し、工事が進んでいる様子には合わない。"}], "explanations": {"スムーズ": "問題なく順調に進んでいる、という意味になる。", "寡黙": "寡黙は口数が少ないさまで、工事の進み方を表さない。", "粗末": "粗末は質の低さを表し、順調な進行の説明に合わない。", "陰気": "陰気は雰囲気を表し、工事が進んでいる様子には合わない。"}, "sentence_index": 0, "correct_answer": "スムーズ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この声はスムーズで、聞いていて心地よい。", "explanation": "ここは〈なめらか〉の意味。スムーズは進み具合の形容で、声の質感は表さない。"}, {"text": "この箱はスムーズで、運べない。", "explanation": "ここは〈重い〉の意味。スムーズは進み方の形容で、物の重さは表さない。"}, {"text": "窓ガラスがスムーズで、外の景色がよく見える。", "explanation": "ここは〈なめらか〉の意味。スムーズは進み方の形容で、ガラス表面の状態は表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c8b42d-f3e7-4b88-90bd-76c3f6398d22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35567, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "スムーズ", "is_correct": true, "explanation": "会議が問題なく終わり、予定より早く帰れたという意味になる。"}, {"text": "静粛", "is_correct": false, "explanation": "静粛は静かなさまで、会議の終わり方の説明には合わない。"}, {"text": "不自由", "is_correct": false, "explanation": "不自由は困る状態を表し、早く帰れたという文と合わない。"}, {"text": "幼稚", "is_correct": false, "explanation": "幼稚は未熟さを表し、会議の進み方とは関係しない。"}], "explanations": {"スムーズ": "会議が問題なく終わり、予定より早く帰れたという意味になる。", "静粛": "静粛は静かなさまで、会議の終わり方の説明には合わない。", "不自由": "不自由は困る状態を表し、早く帰れたという文と合わない。", "幼稚": "幼稚は未熟さを表し、会議の進み方とは関係しない。"}, "sentence_index": 6, "correct_answer": "スムーズ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この湖は水深がスムーズだ。", "explanation": "ここは〈深い〉の意味。スムーズは進み方の形容で、水の深さは表さない。"}, {"text": "この地域は平野がスムーズで、見通しがよい。", "explanation": "ここは〈平ら〉の意味。スムーズは進み方の形容で、地面の起伏は表さない。"}, {"text": "部屋の明るさがスムーズで、目が疲れない。", "explanation": "ここは〈明るい〉の意味。スムーズは進み方の形容で、光の強さは表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c8b42d-f3e7-4b88-90bd-76c3f6398d22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35567, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しい手順のおかげで、作業がスムーズな進んだ。", "corrected_sentence": "新しい手順のおかげで、作業がスムーズに進んだ。", "error_description": "「進んだ」を修飾するには連用形の「に」が必要。連体形の「な」は動詞の前に置けない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "スムーズ", "is_correct": true, "explanation": "「スムーズに」の語幹。「に」を付けて「進み」を修飾する。"}, {"text": "スムーズだ", "is_correct": false, "explanation": "断定形。「進み」を修飾する副詞の位置には入らない。"}, {"text": "スムーズな", "is_correct": false, "explanation": "連体形。名詞を修飾する形で、動詞「進み」には続かない。"}, {"text": "スムーズさ", "is_correct": false, "explanation": "名詞化した形。進み方を修飾する位置には入らない。"}], "correct_form": "スムーズ", "base_form": "スムーズだ", "form_label": "連用形", "sentence_index": 1, "explanations": {"スムーズ": "「スムーズに」の語幹。「に」を付けて「進み」を修飾する。", "スムーズだ": "断定形。「進み」を修飾する副詞の位置には入らない。", "スムーズな": "連体形。名詞を修飾する形で、動詞「進み」には続かない。", "スムーズさ": "名詞化した形。進み方を修飾する位置には入らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c8b42d-f3e7-4b88-90bd-76c3f6398d22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35567, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ネットが安定して、オンライン授業がスムーズな進んだ。", "corrected_sentence": "ネットが安定して、オンライン授業がスムーズに進んだ。", "error_description": "「進んだ」を修飾するのは連用形の「に」。連体形の「な」は名詞の前に置くもので、動詞の前には使えない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "スムーズ", "is_correct": true, "explanation": "「スムーズに」の語幹。「に」を付けて「いかなかった」を修飾する。"}, {"text": "スムーズ化", "is_correct": false, "explanation": "名詞化した形。「いかなかった」を修飾する副詞の位置には入らない。"}, {"text": "スムーズではない", "is_correct": false, "explanation": "否定形。「審査はスムーズにいかなかった」の文の形とは別物。"}, {"text": "スムーズすぎる", "is_correct": false, "explanation": "程度を表す動詞形。「いかなかった」を修飾する位置には入らない。"}], "correct_form": "スムーズ", "base_form": "スムーズだ", "form_label": "連用形", "sentence_index": 7, "explanations": {"スムーズ": "「スムーズに」の語幹。「に」を付けて「いかなかった」を修飾する。", "スムーズ化": "名詞化した形。「いかなかった」を修飾する副詞の位置には入らない。", "スムーズではない": "否定形。「審査はスムーズにいかなかった」の文の形とは別物。", "スムーズすぎる": "程度を表す動詞形。「いかなかった」を修飾する位置には入らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7c8b42d-f3e7-4b88-90bd-76c3f6398d22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
