INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35568, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "何かをうまくするために、がんばること。", "primary_collocate": null, "pronunciation": "はたらく", "ipa": "hatarakɯ", "syllable_count": 4, "sentences": [{"text": "村を豊かにするために、若者たちは朝から晩まで懸命に働いた。", "target_word": "働いた", "complexity_tier": "T3", "furigana": "村[むら]を豊[ゆた]かにするために、若者[わかもの]たちは朝[あさ]から晩[ばん]まで懸命[けんめい]に働[はたら]いた。", "sentence_source": "generated"}, {"text": "彼は仲間の役に立とうと、人一倍よく働く人だ。", "target_word": "働く", "complexity_tier": "T3", "furigana": "彼[かれ]は仲間[なかま]の役[やく]に立[た]とうと、人一倍[ひといちばい]よく働[はたら]く人[ひと]だ。", "sentence_source": "generated"}, {"text": "計画をうまく進めるため、全員が力を尽くして働いた。", "target_word": "働いた", "complexity_tier": "T3", "furigana": "計画[けいかく]をうまく進[すす]めるため、全員[ぜんいん]が力[ちから]を尽[つ]くして働[はたら]いた。", "sentence_source": "generated"}, {"text": "国の復興のために働きたいと、彼女は政治家を目指した。", "target_word": "働き", "complexity_tier": "T3", "furigana": "国[くに]の復興[ふっこう]のために働[はたら]きたいと、彼女[かのじょ]は政治家[せいじか]を目指[めざ]した。", "sentence_source": "generated"}, {"text": "大会を成功させようと、スタッフは休まず働いてくれた。", "target_word": "働いて", "complexity_tier": "T3", "furigana": "大会[たいかい]を成功[せいこう]させようと、スタッフは休[やす]まず働[はたら]いてくれた。", "sentence_source": "generated"}, {"text": "家族を幸せにしたくて、父は必死に働いてきた。", "target_word": "働いて", "complexity_tier": "T3", "furigana": "家族[かぞく]を幸[しあわ]せにしたくて、父[ちち]は必死[ひっし]に働[はたら]いてきた。", "sentence_source": "generated"}, {"text": "良い結果を出すには、チーム全体が一つになって働く必要がある。", "target_word": "働く", "complexity_tier": "T3", "furigana": "良[よ]い結果[けっか]を出[だ]すには、チーム全体[ぜんたい]が一[ひと]つになって働[はたら]く必要[ひつよう]がある。", "sentence_source": "generated"}, {"text": "彼は人々の暮らしをよくするために、命がけで働いた。", "target_word": "働いた", "complexity_tier": "T3", "furigana": "彼[かれ]は人々[ひとびと]の暮[く]らしをよくするために、命[いのち]がけで働[はたら]いた。", "sentence_source": "generated"}, {"text": "約束を守るために、私は寝る時間を削ってでも働くつもりだ。", "target_word": "働く", "complexity_tier": "T3", "furigana": "約束[やくそく]を守[まも]るために、私[わたし]は寝[ね]る時間[じかん]を削[けず]ってでも働[はたら]くつもりだ。", "sentence_source": "generated"}, {"text": "期待に応えようと、新人たちは精一杯働いていた。", "target_word": "働いて", "complexity_tier": "T3", "furigana": "期待[きたい]に応[こた]えようと、新人[しんじん]たちは精一杯[せいいっぱい]働[はたら]いていた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "働く", "label": "辞書形"}, {"form": "働いた", "label": "過去形"}, {"form": "働いて", "label": "て形"}, {"form": "働かない", "label": "否定形"}, {"form": "働きたい", "label": "願望形"}, {"form": "働けば", "label": "仮定形"}], "register": "標準（中立）", "sense_fingerprint": "目標のために力を尽くして励む、働く", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T2: contains vocabulary far above tier T2: 役に立と (Zipf 1.89)']::text[], '33db208a-4ad2-4e69-a0ee-68818b305fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35568, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "働いた", "is_correct": true, "explanation": "過去形「働いた」。「懸命に働いた」と過去の努力を述べる文として成り立つ。"}, {"text": "働き", "is_correct": false, "explanation": "連用形の「働き」は文を終えられず、「懸命に働き。」は不完全。"}, {"text": "働か", "is_correct": false, "explanation": "未然形は文末に置けず、「懸命に働か。」は不完全。"}, {"text": "働かせ", "is_correct": false, "explanation": "使役の連用形は「働かせ。」となり、文として不完全で意味も合わない。"}], "explanations": {"働いた": "過去形「働いた」。「懸命に働いた」と過去の努力を述べる文として成り立つ。", "働き": "連用形の「働き」は文を終えられず、「懸命に働き。」は不完全。", "働か": "未然形は文末に置けず、「懸命に働か。」は不完全。", "働かせ": "使役の連用形は「働かせ。」となり、文として不完全で意味も合わない。"}, "sentence_index": 0, "correct_answer": "働いた"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は大会の委員長の任を働いた。", "explanation": "ここは〈務める〉（役目を担う）の意味。〈働く〉は役目を目的語に取らないので、〈任を務めた〉が正しい。"}, {"text": "チームは勝利のため、全員が力を働いた。", "explanation": "ここは〈力を尽くす〉の意味。〈働く〉は〈力〉を目的語に取らないので、〈力を尽くした〉が自然。"}, {"text": "父は家族の暮らしのため、お金を働いた。", "explanation": "ここは〈稼ぐ〉（お金を得る）の意味。〈働く〉はお金を目的語に取らないので、〈お金を稼いだ〉が正しい。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032573e2-d232-46e2-bb94-ebe49299e77f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35568, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "働く", "is_correct": true, "explanation": "辞書形で「必要がある」に直接続き、力を尽くして働く必要を述べる。"}, {"text": "働いて", "is_correct": false, "explanation": "て形は「必要がある」に続かず、「働いて必要がある」は成立しない。"}, {"text": "働けば", "is_correct": false, "explanation": "仮定形は「働けば必要がある」となり、不自然で意味が通らない。"}, {"text": "働い", "is_correct": false, "explanation": "連用形は「必要がある」の前に来られず、文として成り立たない。"}], "explanations": {"働く": "辞書形で「必要がある」に直接続き、力を尽くして働く必要を述べる。", "働いて": "て形は「必要がある」に続かず、「働いて必要がある」は成立しない。", "働けば": "仮定形は「働けば必要がある」となり、不自然で意味が通らない。", "働い": "連用形は「必要がある」の前に来られず、文として成り立たない。"}, "sentence_index": 6, "correct_answer": "働く"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は仲間の信頼を得るため、誠意を働いた。", "explanation": "ここは〈誠意を示す〉の意味。〈働く〉は誠意を目的語に取らないので、〈誠意を示した〉が正しい。"}, {"text": "彼は受験のため、人生の十年を働いた。", "explanation": "ここは〈費やす〉（時間を使う）の意味。〈働く〉は年月を目的語に取らないので、〈十年を費やした〉が正しい。"}, {"text": "若者たちは村の未来を働いた。", "explanation": "ここは〈担う〉（責任を引き受ける）の意味。〈働く〉は未来を目的語に取らないので、〈未来を担った〉が正しい。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032573e2-d232-46e2-bb94-ebe49299e77f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35568, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "チームは全員で協力して働くた。", "corrected_sentence": "チームは全員で協力して働いた。", "error_description": "過去形は連用形「働い」＋「た」。辞書形「働く」に「た」をつけた「働くた」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "働く", "is_correct": true, "explanation": "辞書形で名詞「人」を修飾する連体形。「よく働く人」で習慣的な努力を表す。"}, {"text": "働か", "is_correct": false, "explanation": "未然形は名詞「人」を修飾できず、「よく働か人だ」は成立しない。"}, {"text": "働け", "is_correct": false, "explanation": "命令形は名詞を修飾できず、「よく働け人だ」は成立しない。"}, {"text": "働こう", "is_correct": false, "explanation": "意向形は名詞を修飾できず、「よく働こう人だ」は成立しない。"}], "correct_form": "働く", "base_form": "働く", "form_label": "辞書形（連体形）", "sentence_index": 1, "explanations": {"働く": "辞書形で名詞「人」を修飾する連体形。「よく働く人」で習慣的な努力を表す。", "働か": "未然形は名詞「人」を修飾できず、「よく働か人だ」は成立しない。", "働け": "命令形は名詞を修飾できず、「よく働け人だ」は成立しない。", "働こう": "意向形は名詞を修飾できず、「よく働こう人だ」は成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032573e2-d232-46e2-bb94-ebe49299e77f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35568, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祖母は家族のために、毎朝早く起きて畑に一生懸命働いている。", "corrected_sentence": "祖母は家族のために、毎朝早く起きて畑で一生懸命働いている。", "error_description": "働く場所を示すのは「で」。「畑に働いている」の「に」は誤りで、「畑で一生懸命働いている」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "働いた", "is_correct": true, "explanation": "過去形「働いた」。過去の努力を述べる文として成り立つ。"}, {"text": "働い", "is_correct": false, "explanation": "連用形の一部で、文末に置けず「命がけで働い。」は不完全。"}, {"text": "働かず", "is_correct": false, "explanation": "ず形は文末で完結せず、「命がけで働かず。」は不完全。"}, {"text": "働いて", "is_correct": false, "explanation": "て形は文末に置けず、「命がけで働いて。」は文が途中で切れる。"}], "correct_form": "働いた", "base_form": "働く", "form_label": "過去形", "sentence_index": 7, "explanations": {"働いた": "過去形「働いた」。過去の努力を述べる文として成り立つ。", "働い": "連用形の一部で、文末に置けず「命がけで働い。」は不完全。", "働かず": "ず形は文末で完結せず、「命がけで働かず。」は不完全。", "働いて": "て形は文末に置けず、「命がけで働いて。」は文が途中で切れる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032573e2-d232-46e2-bb94-ebe49299e77f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
