INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35569, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ある目的のために、積極的に行動する。また、仕事をする。", "primary_collocate": null, "pronunciation": "はたらく", "ipa": "hatarakɯ", "syllable_count": 4, "sentences": [{"text": "高校を卒業したばかりの10代の彼が選んだ道は、地方の有機農家で働くことでした。", "target_word": "働く", "complexity_tier": "T3", "furigana": "高校[こうこう]を卒業[そつぎょう]したばかりの10代[だい]の彼[かれ]が選[えら]んだ道[みち]は、地方[ちほう]の有機[ゆうき]農家[のうか]で働[はたら]くことでした。", "sentence_source": "mined"}, {"text": "父は三十年間、同じ工場で働いています。", "target_word": "働いて", "complexity_tier": "T3", "furigana": "父[ちち]は三十年間[さんじゅうねんかん]、同[おな]じ工場[こうじょう]で働[はたら]いています。", "sentence_source": "generated"}, {"text": "学生のころは、週末だけ書店で働いていました。", "target_word": "働いて", "complexity_tier": "T3", "furigana": "学生[がくせい]のころは、週末[しゅうまつ]だけ書店[しょてん]で働[はたら]いていました。", "sentence_source": "generated"}, {"text": "彼女は病院で働くために、看護師の資格を取りました。", "target_word": "働く", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は病院[びょういん]で働[はたら]くために、看護師[かんごし]の資格[しかく]を取[と]りました。", "sentence_source": "generated"}, {"text": "母は夜遅くまで働いたので、今朝は起きられませんでした。", "target_word": "働いた", "complexity_tier": "T3", "furigana": "母[はは]は夜遅[よるおそ]くまで働[はたら]いたので、今朝[けさ]は起[お]きられませんでした。", "sentence_source": "generated"}, {"text": "将来は海外の会社で働きたいと考えています。", "target_word": "働き", "complexity_tier": "T3", "furigana": "将来[しょうらい]は海外[かいがい]の会社[かいしゃ]で働[はたら]きたいと考[かんが]えています。", "sentence_source": "generated"}, {"text": "彼は昼は大学に通い、夜はコンビニで働いている。", "target_word": "働いて", "complexity_tier": "T3", "furigana": "彼[かれ]は昼[ひる]は大学[だいがく]に通[かよ]い、夜[よる]はコンビニで働[はたら]いている。", "sentence_source": "generated"}, {"text": "一日八時間働いても、給料はあまり上がりません。", "target_word": "働いて", "complexity_tier": "T3", "furigana": "一日[いちにち]八時間[はちじかん]働[はたら]いても、給料[きゅうりょう]はあまり上[あ]がりません。", "sentence_source": "generated"}, {"text": "祖父は定年後も、地域の役所で働くことを選びました。", "target_word": "働く", "complexity_tier": "T3", "furigana": "祖父[そふ]は定年後[ていねんご]も、地域[ちいき]の役所[やくしょ]で働[はたら]くことを選[えら]びました。", "sentence_source": "generated"}, {"text": "働かなければ生活できないので、毎日職場へ向かう。", "target_word": "働かなければ", "complexity_tier": "T3", "furigana": "働[はたら]かなければ生活[せいかつ]できないので、毎日[まいにち]職場[しょくば]へ向[む]かう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "働く", "label": "辞書形"}, {"form": "働いた", "label": "過去形"}, {"form": "働いて", "label": "て形"}, {"form": "働かない", "label": "否定形"}, {"form": "働きたい", "label": "願望形"}, {"form": "働けば", "label": "仮定形"}], "register": "標準（中立）", "sense_fingerprint": "職場や仕事で労働する、働く", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33db208a-4ad2-4e69-a0ee-68818b305fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35569, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "働く", "is_correct": true, "explanation": "辞書形で「〜ことでした」に直接続き、〈仕事をする〉の文として成り立つ。"}, {"text": "働き", "is_correct": false, "explanation": "連用形の「働き」は「〜ことでした」に続かず、名詞節が作れないので文が途中で切れる。"}, {"text": "働け", "is_correct": false, "explanation": "命令・仮定の形で、「〜ことでした」の前には置けない。"}, {"text": "働こう", "is_correct": false, "explanation": "意向形は「〜ことでした」に続かず、ここでは文法的に成立しない。"}], "explanations": {"働く": "辞書形で「〜ことでした」に直接続き、〈仕事をする〉の文として成り立つ。", "働き": "連用形の「働き」は「〜ことでした」に続かず、名詞節が作れないので文が途中で切れる。", "働け": "命令・仮定の形で、「〜ことでした」の前には置けない。", "働こう": "意向形は「〜ことでした」に続かず、ここでは文法的に成立しない。"}, "sentence_index": 0, "correct_answer": "働く"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は三年間、町内会の会長を働いた。", "explanation": "ここは〈務める〉（役目を担う）の意味。〈働く〉は役職を目的語に取らないので、〈会長を務めた〉が正しい。"}, {"text": "彼は夏休みの間に、旅費として三十万円を働いた。", "explanation": "ここは〈稼ぐ〉（お金を得る）の意味。〈働く〉は金額を目的語に取らないので、〈三十万円稼いだ〉が正しい。"}, {"text": "彼は来月の旅行の日程を働いて決めた。", "explanation": "ここは〈立てる〉（計画を作る）の意味。〈働く〉には計画を作る用法がないので、〈日程を立てた〉が自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032573e2-d232-46e2-bb94-ebe49299e77f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35569, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "働いて", "is_correct": true, "explanation": "「働いている」の「働いて」（て形）。「〜ている」に続けて継続を表す。"}, {"text": "働く", "is_correct": false, "explanation": "辞書形は「働くいる」となり、「いる」に続かない。"}, {"text": "働か", "is_correct": false, "explanation": "未然形は「働かいる」となり、文法的に成り立たない。"}, {"text": "働けば", "is_correct": false, "explanation": "仮定形は「働けばいる」となり、続けると文が成立しない。"}], "explanations": {"働いて": "「働いている」の「働いて」（て形）。「〜ている」に続けて継続を表す。", "働く": "辞書形は「働くいる」となり、「いる」に続かない。", "働か": "未然形は「働かいる」となり、文法的に成り立たない。", "働けば": "仮定形は「働けばいる」となり、続けると文が成立しない。"}, "sentence_index": 6, "correct_answer": "働いて"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "父は三十年間、小さな店を働いている。", "explanation": "ここは〈営む〉（事業を経営する）の意味。〈働く〉は店を目的語に取らないので、〈店を営んでいる〉が正しい。"}, {"text": "彼は受付の担当を働いている。", "explanation": "ここは〈担当する〉（任される）の意味。〈働く〉は担当を目的語に取らないので、〈受付を担当している〉が正しい。"}, {"text": "彼は取引先を働いて、契約を結んだ。", "explanation": "ここは〈働きかける〉（説得する）の意味。〈働く〉は相手を目的語に取らないので、〈取引先に働きかけて〉が正しい。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032573e2-d232-46e2-bb94-ebe49299e77f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35569, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "兄は毎朝、近くの工場で働くています。", "corrected_sentence": "兄は毎朝、近くの工場で働いています。", "error_description": "「〜ています」の前はて形の「働いて」。辞書形「働く」に「ている」をつけた「働くている」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "働いて", "is_correct": true, "explanation": "「働いています」の「働いて」（て形）。「〜ています」に続けて継続を表す。"}, {"text": "働く", "is_correct": false, "explanation": "辞書形は「働くています」となり、「ています」の前に置けない。"}, {"text": "働かない", "is_correct": false, "explanation": "否定形は「働かないています」となり、「ています」に続かない。"}, {"text": "働けば", "is_correct": false, "explanation": "仮定形は「働けばいます」となり、文として成り立たない。"}], "correct_form": "働いて", "base_form": "働く", "form_label": "て形", "sentence_index": 1, "explanations": {"働いて": "「働いています」の「働いて」（て形）。「〜ています」に続けて継続を表す。", "働く": "辞書形は「働くています」となり、「ています」の前に置けない。", "働かない": "否定形は「働かないています」となり、「ています」に続かない。", "働けば": "仮定形は「働けばいます」となり、文として成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032573e2-d232-46e2-bb94-ebe49299e77f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35569, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "姉は朝から晩まで病院に働いている。", "corrected_sentence": "姉は朝から晩まで病院で働いている。", "error_description": "働く場所を示すのは「で」。「病院に働いている」の「に」は誤りで、「病院で働く」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "働いて", "is_correct": true, "explanation": "「働いても」の「働いて」（て形）。「〜ても」に続けて逆接を表す。"}, {"text": "働き", "is_correct": false, "explanation": "連用形は「働きても」となり、「ても」に続かない。"}, {"text": "働け", "is_correct": false, "explanation": "命令・仮定の形で、「働けても」は文法的に成立しない。"}, {"text": "働いた", "is_correct": false, "explanation": "過去形は「働いたても」となり、「ても」に続かない。"}], "correct_form": "働いて", "base_form": "働く", "form_label": "て形", "sentence_index": 7, "explanations": {"働いて": "「働いても」の「働いて」（て形）。「〜ても」に続けて逆接を表す。", "働き": "連用形は「働きても」となり、「ても」に続かない。", "働け": "命令・仮定の形で、「働けても」は文法的に成立しない。", "働いた": "過去形は「働いたても」となり、「ても」に続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032573e2-d232-46e2-bb94-ebe49299e77f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35572, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「各国の旗」の「の」は、旗が各国に属することを示すので合う。"}, {"text": "が", "is_correct": false, "explanation": "「各国が旗が」は主語が二つになり、不自然。"}, {"text": "を", "is_correct": false, "explanation": "「各国を旗が」は目的語の関係が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「各国へ旗が並んでいます」は方向を表すが、並ぶ先として不自然。"}], "correct_answer": "の", "explanations": {"の": "「各国の旗」の「の」は、旗が各国に属することを示すので合う。", "が": "「各国が旗が」は主語が二つになり、不自然。", "を": "「各国を旗が」は目的語の関係が成り立たない。", "へ": "「各国へ旗が並んでいます」は方向を表すが、並ぶ先として不自然。"}, "error_tags": {"が": "主語", "を": "対象", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e7f3f6-6c39-43b2-adbf-bdba1f8fbe51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35572, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「各国の選手」の「の」は、選手が各国に属することを示すので合う。"}, {"text": "に", "is_correct": false, "explanation": "「各国に選手が力を出し合う」は相手や位置を表し、相互の関係が合わない。"}, {"text": "より", "is_correct": false, "explanation": "「各国より選手が」は比較の意味になり、文が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「各国を選手が」は目的語が重なり、文が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「各国の選手」の「の」は、選手が各国に属することを示すので合う。", "に": "「各国に選手が力を出し合う」は相手や位置を表し、相互の関係が合わない。", "より": "「各国より選手が」は比較の意味になり、文が成り立たない。", "を": "「各国を選手が」は目的語が重なり、文が成り立たない。"}, "error_tags": {"に": "相手・位置", "より": "比較", "を": "目的語の重複"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e7f3f6-6c39-43b2-adbf-bdba1f8fbe51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35572, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "たくさんの国々のこと。", "primary_collocate": null, "pronunciation": "かっこく", "ipa": "kakkokɯ", "syllable_count": 4, "sentences": [{"text": "世界の各国から、たくさんの学生が日本に来ています。", "target_word": "各国", "complexity_tier": "T3", "furigana": "世界[せかい]の各国[かっこく]から、たくさんの学生[がくせい]が日本[にほん]に来[き]ています。", "sentence_source": "generated"}, {"text": "各国の旗が、広場にずらりと並んでいます。", "target_word": "各国", "complexity_tier": "T3", "furigana": "各国[かっこく]の旗[はた]が、広場[ひろば]にずらりと並[なら]んでいます。", "sentence_source": "generated"}, {"text": "会議には、各国の代表が集まりました。", "target_word": "各国", "complexity_tier": "T3", "furigana": "会議[かいぎ]には、各国[かっこく]の代表[だいひょう]が集[あつ]まりました。", "sentence_source": "generated"}, {"text": "各国で人気のある料理を、先生が教えてくれました。", "target_word": "各国", "complexity_tier": "T3", "furigana": "各国[かっこく]で人気[にんき]のある料理[りょうり]を、先生[せんせい]が教[おし]えてくれました。", "sentence_source": "generated"}, {"text": "この映画は各国で見られているので、有名です。", "target_word": "各国", "complexity_tier": "T3", "furigana": "この映画[えいが]は各国[かっこく]で見[み]られているので、有名[ゆうめい]です。", "sentence_source": "generated"}, {"text": "各国の天気を、毎朝ニュースで調べます。", "target_word": "各国", "complexity_tier": "T3", "furigana": "各国[かっこく]の天気[てんき]を、毎朝[まいあさ]ニュースで調[しら]べます。", "sentence_source": "generated"}, {"text": "各国から手紙が届いて、うれしかったです。", "target_word": "各国", "complexity_tier": "T3", "furigana": "各国[かっこく]から手紙[てがみ]が届[とど]いて、うれしかったです。", "sentence_source": "generated"}, {"text": "オリンピックでは、各国の選手が力を出し合います。", "target_word": "各国", "complexity_tier": "T3", "furigana": "オリンピックでは、各国[かっこく]の選手[せんしゅ]が力[ちから]を出[だ]し合[あ]います。", "sentence_source": "generated"}, {"text": "いつか各国を回る旅に出たいので、お金をためています。", "target_word": "各国", "complexity_tier": "T3", "furigana": "いつか各国[かっこく]を回[まわ]る旅[たび]に出[で]たいので、お金[かね]をためています。", "sentence_source": "generated"}, {"text": "地図を見ながら、各国の名前を覚えました。", "target_word": "各国", "complexity_tier": "T3", "furigana": "地図[ちず]を見[み]ながら、各国[かっこく]の名前[なまえ]を覚[おぼ]えました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "各国", "label": "基本形"}], "register": "標準（丁寧体）", "sense_fingerprint": "世界のたくさんの国々をまとめて指す言い方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88ab33ea-5a2d-4337-99fd-ffa844ac1d2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35572, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "各国", "is_correct": true, "explanation": "「世界の各国」はたくさんの国々を指し、学生が来ている文脈に合う。"}, {"text": "漬物", "is_correct": false, "explanation": "「世界の漬物から学生が来ています」は意味が通らない。"}, {"text": "雨雲", "is_correct": false, "explanation": "「世界の雨雲から学生が来ています」は意味が通らない。"}, {"text": "寝息", "is_correct": false, "explanation": "「世界の寝息から学生が来ています」は意味が通らず、国々を表さない。"}], "explanations": {"各国": "「世界の各国」はたくさんの国々を指し、学生が来ている文脈に合う。", "漬物": "「世界の漬物から学生が来ています」は意味が通らない。", "雨雲": "「世界の雨雲から学生が来ています」は意味が通らない。", "寝息": "「世界の寝息から学生が来ています」は意味が通らず、国々を表さない。"}, "sentence_index": 0, "correct_answer": "各国"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "日本の各国では、雪がたくさん降ります。", "explanation": "ここは〈各地〉の意味。日本の中の地方は国ではないので、各国とは言わない。"}, {"text": "私の各国は、日本です。", "explanation": "ここは〈自国〉の意味。一つの国を指すので、複数の国々を表す各国は合わない。"}, {"text": "各国、机を片付けてください。", "explanation": "ここは〈各自〉の意味。一人ひとりに指示する場面で、国々を指す各国は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e7f3f6-6c39-43b2-adbf-bdba1f8fbe51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35572, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "各国", "is_correct": true, "explanation": "「各国から手紙が届いた」は、いろいろな国からの便りという文脈に合う。"}, {"text": "落ち葉", "is_correct": false, "explanation": "「落ち葉から手紙が届いて」は意味が通らない。"}, {"text": "星空", "is_correct": false, "explanation": "「星空から手紙が届いて」は意味が通らず、差出人にならない。"}, {"text": "寝言", "is_correct": false, "explanation": "「寝言から手紙が届いて」は意味が通らず、文脈とも合わない。"}], "explanations": {"各国": "「各国から手紙が届いた」は、いろいろな国からの便りという文脈に合う。", "落ち葉": "「落ち葉から手紙が届いて」は意味が通らない。", "星空": "「星空から手紙が届いて」は意味が通らず、差出人にならない。", "寝言": "「寝言から手紙が届いて」は意味が通らず、文脈とも合わない。"}, "sentence_index": 6, "correct_answer": "各国"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "クラスの各国が手をあげました。", "explanation": "ここは〈全員〉の意味。一人ひとりを指すので、国々を表す各国は合わない。"}, {"text": "公園で各国がたくさん遊んでいます。", "explanation": "ここは〈子ども〉の意味。遊ぶ主体は子どもで、国々は遊ばないので使わない。"}, {"text": "家の各国を、毎朝そうじしています。", "explanation": "ここは〈部屋〉の意味。各国は国々を指すので、家の中の部屋を表すのには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e7f3f6-6c39-43b2-adbf-bdba1f8fbe51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35572, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "各国を首都を、地図で探しました。", "corrected_sentence": "各国の首都を、地図で探しました。", "error_description": "「各国の首都」の「の」が「を」になっている。名詞を修飾するには「の」が必要。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e7f3f6-6c39-43b2-adbf-bdba1f8fbe51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35572, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夏休みに、各国を食べました。", "corrected_sentence": "夏休みに、各国を回りました。", "error_description": "「各国を回る」の動詞が誤り。国には「回る・訪れる」が合い、「食べる」は合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e7f3f6-6c39-43b2-adbf-bdba1f8fbe51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35573, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「各国の言葉」の「の」は、言葉が各国に属することを示すので合う。"}, {"text": "が", "is_correct": false, "explanation": "「各国が言葉は」は主語が重なり、不自然。"}, {"text": "を", "is_correct": false, "explanation": "「各国を言葉は」は目的語の関係が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「各国へ言葉は」は方向を表すが、言葉の所属を示せない。"}], "correct_answer": "の", "explanations": {"の": "「各国の言葉」の「の」は、言葉が各国に属することを示すので合う。", "が": "「各国が言葉は」は主語が重なり、不自然。", "を": "「各国を言葉は」は目的語の関係が成り立たない。", "へ": "「各国へ言葉は」は方向を表すが、言葉の所属を示せない。"}, "error_tags": {"が": "主語", "を": "対象", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e7f3f6-6c39-43b2-adbf-bdba1f8fbe51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35573, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「各国の祝日」の「の」は、祝日が各国に属することを示すので合う。"}, {"text": "を", "is_correct": false, "explanation": "「各国を祝日は」は目的語が重なり、文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「各国より祝日はちがうので」は比較の意味になり、違いの主語にならない。"}, {"text": "から", "is_correct": false, "explanation": "「各国から祝日はちがうので」は起点を表し、祝日の違いの説明にならない。"}], "correct_answer": "の", "explanations": {"の": "「各国の祝日」の「の」は、祝日が各国に属することを示すので合う。", "を": "「各国を祝日は」は目的語が重なり、文が成り立たない。", "より": "「各国より祝日はちがうので」は比較の意味になり、違いの主語にならない。", "から": "「各国から祝日はちがうので」は起点を表し、祝日の違いの説明にならない。"}, "error_tags": {"を": "目的語の重複", "より": "比較", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e7f3f6-6c39-43b2-adbf-bdba1f8fbe51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35573, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "それぞれの国。いくつもの国。", "primary_collocate": null, "pronunciation": "かっこく", "ipa": "kakkokɯ", "syllable_count": 4, "sentences": [{"text": "各国には、その国だけの祭りがあります。", "target_word": "各国", "complexity_tier": "T3", "furigana": "各国[かっこく]には、その国[くに]だけの祭[まつ]りがあります。", "sentence_source": "generated"}, {"text": "各国の言葉は、それぞれ音もつづりもちがいます。", "target_word": "各国", "complexity_tier": "T3", "furigana": "各国[かっこく]の言葉[ことば]は、それぞれ音[おと]もつづりもちがいます。", "sentence_source": "generated"}, {"text": "各国が自分の国の文化を守ろうとしています。", "target_word": "各国", "complexity_tier": "T3", "furigana": "各国[かっこく]が自分[じぶん]の国[くに]の文化[ぶんか]を守[まも]ろうとしています。", "sentence_source": "generated"}, {"text": "各国の首都の名前を、順番に言ってみましょう。", "target_word": "各国", "complexity_tier": "T3", "furigana": "各国[かっこく]の首都[しゅと]の名前[なまえ]を、順番[じゅんばん]に言[い]ってみましょう。", "sentence_source": "generated"}, {"text": "各国は、自分の国のお金を使っています。", "target_word": "各国", "complexity_tier": "T3", "furigana": "各国[かっこく]は、自分[じぶん]の国[くに]のお金[かね]を使[つか]っています。", "sentence_source": "generated"}, {"text": "各国の先生が、自分の国の歌を紹介しました。", "target_word": "各国", "complexity_tier": "T3", "furigana": "各国[かっこく]の先生[せんせい]が、自分[じぶん]の国[くに]の歌[うた]を紹介[しょうかい]しました。", "sentence_source": "generated"}, {"text": "入国の決まりは各国でちがうので、旅行の前に調べます。", "target_word": "各国", "complexity_tier": "T3", "furigana": "入国[にゅうこく]の決[き]まりは各国[かっこく]でちがうので、旅行[りょこう]の前[まえ]に調[しら]べます。", "sentence_source": "generated"}, {"text": "各国の祝日はちがうので、カレンダーを見くらべました。", "target_word": "各国", "complexity_tier": "T3", "furigana": "各国[かっこく]の祝日[しゅくじつ]はちがうので、カレンダーを見[み]くらべました。", "sentence_source": "generated"}, {"text": "各国が決めた法律は、その国の中で守られます。", "target_word": "各国", "complexity_tier": "T3", "furigana": "各国[かっこく]が決[き]めた法律[ほうりつ]は、その国[くに]の中[なか]で守[まも]られます。", "sentence_source": "generated"}, {"text": "各国が出した意見を、先生が黒板にまとめました。", "target_word": "各国", "complexity_tier": "T3", "furigana": "各国[かっこく]が出[だ]した意見[いけん]を、先生[せんせい]が黒板[こくばん]にまとめました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "各国", "label": "基本形"}], "register": "標準（丁寧体）", "sense_fingerprint": "一つ一つの国がそれぞれ持つ違いに注目した言い方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88ab33ea-5a2d-4337-99fd-ffa844ac1d2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35573, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "各国", "is_correct": true, "explanation": "「各国には」は、それぞれの国ごとに祭りがあるという文脈に合う。"}, {"text": "寝相", "is_correct": false, "explanation": "「寝相には、その国だけの祭りがあります」は意味が通らない。"}, {"text": "漬物", "is_correct": false, "explanation": "「漬物には、その国だけの祭りがあります」は意味が通らない。"}, {"text": "雨雲", "is_correct": false, "explanation": "「雨雲には、その国だけの祭りがあります」は意味が通らない。"}], "explanations": {"各国": "「各国には」は、それぞれの国ごとに祭りがあるという文脈に合う。", "寝相": "「寝相には、その国だけの祭りがあります」は意味が通らない。", "漬物": "「漬物には、その国だけの祭りがあります」は意味が通らない。", "雨雲": "「雨雲には、その国だけの祭りがあります」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "各国"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "日本の各国には、古い神社がたくさんあります。", "explanation": "ここは〈各地〉の意味。日本の中の地方は国ではないので、それぞれの国を表す各国とは言わない。"}, {"text": "私の各国は、とても小さな島です。", "explanation": "ここは〈故郷〉の意味。自分の出身地を指す場面で、各国は使わない。"}, {"text": "各国、お弁当を持ってきてください。", "explanation": "ここは〈各自〉の意味。一人ひとりへの指示なので、国々を指す各国は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e7f3f6-6c39-43b2-adbf-bdba1f8fbe51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35573, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "各国", "is_correct": true, "explanation": "「各国でちがう」は、国ごとに決まりが違うという文脈に合う。"}, {"text": "落ち葉", "is_correct": false, "explanation": "「落ち葉でちがうので」は意味が通らない。"}, {"text": "星空", "is_correct": false, "explanation": "「星空でちがうので」は意味が通らず、決まりの違いを表せない。"}, {"text": "寝言", "is_correct": false, "explanation": "「寝言でちがうので」は意味が通らず、入国の決まりとは関係がない。"}], "explanations": {"各国": "「各国でちがう」は、国ごとに決まりが違うという文脈に合う。", "落ち葉": "「落ち葉でちがうので」は意味が通らない。", "星空": "「星空でちがうので」は意味が通らず、決まりの違いを表せない。", "寝言": "「寝言でちがうので」は意味が通らず、入国の決まりとは関係がない。"}, "sentence_index": 6, "correct_answer": "各国"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "駅前の各国で、新しいケーキを売っています。", "explanation": "ここは〈店〉の意味。各国は国々を指す語で、店や売り場を表すのには使わない。"}, {"text": "妹は、毎晩おふろで各国を口ずさんでいます。", "explanation": "ここは〈鼻歌〉の意味。各国は国々を指す語で、歌を口ずさむ行為には使わない。"}, {"text": "私の各国には、古い庭があります。", "explanation": "ここは〈家〉の意味。一つの家を指す場面で、複数の国を表す各国は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e7f3f6-6c39-43b2-adbf-bdba1f8fbe51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35573, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "各国を決まりを、ノートにまとめました。", "corrected_sentence": "各国の決まりを、ノートにまとめました。", "error_description": "「各国の決まり」の「の」が「を」になっている。名詞を修飾するには「の」が必要。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e7f3f6-6c39-43b2-adbf-bdba1f8fbe51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35573, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "旅行で各国を食べました。", "corrected_sentence": "旅行で各国を訪れました。", "error_description": "「各国を訪れる」の動詞が誤り。国には「訪れる・回る」が合い、「食べる」は合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22e7f3f6-6c39-43b2-adbf-bdba1f8fbe51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35574, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "場所を示す「で」。「カフェでコーヒーを飲んで待った」の場所を表す。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示す。「カフェをコーヒーを飲んで」は目的語が二つ重なり不自然になる。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「カフェへコーヒーを飲んで待った」は場所の意味に合わない。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すので、「カフェがコーヒーを飲んで」では主語が合わない。"}], "correct_answer": "で", "explanations": {"で": "場所を示す「で」。「カフェでコーヒーを飲んで待った」の場所を表す。", "を": "「を」は目的語を示す。「カフェをコーヒーを飲んで」は目的語が二つ重なり不自然になる。", "へ": "「へ」は方向を示すので、「カフェへコーヒーを飲んで待った」は場所の意味に合わない。", "が": "「が」は主語を示すので、「カフェがコーヒーを飲んで」では主語が合わない。"}, "error_tags": {"を": "目的語", "へ": "方向", "が": "主語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66c5ca52-51a7-48b2-bf58-49b55ba482b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35574, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「入る」の到達点を示す「に」。「カフェに入り」の形になる。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示すので、「カフェで入り」は入る先を示せない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は所属や修飾を示すので、「カフェの入り」は文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すので、「カフェより入り」は入る先の意味に合わない。"}], "correct_answer": "に", "explanations": {"に": "「入る」の到達点を示す「に」。「カフェに入り」の形になる。", "で": "「で」は場所や手段を示すので、「カフェで入り」は入る先を示せない。", "の": "「の」は所属や修飾を示すので、「カフェの入り」は文が成り立たない。", "より": "「より」は比較を示すので、「カフェより入り」は入る先の意味に合わない。"}, "error_tags": {"で": "場所・手段", "の": "所属・修飾", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66c5ca52-51a7-48b2-bf58-49b55ba482b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35574, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "コーヒーやケーキなどを食べたり飲んだりするお店です。", "primary_collocate": null, "pronunciation": "かふぇ", "ipa": "kaɸe", "syllable_count": 2, "sentences": [{"text": "駅の近くのカフェで、友達とケーキを食べた。", "target_word": "カフェ", "complexity_tier": "T3", "furigana": "駅[えき]の近[ちか]くのカフェで、友達[ともだち]とケーキを食[た]べた。", "sentence_source": "generated"}, {"text": "雨がやむまで、カフェでコーヒーを飲んで待った。", "target_word": "カフェ", "complexity_tier": "T3", "furigana": "雨[あめ]がやむまで、カフェでコーヒーを飲[の]んで待[ま]った。", "sentence_source": "generated"}, {"text": "このカフェは窓が大きくて、外の景色がよく見える。", "target_word": "カフェ", "complexity_tier": "T3", "furigana": "このカフェは窓[まど]が大[おお]きくて、外[そと]の景色[けしき]がよく見[み]える。", "sentence_source": "generated"}, {"text": "姉は毎週日曜日にカフェへ行って、本を読む。", "target_word": "カフェ", "complexity_tier": "T3", "furigana": "姉[あね]は毎週[まいしゅう]日曜日[にちようび]にカフェへ行[い]って、本[ほん]を読[よ]む。", "sentence_source": "generated"}, {"text": "カフェでアルバイトを始めてから、コーヒーに詳しくなった。", "target_word": "カフェ", "complexity_tier": "T3", "furigana": "カフェでアルバイトを始[はじ]めてから、コーヒーに詳[くわ]しくなった。", "sentence_source": "generated"}, {"text": "新しいカフェができたので、放課後に行ってみた。", "target_word": "カフェ", "complexity_tier": "T3", "furigana": "新[あたら]しいカフェができたので、放課後[ほうかご]に行[い]ってみた。", "sentence_source": "generated"}, {"text": "あのカフェは人気があるので、昼はいつも混んでいる。", "target_word": "カフェ", "complexity_tier": "T3", "furigana": "あのカフェは人気[にんき]があるので、昼[ひる]はいつも混[こ]んでいる。", "sentence_source": "generated"}, {"text": "祖母と一緒にカフェに入り、あたたかい紅茶を注文した。", "target_word": "カフェ", "complexity_tier": "T3", "furigana": "祖母[そぼ]と一緒[いっしょ]にカフェに入[はい]り、あたたかい紅茶[こうちゃ]を注文[ちゅうもん]した。", "sentence_source": "generated"}, {"text": "公園の隣のカフェは、犬を連れて入ることができる。", "target_word": "カフェ", "complexity_tier": "T3", "furigana": "公園[こうえん]の隣[となり]のカフェは、犬[いぬ]を連[つ]れて入[はい]ることができる。", "sentence_source": "generated"}, {"text": "勉強に疲れたので、近くのカフェで少し休んだ。", "target_word": "カフェ", "complexity_tier": "T3", "furigana": "勉強[べんきょう]に疲[つか]れたので、近[ちか]くのカフェで少[すこ]し休[やす]んだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "カフェ", "label": "基本形"}, {"form": "カフェで", "label": "場所格"}, {"form": "カフェに", "label": "位格"}], "register": "plain", "sense_fingerprint": "コーヒーやケーキを楽しみながらくつろぐための小さなお店", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f59eed6c-7780-4a68-92fd-f9cceeb3a107') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35574, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "カフェ", "is_correct": true, "explanation": "飲み物や軽食を楽しむ店で、友達とケーキを食べる文に合う。"}, {"text": "図書館", "is_correct": false, "explanation": "本を借りたり読んだりする施設で、ケーキを食べる場所としては合わない。"}, {"text": "郵便局", "is_correct": false, "explanation": "手紙や荷物を扱う施設で、ケーキを食べる場所ではない。"}, {"text": "薬局", "is_correct": false, "explanation": "薬を受け取る店で、ケーキを食べる場所ではない。"}], "explanations": {"カフェ": "飲み物や軽食を楽しむ店で、友達とケーキを食べる文に合う。", "図書館": "本を借りたり読んだりする施設で、ケーキを食べる場所としては合わない。", "郵便局": "手紙や荷物を扱う施設で、ケーキを食べる場所ではない。", "薬局": "薬を受け取る店で、ケーキを食べる場所ではない。"}, "sentence_index": 0, "correct_answer": "カフェ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "カフェで搭乗手続きをして、荷物を預けた。", "explanation": "ここは〈空港〉の意味。カフェでは搭乗手続きはできないので、この文には合わない。"}, {"text": "カフェで処方箋の薬を受け取った。", "explanation": "ここは〈薬局〉の意味。カフェは処方箋の薬を扱わないので、この文には合わない。"}, {"text": "カフェで住民票を取って、窓口で待った。", "explanation": "ここは〈役所〉の意味。カフェでは住民票は発行されないので、窓口の手続きの話とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66c5ca52-51a7-48b2-bf58-49b55ba482b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35574, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "カフェ", "is_correct": true, "explanation": "人気があって昼は混む店の文に合う。店を指す「カフェ」が入る。"}, {"text": "教科書", "is_correct": false, "explanation": "教科書は人気があって昼に混む、という文には合わない。"}, {"text": "鉛筆", "is_correct": false, "explanation": "鉛筆は人気があって昼に混む、という文には合わない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "冷蔵庫は人気があって昼に混む、という文には合わない。"}], "explanations": {"カフェ": "人気があって昼は混む店の文に合う。店を指す「カフェ」が入る。", "教科書": "教科書は人気があって昼に混む、という文には合わない。", "鉛筆": "鉛筆は人気があって昼に混む、という文には合わない。", "冷蔵庫": "冷蔵庫は人気があって昼に混む、という文には合わない。"}, "sentence_index": 6, "correct_answer": "カフェ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "カフェで髪を切ってもらった。", "explanation": "ここは〈美容院〉の意味。カフェでは髪を切らないので、施術の場所としては合わない。"}, {"text": "カフェで口座を作った。", "explanation": "ここは〈銀行〉の意味。カフェは口座を作る場所ではないので合わない。"}, {"text": "カフェで部品を組み立てた。", "explanation": "ここは〈工場〉の意味。カフェは部品を組み立てる場所ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66c5ca52-51a7-48b2-bf58-49b55ba482b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35574, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "週末は、カフェを友人と話すのが楽しい。", "corrected_sentence": "週末は、カフェで友人と話すのが楽しい。", "error_description": "「話す」の場所を示す「で」を「を」にしたのが誤り。場所は「で」で示すので、正しくは「カフェで友人と話す」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66c5ca52-51a7-48b2-bf58-49b55ba482b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35574, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "午後は、カフェをコーヒーを飲んで過ごした。", "corrected_sentence": "午後は、カフェでコーヒーを飲んで過ごした。", "error_description": "場所を示す「で」を「を」にしたのが誤り。「カフェでコーヒーを飲む」のように、場所は「で」で示す。「を」が二つ重なって不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66c5ca52-51a7-48b2-bf58-49b55ba482b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35575, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "話題の主題を示す「は」。「このカフェは朝七時から開いている」の意味になる。"}, {"text": "に", "is_correct": false, "explanation": "「に」は時点や相手を示すので、「このカフェに朝七時から開いていて」は成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示すので、「このカフェで朝七時から開いていて」は文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は相手や並列を示すので、「このカフェと朝七時から開いていて」は成り立たない。"}], "correct_answer": "は", "explanations": {"は": "話題の主題を示す「は」。「このカフェは朝七時から開いている」の意味になる。", "に": "「に」は時点や相手を示すので、「このカフェに朝七時から開いていて」は成り立たない。", "で": "「で」は場所や手段を示すので、「このカフェで朝七時から開いていて」は文が成り立たない。", "と": "「と」は相手や並列を示すので、「このカフェと朝七時から開いていて」は成り立たない。"}, "error_tags": {"に": "位置・時点", "で": "場所・手段", "と": "相手・並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66c5ca52-51a7-48b2-bf58-49b55ba482b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35575, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「の」は所属を示す。「カフェのメニュー」の形になる。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すので、「カフェをメニューには」は成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「カフェへメニューには」は所属の意味に合わない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すので、「カフェよりメニューには」は成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「の」は所属を示す。「カフェのメニュー」の形になる。", "を": "「を」は目的語を示すので、「カフェをメニューには」は成り立たない。", "へ": "「へ」は方向を示すので、「カフェへメニューには」は所属の意味に合わない。", "より": "「より」は比較を示すので、「カフェよりメニューには」は成り立たない。"}, "error_tags": {"を": "目的語", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66c5ca52-51a7-48b2-bf58-49b55ba482b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35575, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "コーヒーなどの飲み物や軽い食べ物を提供する飲食店。", "primary_collocate": null, "pronunciation": "かふぇ", "ipa": "kaɸe", "syllable_count": 2, "sentences": [{"text": "会社の帰りに、静かなカフェでサンドイッチを食べた。", "target_word": "カフェ", "complexity_tier": "T3", "furigana": "会社[かいしゃ]の帰[かえ]りに、静[しず]かなカフェでサンドイッチを食[た]べた。", "sentence_source": "generated"}, {"text": "このカフェは朝七時から開いていて、出勤前に寄る人が多い。", "target_word": "カフェ", "complexity_tier": "T3", "furigana": "このカフェは朝[あさ]七時[しちじ]から開[ひら]いていて、出勤前[しゅっきんまえ]に寄[よ]る人[ひと]が多[おお]い。", "sentence_source": "generated"}, {"text": "駅前のカフェでは、軽い昼ごはんも出している。", "target_word": "カフェ", "complexity_tier": "T3", "furigana": "駅前[えきまえ]のカフェでは、軽[かる]い昼[ひる]ごはんも出[だ]している。", "sentence_source": "generated"}, {"text": "私は将来、小さなカフェを開いて自分のパンを売りたい。", "target_word": "カフェ", "complexity_tier": "T3", "furigana": "私[わたし]は将来[しょうらい]、小[ちい]さなカフェを開[ひら]いて自分[じぶん]のパンを売[う]りたい。", "sentence_source": "generated"}, {"text": "古い家を直して、おしゃれなカフェに変えた。", "target_word": "カフェ", "complexity_tier": "T3", "furigana": "古[ふる]い家[いえ]を直[なお]して、おしゃれなカフェに変[か]えた。", "sentence_source": "generated"}, {"text": "打ち合わせは、会社のそばのカフェですることになった。", "target_word": "カフェ", "complexity_tier": "T3", "furigana": "打[う]ち合[あ]わせは、会社[かいしゃ]のそばのカフェですることになった。", "sentence_source": "generated"}, {"text": "そのカフェはコーヒーが安いうえに、トーストもおいしい。", "target_word": "カフェ", "complexity_tier": "T3", "furigana": "そのカフェはコーヒーが安[やす]いうえに、トーストもおいしい。", "sentence_source": "generated"}, {"text": "カフェのメニューには、季節のジュースものっている。", "target_word": "カフェ", "complexity_tier": "T3", "furigana": "カフェのメニューには、季節[きせつ]のジュースものっている。", "sentence_source": "generated"}, {"text": "友人は本屋の中にあるカフェで働いている。", "target_word": "カフェ", "complexity_tier": "T3", "furigana": "友人[ゆうじん]は本屋[ほんや]の中[なか]にあるカフェで働[はたら]いている。", "sentence_source": "generated"}, {"text": "夜おそくまで開いているカフェを見つけて、仕事を続けた。", "target_word": "カフェ", "complexity_tier": "T3", "furigana": "夜[よる]おそくまで開[あ]いているカフェを見[み]つけて、仕事[しごと]を続[つづ]けた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "カフェ", "label": "基本形"}, {"form": "カフェの", "label": "連体修飾"}, {"form": "カフェを", "label": "対格"}], "register": "plain", "sense_fingerprint": "飲み物や軽食を出す飲食店で、営業や開店の対象となる店", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T2: contains vocabulary far above tier T2: おそく (Zipf 2.34)']::text[], 'f59eed6c-7780-4a68-92fd-f9cceeb3a107') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35575, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "カフェ", "is_correct": true, "explanation": "軽食や飲み物を出す店で、サンドイッチを食べる場所として合う。"}, {"text": "工場", "is_correct": false, "explanation": "製品を作る場所で、サンドイッチを食べる場所には合わない。"}, {"text": "病院", "is_correct": false, "explanation": "診察や治療をする場所で、食事をする店には合わない。"}, {"text": "美容院", "is_correct": false, "explanation": "髪を切る店で、サンドイッチを食べる場所ではない。"}], "explanations": {"カフェ": "軽食や飲み物を出す店で、サンドイッチを食べる場所として合う。", "工場": "製品を作る場所で、サンドイッチを食べる場所には合わない。", "病院": "診察や治療をする場所で、食事をする店には合わない。", "美容院": "髪を切る店で、サンドイッチを食べる場所ではない。"}, "sentence_index": 0, "correct_answer": "カフェ"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小さなカフェで、毎朝お経を唱えたい。", "explanation": "ここは〈寺〉の意味。カフェはお経を唱える場所ではないので、この文には合わない。"}, {"text": "小さなカフェで部品を組み立てたい。", "explanation": "ここは〈工場〉の意味。カフェは部品を組み立てる場所ではないので合わない。"}, {"text": "小さなカフェで患者を治療したい。", "explanation": "ここは〈病院〉の意味。カフェは患者を治療する施設ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66c5ca52-51a7-48b2-bf58-49b55ba482b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35575, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "カフェ", "is_correct": true, "explanation": "コーヒーが安く、トーストもおいしい店を指す。「そのカフェは」の形で文に合う。"}, {"text": "教科書", "is_correct": false, "explanation": "教科書はコーヒーが安いという話題には合わない。"}, {"text": "鉛筆", "is_correct": false, "explanation": "鉛筆はコーヒーが安いうえにトーストもおいしい、という文には合わない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "冷蔵庫はコーヒーが安い、という文には合わない。"}], "explanations": {"カフェ": "コーヒーが安く、トーストもおいしい店を指す。「そのカフェは」の形で文に合う。", "教科書": "教科書はコーヒーが安いという話題には合わない。", "鉛筆": "鉛筆はコーヒーが安いうえにトーストもおいしい、という文には合わない。", "冷蔵庫": "冷蔵庫はコーヒーが安い、という文には合わない。"}, "sentence_index": 6, "correct_answer": "カフェ"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "カフェの窓口で、お金を預けた。", "explanation": "ここは〈銀行〉の意味。カフェは預金を扱わないので、お金を預ける窓口とは合わない。"}, {"text": "カフェで、荷物を送る手続きをした。", "explanation": "ここは〈郵便局〉の意味。カフェは荷物の発送手続きをする場所ではないので合わない。"}, {"text": "カフェで、判決を聞いた。", "explanation": "ここは〈裁判所〉の意味。カフェは判決を言い渡す場所ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66c5ca52-51a7-48b2-bf58-49b55ba482b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35575, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜は、そのカフェを軽食を出している。", "corrected_sentence": "夜は、そのカフェで軽食を出している。", "error_description": "「出す」の場所を示す「で」を「を」にして、「を」が重なったのが誤り。正しくは「カフェで軽食を出す」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66c5ca52-51a7-48b2-bf58-49b55ba482b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35575, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜おそくまで開いているカフェを探さて、仕事を続けた。", "corrected_sentence": "夜おそくまで開いているカフェを探して、仕事を続けた。", "error_description": "「探す」の活用が誤り。「探さて」は続かないので、正しくは「探して」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66c5ca52-51a7-48b2-bf58-49b55ba482b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
