INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35576, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「家庭」が案内の受け手なので「に」。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は比べる対象がなく、意味が通らない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は出所を示すので、受け手の「家庭」には合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すので、案内を送る相手としては不自然。"}], "correct_answer": "に", "explanations": {"に": "「家庭」が案内の受け手なので「に」。", "より": "比較の「より」は比べる対象がなく、意味が通らない。", "から": "「から」は出所を示すので、受け手の「家庭」には合わない。", "と": "「と」は並列や相手を示すので、案内を送る相手としては不自然。"}, "error_tags": {"より": "比較の助詞", "から": "起点の格助詞", "と": "並列・相手の格助詞"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a24165d-25fb-4287-b029-d82fa4c8a110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35576, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "家族でくらすところ", "primary_collocate": null, "pronunciation": "かてい", "ipa": "kate̞i", "syllable_count": 3, "sentences": [{"text": "私の家庭は四人家族で、小さなマンションに住んでいます。", "target_word": "家庭", "complexity_tier": "T3", "furigana": "私[わたし]の家庭[かてい]は四人[よにん]家族[かぞく]で、小[ちい]さなマンションに住[す]んでいます。", "sentence_source": "generated"}, {"text": "この町には、子どもがいる家庭が多いです。", "target_word": "家庭", "complexity_tier": "T3", "furigana": "この町[まち]には、子[こ]どもがいる家庭[かてい]が多[おお]いです。", "sentence_source": "generated"}, {"text": "先生は、生徒の家庭を一軒ずつ訪ねました。", "target_word": "家庭", "complexity_tier": "T3", "furigana": "先生[せんせい]は、生徒[せいと]の家庭[かてい]を一軒[いっけん]ずつ訪[たず]ねました。", "sentence_source": "generated"}, {"text": "家庭にパソコンがない子どもには、学校が貸し出します。", "target_word": "家庭", "complexity_tier": "T3", "furigana": "家庭[かてい]にパソコンがない子[こ]どもには、学校[がっこう]が貸[か]し出[だ]します。", "sentence_source": "generated"}, {"text": "新しい家庭を作るために、二人は広い家を探しています。", "target_word": "家庭", "complexity_tier": "T3", "furigana": "新[あたら]しい家庭[かてい]を作[つく]るために、二人[ふたり]は広[ひろ]い家[いえ]を探[さが]しています。", "sentence_source": "generated"}, {"text": "どの家庭でも、毎月ごみの日を守る必要があります。", "target_word": "家庭", "complexity_tier": "T3", "furigana": "どの家庭[かてい]でも、毎月[まいつき]ごみの日[ひ]を守[まも]る必要[ひつよう]があります。", "sentence_source": "generated"}, {"text": "電気代が上がって、多くの家庭が困っています。", "target_word": "家庭", "complexity_tier": "T3", "furigana": "電気代[でんきだい]が上[あ]がって、多[おお]くの家庭[かてい]が困[こま]っています。", "sentence_source": "generated"}, {"text": "市は、すべての家庭に防災の案内を送りました。", "target_word": "家庭", "complexity_tier": "T3", "furigana": "市[し]は、すべての家庭[かてい]に防災[ぼうさい]の案内[あんない]を送[おく]りました。", "sentence_source": "generated"}, {"text": "兄は結婚して、自分の家庭を持ちました。", "target_word": "家庭", "complexity_tier": "T3", "furigana": "兄[あに]は結婚[けっこん]して、自分[じぶん]の家庭[かてい]を持[も]ちました。", "sentence_source": "generated"}, {"text": "共働きの家庭が増えたので、夜まで開く保育園が必要です。", "target_word": "家庭", "complexity_tier": "T3", "furigana": "共働[ともばたら]きの家庭[かてい]が増[ふ]えたので、夜[よる]まで開[あ]く保育園[ほいくえん]が必要[ひつよう]です。", "sentence_source": "generated"}], "morphological_forms": [{"form": "家庭", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "家族が一緒に住む場所・世帯としての家庭", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e74715c8-80af-41e0-bc9c-e29c3da457dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35576, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "家庭", "is_correct": true, "explanation": "ここは家族が暮らす場所（家庭）を指す。「四人家族で、マンションに住む」に合う。"}, {"text": "会社", "is_correct": false, "explanation": "会社は働く場所で、家族が住むところではないので合わない。"}, {"text": "学校", "is_correct": false, "explanation": "学校は子どもが通う場所で、家族が暮らす住まいにはならないので合わない。"}, {"text": "病院", "is_correct": false, "explanation": "病院は治療を受ける場所で、家族が住む場所としては合わない。"}], "explanations": {"家庭": "ここは家族が暮らす場所（家庭）を指す。「四人家族で、マンションに住む」に合う。", "会社": "会社は働く場所で、家族が住むところではないので合わない。", "学校": "学校は子どもが通う場所で、家族が暮らす住まいにはならないので合わない。", "病院": "病院は治療を受ける場所で、家族が住む場所としては合わない。"}, "sentence_index": 0, "correct_answer": "家庭"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "祖父は若いころ、自分で家庭を建てた。", "explanation": "ここは〈家〉（建物）の意味。家庭は建物ではないので「建てる」とは言えない。「家庭を築く」なら自然。"}, {"text": "この地域は、家庭の価格が年々上がっている。", "explanation": "ここは〈住宅〉の意味。家庭は人の暮らしを指し、売買される物件ではないので値段とは合わない。"}, {"text": "子どもが生まれて、家庭が一人増えた。", "explanation": "ここは〈家族〉（人の数）の意味。家庭は人数を数える単位ではないので「一人増える」とは言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a24165d-25fb-4287-b029-d82fa4c8a110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35576, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "家庭", "is_correct": true, "explanation": "ここは家族が暮らす場所の意味。電気代の値上がりで困る家庭として合う。"}, {"text": "窓", "is_correct": false, "explanation": "窓は建具で、値上がりで困る主体にはならないので合わない。"}, {"text": "辞書", "is_correct": false, "explanation": "辞書は本で、電気代が上がって困る主体としては成り立たない。"}, {"text": "電池", "is_correct": false, "explanation": "電池は物で、電気代の値上がりで困る主体にはならないので合わない。"}], "explanations": {"家庭": "ここは家族が暮らす場所の意味。電気代の値上がりで困る家庭として合う。", "窓": "窓は建具で、値上がりで困る主体にはならないので合わない。", "辞書": "辞書は本で、電気代が上がって困る主体としては成り立たない。", "電池": "電池は物で、電気代の値上がりで困る主体にはならないので合わない。"}, "sentence_index": 6, "correct_answer": "家庭"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会社の書類には、本人の家庭を記入する欄がある。", "explanation": "ここは〈住所〉の意味。住所は書類に記入するものだが、家庭は記入する対象にはならないので合わない。"}, {"text": "彼は駅の近くに家庭を借りた。", "explanation": "ここは〈住居〉の意味。家庭は借りる物件ではなく暮らしを指すので、「借りる」とは言えない。"}, {"text": "母は三人の家庭を連れて、海へ遊びに行った。", "explanation": "ここは〈家族〉（人の集まり）の意味。家庭は人ではなく暮らしを指すので、「連れて行く」とは言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a24165d-25fb-4287-b029-d82fa4c8a110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35576, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その地域には、子どもを持つ家庭を多いです。", "corrected_sentence": "その地域には、子どもを持つ家庭が多いです。", "error_description": "「多い」の主語は「が」で示す。「家庭を」は誤りで、正しくは「家庭が」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a24165d-25fb-4287-b029-d82fa4c8a110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35576, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼らは来年、新しい家庭を開く予定です。", "corrected_sentence": "彼らは来年、新しい家庭を築く予定です。", "error_description": "「家庭」と組む動詞は「築く」。「開く」は店や会など場所や催しに使うため誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a24165d-25fb-4287-b029-d82fa4c8a110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35577, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「家庭」と「問題」をつなぐ所属の「の」。「家庭の問題」になる。"}, {"text": "を", "is_correct": false, "explanation": "「問題を」が既に目的語なので、「家庭を問題を」は重なって不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「家庭へ問題」は意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は比べる対象がなく、「家庭より問題を」は不自然。"}], "correct_answer": "の", "explanations": {"の": "「家庭」と「問題」をつなぐ所属の「の」。「家庭の問題」になる。", "を": "「問題を」が既に目的語なので、「家庭を問題を」は重なって不自然。", "へ": "「へ」は方向を示すので、「家庭へ問題」は意味が通らない。", "より": "比較の「より」は比べる対象がなく、「家庭より問題を」は不自然。"}, "error_tags": {"を": "目的語の格助詞", "へ": "方向の格助詞", "より": "比較の助詞"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a24165d-25fb-4287-b029-d82fa4c8a110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35577, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「家庭」と「中」をつなぐ所在の「の」。「家庭の中」になる。"}, {"text": "が", "is_correct": false, "explanation": "「家庭が中で」は主語のように続かず、場所を示せない。"}, {"text": "に", "is_correct": false, "explanation": "「家庭に中で」は位置を示す助詞が重なり不自然。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すので、「家庭と中で」は意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「家庭」と「中」をつなぐ所在の「の」。「家庭の中」になる。", "が": "「家庭が中で」は主語のように続かず、場所を示せない。", "に": "「家庭に中で」は位置を示す助詞が重なり不自然。", "と": "「と」は並列や相手を示すので、「家庭と中で」は意味が通らない。"}, "error_tags": {"が": "主格の格助詞", "に": "位置・方向の格助詞", "と": "並列・相手の格助詞"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a24165d-25fb-4287-b029-d82fa4c8a110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35577, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "家族が一緒に生活する場。また、家族関係や生活。", "primary_collocate": null, "pronunciation": "かてい", "ipa": "kate̞i", "syllable_count": 3, "sentences": [{"text": "彼女は仕事も大切だが、家庭も大事にしている。", "target_word": "家庭", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は仕事[しごと]も大切[たいせつ]だが、家庭[かてい]も大事[だいじ]にしている。", "sentence_source": "generated"}, {"text": "家庭の問題を、会社に持ちこまないようにしています。", "target_word": "家庭", "complexity_tier": "T3", "furigana": "家庭[かてい]の問題[もんだい]を、会社[かいしゃ]に持[も]ちこまないようにしています。", "sentence_source": "generated"}, {"text": "温かい家庭で育ったので、私は人に優しくなれました。", "target_word": "家庭", "complexity_tier": "T3", "furigana": "温[あたた]かい家庭[かてい]で育[そだ]ったので、私[わたし]は人[ひと]に優[やさ]しくなれました。", "sentence_source": "generated"}, {"text": "父は仕事ばかりで、家庭のことは母に任せていました。", "target_word": "家庭", "complexity_tier": "T3", "furigana": "父[ちち]は仕事[しごと]ばかりで、家庭[かてい]のことは母[はは]に任[まか]せていました。", "sentence_source": "generated"}, {"text": "家庭が円満だと、毎日の生活も楽しくなります。", "target_word": "家庭", "complexity_tier": "T3", "furigana": "家庭[かてい]が円満[えんまん]だと、毎日[まいにち]の生活[せいかつ]も楽[たの]しくなります。", "sentence_source": "generated"}, {"text": "忙しくても、週末は家庭で過ごす時間を作ります。", "target_word": "家庭", "complexity_tier": "T3", "furigana": "忙[いそが]しくても、週末[しゅうまつ]は家庭[かてい]で過[す]ごす時間[じかん]を作[つく]ります。", "sentence_source": "generated"}, {"text": "複雑な家庭に育った彼は、早く大人になった。", "target_word": "家庭", "complexity_tier": "T3", "furigana": "複雑[ふくざつ]な家庭[かてい]に育[そだ]った彼[かれ]は、早[はや]く大人[おとな]になった。", "sentence_source": "generated"}, {"text": "家庭の中で、お金の使い方をよく話し合います。", "target_word": "家庭", "complexity_tier": "T3", "furigana": "家庭[かてい]の中[なか]で、お金[かね]の使[つか]い方[かた]をよく話[はな]し合[あ]います。", "sentence_source": "generated"}, {"text": "仕事と家庭を両立するのは、簡単ではありません。", "target_word": "家庭", "complexity_tier": "T3", "furigana": "仕事[しごと]と家庭[かてい]を両立[りょうりつ]するのは、簡単[かんたん]ではありません。", "sentence_source": "generated"}, {"text": "彼の家庭は、いつも笑い声が絶えません。", "target_word": "家庭", "complexity_tier": "T3", "furigana": "彼[かれ]の家庭[かてい]は、いつも笑[わら]い声[ごえ]が絶[た]えません。", "sentence_source": "generated"}], "morphological_forms": [{"form": "家庭", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "家族関係や家族との暮らしとしての家庭", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T2: contains vocabulary far above tier T2: 持ちこま (Zipf 1.54)']::text[], 'e74715c8-80af-41e0-bc9c-e29c3da457dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35577, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "家庭", "is_correct": true, "explanation": "ここは家族関係や家庭生活の意味。「仕事も大切だが」と対になる。"}, {"text": "辞書", "is_correct": false, "explanation": "辞書は道具で、仕事と並べて大事にする対象にはならない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "冷蔵庫は家電で、仕事と並べて大事にするものとしては合わない。"}, {"text": "階段", "is_correct": false, "explanation": "階段は建物の一部で、仕事と対比して大事にする対象ではない。"}], "explanations": {"家庭": "ここは家族関係や家庭生活の意味。「仕事も大切だが」と対になる。", "辞書": "辞書は道具で、仕事と並べて大事にする対象にはならない。", "冷蔵庫": "冷蔵庫は家電で、仕事と並べて大事にするものとしては合わない。", "階段": "階段は建物の一部で、仕事と対比して大事にする対象ではない。"}, "sentence_index": 0, "correct_answer": "家庭"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は昨年、家庭を辞めて転職した。", "explanation": "ここは〈会社〉（勤め先）の意味。家庭は辞めて離れる職場ではないので、「辞めて転職」とは合わない。"}, {"text": "台風で家庭の屋根が飛ばされた。", "explanation": "ここは〈家〉（建物）の意味。家庭は屋根をもつ建物ではなく、暮らしや家族関係を指すので「屋根」とは合わない。"}, {"text": "父は古くなった家庭を売却して、引っ越した。", "explanation": "ここは〈住宅〉の意味。家庭は売買される物件ではなく、家族関係や暮らしを指すので「売却」とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a24165d-25fb-4287-b029-d82fa4c8a110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35577, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "家庭", "is_correct": true, "explanation": "ここは家族が生活する環境の意味。「複雑な家庭に育つ」に合う。"}, {"text": "電話", "is_correct": false, "explanation": "電話は道具で、人が育つ環境にはならないので合わない。"}, {"text": "黒板", "is_correct": false, "explanation": "黒板は教室の備品で、人が育つ環境の意味では使えない。"}, {"text": "植木", "is_correct": false, "explanation": "植木は植物で、人が育つ環境としては合わない。"}], "explanations": {"家庭": "ここは家族が生活する環境の意味。「複雑な家庭に育つ」に合う。", "電話": "電話は道具で、人が育つ環境にはならないので合わない。", "黒板": "黒板は教室の備品で、人が育つ環境の意味では使えない。", "植木": "植木は植物で、人が育つ環境としては合わない。"}, "sentence_index": 6, "correct_answer": "家庭"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会社の近くに家庭を借りて、一人で暮らしている。", "explanation": "ここは〈住居〉の意味。家庭は借りる物件ではなく暮らしを指すので、「借りる」とは言えない。"}, {"text": "駅前の広場で、家庭の帰りを待っていた。", "explanation": "ここは〈家族〉の意味。家庭は人ではなく暮らしを指すので、「帰りを待つ」対象にはならない。"}, {"text": "この会議室は、家庭として使うことにした。", "explanation": "ここは〈職場〉の意味。家庭は仕事をする場所ではないので、会議の場として使うとは言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a24165d-25fb-4287-b029-d82fa4c8a110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35577, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "彼は家庭に大事にして、毎日早く帰るようにしている。", "corrected_sentence": "彼は家庭を大事にして、毎日早く帰るようにしている。", "error_description": "「大事にする」の目的語は「を」で示す。「家庭に」は誤りで、正しくは「家庭を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a24165d-25fb-4287-b029-d82fa4c8a110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35577, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夫婦は、家庭を円満に測るために努力している。", "corrected_sentence": "夫婦は、家庭を円満に保つために努力している。", "error_description": "「家庭を円満に」と組む動詞は「保つ」。「測る」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a24165d-25fb-4287-b029-d82fa4c8a110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35578, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "暑い", "is_correct": true, "explanation": "気温が高いことを表し、「寒い（気温が低い）」の対義語。"}, {"text": "硬い", "is_correct": false, "explanation": "「柔らかい」が対義語。気温の高低とは関係がない。"}, {"text": "長い", "is_correct": false, "explanation": "「短い」が対義語。気温の高低とは関係がない。"}, {"text": "重い", "is_correct": false, "explanation": "「軽い」が対義語。気温の寒暖とは関係がない。"}], "correct_answer": "暑い", "explanations": {"暑い": "気温が高いことを表し、「寒い（気温が低い）」の対義語。", "硬い": "「柔らかい」が対義語。気温の高低とは関係がない。", "長い": "「短い」が対義語。気温の高低とは関係がない。", "重い": "「軽い」が対義語。気温の寒暖とは関係がない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a394539-7d4d-4f1a-822d-2e50512ec476') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35578, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "暑い", "is_correct": true, "explanation": "気温が高いことを表し、「寒い（気温が低い）」の対義語。"}, {"text": "遠い", "is_correct": false, "explanation": "「近い」が対義語。距離の話で、気温とは関係がない。"}, {"text": "狭い", "is_correct": false, "explanation": "「広い」が対義語。空間の広さの話で、気温とは関係がない。"}, {"text": "早い", "is_correct": false, "explanation": "「遅い」が対義語。時間の話で、気温とは関係がない。"}], "correct_answer": "暑い", "explanations": {"暑い": "気温が高いことを表し、「寒い（気温が低い）」の対義語。", "遠い": "「近い」が対義語。距離の話で、気温とは関係がない。", "狭い": "「広い」が対義語。空間の広さの話で、気温とは関係がない。", "早い": "「遅い」が対義語。時間の話で、気温とは関係がない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a394539-7d4d-4f1a-822d-2e50512ec476') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35578, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "きおんがひくいこと。", "primary_collocate": null, "pronunciation": "さむい", "ipa": "samɯi", "syllable_count": 3, "sentences": [{"text": "今日は気温が低くて、朝から寒い。", "target_word": "寒い", "complexity_tier": "T3", "furigana": "今日[きょう]は気温[きおん]が低[ひく]くて、朝[あさ]から寒[さむ]い。", "sentence_source": "generated"}, {"text": "冬になると、日本の北の地方はとても寒くなります。", "target_word": "寒く", "complexity_tier": "T3", "furigana": "冬[ふゆ]になると、日本[にほん]の北[きた]の地方[ちほう]はとても寒[さむ]くなります。", "sentence_source": "generated"}, {"text": "寒い日には、温かいスープが飲みたくなる。", "target_word": "寒い", "complexity_tier": "T3", "furigana": "寒[さむ]い日[ひ]には、温[あたた]かいスープが飲[の]みたくなる。", "sentence_source": "generated"}, {"text": "夜になって急に寒くなったので、上着を取りに戻った。", "target_word": "寒く", "complexity_tier": "T3", "furigana": "夜[よる]になって急[きゅう]に寒[さむ]くなったので、上着[うわぎ]を取[と]りに戻[もど]った。", "sentence_source": "generated"}, {"text": "去年の冬は例年より寒かったため、水道管が凍った。", "target_word": "寒かった", "complexity_tier": "T3", "furigana": "去年[きょねん]の冬[ふゆ]は例年[れいねん]より寒[さむ]かったため、水道管[すいどうかん]が凍[こお]った。", "sentence_source": "generated"}, {"text": "この部屋は日が当たらないから、夏でも少し寒い。", "target_word": "寒い", "complexity_tier": "T3", "furigana": "この部屋[へや]は日[ひ]が当[あ]たらないから、夏[なつ]でも少[すこ]し寒[さむ]い。", "sentence_source": "generated"}, {"text": "寒い季節が終わり、やっと春が来た。", "target_word": "寒い", "complexity_tier": "T3", "furigana": "寒[さむ]い季節[きせつ]が終[お]わり、やっと春[はる]が来[き]た。", "sentence_source": "generated"}, {"text": "山の上は町より寒いので、セーターを持っていきましょう。", "target_word": "寒い", "complexity_tier": "T3", "furigana": "山[やま]の上[うえ]は町[まち]より寒[さむ]いので、セーターを持[も]っていきましょう。", "sentence_source": "generated"}, {"text": "寒くて眠れなかったから、毛布をもう一枚出した。", "target_word": "寒くて", "complexity_tier": "T3", "furigana": "寒[さむ]くて眠[ねむ]れなかったから、毛布[もうふ]をもう一枚[いちまい]出[だ]した。", "sentence_source": "generated"}, {"text": "雪が積もるほど寒いのに、子どもたちは外で遊んでいる。", "target_word": "寒い", "complexity_tier": "T3", "furigana": "雪[ゆき]が積[つ]もるほど寒[さむ]いのに、子[こ]どもたちは外[そと]で遊[あそ]んでいる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "寒い", "label": "終止形"}, {"form": "寒く", "label": "連用形"}, {"form": "寒かった", "label": "過去形"}, {"form": "寒くない", "label": "否定形"}, {"form": "寒ければ", "label": "仮定形"}], "register": "中立", "sense_fingerprint": "気温が低いこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '152e28d3-84c3-4bdc-ba2f-89eedcb9cdff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35578, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "寒い", "is_correct": true, "explanation": "終止形で「朝から寒い。」と文を言い切れる。気温が低い状況に合う。"}, {"text": "寒く", "is_correct": false, "explanation": "連用形では「朝から寒く。」と文を言い切れない。"}, {"text": "寒ければ", "is_correct": false, "explanation": "仮定形は条件節で、文の述語にならない。"}, {"text": "寒さ", "is_correct": false, "explanation": "名詞では「朝から寒さ。」となり、述語として成立しない。"}], "explanations": {"寒い": "終止形で「朝から寒い。」と文を言い切れる。気温が低い状況に合う。", "寒く": "連用形では「朝から寒く。」と文を言い切れない。", "寒ければ": "仮定形は条件節で、文の述語にならない。", "寒さ": "名詞では「朝から寒さ。」となり、述語として成立しない。"}, "sentence_index": 0, "correct_answer": "寒い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "注文した料理の味が寒くなったので、店を出た。", "explanation": "ここは〈まずくなる〉の意味。寒いは気温や体感を表すので、味の悪化には使わない。"}, {"text": "冷めたスープは、テーブルの上で寒くなった。", "explanation": "ここは〈冷める〉の意味。料理の温度低下は冷めるで表し、寒いとは言わない。"}, {"text": "お風呂の湯がすっかり寒くなったので、もう一度沸かした。", "explanation": "ここは〈ぬるくなる〉の意味。湯の温度の低下は寒いでは表せず、ぬるいで表す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a394539-7d4d-4f1a-822d-2e50512ec476') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35578, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "寒い", "is_correct": true, "explanation": "「寒い季節」と名詞を修飾する終止形。季節の性質を表す。"}, {"text": "寒がり", "is_correct": false, "explanation": "「寒がり」は寒さを感じやすい人を指す名詞で、「季節」を修飾する形にならず、「寒がり季節」は成り立たない。"}, {"text": "寒そう", "is_correct": false, "explanation": "様子を表す語幹で、名詞「季節」に直接続かない。「寒そうな季節」なら別の意味になり、「寒そう季節」は成り立たない。"}, {"text": "寒くて", "is_correct": false, "explanation": "て形は名詞を修飾できず、「寒くて季節」は成り立たない。"}], "explanations": {"寒い": "「寒い季節」と名詞を修飾する終止形。季節の性質を表す。", "寒がり": "「寒がり」は寒さを感じやすい人を指す名詞で、「季節」を修飾する形にならず、「寒がり季節」は成り立たない。", "寒そう": "様子を表す語幹で、名詞「季節」に直接続かない。「寒そうな季節」なら別の意味になり、「寒そう季節」は成り立たない。", "寒くて": "て形は名詞を修飾できず、「寒くて季節」は成り立たない。"}, "sentence_index": 6, "correct_answer": "寒い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は怒りで顔が寒くなった。", "explanation": "ここは〈熱くなる〉の意味（怒りで顔が火照る）。寒いは気温や体感の低さを表すので、怒りの火照りには合わない。"}, {"text": "パーティーの料理は、香りが寒かった。", "explanation": "ここは〈香ばしい〉の意味。料理の香りの良さは寒いでは表せず、香ばしいで表す。"}, {"text": "池の水面が一晩で寒くなった。", "explanation": "ここは〈凍る〉の意味。水が氷になる変化は凍るで表し、寒いでは表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a394539-7d4d-4f1a-822d-2e50512ec476') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35578, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "山の上は、夜になると寒いなる。", "corrected_sentence": "山の上は、夜になると寒くなる。", "error_description": "連用形の誤り。「寒い」を「寒く」にして「なる」と続ける。「寒いなる」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "寒く", "is_correct": true, "explanation": "文中の形そのもの。連用形で「寒くなります」と変化を表す。"}, {"text": "寒い", "is_correct": false, "explanation": "終止形では「寒いなります」となり、「なる」と続かない。"}, {"text": "寒ければ", "is_correct": false, "explanation": "仮定形は「寒ければなります」となり、成立しない。"}, {"text": "寒くない", "is_correct": false, "explanation": "否定形は「寒くないなります」となり、成立しない。"}], "correct_form": "寒く", "base_form": "寒い", "form_label": "連用形", "sentence_index": 1, "explanations": {"寒く": "文中の形そのもの。連用形で「寒くなります」と変化を表す。", "寒い": "終止形では「寒いなります」となり、「なる」と続かない。", "寒ければ": "仮定形は「寒ければなります」となり、成立しない。", "寒くない": "否定形は「寒くないなります」となり、成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a394539-7d4d-4f1a-822d-2e50512ec476') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35578, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "山の朝は町よりずっと寒いい。", "corrected_sentence": "山の朝は町よりずっと寒い。", "error_description": "形容詞「寒い」の語尾の誤り。「い」を重ねている。正しくは「寒い」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "寒い", "is_correct": true, "explanation": "文中の形そのもの。終止形で「寒いので、セーターを持っていきましょう」と理由を続けている。"}, {"text": "寒く", "is_correct": false, "explanation": "連用形は「寒くので」となり、理由の接続として成立しない。"}, {"text": "寒ければ", "is_correct": false, "explanation": "仮定形は「寒ければので」となり、接続として成立しない。"}, {"text": "寒くて", "is_correct": false, "explanation": "て形は「寒くてので」となり、接続として成立しない。"}], "correct_form": "寒い", "base_form": "寒い", "form_label": "終止形", "sentence_index": 7, "explanations": {"寒い": "文中の形そのもの。終止形で「寒いので、セーターを持っていきましょう」と理由を続けている。", "寒く": "連用形は「寒くので」となり、理由の接続として成立しない。", "寒ければ": "仮定形は「寒ければので」となり、接続として成立しない。", "寒くて": "て形は「寒くてので」となり、接続として成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a394539-7d4d-4f1a-822d-2e50512ec476') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35579, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "暑い", "is_correct": true, "explanation": "気温が高いことを表し、「寒い（気温が低い）」の対義語。"}, {"text": "硬い", "is_correct": false, "explanation": "「柔らかい」が対義語。気温の高低とは関係がない。"}, {"text": "長い", "is_correct": false, "explanation": "「短い」が対義語。気温の高低とは関係がない。"}, {"text": "重い", "is_correct": false, "explanation": "「軽い」が対義語。気温の寒暖とは関係がない。"}], "correct_answer": "暑い", "explanations": {"暑い": "気温が高いことを表し、「寒い（気温が低い）」の対義語。", "硬い": "「柔らかい」が対義語。気温の高低とは関係がない。", "長い": "「短い」が対義語。気温の高低とは関係がない。", "重い": "「軽い」が対義語。気温の寒暖とは関係がない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a394539-7d4d-4f1a-822d-2e50512ec476') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35579, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "暑い", "is_correct": true, "explanation": "気温が高いことを表し、「寒い（気温が低い）」の対義語。"}, {"text": "遠い", "is_correct": false, "explanation": "「近い」が対義語。距離の話で、気温とは関係がない。"}, {"text": "狭い", "is_correct": false, "explanation": "「広い」が対義語。空間の広さの話で、気温とは関係がない。"}, {"text": "早い", "is_correct": false, "explanation": "「遅い」が対義語。時間の話で、気温とは関係がない。"}], "correct_answer": "暑い", "explanations": {"暑い": "気温が高いことを表し、「寒い（気温が低い）」の対義語。", "遠い": "「近い」が対義語。距離の話で、気温とは関係がない。", "狭い": "「広い」が対義語。空間の広さの話で、気温とは関係がない。", "早い": "「遅い」が対義語。時間の話で、気温とは関係がない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a394539-7d4d-4f1a-822d-2e50512ec476') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35579, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "気温が低く、体に冷たく感じられるさま。", "primary_collocate": null, "pronunciation": "さむい", "ipa": "samɯi", "syllable_count": 3, "sentences": [{"text": "峠は北風が強くて、夕方になるとぐっと寒い。", "target_word": "寒い", "complexity_tier": "T3", "furigana": "峠[とうげ]は北風[きたかぜ]が強[つよ]くて、夕方[ゆうがた]になるとぐっと寒[さむ]い。", "sentence_source": "generated"}, {"text": "冬の朝は寒いので、厚いコートを着て出かけます。", "target_word": "寒い", "complexity_tier": "T3", "furigana": "冬[ふゆ]の朝[あさ]は寒[さむ]いので、厚[あつ]いコートを着[き]て出[で]かけます。", "sentence_source": "generated"}, {"text": "窓を開けたままにしておいたから、部屋の中が寒くなってしまった。", "target_word": "寒く", "complexity_tier": "T3", "furigana": "窓[まど]を開[あ]けたままにしておいたから、部屋[へや]の中[なか]が寒[さむ]くなってしまった。", "sentence_source": "generated"}, {"text": "昨日は風が強くて、外に立っているだけでとても寒かった。", "target_word": "寒かった", "complexity_tier": "T3", "furigana": "昨日[きのう]は風[かぜ]が強[つよ]くて、外[そと]に立[た]っているだけでとても寒[さむ]かった。", "sentence_source": "generated"}, {"text": "寒いなら、このマフラーを使ってください。", "target_word": "寒い", "complexity_tier": "T3", "furigana": "寒[さむ]いなら、このマフラーを使[つか]ってください。", "sentence_source": "generated"}, {"text": "北海道の冬は東京よりずっと寒い。", "target_word": "寒い", "complexity_tier": "T3", "furigana": "北海道[ほっかいどう]の冬[ふゆ]は東京[とうきょう]よりずっと寒[さむ]い。", "sentence_source": "generated"}, {"text": "雪が降り出して、手が冷たくなるほど寒い夜だった。", "target_word": "寒い", "complexity_tier": "T3", "furigana": "雪[ゆき]が降[ふ]り出[だ]して、手[て]が冷[つめ]たくなるほど寒[さむ]い夜[よる]だった。", "sentence_source": "generated"}, {"text": "薄着で出かけたせいで、帰り道は寒くて震えた。", "target_word": "寒くて", "complexity_tier": "T3", "furigana": "薄着[うすぎ]で出[で]かけたせいで、帰[かえ]り道[みち]は寒[さむ]くて震[ふる]えた。", "sentence_source": "generated"}, {"text": "寒くなってきたので、ストーブをつけましょう。", "target_word": "寒く", "complexity_tier": "T3", "furigana": "寒[さむ]くなってきたので、ストーブをつけましょう。", "sentence_source": "generated"}, {"text": "暖房が壊れていて、教室の中は外と同じくらい寒かった。", "target_word": "寒かった", "complexity_tier": "T3", "furigana": "暖房[だんぼう]が壊[こわ]れていて、教室[きょうしつ]の中[なか]は外[そと]と同[おな]じくらい寒[さむ]かった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "寒い", "label": "終止形"}, {"form": "寒く", "label": "連用形"}, {"form": "寒かった", "label": "過去形"}, {"form": "寒くない", "label": "否定形"}, {"form": "寒ければ", "label": "仮定形"}], "register": "中立", "sense_fingerprint": "気温が低く体が冷たく感じられる状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '152e28d3-84c3-4bdc-ba2f-89eedcb9cdff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35579, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "寒い", "is_correct": true, "explanation": "終止形で「ぐっと寒い。」と文を言い切れる。気温の描写に合う。"}, {"text": "寒く", "is_correct": false, "explanation": "連用形では「ぐっと寒く。」と文を言い切れない。"}, {"text": "寒ければ", "is_correct": false, "explanation": "仮定形は条件節で、文の述語にならない。"}, {"text": "寒がる", "is_correct": false, "explanation": "「寒がる」は人が寒がる意味で、風や場所の描写には合わない。"}], "explanations": {"寒い": "終止形で「ぐっと寒い。」と文を言い切れる。気温の描写に合う。", "寒く": "連用形では「ぐっと寒く。」と文を言い切れない。", "寒ければ": "仮定形は条件節で、文の述語にならない。", "寒がる": "「寒がる」は人が寒がる意味で、風や場所の描写には合わない。"}, "sentence_index": 0, "correct_answer": "寒い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "冷蔵庫から出したばかりのお茶は、とても寒かった。", "explanation": "ここは〈冷たい〉の意味。寒いは気温や体感を指し、ものの温度には冷たいを使う。"}, {"text": "この卵焼きは、甘さが寒かった。", "explanation": "ここは〈甘い〉の意味。寒いは気温や体感の低さを表すので、味の甘さには使わない。"}, {"text": "真夏の昼は、日差しが強くて寒かった。", "explanation": "ここは〈暑い〉の意味。真夏の強い日差しは暑さの話で、寒さの話ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a394539-7d4d-4f1a-822d-2e50512ec476') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35579, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "寒い", "is_correct": true, "explanation": "「寒い夜」と名詞を修飾する終止形。雪が降り手が冷たくなる夜の様子に合う。"}, {"text": "寒さ", "is_correct": false, "explanation": "名詞は「寒さの夜」の形でなければ、「寒さ夜」は成り立たない。"}, {"text": "寒ければ", "is_correct": false, "explanation": "仮定形は名詞を修飾できず、「寒ければ夜だった」は文として成り立たない。"}, {"text": "寒くて", "is_correct": false, "explanation": "て形は名詞を修飾できず、「寒くて夜」は成り立たない。"}], "explanations": {"寒い": "「寒い夜」と名詞を修飾する終止形。雪が降り手が冷たくなる夜の様子に合う。", "寒さ": "名詞は「寒さの夜」の形でなければ、「寒さ夜」は成り立たない。", "寒ければ": "仮定形は名詞を修飾できず、「寒ければ夜だった」は文として成り立たない。", "寒くて": "て形は名詞を修飾できず、「寒くて夜」は成り立たない。"}, "sentence_index": 6, "correct_answer": "寒い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夕飯のカレーは、ご飯の量が寒かった。", "explanation": "ここは〈少ない〉の意味。寒いは気温や体感を表すので、分量の少なさには使わない。"}, {"text": "恥ずかしくて、顔がとても寒かった。", "explanation": "ここは〈熱い〉の意味（恥ずかしさで顔が火照る）。寒いは冷たさを表すので、火照りには合わない。"}, {"text": "この曲は、テンポがずいぶん寒かった。", "explanation": "ここは〈遅い〉の意味。寒いは気温や体感を表すので、テンポの遅さには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a394539-7d4d-4f1a-822d-2e50512ec476') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35579, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "朝の空気は、思ったより寒いだった。", "corrected_sentence": "朝の空気は、思ったより寒かった。", "error_description": "形容詞「寒い」に「だ」を付けた誤り。形容詞の過去形は「寒かった」で、「寒いだった」とは言わない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "寒い", "is_correct": true, "explanation": "文中の形そのもの。終止形で「寒いので」と理由を続けている。"}, {"text": "寒く", "is_correct": false, "explanation": "連用形は「寒くので」と理由の接続に続かず、文が成立しない。"}, {"text": "寒ければ", "is_correct": false, "explanation": "仮定形は「寒ければので」となり、接続として成立しない。"}, {"text": "寒くて", "is_correct": false, "explanation": "て形は「寒くてので」となり、接続として成立しない。"}], "correct_form": "寒い", "base_form": "寒い", "form_label": "終止形", "sentence_index": 1, "explanations": {"寒い": "文中の形そのもの。終止形で「寒いので」と理由を続けている。", "寒く": "連用形は「寒くので」と理由の接続に続かず、文が成立しない。", "寒ければ": "仮定形は「寒ければので」となり、接続として成立しない。", "寒くて": "て形は「寒くてので」となり、接続として成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a394539-7d4d-4f1a-822d-2e50512ec476') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35579, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜になると急に寒がなる。", "corrected_sentence": "夜になると急に寒くなる。", "error_description": "形容詞「寒い」の連用形の誤り。「寒く」＋「なる」で「寒くなる」とする。「寒が」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "寒くて", "is_correct": true, "explanation": "文中の形そのもの。て形で「寒くて震えた」と原因や状態を続けている。"}, {"text": "寒い", "is_correct": false, "explanation": "終止形では「寒い震えた」となり、文が成立しない。"}, {"text": "寒くない", "is_correct": false, "explanation": "否定形では「寒くない震えた」となり、文が成立しない。"}, {"text": "寒かった", "is_correct": false, "explanation": "過去形では「寒かった震えた」となり、文が成立しない。"}], "correct_form": "寒くて", "base_form": "寒い", "form_label": "て形", "sentence_index": 7, "explanations": {"寒くて": "文中の形そのもの。て形で「寒くて震えた」と原因や状態を続けている。", "寒い": "終止形では「寒い震えた」となり、文が成立しない。", "寒くない": "否定形では「寒くない震えた」となり、文が成立しない。", "寒かった": "過去形では「寒かった震えた」となり、文が成立しない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a394539-7d4d-4f1a-822d-2e50512ec476') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35580, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「自国」と「文化」をつなぐ所属の「の」。「自国の文化」になる。"}, {"text": "を", "is_correct": false, "explanation": "「文化を」が既に目的語なので、「自国を文化を」は重なって不自然。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は比べる対象がなく、意味が通らない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は位置や相手を示すので、「自国に文化を」は不自然。"}], "correct_answer": "の", "explanations": {"の": "「自国」と「文化」をつなぐ所属の「の」。「自国の文化」になる。", "を": "「文化を」が既に目的語なので、「自国を文化を」は重なって不自然。", "より": "比較の「より」は比べる対象がなく、意味が通らない。", "に": "「に」は位置や相手を示すので、「自国に文化を」は不自然。"}, "error_tags": {"を": "目的語の格助詞", "より": "比較の助詞", "に": "位置・相手の格助詞"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a24165d-25fb-4287-b029-d82fa4c8a110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35580, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「自国」と「米」をつなぐ所属の「の」。「自国の米」になる。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「自国へ米」は意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すので、「自国と米」は不自然。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「自国を米だけで足りる」は文として成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「自国」と「米」をつなぐ所属の「の」。「自国の米」になる。", "へ": "「へ」は方向を示すので、「自国へ米」は意味が通らない。", "と": "「と」は並列や相手を示すので、「自国と米」は不自然。", "を": "「を」は目的語を示すが、「自国を米だけで足りる」は文として成り立たない。"}, "error_tags": {"へ": "方向の格助詞", "と": "並列・相手の格助詞", "を": "目的語の格助詞"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a24165d-25fb-4287-b029-d82fa4c8a110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35580, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "自分の国のこと。", "primary_collocate": null, "pronunciation": "じこく", "ipa": "d͡ʑikokɯ", "syllable_count": 3, "sentences": [{"text": "どの国も、まず自国の利益を考えます。", "target_word": "自国", "complexity_tier": "T3", "furigana": "どの国[くに]も、まず自国[じこく]の利益[りえき]を考[かんが]えます。", "sentence_source": "generated"}, {"text": "自国の文化を、外国の人に紹介しました。", "target_word": "自国", "complexity_tier": "T3", "furigana": "自国[じこく]の文化[ぶんか]を、外国[がいこく]の人[ひと]に紹介[しょうかい]しました。", "sentence_source": "generated"}, {"text": "大統領は、自国の経済を守ると話しました。", "target_word": "自国", "complexity_tier": "T3", "furigana": "大統領[だいとうりょう]は、自国[じこく]の経済[けいざい]を守[まも]ると話[はな]しました。", "sentence_source": "generated"}, {"text": "他の国のことを知ると、自国のこともよくわかります。", "target_word": "自国", "complexity_tier": "T3", "furigana": "他[ほか]の国[くに]のことを知[し]ると、自国[じこく]のこともよくわかります。", "sentence_source": "generated"}, {"text": "この選手は、自国の代表として大会に出ます。", "target_word": "自国", "complexity_tier": "T3", "furigana": "この選手[せんしゅ]は、自国[じこく]の代表[だいひょう]として大会[たいかい]に出[で]ます。", "sentence_source": "generated"}, {"text": "自国の言葉で書かれた本は、読みやすいです。", "target_word": "自国", "complexity_tier": "T3", "furigana": "自国[じこく]の言葉[ことば]で書[か]かれた本[ほん]は、読[よ]みやすいです。", "sentence_source": "generated"}, {"text": "その国は、車の部品を自国で作る力を持っています。", "target_word": "自国", "complexity_tier": "T3", "furigana": "その国[くに]は、車[くるま]の部品[ぶひん]を自国[じこく]で作[つく]る力[ちから]を持[も]っています。", "sentence_source": "generated"}, {"text": "輸入に頼らず、自国の米だけで足りる年もあります。", "target_word": "自国", "complexity_tier": "T3", "furigana": "輸入[ゆにゅう]に頼[たよ]らず、自国[じこく]の米[こめ]だけで足[た]りる年[とし]もあります。", "sentence_source": "generated"}, {"text": "政府は、自国の産業を助けるために税を変えました。", "target_word": "自国", "complexity_tier": "T3", "furigana": "政府[せいふ]は、自国[じこく]の産業[さんぎょう]を助[たす]けるために税[ぜい]を変[か]えました。", "sentence_source": "generated"}, {"text": "外国の料理より、自国の料理のほうが好きな人も多い。", "target_word": "自国", "complexity_tier": "T3", "furigana": "外国[がいこく]の料理[りょうり]より、自国[じこく]の料理[りょうり]のほうが好[す]きな人[ひと]も多[おお]い。", "sentence_source": "generated"}], "morphological_forms": [{"form": "自国", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "他国に対して、自分たちの属する国", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e74715c8-80af-41e0-bc9c-e29c3da457dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35580, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自国", "is_correct": true, "explanation": "「自分たちの国」を指す。「どの国も」と対になり、利益を考える主体として合う。"}, {"text": "電車", "is_correct": false, "explanation": "電車は乗り物で、国の利益を考える対象にはならないので合わない。"}, {"text": "教科書", "is_correct": false, "explanation": "教科書は本で、国の利益を考える文脈には合わない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "冷蔵庫は家電で、国の利益を指す語としては不自然。"}], "explanations": {"自国": "「自分たちの国」を指す。「どの国も」と対になり、利益を考える主体として合う。", "電車": "電車は乗り物で、国の利益を考える対象にはならないので合わない。", "教科書": "教科書は本で、国の利益を考える文脈には合わない。", "冷蔵庫": "冷蔵庫は家電で、国の利益を指す語としては不自然。"}, "sentence_index": 0, "correct_answer": "自国"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "自国が選挙に行くのは、大切な権利だ。", "explanation": "ここは〈国民〉の意味。自国は国そのものを指すので、選挙に行く主体にはならない。"}, {"text": "彼は三年前に、日本の自国を取得した。", "explanation": "ここは〈国籍〉の意味。自国は国そのものを指すので、取得する対象にはならない。"}, {"text": "風邪を引いて、自国の体調がずっと悪い。", "explanation": "ここは〈自分〉の意味。国には体調がないので、自国の体調とは言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a24165d-25fb-4287-b029-d82fa4c8a110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35580, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自国", "is_correct": true, "explanation": "「自分たちの国」の意味。車の部品を作る国として合う。"}, {"text": "教室", "is_correct": false, "explanation": "教室は授業の場所で、車の部品を作る場所としては合わない。"}, {"text": "寝室", "is_correct": false, "explanation": "寝室は寝るための部屋で、部品を作る場所ではない。"}, {"text": "夕食", "is_correct": false, "explanation": "夕食は食事で、部品を作る場所を示す語としては合わない。"}], "explanations": {"自国": "「自分たちの国」の意味。車の部品を作る国として合う。", "教室": "教室は授業の場所で、車の部品を作る場所としては合わない。", "寝室": "寝室は寝るための部屋で、部品を作る場所ではない。", "夕食": "夕食は食事で、部品を作る場所を示す語としては合わない。"}, "sentence_index": 6, "correct_answer": "自国"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は空港で、自国を見せて入国審査を受けた。", "explanation": "ここは〈旅券〉（パスポート）の意味。自国は国そのものを指すので、審査で見せるものにはならない。"}, {"text": "自国を移す計画が、来年から始まる。", "explanation": "ここは〈首都〉の意味。自国は国全体を指すので、移転の対象とは言えない。"}, {"text": "自国が三人増えて、町が賑やかになった。", "explanation": "ここは〈住民〉（人）の意味。自国は国そのものを指すので、人の数として増えることはない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a24165d-25fb-4287-b029-d82fa4c8a110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35580, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この選手は、自国に代表として世界大会に出ます。", "corrected_sentence": "この選手は、自国の代表として世界大会に出ます。", "error_description": "「自国」に「の」を付けて「自国の代表」とする。「に」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a24165d-25fb-4287-b029-d82fa4c8a110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35580, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "母は、自国を作られた布を大切にしている。", "corrected_sentence": "母は、自国で作られた布を大切にしている。", "error_description": "「作られる」の場所は「で」で示す。「を」は誤りで、正しくは「自国で」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a24165d-25fb-4287-b029-d82fa4c8a110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35581, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "へ", "options": [{"text": "へ", "is_correct": true, "explanation": "「帰る」の行き先を示す「へ」。「自国へ帰る」になる。"}, {"text": "を", "is_correct": false, "explanation": "「帰る」は目的語を取らないので、「を」は不自然。"}, {"text": "が", "is_correct": false, "explanation": "「自国が帰る」は主語として不自然。"}, {"text": "と", "is_correct": false, "explanation": "「と」は共同の相手を示すが、「自国と帰る」は意味が通らない。"}], "correct_answer": "へ", "explanations": {"へ": "「帰る」の行き先を示す「へ」。「自国へ帰る」になる。", "を": "「帰る」は目的語を取らないので、「を」は不自然。", "が": "「自国が帰る」は主語として不自然。", "と": "「と」は共同の相手を示すが、「自国と帰る」は意味が通らない。"}, "error_tags": {"を": "目的語の格助詞", "が": "主格の格助詞", "と": "並列・共同の格助詞"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a24165d-25fb-4287-b029-d82fa4c8a110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35581, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「自国」と「大学」をつなぐ所属の「の」。「自国の大学」になる。"}, {"text": "に", "is_correct": false, "explanation": "「に」は位置や相手を示すので、「自国に大学で」は不自然。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すので、「自国が大学で教える」は主語の意味になり不自然。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」は比べる対象がなく、「自国より大学で」は意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「自国」と「大学」をつなぐ所属の「の」。「自国の大学」になる。", "に": "「に」は位置や相手を示すので、「自国に大学で」は不自然。", "が": "「が」は主語を示すので、「自国が大学で教える」は主語の意味になり不自然。", "より": "比較の「より」は比べる対象がなく、「自国より大学で」は意味が通らない。"}, "error_tags": {"に": "位置・相手の格助詞", "より": "比較の助詞", "が": "主格の格助詞"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a24165d-25fb-4287-b029-d82fa4c8a110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35581, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "自分が生まれ育った国、または国籍のある国。", "primary_collocate": null, "pronunciation": "じこく", "ipa": "d͡ʑikokɯ", "syllable_count": 3, "sentences": [{"text": "留学生は、自国の家族に毎週電話をかけます。", "target_word": "自国", "complexity_tier": "T3", "furigana": "留学生[りゅうがくせい]は、自国[じこく]の家族[かぞく]に毎週[まいしゅう]電話[でんわ]をかけます。", "sentence_source": "generated"}, {"text": "彼は十年ぶりに自国へ帰りました。", "target_word": "自国", "complexity_tier": "T3", "furigana": "彼[かれ]は十年[じゅうねん]ぶりに自国[じこく]へ帰[かえ]りました。", "sentence_source": "generated"}, {"text": "日本で働く外国人が、自国の料理店を開きました。", "target_word": "自国", "complexity_tier": "T3", "furigana": "日本[にほん]で働[はたら]く外国人[がいこくじん]が、自国[じこく]の料理店[りょうりてん]を開[ひら]きました。", "sentence_source": "generated"}, {"text": "戦争のため、自国を離れた人が大勢います。", "target_word": "自国", "complexity_tier": "T3", "furigana": "戦争[せんそう]のため、自国[じこく]を離[はな]れた人[ひと]が大勢[おおぜい]います。", "sentence_source": "generated"}, {"text": "自国のパスポートを持って、空港に行きました。", "target_word": "自国", "complexity_tier": "T3", "furigana": "自国[じこく]のパスポートを持[も]って、空港[くうこう]に行[い]きました。", "sentence_source": "generated"}, {"text": "彼女は、自国を出てから一度も戻っていません。", "target_word": "自国", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は、自国[じこく]を出[で]てから一度[いちど]も戻[もど]っていません。", "sentence_source": "generated"}, {"text": "自国の友達と、毎日オンラインで話します。", "target_word": "自国", "complexity_tier": "T3", "furigana": "自国[じこく]の友達[ともだち]と、毎日[まいにち]オンラインで話[はな]します。", "sentence_source": "generated"}, {"text": "留学を終えたら、自国の大学で教えるつもりです。", "target_word": "自国", "complexity_tier": "T3", "furigana": "留学[りゅうがく]を終[お]えたら、自国[じこく]の大学[だいがく]で教[おし]えるつもりです。", "sentence_source": "generated"}, {"text": "自国の祭りが恋しくて、ホームシックになりました。", "target_word": "自国", "complexity_tier": "T3", "furigana": "自国[じこく]の祭[まつ]りが恋[こい]しくて、ホームシックになりました。", "sentence_source": "generated"}, {"text": "彼は自国を愛しているので、いつか政治家になりたいと言う。", "target_word": "自国", "complexity_tier": "T3", "furigana": "彼[かれ]は自国[じこく]を愛[あい]しているので、いつか政治家[せいじか]になりたいと言[い]う。", "sentence_source": "generated"}], "morphological_forms": [{"form": "自国", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "本人が生まれ育った母国、国籍を持つ国", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e74715c8-80af-41e0-bc9c-e29c3da457dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35581, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自国", "is_correct": true, "explanation": "「本人が生まれ育った国」を指す。「留学生の家族」が住む国として合う。"}, {"text": "教室", "is_correct": false, "explanation": "教室は授業の場所で、家族がいる場所としては合わない。"}, {"text": "研究室", "is_correct": false, "explanation": "研究室は研究の場で、家族の所在地としては不自然。"}, {"text": "辞書", "is_correct": false, "explanation": "辞書は本で、家族の所在を示す語としては合わない。"}], "explanations": {"自国": "「本人が生まれ育った国」を指す。「留学生の家族」が住む国として合う。", "教室": "教室は授業の場所で、家族がいる場所としては合わない。", "研究室": "研究室は研究の場で、家族の所在地としては不自然。", "辞書": "辞書は本で、家族の所在を示す語としては合わない。"}, "sentence_index": 0, "correct_answer": "自国"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "台風の接近で、自国が避難所に集まった。", "explanation": "ここは〈住民〉の意味。自国は国を指すので、避難所に集まる人の代わりにはならない。"}, {"text": "自国が選挙で一票を投じた。", "explanation": "ここは〈国民〉の意味。自国は国そのものなので、一票を投じる主体にはならない。"}, {"text": "彼は日本の自国を持っている。", "explanation": "ここは〈国籍〉の意味。自国は国そのものを指すので、持つ対象としては合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a24165d-25fb-4287-b029-d82fa4c8a110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35581, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自国", "is_correct": true, "explanation": "「本人が生まれ育った国」の意味。「自国の友達」として合う。"}, {"text": "窓", "is_correct": false, "explanation": "窓は建具で、友達の所属を示す語としては合わない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "冷蔵庫は家電で、友達を修飾する語としては不自然。"}, {"text": "植木", "is_correct": false, "explanation": "植木は植物で、友達の所属を示す語としては合わない。"}], "explanations": {"自国": "「本人が生まれ育った国」の意味。「自国の友達」として合う。", "窓": "窓は建具で、友達の所属を示す語としては合わない。", "冷蔵庫": "冷蔵庫は家電で、友達を修飾する語としては不自然。", "植木": "植木は植物で、友達の所属を示す語としては合わない。"}, "sentence_index": 6, "correct_answer": "自国"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は自国に留学して、語学を学んだ。", "explanation": "ここは〈外国〉の意味。自国は生まれ育った国なので、そこに留学するとは言えない。"}, {"text": "彼は次の選挙に、自国として立候補した。", "explanation": "ここは〈候補者〉（人）の意味。自国は国を指すので、立候補する主体にはならない。"}, {"text": "彼は来年、自国を卒業する予定だ。", "explanation": "ここは〈学校〉の意味。自国は国を指すので、卒業の対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a24165d-25fb-4287-b029-d82fa4c8a110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35581, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "留学生は、自国が家族に毎週手紙を書きます。", "corrected_sentence": "留学生は、自国の家族に毎週手紙を書きます。", "error_description": "「自国」は家族の所在を示すので「の」。「が」は主語になり不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a24165d-25fb-4287-b029-d82fa4c8a110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35581, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "留学後は、自国を大学で教えるつもりです。", "corrected_sentence": "留学後は、自国の大学で教えるつもりです。", "error_description": "「自国」と「大学」は所属の「の」で結ぶ。「を」は目的語となり誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a24165d-25fb-4287-b029-d82fa4c8a110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
