INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35582, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「兄に頼る」は頼る相手を表す「に」で、文の意味に合う。"}, {"text": "を", "is_correct": false, "explanation": "「兄を頼る」は頼る相手の示し方として不自然で、文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「兄と頼る」は相手の示し方として不自然で、意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」では「兄へ頼る」となり、頼る相手を示す形として不自然。"}], "correct_answer": "に", "explanations": {"に": "「兄に頼る」は頼る相手を表す「に」で、文の意味に合う。", "を": "「兄を頼る」は頼る相手の示し方として不自然で、文が成り立たない。", "と": "「兄と頼る」は相手の示し方として不自然で、意味が通らない。", "へ": "方向を表す「へ」では「兄へ頼る」となり、頼る相手を示す形として不自然。"}, "error_tags": {"を": "目的語", "と": "相手・並列", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea56fd11-3342-43a9-97d5-69b456bcdfc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35582, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "誰かや何かを信じて、助けてもらうこと。", "primary_collocate": null, "pronunciation": "たよる", "ipa": "tajoɾɯ", "syllable_count": 3, "sentences": [{"text": "信じて頼れる友人が一人でもいれば、心強い。", "target_word": "頼れる", "complexity_tier": "T3", "furigana": "信[しん]じて頼[たよ]れる友人[ゆうじん]が一人[ひとり]でもいれば、心強[こころづよ]い。", "sentence_source": "generated"}, {"text": "彼は責任感が強いので、みんなが安心して頼る。", "target_word": "頼る", "complexity_tier": "T3", "furigana": "彼[かれ]は責任感[せきにんかん]が強[つよ]いので、みんなが安心[あんしん]して頼[たよ]る。", "sentence_source": "generated"}, {"text": "病気のとき、遠くに住む叔母を頼って上京した。", "target_word": "頼って", "complexity_tier": "T3", "furigana": "病気[びょうき]のとき、遠[とお]くに住[す]む叔母[おば]を頼[たよ]って上京[じょうきょう]した。", "sentence_source": "generated"}, {"text": "新人のころは、先輩に頼ってばかりで成長しなかった。", "target_word": "頼って", "complexity_tier": "T3", "furigana": "新人[しんじん]のころは、先輩[せんぱい]に頼[たよ]ってばかりで成長[せいちょう]しなかった。", "sentence_source": "generated"}, {"text": "神に頼る気持ちで、合格を祈った。", "target_word": "頼る", "complexity_tier": "T3", "furigana": "神[かみ]に頼[たよ]る気持[きも]ちで、合格[ごうかく]を祈[いの]った。", "sentence_source": "generated"}, {"text": "彼女は誰にも頼らずに、一人で子どもを育てた。", "target_word": "頼らず", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は誰[だれ]にも頼[たよ]らずに、一人[ひとり]で子[こ]どもを育[そだ]てた。", "sentence_source": "generated"}, {"text": "困ったときは、遠慮せずに周りに頼れば、きっと誰かが助けてくれる。", "target_word": "頼れば", "complexity_tier": "T3", "furigana": "困[こま]ったときは、遠慮[えんりょ]せずに周[まわ]りに頼[たよ]れば、きっと誰[だれ]かが助[たす]けてくれる。", "sentence_source": "generated"}, {"text": "弟は何でも兄に頼る癖がついている。", "target_word": "頼る", "complexity_tier": "T3", "furigana": "弟[おとうと]は何[なん]でも兄[あに]に頼[たよ]る癖[くせ]がついている。", "sentence_source": "generated"}, {"text": "彼の腕を信じて、多くの患者が頼ってきた。", "target_word": "頼って", "complexity_tier": "T3", "furigana": "彼[かれ]の腕[うで]を信[しん]じて、多[おお]くの患者[かんじゃ]が頼[たよ]ってきた。", "sentence_source": "generated"}, {"text": "知り合いを頼って大阪に来たが、すぐに仕事は見つからなかった。", "target_word": "頼って", "complexity_tier": "T3", "furigana": "知[し]り合[あ]いを頼[たよ]って大阪[おおさか]に来[き]たが、すぐに仕事[しごと]は見[み]つからなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "頼る", "label": "終止形"}, {"form": "頼らない", "label": "否定形"}, {"form": "頼ります", "label": "丁寧形"}, {"form": "頼って", "label": "て形"}, {"form": "頼った", "label": "た形"}, {"form": "頼れば", "label": "仮定形"}, {"form": "頼れる", "label": "可能形"}], "register": "neutral", "sense_fingerprint": "人や存在を信じて助けを当てにする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e1d13d0-4a75-4ad6-af0d-7ff5a6956501') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35582, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "頼れる", "is_correct": true, "explanation": "「信じて頼れる友人」の形で、信じて助けを求められる友人という文意に合う。"}, {"text": "頼ろう", "is_correct": false, "explanation": "意志形のため「信じて頼ろう友人」となり、名詞を修飾できず文が成り立たない。"}, {"text": "頼らず", "is_correct": false, "explanation": "否定の連用形のため、「信じて頼らず友人」となり修飾の形が崩れる。"}, {"text": "頼れ", "is_correct": false, "explanation": "命令形のため、「信じて頼れ友人」と名詞を修飾できない。"}], "explanations": {"頼れる": "「信じて頼れる友人」の形で、信じて助けを求められる友人という文意に合う。", "頼ろう": "意志形のため「信じて頼ろう友人」となり、名詞を修飾できず文が成り立たない。", "頼らず": "否定の連用形のため、「信じて頼らず友人」となり修飾の形が崩れる。", "頼れ": "命令形のため、「信じて頼れ友人」と名詞を修飾できない。"}, "sentence_index": 0, "correct_answer": "頼れる"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "賞味期限の切れた牛乳を頼って、お腹を壊した。", "explanation": "ここは〈飲む〉の意味。牛乳は信じて助けてもらう相手ではなく、口にするものなので、頼るとは言えない。"}, {"text": "窓ガラスの汚れに頼って、寒い冬を乗り切った。", "explanation": "ここは〈我慢する〉の意味。汚れは助けてくれる相手ではなく、耐えるための手段にもならないので、頼るとは言えない。"}, {"text": "雨粒に頼って、この日の計画を決めた。", "explanation": "ここは〈占う〉の意味。雨粒は信じて助けてもらう相手ではなく、未来を読むための材料にもならないので、頼るとは言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea56fd11-3342-43a9-97d5-69b456bcdfc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35582, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "頼れば", "is_correct": true, "explanation": "「周りに頼れば」の条件形で、助けを求めれば誰かが助けるという文意に合う。"}, {"text": "頼る", "is_correct": false, "explanation": "終止形のため「周りに頼る、きっと」となり条件の文脈が成り立たない。"}, {"text": "頼れ", "is_correct": false, "explanation": "命令形のため「周りに頼れ、きっと」となり文の流れが崩れる。"}, {"text": "頼らない", "is_correct": false, "explanation": "否定形のため、助けを求めないという逆の意味になり、文脈に合わない。"}], "explanations": {"頼れば": "「周りに頼れば」の条件形で、助けを求めれば誰かが助けるという文意に合う。", "頼る": "終止形のため「周りに頼る、きっと」となり条件の文脈が成り立たない。", "頼れ": "命令形のため「周りに頼れ、きっと」となり文の流れが崩れる。", "頼らない": "否定形のため、助けを求めないという逆の意味になり、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "頼れば"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "機械の音に頼って、友達の悩みを聞いた。", "explanation": "ここは〈受け流す〉の意味。機械の音は信じて助けてもらう相手ではなく、受け流すものなので、頼るとは言えない。"}, {"text": "ごみ箱に頼って、大切な手紙を捨てた。", "explanation": "ここは〈捨てる〉の意味。ごみ箱は信じて助けてもらう相手ではなく、物を捨てる場所なので、頼るとは言えない。"}, {"text": "その話の真偽に頼って、大事な約束を守った。", "explanation": "ここは〈確かめる〉の意味。真偽は助けを求める相手ではなく、確かめて判断する対象なので、頼るとは言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea56fd11-3342-43a9-97d5-69b456bcdfc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35582, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "困ったときは、先輩に頼れ相談する。", "corrected_sentence": "困ったときは、先輩に頼って相談する。", "error_description": "「頼って相談する」の連用形は「頼って」。命令形の「頼れ」を連用の位置に使ったため誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "頼る", "is_correct": true, "explanation": "終止形で、みんなが安心して頼るという文の形に合う。"}, {"text": "頼って", "is_correct": false, "explanation": "て形のため、文末に置けず「安心して頼って。」と文が成り立たない。"}, {"text": "頼らず", "is_correct": false, "explanation": "否定の連用形のため、「安心して頼らず。」と文として終わらない。"}, {"text": "頼らせ", "is_correct": false, "explanation": "使役の語幹のため、「みんなが安心して頼らせ。」と文として終わらず不自然。"}], "correct_form": "頼る", "base_form": "頼る", "form_label": "終止形", "sentence_index": 1, "explanations": {"頼る": "終止形で、みんなが安心して頼るという文の形に合う。", "頼って": "て形のため、文末に置けず「安心して頼って。」と文が成り立たない。", "頼らず": "否定の連用形のため、「安心して頼らず。」と文として終わらない。", "頼らせ": "使役の語幹のため、「みんなが安心して頼らせ。」と文として終わらず不自然。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea56fd11-3342-43a9-97d5-69b456bcdfc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35582, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "困ったときは、友人に頼りば、きっと助かる。", "corrected_sentence": "困ったときは、友人に頼れば、きっと助かる。", "error_description": "「頼る」の仮定形は「頼れば」。「頼りば」は誤った活用で、正しくは「頼れば」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "頼る", "is_correct": true, "explanation": "終止形で、弟が兄に頼る癖という名詞句の修飾として文の形に合う。"}, {"text": "頼れば", "is_correct": false, "explanation": "仮定形のため、「兄に頼れば癖」と名詞を修飾できず、文の形が崩れる。"}, {"text": "頼ります", "is_correct": false, "explanation": "丁寧形のため、「兄に頼ります癖」と名詞を修飾できない。"}, {"text": "頼れ", "is_correct": false, "explanation": "命令形のため、「兄に頼れ癖」と名詞を修飾できず、文の形が崩れる。"}], "correct_form": "頼る", "base_form": "頼る", "form_label": "終止形", "sentence_index": 7, "explanations": {"頼る": "終止形で、弟が兄に頼る癖という名詞句の修飾として文の形に合う。", "頼れば": "仮定形のため、「兄に頼れば癖」と名詞を修飾できず、文の形が崩れる。", "頼ります": "丁寧形のため、「兄に頼ります癖」と名詞を修飾できない。", "頼れ": "命令形のため、「兄に頼れ癖」と名詞を修飾できず、文の形が崩れる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea56fd11-3342-43a9-97d5-69b456bcdfc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35583, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「人に頼る」は助けを求める相手を表す「に」で、文の意味に合う。"}, {"text": "を", "is_correct": false, "explanation": "「人を頼る」は頼る相手を示す形として不自然。"}, {"text": "で", "is_correct": false, "explanation": "手段を表す「で」では、助けを求める相手を示せず文が崩れる。"}, {"text": "と", "is_correct": false, "explanation": "「人と頼る」は相手の示し方として不自然で、意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "「人に頼る」は助けを求める相手を表す「に」で、文の意味に合う。", "を": "「人を頼る」は頼る相手を示す形として不自然。", "で": "手段を表す「で」では、助けを求める相手を示せず文が崩れる。", "と": "「人と頼る」は相手の示し方として不自然で、意味が通らない。"}, "error_tags": {"を": "目的語", "で": "手段", "と": "相手・並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea56fd11-3342-43a9-97d5-69b456bcdfc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35583, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「杖に頼らない」は頼る対象を表す「に」で、文の意味に合う。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」では「杖へ頼らない」となり、頼る対象を示せない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は修飾を表すため、「杖の頼らないと」となり文が崩れる。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」では「杖より頼らないと」となり、頼る対象の示し方として不自然。"}], "correct_answer": "に", "explanations": {"に": "「杖に頼らない」は頼る対象を表す「に」で、文の意味に合う。", "へ": "方向を表す「へ」では「杖へ頼らない」となり、頼る対象を示せない。", "の": "「の」は修飾を表すため、「杖の頼らないと」となり文が崩れる。", "より": "比較の「より」では「杖より頼らないと」となり、頼る対象の示し方として不自然。"}, "error_tags": {"へ": "方向", "の": "修飾", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea56fd11-3342-43a9-97d5-69b456bcdfc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35583, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "自分の力だけでは足りないときに、他の人や物に助けを求めて、それに支えてもらうこと。", "primary_collocate": null, "pronunciation": "たよる", "ipa": "tajoɾɯ", "syllable_count": 3, "sentences": [{"text": "デザイナーの直感に頼るのではなく、計算された論理によって、機能的かつ独創的な都市空間を創出することが目指されています。", "target_word": "頼る", "complexity_tier": "T4", "furigana": "デザイナーの直感[ちょっかん]に頼[たよ]るのではなく、計算[けいさん]された論理[ろんり]によって、機能的[きのうてき]かつ独創的[どくそうてき]な都市空間[としくうかん]を創出[そうしゅつ]することが目指[めざ]されています。", "sentence_source": "mined"}, {"text": "地図がなかったので、道を知っている地元の人に頼るしかなかった。", "target_word": "頼る", "complexity_tier": "T3", "furigana": "地図[ちず]がなかったので、道[みち]を知[し]っている地元[じもと]の人[ひと]に頼[たよ]るしかなかった。", "sentence_source": "generated"}, {"text": "一人暮らしを始めたが、お金が足りず、結局親に頼ってしまった。", "target_word": "頼って", "complexity_tier": "T3", "furigana": "一人暮[ひとりぐ]らしを始[はじ]めたが、お金[かね]が足[た]りず、結局[けっきょく]親[おや]に頼[たよ]ってしまった。", "sentence_source": "generated"}, {"text": "彼は他人に頼らず、自分の力で店を大きくした。", "target_word": "頼らず", "complexity_tier": "T3", "furigana": "彼[かれ]は他人[たにん]に頼[たよ]らず、自分[じぶん]の力[ちから]で店[みせ]を大[おお]きくした。", "sentence_source": "generated"}, {"text": "停電したときは、懐中電灯の明かりに頼って階段を下りた。", "target_word": "頼って", "complexity_tier": "T3", "furigana": "停電[ていでん]したときは、懐中電灯[かいちゅうでんとう]の明[あか]かりに頼[たよ]って階段[かいだん]を下[お]りた。", "sentence_source": "generated"}, {"text": "日本語がわからない旅行者は、翻訳アプリに頼ることが多い。", "target_word": "頼る", "complexity_tier": "T3", "furigana": "日本語[にほんご]がわからない旅行者[りょこうしゃ]は、翻訳[ほんやく]アプリに頼[たよ]ることが多[おお]い。", "sentence_source": "generated"}, {"text": "仕事が多すぎるときは、同僚に頼ってもかまわない。", "target_word": "頼って", "complexity_tier": "T3", "furigana": "仕事[しごと]が多[おお]すぎるときは、同僚[どうりょう]に頼[たよ]ってもかまわない。", "sentence_source": "generated"}, {"text": "足をけがした祖父は、杖に頼らないと歩けない。", "target_word": "頼らない", "complexity_tier": "T3", "furigana": "足[あし]をけがした祖父[そふ]は、杖[つえ]に頼[たよ]らないと歩[ある]けない。", "sentence_source": "generated"}, {"text": "山で霧が出て、方位磁石だけに頼って下山した。", "target_word": "頼って", "complexity_tier": "T3", "furigana": "山[やま]で霧[きり]が出[で]て、方位磁石[ほういじしゃく]だけに頼[たよ]って下山[げざん]した。", "sentence_source": "generated"}, {"text": "彼女は困ったとき、いつも姉に頼る。", "target_word": "頼る", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は困[こま]ったとき、いつも姉[あね]に頼[たよ]る。", "sentence_source": "generated"}], "morphological_forms": [{"form": "頼る", "label": "終止形"}, {"form": "頼らない", "label": "否定形"}, {"form": "頼ります", "label": "丁寧形"}, {"form": "頼って", "label": "て形"}, {"form": "頼った", "label": "た形"}, {"form": "頼れば", "label": "仮定形"}, {"form": "頼ろう", "label": "意志形"}], "register": "neutral", "sense_fingerprint": "自力で足りない時に他者や道具の助けを当てにする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e1d13d0-4a75-4ad6-af0d-7ff5a6956501') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35583, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "頼る", "is_correct": true, "explanation": "「直感に頼る」の形で、デザイナーが直感を当てにするのではないという文意に合う。"}, {"text": "創出する", "is_correct": false, "explanation": "作り出す動作を表し、「直感に創出する」とは言えず文が成り立たない。"}, {"text": "目指す", "is_correct": false, "explanation": "目標に向かう動詞で、「直感に目指す」とは言えないので文が崩れる。"}, {"text": "整理する", "is_correct": false, "explanation": "物事をまとめる動詞で、「直感に整理する」は意味が通らない。"}], "explanations": {"頼る": "「直感に頼る」の形で、デザイナーが直感を当てにするのではないという文意に合う。", "創出する": "作り出す動作を表し、「直感に創出する」とは言えず文が成り立たない。", "目指す": "目標に向かう動詞で、「直感に目指す」とは言えないので文が崩れる。", "整理する": "物事をまとめる動詞で、「直感に整理する」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "頼る"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏の暑さに頼って、宿題を全部終わらせた。", "explanation": "ここは〈利用〉の意味。暑さは助けを求める相手ではなく、使って役立てる対象なので、頼るとは言えない。"}, {"text": "その事故は、彼の不注意に頼って起きた。", "explanation": "ここは〈原因〉の意味。不注意は助けを求める相手ではなく、事故を引き起こす原因なので、頼るとは言えない。"}, {"text": "時間に頼って、テストの答えを書いた。", "explanation": "ここは〈やりくり〉の意味。時間は助けてくれる相手ではなく、やりくりして使うものなので、頼るとは言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea56fd11-3342-43a9-97d5-69b456bcdfc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35583, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "頼って", "is_correct": true, "explanation": "「頼ってもかまわない」の形で、同僚に助けを求めてよいという文意に合う。"}, {"text": "頼る", "is_correct": false, "explanation": "終止形のため、「同僚に頼るもかまわない」となり文が成り立たない。"}, {"text": "頼らず", "is_correct": false, "explanation": "否定の連用形のため、「頼らずもかまわない」となり文の形が崩れる。"}, {"text": "頼れ", "is_correct": false, "explanation": "命令形のため、「頼れもかまわない」は文として続かない。"}], "explanations": {"頼って": "「頼ってもかまわない」の形で、同僚に助けを求めてよいという文意に合う。", "頼る": "終止形のため、「同僚に頼るもかまわない」となり文が成り立たない。", "頼らず": "否定の連用形のため、「頼らずもかまわない」となり文の形が崩れる。", "頼れ": "命令形のため、「頼れもかまわない」は文として続かない。"}, "sentence_index": 6, "correct_answer": "頼って"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "眠気に頼って、夜更かしを続けた。", "explanation": "ここは〈負ける〉の意味。眠気は支えてくれるものではなく、抗うべき相手なので、頼るとは言えない。"}, {"text": "雨音に頼って、宿題を終わらせた。", "explanation": "ここは〈気晴らし〉の意味。雨音は助けを求める対象ではなく、気を紛らわせるものとして扱うのが自然なので、頼るとは言えない。"}, {"text": "ドアの鍵に頼って、大事な話を決めた。", "explanation": "ここは〈相談〉の意味。鍵は相談の相手にはならないので、頼るとは言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea56fd11-3342-43a9-97d5-69b456bcdfc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35583, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "困ったときは、先輩に頼りて相談する。", "corrected_sentence": "困ったときは、先輩に頼って相談する。", "error_description": "「頼る」の連用形は「頼って」。「頼りて」は誤った活用で、正しくは「頼って」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "頼る", "is_correct": true, "explanation": "「〜しかなかった」の前に置く終止形で、文の形に合う。"}, {"text": "頼った", "is_correct": false, "explanation": "過去形のため、「頼ったしかなかった」となり文の形が崩れる。"}, {"text": "頼って", "is_correct": false, "explanation": "て形のため、「頼ってしかなかった」と文として続かない。"}, {"text": "頼れ", "is_correct": false, "explanation": "命令形のため、「頼れしかなかった」と文が成り立たない。"}], "correct_form": "頼る", "base_form": "頼る", "form_label": "終止形", "sentence_index": 1, "explanations": {"頼る": "「〜しかなかった」の前に置く終止形で、文の形に合う。", "頼った": "過去形のため、「頼ったしかなかった」となり文の形が崩れる。", "頼って": "て形のため、「頼ってしかなかった」と文として続かない。", "頼れ": "命令形のため、「頼れしかなかった」と文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea56fd11-3342-43a9-97d5-69b456bcdfc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35583, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "困ったときは、姉に頼てもいい。", "corrected_sentence": "困ったときは、姉に頼ってもいい。", "error_description": "「頼る」のて形は「頼って」。「頼て」は活用の誤りで、正しくは「頼ってもいい」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "頼らない", "is_correct": true, "explanation": "否定形で、杖に頼らないと歩けないという文の意味に合う。"}, {"text": "頼る", "is_correct": false, "explanation": "肯定の終止形のため、「頼るないと」となり否定の文脈と合わない。"}, {"text": "頼って", "is_correct": false, "explanation": "て形のため、「頼ってないと」となり文として続かない。"}, {"text": "頼らず", "is_correct": false, "explanation": "否定の連用形のため、「頼らずないと」となり文の形が崩れる。"}], "correct_form": "頼らない", "base_form": "頼る", "form_label": "否定形", "sentence_index": 7, "explanations": {"頼らない": "否定形で、杖に頼らないと歩けないという文の意味に合う。", "頼る": "肯定の終止形のため、「頼るないと」となり否定の文脈と合わない。", "頼って": "て形のため、「頼ってないと」となり文として続かない。", "頼らず": "否定の連用形のため、「頼らずないと」となり文の形が崩れる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea56fd11-3342-43a9-97d5-69b456bcdfc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35586, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a24165d-25fb-4287-b029-d82fa4c8a110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35586, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「向ける」は働きかける相手を「に」で示すので、「子どもがいる層に向けて」が成り立つ。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や共同を示すので、「層と向けて」では向ける先を表せない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示すので、「層で向けて」では向ける先を表せない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞修飾に使い、「層の向けて」では動詞の向ける先にならない。"}], "correct_answer": "に", "explanations": {"に": "「向ける」は働きかける相手を「に」で示すので、「子どもがいる層に向けて」が成り立つ。", "と": "「と」は並列や共同を示すので、「層と向けて」では向ける先を表せない。", "で": "「で」は場所や手段を示すので、「層で向けて」では向ける先を表せない。", "の": "「の」は名詞修飾に使い、「層の向けて」では動詞の向ける先にならない。"}, "error_tags": {"と": "並列・共同", "で": "場所・手段", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a24165d-25fb-4287-b029-d82fa4c8a110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35586, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある人たちのまとまり。例えば、お金持ちの人たちのこと。", "primary_collocate": null, "pronunciation": "そう", "ipa": "soː", "syllable_count": 2, "sentences": [{"text": "この店の商品は、若い層によく売れています。", "target_word": "層", "complexity_tier": "T3", "furigana": "この店[みせ]の商品[しょうひん]は、若[わか]い層[そう]によく売[う]れています。", "sentence_source": "generated"}, {"text": "収入が高い層ほど、貯金が多い傾向があります。", "target_word": "層", "complexity_tier": "T3", "furigana": "収入[しゅうにゅう]が高[たか]い層[そう]ほど、貯金[ちょきん]が多[おお]い傾向[けいこう]があります。", "sentence_source": "generated"}, {"text": "その雑誌は、二十代の女性の層を狙って作られた。", "target_word": "層", "complexity_tier": "T3", "furigana": "その雑誌[ざっし]は、二十代[にじゅうだい]の女性[じょせい]の層[そう]を狙[ねら]って作[つく]られた。", "sentence_source": "generated"}, {"text": "年配の層には、紙の新聞を読む人が多いです。", "target_word": "層", "complexity_tier": "T3", "furigana": "年配[ねんぱい]の層[そう]には、紙[かみ]の新聞[しんぶん]を読[よ]む人[ひと]が多[おお]いです。", "sentence_source": "generated"}, {"text": "新しい政策は、収入の低い層を助けるためのものです。", "target_word": "層", "complexity_tier": "T3", "furigana": "新[あたら]しい政策[せいさく]は、収入[しゅうにゅう]の低[ひく]い層[そう]を助[たす]けるためのものです。", "sentence_source": "generated"}, {"text": "広い層に読まれるよう、やさしい言葉で書きました。", "target_word": "層", "complexity_tier": "T3", "furigana": "広[ひろ]い層[そう]に読[よ]まれるよう、やさしい言葉[ことば]で書[か]きました。", "sentence_source": "generated"}, {"text": "豊かな層だけが得をする社会は、公平とは言えません。", "target_word": "層", "complexity_tier": "T3", "furigana": "豊[ゆた]かな層[そう]だけが得[とく]をする社会[しゃかい]は、公平[こうへい]とは言[い]えません。", "sentence_source": "generated"}, {"text": "子どもがいる層に向けて、安い家族用プランを出した。", "target_word": "層", "complexity_tier": "T3", "furigana": "子[こ]どもがいる層[そう]に向[む]けて、安[やす]い家族用[かぞくよう]プランを出[だ]した。", "sentence_source": "generated"}, {"text": "会社は、これまで来なかった層の客を呼びたいと考えている。", "target_word": "層", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は、これまで来[こ]なかった層[そう]の客[きゃく]を呼[よ]びたいと考[かんが]えている。", "sentence_source": "generated"}, {"text": "中間の層が減ると、社会の不安が大きくなると言われる。", "target_word": "層", "complexity_tier": "T3", "furigana": "中間[ちゅうかん]の層[そう]が減[へ]ると、社会[しゃかい]の不安[ふあん]が大[おお]きくなると言[い]われる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "層", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "年齢・収入などで分けた社会の人々の集まり（階層）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e74715c8-80af-41e0-bc9c-e29c3da457dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35586, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "層", "is_correct": true, "explanation": "「若い層」は年齢でまとめた人々の集まりを表し、文に合う。"}, {"text": "方向", "is_correct": false, "explanation": "「若い方向によく売れる」は意味が通らず、人々の集まりを表せない。"}, {"text": "品質", "is_correct": false, "explanation": "「若い品質」は成り立たず、人の集まりを指せない。"}, {"text": "態度", "is_correct": false, "explanation": "「若い態度」では人々のまとまりを表せない。"}], "explanations": {"層": "「若い層」は年齢でまとめた人々の集まりを表し、文に合う。", "方向": "「若い方向によく売れる」は意味が通らず、人々の集まりを表せない。", "品質": "「若い品質」は成り立たず、人の集まりを指せない。", "態度": "「若い態度」では人々のまとまりを表せない。"}, "sentence_index": 0, "correct_answer": "層"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この町の層は、駅の北側にまとまっている。", "explanation": "ここは〈区画〉（土地の区切り）の意味。〈層〉は人々のまとまりなので、土地の区切りには使えない。"}, {"text": "階段の層が一つ欠けている。", "explanation": "ここは〈段〉の意味。〈層〉は人の集まりや重なりを指し、階段の一段には使わない。"}, {"text": "この本の層だけ読みました。", "explanation": "ここは〈部分〉の意味。〈層〉は人々のまとまりなので、本の一部には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a24165d-25fb-4287-b029-d82fa4c8a110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35586, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "層", "is_correct": true, "explanation": "「豊かな層」は豊かな人々のまとまりを指し、文に合う。"}, {"text": "方針", "is_correct": false, "explanation": "「豊かな方針だけが得をする」は意味が通らず、人々の集まりを表せない。"}, {"text": "手順", "is_correct": false, "explanation": "「豊かな手順」は成り立たず、人々を指せない。"}, {"text": "規則", "is_correct": false, "explanation": "「豊かな規則」では集団を表せない。"}], "explanations": {"層": "「豊かな層」は豊かな人々のまとまりを指し、文に合う。", "方針": "「豊かな方針だけが得をする」は意味が通らず、人々の集まりを表せない。", "手順": "「豊かな手順」は成り立たず、人々を指せない。", "規則": "「豊かな規則」では集団を表せない。"}, "sentence_index": 6, "correct_answer": "層"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "田中さんの層は、五十歳です。", "explanation": "ここは〈年齢〉の意味。〈層〉は同じ特徴をもつ人々のまとまりで、一人の年齢は指せない。"}, {"text": "彼は三年で層が上がった。", "explanation": "ここは〈階級〉の意味。〈層〉は人々のまとまりで、個人の昇進には使えない。"}, {"text": "彼は会社で層を失った。", "explanation": "ここは〈地位〉の意味。〈層〉は人々の集まりで、一人の立場は指せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a24165d-25fb-4287-b029-d82fa4c8a110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35586, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "高齢の層を、アンケートの回答が多く届いた。", "corrected_sentence": "高齢の層から、アンケートの回答が多く届いた。", "error_description": "「層」に続く助詞が誤り。「届く」は起点を「から」で示すので、「を」は誤り。正しくは「から」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a24165d-25fb-4287-b029-d82fa4c8a110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35586, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "中間の層が属する人々は、税金の負担が重いと感じている。", "corrected_sentence": "中間の層に属する人々は、税金の負担が重いと感じている。", "error_description": "「層」に続く助詞が誤り。「属する」は「に」を取るので、「が」は誤り。正しくは「に」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a24165d-25fb-4287-b029-d82fa4c8a110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
