INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35588, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "function", "definition": "ほかのものを除いた残りを表すこと。", "primary_collocate": null, "pronunciation": "いがい", "ipa": "iɡai", "syllable_count": 3, "sentences": [{"text": "日曜日以外は、毎日この店が開いています。", "target_word": "以外", "complexity_tier": "T3", "furigana": "日曜日[にちようび]以外[いがい]は、毎日[まいにち]この店[みせ]が開[あ]いています。", "sentence_source": "generated"}, {"text": "私以外の家族は、みんな辛い物が好きです。", "target_word": "以外", "complexity_tier": "T3", "furigana": "私[わたし]以外[いがい]の家族[かぞく]は、みんな辛[から]い物[もの]が好[す]きです。", "sentence_source": "generated"}, {"text": "犬以外の動物は、このホテルに連れて入れません。", "target_word": "以外", "complexity_tier": "T3", "furigana": "犬[いぬ]以外[いがい]の動物[どうぶつ]は、このホテルに連[つ]れて入[はい]れません。", "sentence_source": "generated"}, {"text": "彼は仕事以外の話をほとんどしない。", "target_word": "以外", "complexity_tier": "T3", "furigana": "彼[かれ]は仕事[しごと]以外[いがい]の話[はなし]をほとんどしない。", "sentence_source": "generated"}, {"text": "現金以外では払えないので、先に銀行へ行きました。", "target_word": "以外", "complexity_tier": "T3", "furigana": "現金[げんきん]以外[いがい]では払[はら]えないので、先[さき]に銀行[ぎんこう]へ行[い]きました。", "sentence_source": "generated"}, {"text": "田中さん以外は、全員会議に来ました。", "target_word": "以外", "complexity_tier": "T3", "furigana": "田中[たなか]さん以外[いがい]は、全員[ぜんいん]会議[かいぎ]に来[き]ました。", "sentence_source": "generated"}, {"text": "この道以外に、駅へ行く方法はありません。", "target_word": "以外", "complexity_tier": "T3", "furigana": "この道[みち]以外[いがい]に、駅[えき]へ行[い]く方法[ほうほう]はありません。", "sentence_source": "generated"}, {"text": "英語以外の外国語も、勉強してみたいです。", "target_word": "以外", "complexity_tier": "T3", "furigana": "英語[えいご]以外[いがい]の外国語[がいこくご]も、勉強[べんきょう]してみたいです。", "sentence_source": "generated"}, {"text": "自分以外の人の気持ちを、考えてみましょう。", "target_word": "以外", "complexity_tier": "T3", "furigana": "自分[じぶん]以外[いがい]の人[ひと]の気持[きも]ちを、考[かんが]えてみましょう。", "sentence_source": "generated"}, {"text": "水以外は持ちこめませんから、飲み物は注意してください。", "target_word": "以外", "complexity_tier": "T3", "furigana": "水[みず]以外[いがい]は持[も]ちこめませんから、飲[の]み物[もの]は注意[ちゅうい]してください。", "sentence_source": "generated"}], "morphological_forms": [{"form": "以外", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "名詞のあとにつき、それを除いた残りを表す", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T1: contains vocabulary far above tier T1: 持ちこめ (Zipf 1.12)']::text[], 'e74715c8-80af-41e0-bc9c-e29c3da457dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35588, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "以外", "is_correct": true, "explanation": "「日曜日以外」は日曜日を除いた残りを表し、文に合う。"}, {"text": "以上", "is_correct": false, "explanation": "「日曜日以上は毎日開いている」は文が成り立たない。"}, {"text": "以内", "is_correct": false, "explanation": "「日曜日以内」は範囲の意味になり、文に合わない。"}, {"text": "以下", "is_correct": false, "explanation": "「日曜日以下」は意味が通らない。"}], "explanations": {"以外": "「日曜日以外」は日曜日を除いた残りを表し、文に合う。", "以上": "「日曜日以上は毎日開いている」は文が成り立たない。", "以内": "「日曜日以内」は範囲の意味になり、文に合わない。", "以下": "「日曜日以下」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "以外"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "受付は三日以外から始まります。", "explanation": "ここは〈以後〉（三日から後）の意味。〈以外〉は除くことなので、三日を起点とする期間は表せない。"}, {"text": "試験は以外に簡単でした。", "explanation": "ここは〈意外〉（思いがけない）の意味。〈以外〉は除外を表すので、感想には使えない。"}, {"text": "その映画は想像以外に面白かった。", "explanation": "ここは〈想像以上〉（想像より上）の意味。〈以外〉は除外で、程度の上回りを表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a24165d-25fb-4287-b029-d82fa4c8a110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35588, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "以外", "is_correct": true, "explanation": "「この道以外に」は、この道を除いた別の手段を表し、文に合う。"}, {"text": "以降", "is_correct": false, "explanation": "「この道以降」は時点以後の意味で、場所には使えない。"}, {"text": "以前", "is_correct": false, "explanation": "「この道以前」は時点の前の意味で、場所には使えない。"}, {"text": "以来", "is_correct": false, "explanation": "「この道以来」は時点を起点とする意味で、文に合わない。"}], "explanations": {"以外": "「この道以外に」は、この道を除いた別の手段を表し、文に合う。", "以降": "「この道以降」は時点以後の意味で、場所には使えない。", "以前": "「この道以前」は時点の前の意味で、場所には使えない。", "以来": "「この道以来」は時点を起点とする意味で、文に合わない。"}, "sentence_index": 6, "correct_answer": "以外"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この部屋の定員は十人以外です。", "explanation": "ここは〈以下〉（十人を上限とする）の意味。〈以外〉は除くことなので、上限は表せない。"}, {"text": "駅までは十分以外で歩けます。", "explanation": "ここは〈以内〉（十分の範囲の中）の意味。〈以外〉は除くことなので、時間の範囲は表せない。"}, {"text": "彼は十年以外からこの町に住んでいる。", "explanation": "ここは〈以前〉（十年より前）の意味。〈以外〉は除外で、起点より前の時期は表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a24165d-25fb-4287-b029-d82fa4c8a110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35588, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祝日以外を、毎日この店が開いています。", "corrected_sentence": "祝日以外は、毎日この店が開いています。", "error_description": "「以外」に続く助詞が誤り。主題を示す「は」が正しく、「を」は他動詞の目的語に使うため誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a24165d-25fb-4287-b029-d82fa4c8a110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35588, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この道以外を、駅へ行く道はありません。", "corrected_sentence": "この道以外に、駅へ行く道はありません。", "error_description": "「以外」に続く助詞が誤り。「ありません」の文では「に」で別の手段を示すので、「を」は誤り。正しくは「に」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a24165d-25fb-4287-b029-d82fa4c8a110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35590, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "低い", "is_correct": true, "explanation": "対義語。「性能が高い」の反対は「性能が低い」。"}, {"text": "軽い", "is_correct": false, "explanation": "「重い」の対義語で、程度の高低の対義語ではない。"}, {"text": "浅い", "is_correct": false, "explanation": "「深い」の対義語。程度の高さの反対ではない。"}, {"text": "易しい", "is_correct": false, "explanation": "「難しい」の対義語。性能の反対にはならない。"}], "correct_answer": "低い", "explanations": {"低い": "対義語。「性能が高い」の反対は「性能が低い」。", "軽い": "「重い」の対義語で、程度の高低の対義語ではない。", "浅い": "「深い」の対義語。程度の高さの反対ではない。", "易しい": "「難しい」の対義語。性能の反対にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33441540-5e68-48c9-ab4d-7372add938d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35590, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "低い", "is_correct": true, "explanation": "対義語。「評判が高い」の反対は「評判が低い」。"}, {"text": "狭い", "is_correct": false, "explanation": "「広い」の対義語で、評判の程度には使わない。"}, {"text": "薄い", "is_correct": false, "explanation": "「厚い」の対義語。評判とは関係しない。"}, {"text": "弱い", "is_correct": false, "explanation": "「強い」の対義語。評判の高低の反対語にはならない。"}], "correct_answer": "低い", "explanations": {"低い": "対義語。「評判が高い」の反対は「評判が低い」。", "狭い": "「広い」の対義語で、評判の程度には使わない。", "薄い": "「厚い」の対義語。評判とは関係しない。", "弱い": "「強い」の対義語。評判の高低の反対語にはならない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33441540-5e68-48c9-ab4d-7372add938d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35590, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "質・評価・能力・性能などの程度がすぐれていること。", "primary_collocate": null, "pronunciation": "たかい", "ipa": "takai", "syllable_count": 3, "sentences": [{"text": "この店の料理は質が高いので、いつも客でいっぱいだ。", "target_word": "高い", "complexity_tier": "T3", "furigana": "この店[みせ]の料理[りょうり]は質[しつ]が高[たか]いので、いつも客[きゃく]でいっぱいだ。", "sentence_source": "generated"}, {"text": "彼の技術は世界でも評価が高い。", "target_word": "高い", "complexity_tier": "T3", "furigana": "彼[かれ]の技術[ぎじゅつ]は世界[せかい]でも評価[ひょうか]が高[たか]い。", "sentence_source": "generated"}, {"text": "品質が高い製品は、長く使える。", "target_word": "高い", "complexity_tier": "T3", "furigana": "品質[ひんしつ]が高[たか]い製品[せいひん]は、長[なが]く使[つか]える。", "sentence_source": "generated"}, {"text": "このカメラは性能が高いと評判だ。", "target_word": "高い", "complexity_tier": "T3", "furigana": "このカメラは性能[せいのう]が高[たか]いと評判[ひょうばん]だ。", "sentence_source": "generated"}, {"text": "先生は私の作文を高く評価してくれた。", "target_word": "高く", "complexity_tier": "T3", "furigana": "先生[せんせい]は私[わたし]の作文[さくぶん]を高[たか]く評価[ひょうか]してくれた。", "sentence_source": "generated"}, {"text": "彼女は能力が高いので、新しい仕事もすぐに覚えた。", "target_word": "高い", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は能力[のうりょく]が高[たか]いので、新[あたら]しい仕事[しごと]もすぐに覚[おぼ]えた。", "sentence_source": "generated"}, {"text": "この大学は教育の質が高いことで有名だ。", "target_word": "高い", "complexity_tier": "T3", "furigana": "この大学[だいがく]は教育[きょういく]の質[しつ]が高[たか]いことで有名[ゆうめい]だ。", "sentence_source": "generated"}, {"text": "質の高い睡眠をとると、朝まで元気でいられる。", "target_word": "高い", "complexity_tier": "T3", "furigana": "質[しつ]の高[たか]い睡眠[すいみん]をとると、朝[あさ]まで元気[げんき]でいられる。", "sentence_source": "generated"}, {"text": "彼の書いた小説は芸術性が高く、多くの賞を受けた。", "target_word": "高く", "complexity_tier": "T3", "furigana": "彼[かれ]の書[か]いた小説[しょうせつ]は芸術性[げいじゅつせい]が高[たか]く、多[おお]くの賞[しょう]を受[う]けた。", "sentence_source": "generated"}, {"text": "評判の高いレストランなので、予約が取れなかった。", "target_word": "高い", "complexity_tier": "T3", "furigana": "評判[ひょうばん]の高[たか]いレストランなので、予約[よやく]が取[と]れなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "高い", "label": "終止形・連体形"}, {"form": "高く", "label": "連用形"}, {"form": "高かった", "label": "過去形"}, {"form": "高くない", "label": "否定形"}, {"form": "高ければ", "label": "仮定形"}], "register": "neutral (plain form)", "sense_fingerprint": "質・評価・能力・性能などの程度がすぐれている、という意味の「高い」(値段や高さではない)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07e99574-5a76-414c-a8d8-98dc1fc98f23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35590, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高い", "is_correct": true, "explanation": "「質が高い」は料理の出来映えがすぐれているという意味で、文の意味に合う。"}, {"text": "広い", "is_correct": false, "explanation": "広いは面積や範囲の広さを表す。料理の質には使えず、「質が広い」は成り立たない。"}, {"text": "重い", "is_correct": false, "explanation": "重いは重さや負担の大きさを表す。質の程度とは結びつかず、ここには入らない。"}, {"text": "遅い", "is_correct": false, "explanation": "遅いは速さが低いことを表す。質の程度は言えないので、「質が遅い」は合わない。"}], "explanations": {"高い": "「質が高い」は料理の出来映えがすぐれているという意味で、文の意味に合う。", "広い": "広いは面積や範囲の広さを表す。料理の質には使えず、「質が広い」は成り立たない。", "重い": "重いは重さや負担の大きさを表す。質の程度とは結びつかず、ここには入らない。", "遅い": "遅いは速さが低いことを表す。質の程度は言えないので、「質が遅い」は合わない。"}, "sentence_index": 0, "correct_answer": "高い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会議の時間が高くて、なかなか終わらなかった。", "explanation": "ここは〈長い〉の意味。時間の長さは「長い」で言い、「時間が高い」とは言わない。"}, {"text": "この布は生地の厚さが高くて、冬でも暖かい。", "explanation": "ここは〈厚い〉の意味。厚さの程度は「厚い」で表すので、「厚さが高い」とは言わない。"}, {"text": "彼女は体力が高いので、長距離を走り切れる。", "explanation": "ここは〈強い〉の意味。体力の程度は「強い」で表すので、「体力が高い」とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33441540-5e68-48c9-ab4d-7372add938d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35590, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高い", "is_correct": true, "explanation": "「教育の質が高い」は教育の水準がすぐれているという意味で、文に合う。"}, {"text": "大きい", "is_correct": false, "explanation": "大きいは大小や規模を表す。「質が大きい」とは言わないので不自然。"}, {"text": "硬い", "is_correct": false, "explanation": "硬いは固さや堅さを表す。質の程度には使わないので合わない。"}, {"text": "冷たい", "is_correct": false, "explanation": "冷たいは温度や態度の冷たさを表す。「質が冷たい」は成り立たない。"}], "explanations": {"高い": "「教育の質が高い」は教育の水準がすぐれているという意味で、文に合う。", "大きい": "大きいは大小や規模を表す。「質が大きい」とは言わないので不自然。", "硬い": "硬いは固さや堅さを表す。質の程度には使わないので合わない。", "冷たい": "冷たいは温度や態度の冷たさを表す。「質が冷たい」は成り立たない。"}, "sentence_index": 6, "correct_answer": "高い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このクラスは出席者の数が高いので、教室が狭く感じる。", "explanation": "ここは〈多い〉の意味。人の数の多さは「多い」で表すので、「数が高い」とは言わない。"}, {"text": "この大学は入試の審査が高いので、受験者は多くない。", "explanation": "ここは〈厳しい〉の意味。審査の厳しさは「厳しい」で言い、「審査が高い」とは言わない。"}, {"text": "この地域は自然が高くて、観光客が多い。", "explanation": "ここは〈豊かだ〉の意味。自然の多さや豊かさは「豊か」で言うので、「自然が高い」とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33441540-5e68-48c9-ab4d-7372add938d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35590, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この店は料理の質を高いので、昼でも席が埋まっている。", "corrected_sentence": "この店は料理の質が高いので、昼でも席が埋まっている。", "error_description": "誤りは「質を」の助詞。形容詞「高い」の主語は「が」で示すので「質が高い」が正しい。「を」は動詞の目的語を示すため、ここでは文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "高い", "is_correct": true, "explanation": "終止形。「評価が高い」と文を言い切る形で、本文の形と一致する。"}, {"text": "高く", "is_correct": false, "explanation": "連用形。文を終えられず、「高く評価する」のように後ろへ続く形。"}, {"text": "高さ", "is_correct": false, "explanation": "名詞形。文を言い切れず、「評価の高さ」のように名詞に続く形。"}, {"text": "高ければ", "is_correct": false, "explanation": "仮定形。「〜なら」という条件を表し、文を言い切れない。"}], "correct_form": "高い", "base_form": "高い", "form_label": "終止形（述語）", "sentence_index": 1, "explanations": {"高い": "終止形。「評価が高い」と文を言い切る形で、本文の形と一致する。", "高く": "連用形。文を終えられず、「高く評価する」のように後ろへ続く形。", "高さ": "名詞形。文を言い切れず、「評価の高さ」のように名詞に続く形。", "高ければ": "仮定形。「〜なら」という条件を表し、文を言い切れない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33441540-5e68-48c9-ab4d-7372add938d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35590, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この旅館は接客の質が高くことで有名だ。", "corrected_sentence": "この旅館は接客の質が高いことで有名だ。", "error_description": "誤りは「高く」。「こと」という名詞の前は連体形「高い」が必要。連用形「高く」を使うと「高くこと」となり、文法的に成り立たない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "高い", "is_correct": true, "explanation": "連体形。「質の高い睡眠」のように後ろの名詞を修飾する形で、本文と一致する。"}, {"text": "高くて", "is_correct": false, "explanation": "て形。名詞を直接修飾できず、「高くて睡眠」は成り立たない。"}, {"text": "高そう", "is_correct": false, "explanation": "様態の形。見た目の判断を表し、睡眠の質の程度を述べる文には合わない。"}, {"text": "高かろう", "is_correct": false, "explanation": "推量の形。名詞を直接修飾できず、「高かろう睡眠」は成り立たない。"}], "correct_form": "高い", "base_form": "高い", "form_label": "連体形（名詞修飾）", "sentence_index": 7, "explanations": {"高い": "連体形。「質の高い睡眠」のように後ろの名詞を修飾する形で、本文と一致する。", "高くて": "て形。名詞を直接修飾できず、「高くて睡眠」は成り立たない。", "高そう": "様態の形。見た目の判断を表し、睡眠の質の程度を述べる文には合わない。", "高かろう": "推量の形。名詞を直接修飾できず、「高かろう睡眠」は成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33441540-5e68-48c9-ab4d-7372add938d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35591, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "低い", "is_correct": true, "explanation": "対義語。「技術力が高い」の程度の高さに対して、程度の低さを表す語になる。"}, {"text": "狭い", "is_correct": false, "explanation": "空間の広さの対義語で、技術力の程度の高低とは関係しない。"}, {"text": "遅い", "is_correct": false, "explanation": "速さの対義語で、程度の大きさや価値の対義語ではない。"}, {"text": "浅い", "is_correct": false, "explanation": "深さの対義語で、ここでの程度の高低の対義語にはならない。"}], "correct_answer": "低い", "explanations": {"低い": "対義語。「技術力が高い」の程度の高さに対して、程度の低さを表す語になる。", "狭い": "空間の広さの対義語で、技術力の程度の高低とは関係しない。", "遅い": "速さの対義語で、程度の大きさや価値の対義語ではない。", "浅い": "深さの対義語で、ここでの程度の高低の対義語にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64e7d4f9-aee5-437b-a6be-eb6c0a13dc6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35591, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "低い", "is_correct": true, "explanation": "対義語。「完成度が高い」に対して、完成度の程度が小さいことを表す。"}, {"text": "軽い", "is_correct": false, "explanation": "重さの対義語で、完成度の程度の高低とは関係しない。"}, {"text": "硬い", "is_correct": false, "explanation": "柔らかさの対義語で、程度の高低を表す語ではない。"}, {"text": "短い", "is_correct": false, "explanation": "長さの対義語で、完成度の程度とは無関係。"}], "correct_answer": "低い", "explanations": {"低い": "対義語。「完成度が高い」に対して、完成度の程度が小さいことを表す。", "軽い": "重さの対義語で、完成度の程度の高低とは関係しない。", "硬い": "柔らかさの対義語で、程度の高低を表す語ではない。", "短い": "長さの対義語で、完成度の程度とは無関係。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64e7d4f9-aee5-437b-a6be-eb6c0a13dc6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35591, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "程度がすぐれている、価値が大きいという意味の形容詞。", "primary_collocate": null, "pronunciation": "たかい", "ipa": "takai", "syllable_count": 3, "sentences": [{"text": "不確実性の高い技術的課題に挑む起業家に対し、リスクマネーを供給することで、彼らは市場の失敗を補完し、破壊的なイノベーションの萌芽を育むのである。", "target_word": "高い", "complexity_tier": "T5", "furigana": "不確実性(ふかくじつせい)の高(たか)い技術的(ぎじゅつてき)課題(かだい)に挑(いど)む起業家(きぎょうか)に対(たい)し、リスクマネーを供給(きょうきゅう)することで、彼(かれ)らは市場(しじょう)の失敗(しっぱい)を補完(ほかん)し、破壊的(はかいてき)なイノベーションの萌芽(ほうが)を育(はぐく)むのである。", "sentence_source": "mined"}, {"text": "その作品は、完成度の高さと美しさで人々を魅了しました。", "target_word": "高さ", "complexity_tier": "T4", "furigana": "その作品[さくひん]は、完成度[かんせいど]の高[たか]さと美[うつく]しさで人々[ひとびと]を魅了[みりょう]しました。", "sentence_source": "generated"}, {"text": "この鞄は耐久性が高く、長く使う人が多い。", "target_word": "高く", "complexity_tier": "T3", "furigana": "この鞄[かばん]は耐久性[たいきゅうせい]が高[たか]く、長[なが]く使[つか]う人[ひと]が多[おお]い。", "sentence_source": "generated"}, {"text": "この工場は技術力が高いと評判で、海外からも注文が来る。", "target_word": "高い", "complexity_tier": "T3", "furigana": "この工場は技術力[ぎじゅつりょく]が高[たか]いと評判[ひょうばん]で、海外[かいがい]からも注文[ちゅうもん]が来[く]る。", "sentence_source": "generated"}, {"text": "彼女は意識が高く、毎日ごみの分別を欠かさない。", "target_word": "高く", "complexity_tier": "T3", "furigana": "彼女(かのじょ)は意識(いしき)が高(たか)く、毎日(まいにち)ごみの分別(ぶんべつ)を欠(か)かさない。", "sentence_source": "generated"}, {"text": "このワインは品質が高く、ヨーロッパでも売れている。", "target_word": "高く", "complexity_tier": "T3", "furigana": "このワインは品質[ひんしつ]が高[たか]く、ヨーロッパでも売[う]れている。", "sentence_source": "generated"}, {"text": "山田さんは評価の高い医者で、遠くから患者が来る。", "target_word": "高い", "complexity_tier": "T3", "furigana": "山田(やまだ)さんは評価(ひょうか)の高(たか)い医者(いしゃ)で、遠(とお)くから患者(かんじゃ)が来(く)る。", "sentence_source": "generated"}, {"text": "この絵は芸術的価値が高いので、美術館が大切に保管している。", "target_word": "高い", "complexity_tier": "T4", "furigana": "この絵(え)は芸術的(げいじゅつてき)価値(かち)が高(たか)いので、美術館(びじゅつかん)が大切(たいせつ)に保管(ほかん)している。", "sentence_source": "generated"}, {"text": "この大学は研究の水準が高く、世界中から学生が集まる。", "target_word": "高く", "complexity_tier": "T3", "furigana": "この大学は研究[けんきゅう]の水準[すいじゅん]が高[たか]く、世界中[せかいじゅう]から学生[がくせい]が集[あつ]まる。", "sentence_source": "generated"}, {"text": "この店は料理の完成度が高いので、遠くからも客が訪れる。", "target_word": "高い", "complexity_tier": "T3", "furigana": "この店は料理[りょうり]の完成度[かんせいど]が高[たか]いので、遠[とお]くからも客[きゃく]が訪[おとず]れる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "高い", "label": "基本形"}, {"form": "高く", "label": "連用形"}, {"form": "高くない", "label": "否定形"}, {"form": "高かった", "label": "過去形"}, {"form": "高ければ", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "程度・価値・可能性などが大きいことを表す形容詞(たかい)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: contains vocabulary far above tier T1: 萌芽 (Zipf 2.48)','sentence 4 above tier T1: 3 words above tier T1 (max 2): ごみ (Zipf 3.88), 分別 (Zipf 3.6), 欠かさ (Zipf 3.32)']::text[], '08e7e9f6-0f05-455b-afc5-ee87762d7379') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35591, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高い", "is_correct": true, "explanation": "「不確実性の高い課題」の形で、程度が大きいことを表す連体形。名詞を修飾できる。"}, {"text": "高く", "is_correct": false, "explanation": "連用形で、「不確実性の」と名詞の間に入って修飾する形にならない。"}, {"text": "高さ", "is_correct": false, "explanation": "名詞形になり、「不確実性の高さ技術的課題」では修飾が成り立たない。"}, {"text": "高くて", "is_correct": false, "explanation": "て形で、名詞を直接修飾できず、「の」の後に続けられない。"}], "explanations": {"高い": "「不確実性の高い課題」の形で、程度が大きいことを表す連体形。名詞を修飾できる。", "高く": "連用形で、「不確実性の」と名詞の間に入って修飾する形にならない。", "高さ": "名詞形になり、「不確実性の高さ技術的課題」では修飾が成り立たない。", "高くて": "て形で、名詞を直接修飾できず、「の」の後に続けられない。"}, "sentence_index": 0, "correct_answer": "高い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今日の展示会は来場者が高いと聞いた。", "explanation": "〈多い〉の意味。人の数には「高い」を使えず、「来場者が多い」と言うのが自然。"}, {"text": "このスープは味が高くて、体がよく温まる。", "explanation": "〈濃い〉の意味。味の濃さは「濃い」で表し、「高い」では不自然になる。"}, {"text": "この箱は重さが高くて、一人では運べない。", "explanation": "〈重い〉の意味。重さには「重い」を使い、「高い」は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64e7d4f9-aee5-437b-a6be-eb6c0a13dc6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35591, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高い", "is_correct": true, "explanation": "「評価の高い医者」の形で、評価が大きいことを表す連体形。名詞を修飾する。"}, {"text": "高め", "is_correct": false, "explanation": "「やや高め」の意味で、「評価の」に続けて名詞を修飾する形にならない。"}, {"text": "高み", "is_correct": false, "explanation": "「高い所」を表す名詞で、評価の程度を表さないので「評価の高み医者」は成り立たない。"}, {"text": "高まり", "is_correct": false, "explanation": "「高まる」の名詞形で評価が上がる動きを表すが、「評価の高まり医者」の形にならない。"}], "explanations": {"高い": "「評価の高い医者」の形で、評価が大きいことを表す連体形。名詞を修飾する。", "高め": "「やや高め」の意味で、「評価の」に続けて名詞を修飾する形にならない。", "高み": "「高い所」を表す名詞で、評価の程度を表さないので「評価の高み医者」は成り立たない。", "高まり": "「高まる」の名詞形で評価が上がる動きを表すが、「評価の高まり医者」の形にならない。"}, "sentence_index": 6, "correct_answer": "高い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この店は駅から高いので、すぐに行ける。", "explanation": "〈近い〉の意味。距離には「高い」を使わず、「駅から近い」と言うのが自然。"}, {"text": "この路地は高いので、車は入れない。", "explanation": "〈狭い〉の意味。道幅には「高い」を使えず、「狭い」と言うのが自然。"}, {"text": "この店は開店時間が高いので、夜中に行ける。", "explanation": "〈早い〉の意味。時刻には「早い」を使い、「高い」では開店時間を表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64e7d4f9-aee5-437b-a6be-eb6c0a13dc6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35591, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この商品は品質が高いて、売れ行きも好調だ。", "corrected_sentence": "この商品は品質が高くて、売れ行きも好調だ。", "error_description": "形容詞の連用形の誤り。「て」で続けるときは「高い」の「い」を「く」に変えて「高くて」とする。「高いて」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "高さ", "is_correct": true, "explanation": "「完成度の高さと美しさ」で、程度を名詞として並列している。"}, {"text": "高く", "is_correct": false, "explanation": "連用形で、名詞として「と美しさ」に続けられない。"}, {"text": "高かった", "is_correct": false, "explanation": "過去形で、名詞として並列の「と」に続けられない。"}, {"text": "高ければ", "is_correct": false, "explanation": "仮定形で、「高ければと美しさ」の形にならず、並列が成り立たない。"}], "correct_form": "高さ", "base_form": "高い", "form_label": "名詞化（〜さ）", "sentence_index": 1, "explanations": {"高さ": "「完成度の高さと美しさ」で、程度を名詞として並列している。", "高く": "連用形で、名詞として「と美しさ」に続けられない。", "高かった": "過去形で、名詞として並列の「と」に続けられない。", "高ければ": "仮定形で、「高ければと美しさ」の形にならず、並列が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64e7d4f9-aee5-437b-a6be-eb6c0a13dc6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35591, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その選手は得点力が高き、チームの中心だ。", "corrected_sentence": "その選手は得点力が高く、チームの中心だ。", "error_description": "活用形の誤り。文中で「得点力が高く、〜」と続ける連用形が正しく、文語の連体形「高き」は現代文では文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "高い", "is_correct": true, "explanation": "基本形で、「価値が高いので」と理由を述べる形として合う。"}, {"text": "高くない", "is_correct": false, "explanation": "否定形で、「価値が高くないので」は理由の意味が反対になる。"}, {"text": "高くて", "is_correct": false, "explanation": "て形で、「ので」に続けて理由を述べる形として成り立たない。"}, {"text": "高そう", "is_correct": false, "explanation": "様態の形で、「高そうなので」の形が必要になり、ここでは成り立たない。"}], "correct_form": "高い", "base_form": "高い", "form_label": "基本形（連体・終止）", "sentence_index": 7, "explanations": {"高い": "基本形で、「価値が高いので」と理由を述べる形として合う。", "高くない": "否定形で、「価値が高くないので」は理由の意味が反対になる。", "高くて": "て形で、「ので」に続けて理由を述べる形として成り立たない。", "高そう": "様態の形で、「高そうなので」の形が必要になり、ここでは成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64e7d4f9-aee5-437b-a6be-eb6c0a13dc6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35592, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「廊下に出ました」は出る先を「に」で示すので成り立つ。"}, {"text": "で", "is_correct": false, "explanation": "「で」は動作の場所を示すので、「廊下で出ました」は出る先を表せず不自然。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すので、出る先を表せず不自然。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞修飾に使い、「廊下の出ました」では動詞の行き先にならない。"}], "correct_answer": "に", "explanations": {"に": "「廊下に出ました」は出る先を「に」で示すので成り立つ。", "で": "「で」は動作の場所を示すので、「廊下で出ました」は出る先を表せず不自然。", "と": "「と」は並列や相手を示すので、出る先を表せず不自然。", "の": "「の」は名詞修飾に使い、「廊下の出ました」では動詞の行き先にならない。"}, "error_tags": {"で": "場所・手段", "と": "並列・共同", "の": "連体修飾"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "入る", "is_correct": true, "explanation": "「入る」は外から中へ行く意味で、「出る」の対義語。"}, {"text": "歩く", "is_correct": false, "explanation": "移動の仕方を表す語で、「出る」の対義語ではない。"}, {"text": "座る", "is_correct": false, "explanation": "姿勢を表す語で、「出る」の対義語ではない。"}, {"text": "眠る", "is_correct": false, "explanation": "睡眠を表す語で、「出る」の対義語ではない。"}], "correct_answer": "入る", "explanations": {"入る": "「入る」は外から中へ行く意味で、「出る」の対義語。", "歩く": "移動の仕方を表す語で、「出る」の対義語ではない。", "座る": "姿勢を表す語で、「出る」の対義語ではない。", "眠る": "睡眠を表す語で、「出る」の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a24165d-25fb-4287-b029-d82fa4c8a110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35592, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「庭に出たがっています」は出る先を「に」で示すので成り立つ。"}, {"text": "が", "is_correct": false, "explanation": "「庭が出たがっています」は庭を主語にする形になり、犬が出ていく文として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や共同を示すので、「犬が庭と出たがっています」は成り立たず、出る先を表せない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較や起点を示すので、「庭より出たがっています」では出る先を表せず不自然。"}], "correct_answer": "に", "explanations": {"に": "「庭に出たがっています」は出る先を「に」で示すので成り立つ。", "が": "「庭が出たがっています」は庭を主語にする形になり、犬が出ていく文として成り立たない。", "と": "「と」は並列や共同を示すので、「犬が庭と出たがっています」は成り立たず、出る先を表せない。", "より": "「より」は比較や起点を示すので、「庭より出たがっています」では出る先を表せず不自然。"}, "error_tags": {"が": "主語", "と": "並列・共同", "より": "比較・起点"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "入る", "is_correct": true, "explanation": "「入る」は外から中へ行く意味で、「出る」の対義語。"}, {"text": "走る", "is_correct": false, "explanation": "移動の仕方を表す語で、「出る」の対義語ではない。"}, {"text": "笑う", "is_correct": false, "explanation": "笑う動作を表す語で、「出る」の対義語ではない。"}, {"text": "読む", "is_correct": false, "explanation": "読書の動作を表す語で、「出る」の対義語ではない。"}], "correct_answer": "入る", "explanations": {"入る": "「入る」は外から中へ行く意味で、「出る」の対義語。", "走る": "移動の仕方を表す語で、「出る」の対義語ではない。", "笑う": "笑う動作を表す語で、「出る」の対義語ではない。", "読む": "読書の動作を表す語で、「出る」の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a24165d-25fb-4287-b029-d82fa4c8a110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35592, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "中から外へ行くこと。", "primary_collocate": null, "pronunciation": "でる", "ipa": "deɾɯ", "syllable_count": 2, "sentences": [{"text": "朝七時に家を出て、学校へ行きます。", "target_word": "出て", "complexity_tier": "T3", "furigana": "朝[あさ]七時[しちじ]に家[いえ]を出[で]て、学校[がっこう]へ行[い]きます。", "sentence_source": "generated"}, {"text": "部屋が暑かったので、廊下に出ました。", "target_word": "出ました", "complexity_tier": "T3", "furigana": "部屋[へや]が暑[あつ]かったので、廊下[ろうか]に出[で]ました。", "sentence_source": "generated"}, {"text": "彼は急いで店を出たが、雨が降っていた。", "target_word": "出た", "complexity_tier": "T3", "furigana": "彼[かれ]は急[いそ]いで店[みせ]を出[で]たが、雨[あめ]が降[ふ]っていた。", "sentence_source": "generated"}, {"text": "毎朝、八時に家を出る。", "target_word": "出る", "complexity_tier": "T3", "furigana": "毎朝[まいあさ]、八時[はちじ]に家[いえ]を出[で]る。", "sentence_source": "generated"}, {"text": "切符を買って、改札を出ます。", "target_word": "出ます", "complexity_tier": "T3", "furigana": "切符[きっぷ]を買[か]って、改札[かいさつ]を出[で]ます。", "sentence_source": "generated"}, {"text": "子どもは教室から走って出ていきました。", "target_word": "出て", "complexity_tier": "T3", "furigana": "子[こ]どもは教室[きょうしつ]から走[はし]って出[で]ていきました。", "sentence_source": "generated"}, {"text": "部屋を出るときは、電気を消してください。", "target_word": "出る", "complexity_tier": "T3", "furigana": "部屋[へや]を出[で]るときは、電気[でんき]を消[け]してください。", "sentence_source": "generated"}, {"text": "犬が庭に出たがっています。", "target_word": "出たがって", "complexity_tier": "T3", "furigana": "犬[いぬ]が庭[にわ]に出[で]たがっています。", "sentence_source": "generated"}, {"text": "会議が終わって、みんな部屋を出ました。", "target_word": "出ました", "complexity_tier": "T3", "furigana": "会議[かいぎ]が終[お]わって、みんな部屋[へや]を出[で]ました。", "sentence_source": "generated"}, {"text": "風呂から出たら、すぐに髪をかわかします。", "target_word": "出たら", "complexity_tier": "T3", "furigana": "風呂[ふろ]から出[で]たら、すぐに髪[かみ]をかわかします。", "sentence_source": "generated"}], "morphological_forms": [{"form": "出る", "label": "辞書形"}, {"form": "出ます", "label": "ます形"}, {"form": "出て", "label": "て形"}, {"form": "出た", "label": "た形"}, {"form": "出ない", "label": "ない形"}, {"form": "出たら", "label": "たら形"}], "register": "neutral", "sense_fingerprint": "建物・部屋・乗り物など、ある場所の中から外へ移動する", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T1: contains vocabulary far above tier T1: かわかし (Zipf 1.27)']::text[], 'e74715c8-80af-41e0-bc9c-e29c3da457dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35592, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "出て", "is_correct": true, "explanation": "「家を出て、学校へ行きます」は動作の順序を表すて形で、文が続く。"}, {"text": "出よう", "is_correct": false, "explanation": "意志形の「出よう、学校へ行きます」は文として続かない。"}, {"text": "出ろ", "is_correct": false, "explanation": "命令形は文の途中に置けず、文に合わない。"}, {"text": "出させ", "is_correct": false, "explanation": "使役の形では「家を出させて」となり、意味が合わない。"}], "explanations": {"出て": "「家を出て、学校へ行きます」は動作の順序を表すて形で、文が続く。", "出よう": "意志形の「出よう、学校へ行きます」は文として続かない。", "出ろ": "命令形は文の途中に置けず、文に合わない。", "出させ": "使役の形では「家を出させて」となり、意味が合わない。"}, "sentence_index": 0, "correct_answer": "出て"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "約束の時間を出る。", "explanation": "ここは〈過ぎる〉の意味。〈出る〉は中から外へ行くことで、時間の経過には使わない。"}, {"text": "毎朝、この机を出る。", "explanation": "ここは〈離れる〉の意味。〈出る〉は囲まれた場所から外へ行くことで、机のような物からは離れない。"}, {"text": "彼はこの計画を出る。", "explanation": "ここは〈抜ける〉の意味。〈出る〉は場所から外へ行くことで、計画から抜ける意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a24165d-25fb-4287-b029-d82fa4c8a110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35592, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出る", "is_correct": true, "explanation": "「部屋を出るときは」は、部屋から外へ行く時を表し、文に合う。"}, {"text": "出せ", "is_correct": false, "explanation": "「出す」の命令形で、「部屋を出せときは」は文が成り立たない。"}, {"text": "出そう", "is_correct": false, "explanation": "「出す」の意志形で、「ときは」と続かず文に合わない。"}, {"text": "出まし", "is_correct": false, "explanation": "丁寧形の語幹で、「ときは」と続かず文に合わない。"}], "explanations": {"出る": "「部屋を出るときは」は、部屋から外へ行く時を表し、文に合う。", "出せ": "「出す」の命令形で、「部屋を出せときは」は文が成り立たない。", "出そう": "「出す」の意志形で、「ときは」と続かず文に合わない。", "出まし": "丁寧形の語幹で、「ときは」と続かず文に合わない。"}, "sentence_index": 6, "correct_answer": "出る"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "風呂から沈んだら、すぐに髪をかわかします。", "explanation": "ここは〈沈む〉の意味。〈出る〉は中から外へ行くことで、水の中へ下がる動きは表せない。"}, {"text": "風呂から浮かんだら、すぐに髪をかわかします。", "explanation": "ここは〈浮かぶ〉の意味。〈出る〉は外へ行くことで、水面へ上がる動きは表せない。"}, {"text": "風呂から生まれたら、すぐに髪をかわかします。", "explanation": "ここは〈生まれる〉の意味。〈出る〉は中から外へ行くことで、誕生の意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a24165d-25fb-4287-b029-d82fa4c8a110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35592, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "朝七時に家を出で、駅へ行きます。", "corrected_sentence": "朝七時に家を出て、駅へ行きます。", "error_description": "「出る」のて形が誤り。一段動詞のて形は「出て」で、「出で」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "出ました", "is_correct": true, "explanation": "「廊下に出ました」は丁寧形の過去で、文の時制と丁寧さに合う。"}, {"text": "出ません", "is_correct": false, "explanation": "現在の否定形で、過去の出来事を述べる文と合わない。"}, {"text": "出よう", "is_correct": false, "explanation": "意志形で、「出ました」が表す過去の動作とは合わない。"}, {"text": "出でた", "is_correct": false, "explanation": "一段動詞の過去は「出た」で、「出でた」は誤った形。"}], "correct_form": "出ました", "base_form": "出る", "form_label": "丁寧形・過去", "sentence_index": 1, "explanations": {"出ました": "「廊下に出ました」は丁寧形の過去で、文の時制と丁寧さに合う。", "出ません": "現在の否定形で、過去の出来事を述べる文と合わない。", "出よう": "意志形で、「出ました」が表す過去の動作とは合わない。", "出でた": "一段動詞の過去は「出た」で、「出でた」は誤った形。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a24165d-25fb-4287-b029-d82fa4c8a110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35592, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "寝室から出だら、すぐに電気を消します。", "corrected_sentence": "寝室から出たら、すぐに電気を消します。", "error_description": "「出る」のたら形の誤り。過去形の「出た」に「ら」を付けた「出たら」が正しく、「出だら」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "出たがって", "is_correct": true, "explanation": "「出たがっています」の前の形で、て形として文の中で続く。"}, {"text": "出たがった", "is_correct": false, "explanation": "過去形で、現在の願望を述べる文と合わない。"}, {"text": "出たがる", "is_correct": false, "explanation": "辞書形で、「て」で続けられず文の形に合わない。"}, {"text": "出たがり", "is_correct": false, "explanation": "「出たがる」の連用形で、「います」に続けると文が成り立たない。"}], "correct_form": "出たがって", "base_form": "出る", "form_label": "〜たがる・て形", "sentence_index": 7, "explanations": {"出たがって": "「出たがっています」の前の形で、て形として文の中で続く。", "出たがった": "過去形で、現在の願望を述べる文と合わない。", "出たがる": "辞書形で、「て」で続けられず文の形に合わない。", "出たがり": "「出たがる」の連用形で、「います」に続けると文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a24165d-25fb-4287-b029-d82fa4c8a110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35594, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「熱がある場合は」で、条件を主題として示す正しい助詞。"}, {"text": "を", "is_correct": false, "explanation": "「場合を」では目的語になり、条件の文が成立しない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列を示すため、「場合と」では条件の文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、ここに方向の意味はないので合わない。"}], "correct_answer": "は", "explanations": {"は": "「熱がある場合は」で、条件を主題として示す正しい助詞。", "を": "「場合を」では目的語になり、条件の文が成立しない。", "と": "「と」は並列を示すため、「場合と」では条件の文として成り立たない。", "へ": "「へ」は方向を示すが、ここに方向の意味はないので合わない。"}, "error_tags": {"を": "目的語", "と": "並列", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b56acd-0d08-4b17-bc86-fe4551bddf01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35594, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「一人で行く場合は」で、条件を主題として示す正しい助詞。"}, {"text": "を", "is_correct": false, "explanation": "「場合を」では目的語になり、条件の文が成立しない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段を示すため、「場合で」は条件の文として不自然。"}, {"text": "の", "is_correct": false, "explanation": "「の」は後ろに名詞を続ける連体修飾で、「場合の」のあとに名詞がなく文が成り立たない。"}], "correct_answer": "は", "explanations": {"は": "「一人で行く場合は」で、条件を主題として示す正しい助詞。", "を": "「場合を」では目的語になり、条件の文が成立しない。", "で": "「で」は手段を示すため、「場合で」は条件の文として不自然。", "の": "「の」は後ろに名詞を続ける連体修飾で、「場合の」のあとに名詞がなく文が成り立たない。"}, "error_tags": {"を": "目的語", "で": "手段", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b56acd-0d08-4b17-bc86-fe4551bddf01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35594, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かが起こるときのこと。", "primary_collocate": null, "pronunciation": "ばあい", "ipa": "baai", "syllable_count": 3, "sentences": [{"text": "寒い場合は、上着を着てください。", "target_word": "場合", "complexity_tier": "T3", "furigana": "寒[さむ]い場合[ばあい]は、上着[うわぎ]を着[き]てください。", "sentence_source": "generated"}, {"text": "熱がある場合は、学校を休みます。", "target_word": "場合", "complexity_tier": "T3", "furigana": "熱[ねつ]がある場合[ばあい]は、学校[がっこう]を休[やす]みます。", "sentence_source": "generated"}, {"text": "雨の場合は、体育館で試合をします。", "target_word": "場合", "complexity_tier": "T3", "furigana": "雨[あめ]の場合[ばあい]は、体育館[たいいくかん]で試合[しあい]をします。", "sentence_source": "generated"}, {"text": "電車が止まった場合は、バスで行きましょう。", "target_word": "場合", "complexity_tier": "T3", "furigana": "電車[でんしゃ]が止[と]まった場合[ばあい]は、バスで行[い]きましょう。", "sentence_source": "generated"}, {"text": "分からない場合は、先生に聞いてください。", "target_word": "場合", "complexity_tier": "T3", "furigana": "分[わ]からない場合[ばあい]は、先生[せんせい]に聞[き]いてください。", "sentence_source": "generated"}, {"text": "授業に遅れる場合は、前の日に電話をします。", "target_word": "場合", "complexity_tier": "T3", "furigana": "授業[じゅぎょう]に遅[おく]れる場合[ばあい]は、前[まえ]の日[ひ]に電話[でんわ]をします。", "sentence_source": "generated"}, {"text": "財布を落とした場合は、すぐ交番に行きます。", "target_word": "場合", "complexity_tier": "T3", "furigana": "財布[さいふ]を落[お]とした場合[ばあい]は、すぐ交番[こうばん]に行[い]きます。", "sentence_source": "generated"}, {"text": "一人で行く場合は、地図を持って行くと安心です。", "target_word": "場合", "complexity_tier": "T3", "furigana": "一人[ひとり]で行[い]く場合[ばあい]は、地図[ちず]を持[も]って行[い]くと安心[あんしん]です。", "sentence_source": "generated"}, {"text": "切符がない場合は、入ることができません。", "target_word": "場合", "complexity_tier": "T3", "furigana": "切符[きっぷ]がない場合[ばあい]は、入[はい]ることができません。", "sentence_source": "generated"}, {"text": "人によって、考え方が違う場合もあります。", "target_word": "場合", "complexity_tier": "T3", "furigana": "人[ひと]によって、考[かんが]え方[かた]が違[ちが]う場合[ばあい]もあります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "場合", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "何かが起こるときや、そのときの状況(名詞)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d75d5cb-9168-42ec-b5c5-aaf58a772dde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35594, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "場合", "is_correct": true, "explanation": "「寒い場合は」で、条件を示す正しい用法。"}, {"text": "理由", "is_correct": false, "explanation": "理由は原因を述べる語で、寒さを条件とする指示文には合わない。"}, {"text": "結果", "is_correct": false, "explanation": "結果は出来事の帰結を指し、寒さを条件とする指示に合わない。"}, {"text": "目的", "is_correct": false, "explanation": "目的は達成したいことを指し、寒さを条件とする指示には合わない。"}], "explanations": {"場合": "「寒い場合は」で、条件を示す正しい用法。", "理由": "理由は原因を述べる語で、寒さを条件とする指示文には合わない。", "結果": "結果は出来事の帰結を指し、寒さを条件とする指示に合わない。", "目的": "目的は達成したいことを指し、寒さを条件とする指示には合わない。"}, "sentence_index": 0, "correct_answer": "場合"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は最後まで、物語の場合を明かさなかった。", "explanation": "ここは〈結末〉の意味。場合は条件を表すので、物語の結末は指さない。"}, {"text": "その場合を保つのは、とても難しい。", "explanation": "ここは〈状態〉の意味。場合は保つことのできるものではないので、状態を保つ文には合わない。"}, {"text": "この小説の感動的な場合で、読者は涙を流した。", "explanation": "ここは〈場面〉の意味。場合は条件を表し、小説の場面を指さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b56acd-0d08-4b17-bc86-fe4551bddf01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35594, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "場合", "is_correct": true, "explanation": "「財布を落とした場合は」で、起きたときの条件を示す正しい用法。"}, {"text": "結末", "is_correct": false, "explanation": "結末は物事の終わりを指し、財布を落とした時点の条件には合わない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空模様を指し、財布を落とした条件を示す文には合わない。"}, {"text": "紛失", "is_correct": false, "explanation": "紛失は失うこと自体を指し、条件を示す文として成立しない。"}], "explanations": {"場合": "「財布を落とした場合は」で、起きたときの条件を示す正しい用法。", "結末": "結末は物事の終わりを指し、財布を落とした時点の条件には合わない。", "天気": "天気は空模様を指し、財布を落とした条件を示す文には合わない。", "紛失": "紛失は失うこと自体を指し、条件を示す文として成立しない。"}, "sentence_index": 6, "correct_answer": "場合"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は長い時間をかけて、大切な場合を仕上げた。", "explanation": "ここは〈作品〉の意味。場合は仕上げるものではないので、作品を完成させる文には合わない。"}, {"text": "彼は司会の場合を任された。", "explanation": "ここは〈役目〉の意味。場合は任せられるものではないので、役目を任せる文には合わない。"}, {"text": "彼女は友人に長い場合を書いた。", "explanation": "ここは〈手紙〉の意味。場合は書く物ではないので、手紙を書く文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b56acd-0d08-4b17-bc86-fe4551bddf01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35594, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "風邪をひいた場合で、早めに病院へ行ってください。", "corrected_sentence": "風邪をひいた場合は、早めに病院へ行ってください。", "error_description": "「場合」に続く助詞が誤り。条件を示すには「場合は」が正しく、「で」では手段の意味になり不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b56acd-0d08-4b17-bc86-fe4551bddf01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35594, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "お客様がいらっしゃる場合を、お茶を出します。", "corrected_sentence": "お客様がいらっしゃる場合は、お茶を出します。", "error_description": "「場合」に続く助詞が誤り。条件を主題として示すには「場合は」が正しく、「を」では目的語になり文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b56acd-0d08-4b17-bc86-fe4551bddf01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35595, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「雨が降った場合は」で、条件を主題として示す正しい助詞。"}, {"text": "を", "is_correct": false, "explanation": "「場合を」では目的語になり、条件の文が成立しない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すため、「場合で」は条件の文として不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、ここに方向の意味はないので合わない。"}], "correct_answer": "は", "explanations": {"は": "「雨が降った場合は」で、条件を主題として示す正しい助詞。", "を": "「場合を」では目的語になり、条件の文が成立しない。", "で": "「で」は手段や場所を示すため、「場合で」は条件の文として不自然。", "へ": "「へ」は方向を示すが、ここに方向の意味はないので合わない。"}, "error_tags": {"を": "目的語", "で": "手段", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b56acd-0d08-4b17-bc86-fe4551bddf01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35595, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「火事になった場合は」で、条件を主題として示す正しい助詞。"}, {"text": "を", "is_correct": false, "explanation": "「場合を」では目的語になり、逃げるという動作の対象にならず不自然。"}, {"text": "が", "is_correct": false, "explanation": "「場合が」は主語として「逃げます」に続かず、文が成立しない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すため、「場合と」では条件の意味が通らない。"}], "correct_answer": "は", "explanations": {"は": "「火事になった場合は」で、条件を主題として示す正しい助詞。", "を": "「場合を」では目的語になり、逃げるという動作の対象にならず不自然。", "が": "「場合が」は主語として「逃げます」に続かず、文が成立しない。", "と": "「と」は並列や相手を示すため、「場合と」では条件の意味が通らない。"}, "error_tags": {"を": "目的語", "が": "主語", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b56acd-0d08-4b17-bc86-fe4551bddf01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35595, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある事柄が起こる状況や時。特定の条件のもとでの状態。", "primary_collocate": null, "pronunciation": "ばあい", "ipa": "baai", "syllable_count": 3, "sentences": [{"text": "特に多色印刷の場合、色ごとに異なる版木を使い分ける必要があり、職人たちの高度な技術と協力が不可欠です。", "target_word": "場合", "complexity_tier": "T3", "furigana": "特[とく]に多色[たしょく]印刷[いんさつ]の場合[ばあい]、色[いろ]ごとに異[こと]なる版木[はんぎ]を使[つか]い分[わ]ける必要[ひつよう]があり、職人[しょくにん]たちの高度[こうど]な技術[ぎじゅつ]と協力[きょうりょく]が不可欠[ふかけつ]です。", "sentence_source": "mined"}, {"text": "雨が降った場合は、遠足を中止にします。", "target_word": "場合", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]った場合[ばあい]は、遠足[えんそく]を中止[ちゅうし]にします。", "sentence_source": "generated"}, {"text": "急いでいる場合は、タクシーを使ってください。", "target_word": "場合", "complexity_tier": "T3", "furigana": "急[いそ]いでいる場合[ばあい]は、タクシーを使[つか]ってください。", "sentence_source": "generated"}, {"text": "場合によっては、予定を変えることもあります。", "target_word": "場合", "complexity_tier": "T3", "furigana": "場合[ばあい]によっては、予定[よてい]を変[か]えることもあります。", "sentence_source": "generated"}, {"text": "道に迷った場合、まず駅員に聞くのがいちばんです。", "target_word": "場合", "complexity_tier": "T3", "furigana": "道[みち]に迷[まよ]った場合[ばあい]、まず駅員[えきいん]に聞[き]くのがいちばんです。", "sentence_source": "generated"}, {"text": "子どもの場合、薬の量を大人より少なくします。", "target_word": "場合", "complexity_tier": "T3", "furigana": "子[こ]どもの場合[ばあい]、薬[くすり]の量[りょう]を大人[おとな]より少[すく]なくします。", "sentence_source": "generated"}, {"text": "忘れ物をした場合は、事務室に連絡してください。", "target_word": "場合", "complexity_tier": "T3", "furigana": "忘[わす]れ物[もの]をした場合[ばあい]は、事務室[じむしつ]に連絡[れんらく]してください。", "sentence_source": "generated"}, {"text": "万一、火事になった場合は、階段で逃げます。", "target_word": "場合", "complexity_tier": "T3", "furigana": "万一[まんいち]、火事[かじ]になった場合[ばあい]は、階段[かいだん]で逃[に]げます。", "sentence_source": "generated"}, {"text": "大きな地震が起きた場合に備えて、水を用意しています。", "target_word": "場合", "complexity_tier": "T3", "furigana": "大[おお]きな地震[じしん]が起[お]きた場合[ばあい]に備[そな]えて、水[みず]を用意[ようい]しています。", "sentence_source": "generated"}, {"text": "この問題は、答えが一つではない場合もあります。", "target_word": "場合", "complexity_tier": "T3", "furigana": "この問題[もんだい]は、答[こた]えが一つ[ひとつ]ではない場合[ばあい]もあります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "場合", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "ある事柄が起こる状況や、特定の条件のもとでの状態(名詞)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: contains vocabulary far above tier T1: 版木 (Zipf 2.03)']::text[], '9d75d5cb-9168-42ec-b5c5-aaf58a772dde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35595, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "場合", "is_correct": true, "explanation": "「特に多色印刷の場合」で、前提となる条件や状況を示す正しい用法。"}, {"text": "時計", "is_correct": false, "explanation": "時計は時刻を示す道具で、工程の条件を示すこの文脈には合わない。"}, {"text": "理由", "is_correct": false, "explanation": "理由は原因を述べる語で、工程の条件を示す文には合わない。"}, {"text": "結果", "is_correct": false, "explanation": "結果は出来上がったものを指し、工程の前提条件の提示には使えない。"}], "explanations": {"場合": "「特に多色印刷の場合」で、前提となる条件や状況を示す正しい用法。", "時計": "時計は時刻を示す道具で、工程の条件を示すこの文脈には合わない。", "理由": "理由は原因を述べる語で、工程の条件を示す文には合わない。", "結果": "結果は出来上がったものを指し、工程の前提条件の提示には使えない。"}, "sentence_index": 0, "correct_answer": "場合"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その映画は感動的な場合で、観客はみな涙を流した。", "explanation": "ここは〈場面〉の意味。場合は条件や状況を表し、映画の場面を指さないので合わない。"}, {"text": "家庭の場合で、彼は今年の留学をあきらめた。", "explanation": "ここは〈事情〉の意味。場合は理由を表さないので、家庭の事情とは言えない。"}, {"text": "彼女は座る場合を探して、窓際の席を選んだ。", "explanation": "ここは〈場所〉の意味。場合は条件を表し、座る場所を指さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b56acd-0d08-4b17-bc86-fe4551bddf01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35595, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "場合", "is_correct": true, "explanation": "「忘れ物をした場合は」で、起きたときの条件を示す正しい用法。"}, {"text": "目的", "is_correct": false, "explanation": "目的は達成したいことを指し、忘れ物をした条件を示す文には合わない。"}, {"text": "結末", "is_correct": false, "explanation": "結末は物事の終わりを指し、忘れ物の時点の条件には合わない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空模様を指し、忘れ物をした条件を示す文には合わない。"}], "explanations": {"場合": "「忘れ物をした場合は」で、起きたときの条件を示す正しい用法。", "目的": "目的は達成したいことを指し、忘れ物をした条件を示す文には合わない。", "結末": "結末は物事の終わりを指し、忘れ物の時点の条件には合わない。", "天気": "天気は空模様を指し、忘れ物をした条件を示す文には合わない。"}, "sentence_index": 6, "correct_answer": "場合"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は一番の場合で、表彰台に上がった。", "explanation": "ここは〈成績〉の意味。場合は条件を表し、競技の順位や成績は指さないので合わない。"}, {"text": "彼は留学の場合を得て、海外で暮らすことになった。", "explanation": "ここは〈機会〉の意味。場合は得られるものではなく、機会を得る文には合わない。"}, {"text": "彼は通勤の場合を変えて、自転車で会社に行くことにした。", "explanation": "ここは〈手段〉の意味。場合は交通の方法を指さないので、通勤手段の変更には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b56acd-0d08-4b17-bc86-fe4551bddf01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35595, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "地震が起きた場合を、すぐに机の下に入ってください。", "corrected_sentence": "地震が起きた場合は、すぐに机の下に入ってください。", "error_description": "「場合」に続く助詞が誤り。条件を示す主題として「場合は」と書くのが正しく、「を」では文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b56acd-0d08-4b17-bc86-fe4551bddf01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35595, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "電車が遅れた場合の、駅員に相談してください。", "corrected_sentence": "電車が遅れた場合は、駅員に相談してください。", "error_description": "「場合」に続く助詞が誤り。条件を示すには「場合は」が正しく、「の」では連体修飾になり文が続かない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b56acd-0d08-4b17-bc86-fe4551bddf01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
