INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35596, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "品物がどれだけよいかを表すことば。", "primary_collocate": null, "pronunciation": "ひんしつ", "ipa": "çiɴɕitsɯ", "syllable_count": 4, "sentences": [{"text": "この店の野菜は品質がよいので、人気があります。", "target_word": "品質", "complexity_tier": "T3", "furigana": "この店[みせ]の野菜[やさい]は品質[ひんしつ]がよいので、人気[にんき]があります。", "sentence_source": "generated"}, {"text": "値段は安いが、品質が悪くてすぐ壊れた。", "target_word": "品質", "complexity_tier": "T3", "furigana": "値段[ねだん]は安[やす]いが、品質[ひんしつ]が悪[わる]くてすぐ壊[こわ]れた。", "sentence_source": "generated"}, {"text": "工場では、毎日品物を調べて品質を守っています。", "target_word": "品質", "complexity_tier": "T3", "furigana": "工場[こうじょう]では、毎日[まいにち]品物[しなもの]を調[しら]べて品質[ひんしつ]を守[まも]っています。", "sentence_source": "generated"}, {"text": "同じ値段なら、品質のよいほうを買いたい。", "target_word": "品質", "complexity_tier": "T3", "furigana": "同[おな]じ値段[ねだん]なら、品質[ひんしつ]のよいほうを買[か]いたい。", "sentence_source": "generated"}, {"text": "この靴は品質が高く、五年使ってもきれいです。", "target_word": "品質", "complexity_tier": "T3", "furigana": "この靴[くつ]は品質[ひんしつ]が高[たか]く、五年[ごねん]使[つか]ってもきれいです。", "sentence_source": "generated"}, {"text": "品質が落ちたので、そのメーカーの商品は買わなくなった。", "target_word": "品質", "complexity_tier": "T3", "furigana": "品質[ひんしつ]が落[お]ちたので、そのメーカーの商品[しょうひん]は買[か]わなくなった。", "sentence_source": "generated"}, {"text": "安い物は品質が心配だと、母は言います。", "target_word": "品質", "complexity_tier": "T3", "furigana": "安[やす]い物[もの]は品質[ひんしつ]が心配[しんぱい]だと、母[はは]は言[い]います。", "sentence_source": "generated"}, {"text": "品質のよい米を作るために、農家は水を大切にしています。", "target_word": "品質", "complexity_tier": "T3", "furigana": "品質[ひんしつ]のよい米[こめ]を作[つく]るために、農家[のうか]は水[みず]を大切[たいせつ]にしています。", "sentence_source": "generated"}, {"text": "輸入した果物の品質を、検査員が調べた。", "target_word": "品質", "complexity_tier": "T3", "furigana": "輸入[ゆにゅう]した果物[くだもの]の品質[ひんしつ]を、検査員[けんさいん]が調[しら]べた。", "sentence_source": "generated"}, {"text": "高いからといって、品質がよいとは限りません。", "target_word": "品質", "complexity_tier": "T3", "furigana": "高[たか]いからといって、品質[ひんしつ]がよいとは限[かぎ]りません。", "sentence_source": "generated"}], "morphological_forms": [{"form": "品質", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "野菜・靴・米などの品物そのもののよしあし", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e74715c8-80af-41e0-bc9c-e29c3da457dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35596, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "品質", "is_correct": true, "explanation": "「品質」は品物の良さの程度を表し、「野菜は品質がよい」として人気の理由に合う。"}, {"text": "歌声", "is_correct": false, "explanation": "「野菜は歌声がよい」は意味が通らず、人気の理由にならない。"}, {"text": "数量", "is_correct": false, "explanation": "「数量がよい」は良さを評価する言い方ではなく、ここでは不自然。"}, {"text": "音", "is_correct": false, "explanation": "「野菜は音がよい」は良さを表さず、人気の理由として成り立たない。"}], "explanations": {"品質": "「品質」は品物の良さの程度を表し、「野菜は品質がよい」として人気の理由に合う。", "歌声": "「野菜は歌声がよい」は意味が通らず、人気の理由にならない。", "数量": "「数量がよい」は良さを評価する言い方ではなく、ここでは不自然。", "音": "「野菜は音がよい」は良さを表さず、人気の理由として成り立たない。"}, "sentence_index": 0, "correct_answer": "品質"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この店の店員は品質がよく、いつも笑顔で話してくれる。", "explanation": "ここは〈人柄〉の意味。品質は物の良さの程度を表すので、人の性格には使わない。"}, {"text": "このスープは品質が深く、一口飲むと驚く。", "explanation": "ここは〈味〉の意味。品質は物の良さの程度で、味の深さを表すときには使わない。"}, {"text": "この米は品質が三十種類もある。", "explanation": "ここは〈品種〉の意味。品質は良さの程度を表すので、種類の数を数えるときには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a24165d-25fb-4287-b029-d82fa4c8a110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35596, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "品質", "is_correct": true, "explanation": "「品質」が安い物の心配事として自然で、文の意味に合う。"}, {"text": "歌声", "is_correct": false, "explanation": "「安い物は歌声が心配だ」は意味が通らず、母の発言として成り立たない。"}, {"text": "足音", "is_correct": false, "explanation": "「安い物の足音」は心配の対象にならず、文に合わない。"}, {"text": "季節", "is_correct": false, "explanation": "「安い物は季節が心配」では心配の内容が不明で、文として自然ではない。"}], "explanations": {"品質": "「品質」が安い物の心配事として自然で、文の意味に合う。", "歌声": "「安い物は歌声が心配だ」は意味が通らず、母の発言として成り立たない。", "足音": "「安い物の足音」は心配の対象にならず、文に合わない。", "季節": "「安い物は季節が心配」では心配の内容が不明で、文として自然ではない。"}, "sentence_index": 6, "correct_answer": "品質"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この店は品質が安く、学生でも買いやすい。", "explanation": "ここは〈価格〉の意味。品質は物の良さの程度で、値段の安さには使わない。"}, {"text": "この会社は品質が大きく、社員が千人を超える。", "explanation": "ここは〈規模〉の意味。品質は良さの程度を表し、会社の大きさには使わない。"}, {"text": "私は品質が弱く、すぐ風邪をひく。", "explanation": "ここは〈体質〉の意味。品質は物の良さを表すので、人の体の強さには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a24165d-25fb-4287-b029-d82fa4c8a110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35596, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この店の野菜は品質を高くて、人気があります。", "corrected_sentence": "この店の野菜は品質が高くて、人気があります。", "error_description": "「品質」に続く助詞が誤り。「高い」は主語を「が」で示すので、「品質を」ではなく「品質が」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a24165d-25fb-4287-b029-d82fa4c8a110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35596, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この店は品質が増えたので、客が増えた。", "corrected_sentence": "この店は品質が上がったので、客が増えた。", "error_description": "「品質」に続く述語が誤り。「増える」は数や量が多くなることを表すので、良さの程度が高くなることを表す「上がる」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a24165d-25fb-4287-b029-d82fa4c8a110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35597, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「品質が悪く」の「が」で、「悪い」の主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "「品質を悪く」は目的語の形になり、形容詞「悪い」の主語にならない。"}, {"text": "で", "is_correct": false, "explanation": "「品質で悪く」は手段を表すが、ここでは意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「品質へ悪く」は方向を示すが、形容詞「悪い」とつながらない。"}], "correct_answer": "が", "explanations": {"が": "「品質が悪く」の「が」で、「悪い」の主語を示す。", "を": "「品質を悪く」は目的語の形になり、形容詞「悪い」の主語にならない。", "で": "「品質で悪く」は手段を表すが、ここでは意味が通らない。", "へ": "「品質へ悪く」は方向を示すが、形容詞「悪い」とつながらない。"}, "error_tags": {"を": "目的語（を）", "で": "手段（で）", "へ": "方向（へ）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a24165d-25fb-4287-b029-d82fa4c8a110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35597, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「品質が安定した」の「が」で、「安定した」の主語を示す。"}, {"text": "に", "is_correct": false, "explanation": "「品質に安定した」は「安定した」の結びつきとして不自然。"}, {"text": "から", "is_correct": false, "explanation": "「品質から安定した」は起点の意味になり、安定の主語にならない。"}, {"text": "より", "is_correct": false, "explanation": "「品質より安定した」は比較の形で、ここでは文として成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「品質が安定した」の「が」で、「安定した」の主語を示す。", "に": "「品質に安定した」は「安定した」の結びつきとして不自然。", "から": "「品質から安定した」は起点の意味になり、安定の主語にならない。", "より": "「品質より安定した」は比較の形で、ここでは文として成り立たない。"}, "error_tags": {"に": "帰着（に）", "から": "起点（から）", "より": "比較（より）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a24165d-25fb-4287-b029-d82fa4c8a110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35597, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物やサービスが持つ、良さの程度。どれだけ素晴らしいか、または役に立つかの度合い。", "primary_collocate": null, "pronunciation": "ひんしつ", "ipa": "çiɴɕitsɯ", "syllable_count": 4, "sentences": [{"text": "このホテルは、サービスの品質が高いと評判です。", "target_word": "品質", "complexity_tier": "T3", "furigana": "このホテルは、サービスの品質[ひんしつ]が高[たか]いと評判[ひょうばん]です。", "sentence_source": "generated"}, {"text": "電話の音声品質が悪く、相手の声が聞き取れなかった。", "target_word": "品質", "complexity_tier": "T3", "furigana": "電話[でんわ]の音声[おんせい]品質[ひんしつ]が悪[わる]く、相手[あいて]の声[こえ]が聞[き]き取[と]れなかった。", "sentence_source": "generated"}, {"text": "病院は、医療の品質を高める努力を続けている。", "target_word": "品質", "complexity_tier": "T3", "furigana": "病院[びょういん]は、医療[いりょう]の品質[ひんしつ]を高[たか]める努力[どりょく]を続[つづ]けている。", "sentence_source": "generated"}, {"text": "動画の品質を下げれば、通信量は少なくなります。", "target_word": "品質", "complexity_tier": "T3", "furigana": "動画[どうが]の品質[ひんしつ]を下[さ]げれば、通信量[つうしんりょう]は少[すく]なくなります。", "sentence_source": "generated"}, {"text": "客の数が増えて、サービスの品質が下がってしまった。", "target_word": "品質", "complexity_tier": "T3", "furigana": "客[きゃく]の数[かず]が増[ふ]えて、サービスの品質[ひんしつ]が下[さ]がってしまった。", "sentence_source": "generated"}, {"text": "写真の品質が高いので、大きく印刷してもきれいです。", "target_word": "品質", "complexity_tier": "T3", "furigana": "写真[しゃしん]の品質[ひんしつ]が高[たか]いので、大[おお]きく印刷[いんさつ]してもきれいです。", "sentence_source": "generated"}, {"text": "この会社は、教育の品質で他社と差をつけている。", "target_word": "品質", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]は、教育[きょういく]の品質[ひんしつ]で他社[たしゃ]と差[さ]をつけている。", "sentence_source": "generated"}, {"text": "新しい機械を入れたので、製品の品質が安定した。", "target_word": "品質", "complexity_tier": "T3", "furigana": "新[あたら]しい機械[きかい]を入[い]れたので、製品[せいひん]の品質[ひんしつ]が安定[あんてい]した。", "sentence_source": "generated"}, {"text": "修理の品質に満足したので、また同じ店に頼みます。", "target_word": "品質", "complexity_tier": "T3", "furigana": "修理[しゅうり]の品質[ひんしつ]に満足[まんぞく]したので、また同[おな]じ店[みせ]に頼[たの]みます。", "sentence_source": "generated"}, {"text": "授業の品質を上げるため、先生たちは毎週話し合っています。", "target_word": "品質", "complexity_tier": "T3", "furigana": "授業[じゅぎょう]の品質[ひんしつ]を上[あ]げるため、先生[せんせい]たちは毎週[まいしゅう]話[はな]し合[あ]っています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "品質", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "サービス・音声・映像・教育などが、どれだけ優れ役に立つかの度合い", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e74715c8-80af-41e0-bc9c-e29c3da457dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35597, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "品質", "is_correct": true, "explanation": "「サービスの品質が高い」は、評判の理由として文に合う。"}, {"text": "速さ", "is_correct": false, "explanation": "「サービスの速さが高い」とは言わず、評判の内容として合わない。"}, {"text": "数", "is_correct": false, "explanation": "「サービスの数が高い」は意味が通らず、評判の理由にならない。"}, {"text": "種類", "is_correct": false, "explanation": "「種類が高い」は評判の理由として不自然で、この文には合わない。"}], "explanations": {"品質": "「サービスの品質が高い」は、評判の理由として文に合う。", "速さ": "「サービスの速さが高い」とは言わず、評判の内容として合わない。", "数": "「サービスの数が高い」は意味が通らず、評判の理由にならない。", "種類": "「種類が高い」は評判の理由として不自然で、この文には合わない。"}, "sentence_index": 0, "correct_answer": "品質"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この番組は品質が豊かで、毎回新しい発見がある。", "explanation": "ここは〈内容〉の意味。品質は良さの程度で、番組の中身の豊かさには使わない。"}, {"text": "彼女は品質が高く、どんな場でも落ち着いて見える。", "explanation": "ここは〈品格〉の意味。品質はサービスや物の良さで、人の品位には使わない。"}, {"text": "この店は品質が十種類もあり、どれでも選べる。", "explanation": "ここは〈品数〉の意味。品質は良さの程度を表し、商品の種類の数は表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a24165d-25fb-4287-b029-d82fa4c8a110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35597, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "品質", "is_correct": true, "explanation": "「教育の品質で他社と差をつける」は自然で、文の意味に合う。"}, {"text": "歌声", "is_correct": false, "explanation": "「教育の歌声で差をつける」は意味が通らず、比較の内容として成り立たない。"}, {"text": "天気", "is_correct": false, "explanation": "「教育の天気」は差の要素として成り立たず、文に合わない。"}, {"text": "季節", "is_correct": false, "explanation": "「教育の季節で差をつける」は差の要素として成り立たず、文に合わない。"}], "explanations": {"品質": "「教育の品質で他社と差をつける」は自然で、文の意味に合う。", "歌声": "「教育の歌声で差をつける」は意味が通らず、比較の内容として成り立たない。", "天気": "「教育の天気」は差の要素として成り立たず、文に合わない。", "季節": "「教育の季節で差をつける」は差の要素として成り立たず、文に合わない。"}, "sentence_index": 6, "correct_answer": "品質"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この本は品質が多く、読み終えるのに一か月かかる。", "explanation": "ここは〈分量〉の意味。品質は良さの程度で、ページ数や量の多さには使わない。"}, {"text": "彼は品質がよく、どんな仕事も手早く片付ける。", "explanation": "ここは〈手際〉の意味。品質は物やサービスの良さで、人の仕事ぶりには使わない。"}, {"text": "この金属は品質が柔らかく、加工しやすい。", "explanation": "ここは〈性質〉の意味。品質は良さの程度を表すので、材料の柔らかさには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a24165d-25fb-4287-b029-d82fa4c8a110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35597, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このホテルは、サービスの品質を高いと評判になった。", "corrected_sentence": "このホテルは、サービスの品質が高いと評判になった。", "error_description": "「品質」に続く助詞が誤り。「高い」の主語を示すには「が」を使うので、「品質を」は「品質が」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a24165d-25fb-4287-b029-d82fa4c8a110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35597, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "研修の品質を増やすため、社員たちは毎週話し合っています。", "corrected_sentence": "研修の品質を上げるため、社員たちは毎週話し合っています。", "error_description": "「品質」に続く動詞が誤り。「増やす」は数や量を多くする語なので、良さの程度を高める「上げる」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a24165d-25fb-4287-b029-d82fa4c8a110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35600, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「地元の人」の「の」で、地元が人を修飾する。"}, {"text": "が", "is_correct": false, "explanation": "「地元が人に」は主語にならず、修飾関係も作れない。"}, {"text": "を", "is_correct": false, "explanation": "「地元を人に」は「教えてもらう」と結びつかず不自然。"}, {"text": "と", "is_correct": false, "explanation": "「地元と人に」は並列の「と」で、文の流れに合わない。"}], "correct_answer": "の", "explanations": {"の": "「地元の人」の「の」で、地元が人を修飾する。", "が": "「地元が人に」は主語にならず、修飾関係も作れない。", "を": "「地元を人に」は「教えてもらう」と結びつかず不自然。", "と": "「地元と人に」は並列の「と」で、文の流れに合わない。"}, "error_tags": {"が": "主語（が）", "を": "目的語（を）", "と": "並列（と）"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a24165d-25fb-4287-b029-d82fa4c8a110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35600, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「地元でとれた」の「で」で、とれた場所を示す。"}, {"text": "に", "is_correct": false, "explanation": "「地元にとれた魚」は場所を示せず、文として成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「地元よりとれた魚」は比較の形で、とれた場所を表せない。"}, {"text": "へ", "is_correct": false, "explanation": "「地元へとれた魚」は方向を示すが、とれる場所にはならない。"}], "correct_answer": "で", "explanations": {"で": "「地元でとれた」の「で」で、とれた場所を示す。", "に": "「地元にとれた魚」は場所を示せず、文として成り立たない。", "より": "「地元よりとれた魚」は比較の形で、とれた場所を表せない。", "へ": "「地元へとれた魚」は方向を示すが、とれる場所にはならない。"}, "error_tags": {"に": "帰着（に）", "より": "比較（より）", "へ": "方向（へ）"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a24165d-25fb-4287-b029-d82fa4c8a110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35600, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "自分が住んでいる、または生まれ育った場所のこと。", "primary_collocate": null, "pronunciation": "じもと", "ipa": "dʑimoto", "syllable_count": 3, "sentences": [{"text": "大学を卒業して、地元に帰って働くつもりです。", "target_word": "地元", "complexity_tier": "T3", "furigana": "大学[だいがく]を卒業[そつぎょう]して、地元[じもと]に帰[かえ]って働[はたら]くつもりです。", "sentence_source": "generated"}, {"text": "地元の人に、おいしい店を教えてもらいました。", "target_word": "地元", "complexity_tier": "T3", "furigana": "地元[じもと]の人[ひと]に、おいしい店[みせ]を教[おし]えてもらいました。", "sentence_source": "generated"}, {"text": "私は地元の高校に通っていました。", "target_word": "地元", "complexity_tier": "T3", "furigana": "私[わたし]は地元[じもと]の高校[こうこう]に通[かよ]っていました。", "sentence_source": "generated"}, {"text": "正月に地元へ帰ると、昔の友達に会えます。", "target_word": "地元", "complexity_tier": "T3", "furigana": "正月[しょうがつ]に地元[じもと]へ帰[かえ]ると、昔[むかし]の友達[ともだち]に会[あ]えます。", "sentence_source": "generated"}, {"text": "地元のチームが勝って、町中が喜んだ。", "target_word": "地元", "complexity_tier": "T3", "furigana": "地元[じもと]のチームが勝[か]って、町中[まちじゅう]が喜[よろこ]んだ。", "sentence_source": "generated"}, {"text": "この祭りは、地元の人たちが毎年準備している。", "target_word": "地元", "complexity_tier": "T3", "furigana": "この祭[まつ]りは、地元[じもと]の人[ひと]たちが毎年[まいとし]準備[じゅんび]している。", "sentence_source": "generated"}, {"text": "東京に住んでいるが、地元は北海道だ。", "target_word": "地元", "complexity_tier": "T3", "furigana": "東京[とうきょう]に住[す]んでいるが、地元[じもと]は北海道[ほっかいどう]だ。", "sentence_source": "generated"}, {"text": "地元でとれた魚は、新鮮で安いです。", "target_word": "地元", "complexity_tier": "T3", "furigana": "地元[じもと]でとれた魚[さかな]は、新鮮[しんせん]で安[やす]いです。", "sentence_source": "generated"}, {"text": "彼は地元のために、市長になりたいと言った。", "target_word": "地元", "complexity_tier": "T3", "furigana": "彼[かれ]は地元[じもと]のために、市長[しちょう]になりたいと言[い]った。", "sentence_source": "generated"}, {"text": "地元の言葉で話すと、母はうれしそうに笑う。", "target_word": "地元", "complexity_tier": "T3", "furigana": "地元[じもと]の言葉[ことば]で話[はな]すと、母[はは]はうれしそうに笑[わら]う。", "sentence_source": "generated"}], "morphological_forms": [{"form": "地元", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "自分が住んでいる、または生まれ育った土地・地域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e74715c8-80af-41e0-bc9c-e29c3da457dc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35600, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地元", "is_correct": true, "explanation": "「地元」は生まれ育った土地を指し、「地元に帰って働く」として文の意味に合う。"}, {"text": "教室", "is_correct": false, "explanation": "「教室に帰って働く」は場所として意味が通らず、文に合わない。"}, {"text": "寝室", "is_correct": false, "explanation": "「寝室に帰って働く」は不自然で、働く場所として成り立たない。"}, {"text": "台所", "is_correct": false, "explanation": "「台所に帰って働く」は意味が通らず、文の流れに合わない。"}], "explanations": {"地元": "「地元」は生まれ育った土地を指し、「地元に帰って働く」として文の意味に合う。", "教室": "「教室に帰って働く」は場所として意味が通らず、文に合わない。", "寝室": "「寝室に帰って働く」は不自然で、働く場所として成り立たない。", "台所": "「台所に帰って働く」は意味が通らず、文の流れに合わない。"}, "sentence_index": 0, "correct_answer": "地元"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私の地元は狭いワンルームで、家賃も安い。", "explanation": "ここは〈自宅〉の意味。地元は住んでいる地域を指し、住居そのものには使わない。"}, {"text": "私の地元は三人で、毎日一緒に食事をする。", "explanation": "ここは〈家族〉の意味。地元は場所を表すので、人の数や家族には使わない。"}, {"text": "この地元は縮尺が大きくて見やすい。", "explanation": "ここは〈地図〉の意味。地元は地域を指す語で、縮尺のある紙面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a24165d-25fb-4287-b029-d82fa4c8a110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35600, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地元", "is_correct": true, "explanation": "「東京に住んでいるが、地元は北海道だ」の空欄に入り、生まれ育った土地を指す。"}, {"text": "玄関", "is_correct": false, "explanation": "「玄関は北海道だ」は意味が通らず、文の対比として成り立たない。"}, {"text": "厨房", "is_correct": false, "explanation": "「厨房は北海道だ」は意味が通らず、文の対比に合わない。"}, {"text": "体育館", "is_correct": false, "explanation": "「体育館は北海道だ」は意味が通らず、文に合わない。"}], "explanations": {"地元": "「東京に住んでいるが、地元は北海道だ」の空欄に入り、生まれ育った土地を指す。", "玄関": "「玄関は北海道だ」は意味が通らず、文の対比として成り立たない。", "厨房": "「厨房は北海道だ」は意味が通らず、文の対比に合わない。", "体育館": "「体育館は北海道だ」は意味が通らず、文に合わない。"}, "sentence_index": 6, "correct_answer": "地元"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "私の地元は十階建てのビルで、毎朝ここに通勤する。", "explanation": "ここは〈職場〉の意味。地元は住んでいる地域のことで、勤め先のビルを指すことはない。"}, {"text": "この地元は白くて割れにくく、毎日の食事で使っている。", "explanation": "ここは〈食器〉の意味。地元は地域を表す語で、皿や器の性質には使わない。"}, {"text": "私の地元は三階にあり、月に一度検査を受けに通っている。", "explanation": "ここは〈病院〉の意味。地元は地域のことで、通院先の施設には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a24165d-25fb-4287-b029-d82fa4c8a110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35600, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私は地元を大学に通っていました。", "corrected_sentence": "私は地元の大学に通っていました。", "error_description": "「地元」に続く助詞が誤り。名詞「大学」を修飾するには「の」が必要で、「を」では不自然になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a24165d-25fb-4287-b029-d82fa4c8a110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35600, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "私は地元を住んでいますが、実家は北海道です。", "corrected_sentence": "私は地元に住んでいますが、実家は北海道です。", "error_description": "「住む」は場所を「に」で示すので、「地元を」ではなく「地元に」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a24165d-25fb-4287-b029-d82fa4c8a110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35602, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "材料や手段を表す『で』。『布の余りで作る』は自然。"}, {"text": "に", "is_correct": false, "explanation": "『に』は場所や相手を示すので、材料の意味にならない。"}, {"text": "を", "is_correct": false, "explanation": "『を』を付けると余り自体が作られる対象になり、かばんを作ったという文と合わない。"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は行き先や方向を示すので、材料を表す文脈では使えない。"}], "correct_answer": "で", "explanations": {"で": "材料や手段を表す『で』。『布の余りで作る』は自然。", "に": "『に』は場所や相手を示すので、材料の意味にならない。", "を": "『を』を付けると余り自体が作られる対象になり、かばんを作ったという文と合わない。", "へ": "『へ』は行き先や方向を示すので、材料を表す文脈では使えない。"}, "error_tags": {"に": "場所・相手", "を": "対象", "へ": "方向"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不足", "is_correct": true, "explanation": "余り（余った量）の対義語。必要な量に足りないこと。"}, {"text": "増加", "is_correct": false, "explanation": "数や量が増える意味で、残りを指す余りの対義語ではない。"}, {"text": "完成", "is_correct": false, "explanation": "物事が仕上がる意味で、余りとは対になる関係ではない。"}, {"text": "準備", "is_correct": false, "explanation": "前もって整えておく意味で、使ったあとの残りとは対にならない。"}], "correct_answer": "不足", "explanations": {"不足": "余り（余った量）の対義語。必要な量に足りないこと。", "増加": "数や量が増える意味で、残りを指す余りの対義語ではない。", "完成": "物事が仕上がる意味で、余りとは対になる関係ではない。", "準備": "前もって整えておく意味で、使ったあとの残りとは対にならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66c5ca52-51a7-48b2-bf58-49b55ba482b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35602, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "『余りが出る』の主語を示す『が』。自然な文になる。"}, {"text": "で", "is_correct": false, "explanation": "『で』は手段や場所を示すので、『出る』の主語にはならない。"}, {"text": "より", "is_correct": false, "explanation": "『より』は比較を表すので、出るものを示す文の形に合わない。"}, {"text": "と", "is_correct": false, "explanation": "『と』は並べる相手を示すので、『出た』の主語を表せない。"}], "correct_answer": "が", "explanations": {"が": "『余りが出る』の主語を示す『が』。自然な文になる。", "で": "『で』は手段や場所を示すので、『出る』の主語にはならない。", "より": "『より』は比較を表すので、出るものを示す文の形に合わない。", "と": "『と』は並べる相手を示すので、『出た』の主語を表せない。"}, "error_tags": {"で": "手段", "より": "比較", "と": "並列・相手"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不足", "is_correct": true, "explanation": "余り（余った量）の対義語。必要な量に足りないこと。"}, {"text": "購入", "is_correct": false, "explanation": "お金を払って品物を手に入れることで、余りとは対にならない。"}, {"text": "節約", "is_correct": false, "explanation": "無駄に使わないことで、残りの量を示す余りの対義語ではない。"}, {"text": "整理", "is_correct": false, "explanation": "物を片付けて並べ直すことで、余りとは対になる関係ではない。"}], "correct_answer": "不足", "explanations": {"不足": "余り（余った量）の対義語。必要な量に足りないこと。", "購入": "お金を払って品物を手に入れることで、余りとは対にならない。", "節約": "無駄に使わないことで、残りの量を示す余りの対義語ではない。", "整理": "物を片付けて並べ直すことで、余りとは対になる関係ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66c5ca52-51a7-48b2-bf58-49b55ba482b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35602, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かを使ったあとに、まだ残っているものです。", "primary_collocate": null, "pronunciation": "あまり", "ipa": "amaɾi", "syllable_count": 3, "sentences": [{"text": "夕食の余りを、次の日の弁当に入れた。", "target_word": "余り", "complexity_tier": "T3", "furigana": "夕食[ゆうしょく]の余[あま]りを、次[つぎ]の日[ひ]の弁当[べんとう]に入[い]れた。", "sentence_source": "generated"}, {"text": "布の余りで、小さなかばんを作った。", "target_word": "余り", "complexity_tier": "T3", "furigana": "布[ぬの]の余[あま]りで、小[ちい]さなかばんを作[つく]った。", "sentence_source": "generated"}, {"text": "旅行で使った費用の余りは、母に返した。", "target_word": "余り", "complexity_tier": "T3", "furigana": "旅行[りょこう]で使[つか]った費用[ひよう]の余[あま]りは、母[はは]に返[かえ]した。", "sentence_source": "generated"}, {"text": "工事に使ったペンキの余りが、倉庫に置いてある。", "target_word": "余り", "complexity_tier": "T3", "furigana": "工事[こうじ]に使[つか]ったペンキの余[あま]りが、倉庫[そうこ]に置[お]いてある。", "sentence_source": "generated"}, {"text": "料理を作りすぎたので、余りを隣の家にあげた。", "target_word": "余り", "complexity_tier": "T3", "furigana": "料理[りょうり]を作[つく]りすぎたので、余[あま]りを隣[となり]の家[いえ]にあげた。", "sentence_source": "generated"}, {"text": "毛糸の余りを集めて、マフラーを編んだ。", "target_word": "余り", "complexity_tier": "T3", "furigana": "毛糸[けいと]の余[あま]りを集[あつ]めて、マフラーを編[あ]んだ。", "sentence_source": "generated"}, {"text": "買い物の余りのお金は、貯金箱に入れる。", "target_word": "余り", "complexity_tier": "T3", "furigana": "買[か]い物[もの]の余[あま]りのお金[かね]は、貯金箱[ちょきんばこ]に入[い]れる。", "sentence_source": "generated"}, {"text": "材料に余りが出ないように、必要な量だけ買った。", "target_word": "余り", "complexity_tier": "T3", "furigana": "材料[ざいりょう]に余[あま]りが出[で]ないように、必要[ひつよう]な量[りょう]だけ買[か]った。", "sentence_source": "generated"}, {"text": "パーティーの余りのケーキを、みんなで分けた。", "target_word": "余り", "complexity_tier": "T3", "furigana": "パーティーの余[あま]りのケーキを、みんなで分[わ]けた。", "sentence_source": "generated"}, {"text": "紙の余りを捨てずに、メモ用紙にして使っている。", "target_word": "余り", "complexity_tier": "T3", "furigana": "紙[かみ]の余[あま]りを捨[す]てずに、メモ用紙[ようし]にして使[つか]っている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "余り", "label": "基本形"}], "register": "plain", "sense_fingerprint": "使ったあとに残った物やお金。食べ物・布・材料などの残り。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f59eed6c-7780-4a68-92fd-f9cceeb3a107') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35602, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "余り", "is_correct": true, "explanation": "正解。夕食のあとに残った料理を指す『余り』が入る。"}, {"text": "献立", "is_correct": false, "explanation": "献立は料理の予定表のことで、弁当に入れる物ではないので文が成り立たない。"}, {"text": "食器", "is_correct": false, "explanation": "食器は器具のことで、夕食の残りを弁当に入れるという意味にならない。"}, {"text": "余韻", "is_correct": false, "explanation": "余韻は音や味が消えたあとに残る感覚で、弁当に入れる物ではない。"}], "explanations": {"余り": "正解。夕食のあとに残った料理を指す『余り』が入る。", "献立": "献立は料理の予定表のことで、弁当に入れる物ではないので文が成り立たない。", "食器": "食器は器具のことで、夕食の残りを弁当に入れるという意味にならない。", "余韻": "余韻は音や味が消えたあとに残る感覚で、弁当に入れる物ではない。"}, "sentence_index": 0, "correct_answer": "余り"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "映画の余りは、もう少しで終わる。", "explanation": "ここは〈終わり〉（最後の部分）の意味。〈余り〉は使ったあとに残った物を指すので、映画の終わりの部分には使わない。"}, {"text": "十を三で割った余りを、黒板に書いた。", "explanation": "ここは〈割り算の余り〉の意味。使ったあとに残った物やお金ではないので、この文には合わない。"}, {"text": "この案には、もう検討の余りがない。", "explanation": "ここは〈余地〉（考えたり変えたりできる余裕）の意味。〈余り〉は使ったあとに残った物なので、検討の余地の意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66c5ca52-51a7-48b2-bf58-49b55ba482b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35602, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "余り", "is_correct": true, "explanation": "正解。買い物のあとに残ったお金を指す『余り』が入る。"}, {"text": "領収書", "is_correct": false, "explanation": "領収書は買い物の証明書で、お金を貯金箱に入れる物ではない。"}, {"text": "売り場", "is_correct": false, "explanation": "売り場は場所を指し、お金の残りとして貯金箱に入れるものではない。"}, {"text": "余白", "is_correct": false, "explanation": "余白は紙などの空いた部分で、貯金箱に入れるお金の意味にならない。"}], "explanations": {"余り": "正解。買い物のあとに残ったお金を指す『余り』が入る。", "領収書": "領収書は買い物の証明書で、お金を貯金箱に入れる物ではない。", "売り場": "売り場は場所を指し、お金の残りとして貯金箱に入れるものではない。", "余白": "余白は紙などの空いた部分で、貯金箱に入れるお金の意味にならない。"}, "sentence_index": 6, "correct_answer": "余り"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "まだ使っていない材料の余りを、今日は買い足した。", "explanation": "ここは〈これから使う材料〉の意味。〈余り〉は使ったあとに残った物を指すので、まだ使っていない材料には使わない。"}, {"text": "七を二で割った余りは、一だ。", "explanation": "ここは〈割り算の余り〉の意味。使ったあとに残った物やお金ではないので、この文には合わない。"}, {"text": "演奏の余りが、会場にいつまでも響いた。", "explanation": "ここは〈余韻〉（音が消えたあとに残る響き）の意味。〈余り〉は使ったあとの残り物なので、響きには合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66c5ca52-51a7-48b2-bf58-49b55ba482b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35602, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "古い布の余りに、小さなかばんを作った。", "corrected_sentence": "古い布の余りで、小さなかばんを作った。", "error_description": "誤りは『余りに』。材料や手段を表す『で』が正しい。『に』を付けると場所や相手のように扱われ、『作った』の材料として成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66c5ca52-51a7-48b2-bf58-49b55ba482b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35602, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "買い物の余りをお金は、そのまま貯金箱に入れる。", "corrected_sentence": "買い物の余りのお金は、そのまま貯金箱に入れる。", "error_description": "誤りは『余りを』。『余り』に続けるのは『の』で、『余りのお金』と続けるのが正しい。『を』だと『余り』が目的語になり、後のお金と続かない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66c5ca52-51a7-48b2-bf58-49b55ba482b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35603, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『書く』の対象を示す『を』。『余りを書く』が正しい。"}, {"text": "で", "is_correct": false, "explanation": "『で』は手段や場所を示すので、『書く』の対象にはならない。"}, {"text": "に", "is_correct": false, "explanation": "『に』は場所や相手を示すので、書く対象を表すことはできない。"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は方向を示すので、書く対象には使えない。"}], "correct_answer": "を", "explanations": {"を": "『書く』の対象を示す『を』。『余りを書く』が正しい。", "で": "『で』は手段や場所を示すので、『書く』の対象にはならない。", "に": "『に』は場所や相手を示すので、書く対象を表すことはできない。", "へ": "『へ』は方向を示すので、書く対象には使えない。"}, "error_tags": {"で": "手段", "に": "場所・相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66c5ca52-51a7-48b2-bf58-49b55ba482b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35603, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "『余りが三つ出た』の主語を示す『が』。自然な文になる。"}, {"text": "と", "is_correct": false, "explanation": "『と』は並べる相手を示すので、『出た』の主語を表せない。"}, {"text": "より", "is_correct": false, "explanation": "『より』は比較を表すので、出たものを示す文の形に合わない。"}, {"text": "の", "is_correct": false, "explanation": "『の』は名詞をつなぐ助詞なので、『出た』の主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "『余りが三つ出た』の主語を示す『が』。自然な文になる。", "と": "『と』は並べる相手を示すので、『出た』の主語を表せない。", "より": "『より』は比較を表すので、出たものを示す文の形に合わない。", "の": "『の』は名詞をつなぐ助詞なので、『出た』の主語にはならない。"}, "error_tags": {"と": "並列・相手", "より": "比較", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66c5ca52-51a7-48b2-bf58-49b55ba482b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35603, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "割り算で割り切れずに残る数。または、数や量を引いた残りの数。", "primary_collocate": null, "pronunciation": "あまり", "ipa": "amaɾi", "syllable_count": 3, "sentences": [{"text": "十を三で割ると、答えは三で、余りは一だ。", "target_word": "余り", "complexity_tier": "T3", "furigana": "十[じゅう]を三[さん]で割[わ]ると、答[こた]えは三[さん]で、余[あま]りは一[いち]だ。", "sentence_source": "generated"}, {"text": "割り算の余りを書くのを忘れて、点が引かれた。", "target_word": "余り", "complexity_tier": "T3", "furigana": "割[わ]り算[ざん]の余[あま]りを書[か]くのを忘[わす]れて、点[てん]が引[ひ]かれた。", "sentence_source": "generated"}, {"text": "二十個のあめを六人で分けたら、余りは二個だった。", "target_word": "余り", "complexity_tier": "T3", "furigana": "二十個[にじっこ]のあめを六人[ろくにん]で分[わ]けたら、余[あま]りは二個[にこ]だった。", "sentence_source": "generated"}, {"text": "七で割った余りが三になる数を探した。", "target_word": "余り", "complexity_tier": "T3", "furigana": "七[なな]で割[わ]った余[あま]りが三[さん]になる数[かず]を探[さが]した。", "sentence_source": "generated"}, {"text": "余りが出ないように、人数で均等に分けた。", "target_word": "余り", "complexity_tier": "T3", "furigana": "余[あま]りが出[で]ないように、人数[にんずう]で均等[きんとう]に分[わ]けた。", "sentence_source": "generated"}, {"text": "財布に百円あって、八十円使ったら、余りは二十円だ。", "target_word": "余り", "complexity_tier": "T3", "furigana": "財布[さいふ]に百円[ひゃくえん]あって、八十円[はちじゅうえん]使ったら、余り[あまり]は二十円[にじゅうえん]だ。", "sentence_source": "generated"}, {"text": "席の数と人数を比べると、余りは四席だった。", "target_word": "余り", "complexity_tier": "T3", "furigana": "席[せき]の数[かず]と人数[にんずう]を比[くら]べると、余[あま]りは四席[よんせき]だった。", "sentence_source": "generated"}, {"text": "荷物を箱に詰めたら、余りが三つ出た。", "target_word": "余り", "complexity_tier": "T3", "furigana": "荷物[にもつ]を箱[はこ]に詰[つ]めたら、余[あま]りが三[みっ]つ出[で]た。", "sentence_source": "generated"}, {"text": "余りのある割り算を、分数で表してみた。", "target_word": "余り", "complexity_tier": "T3", "furigana": "余[あま]りのある割[わ]り算[ざん]を、分数[ぶんすう]で表[あらわ]してみた。", "sentence_source": "generated"}, {"text": "十五を四で割ると、商は三で余りは三になる。", "target_word": "余り", "complexity_tier": "T3", "furigana": "十五[じゅうご]を四[よん]で割[わ]ると、商[しょう]は三[さん]で余[あま]りは三[さん]になる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "余り", "label": "基本形"}], "register": "plain", "sense_fingerprint": "割り算や引き算のあとに残る数、分けたあとに出る端数。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f59eed6c-7780-4a68-92fd-f9cceeb3a107') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35603, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "余り", "is_correct": true, "explanation": "正解。割り算で割り切れずに残る数の『余り』が入る。"}, {"text": "割れ目", "is_correct": false, "explanation": "割れ目は物が裂けた部分のことで、数の『余り』の位置には入らない。"}, {"text": "食器", "is_correct": false, "explanation": "食器は器具のことで、割り算の結果として一になる文には合わない。"}, {"text": "献立", "is_correct": false, "explanation": "献立は料理の予定表で、数の結果を表す文にならない。"}], "explanations": {"余り": "正解。割り算で割り切れずに残る数の『余り』が入る。", "割れ目": "割れ目は物が裂けた部分のことで、数の『余り』の位置には入らない。", "食器": "食器は器具のことで、割り算の結果として一になる文には合わない。", "献立": "献立は料理の予定表で、数の結果を表す文にならない。"}, "sentence_index": 0, "correct_answer": "余り"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "旅行の余りのお金で、母に花を買った。", "explanation": "ここは〈使ったあとに残ったお金〉の意味。割り算の余りではないので、数の話には合わない。"}, {"text": "演奏の余りが、会場にいつまでも響いた。", "explanation": "ここは〈余韻〉（音が消えたあとに残る響き）の意味。割り算の余りではないので、この文には合わない。"}, {"text": "この案には、もう検討の余りがない。", "explanation": "ここは〈余地〉（考えたり変えたりできる余裕）の意味。割り算の余りではないので、この文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66c5ca52-51a7-48b2-bf58-49b55ba482b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35603, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "余り", "is_correct": true, "explanation": "正解。比べたあとに残った席の数を示す『余り』が入る。"}, {"text": "余韻", "is_correct": false, "explanation": "余韻は音や味が消えたあとに残る感覚で、席の数の意味にならない。"}, {"text": "売り場", "is_correct": false, "explanation": "売り場は場所を指し、席の数を表す文には入らない。"}, {"text": "余白", "is_correct": false, "explanation": "余白は空いた部分のことで、席の数としては文が成り立たない。"}], "explanations": {"余り": "正解。比べたあとに残った席の数を示す『余り』が入る。", "余韻": "余韻は音や味が消えたあとに残る感覚で、席の数の意味にならない。", "売り場": "売り場は場所を指し、席の数を表す文には入らない。", "余白": "余白は空いた部分のことで、席の数としては文が成り立たない。"}, "sentence_index": 6, "correct_answer": "余り"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "買い物の余りで、友達にお菓子をあげた。", "explanation": "ここは〈使ったあとに残った物〉の意味。割り算の余りではないので、この文には合わない。"}, {"text": "夏休みの余りは、あと三日だ。", "explanation": "ここは〈残り〉（まだ先に残っている時間）の意味。割り算の余りではないので、この文には合わない。"}, {"text": "映画の余りは、もう少しで終わる。", "explanation": "ここは〈終わり〉（最後の部分）の意味。割り算の余りではないので、この文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66c5ca52-51a7-48b2-bf58-49b55ba482b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35603, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "七を三で割ると、余りに一になる。", "corrected_sentence": "七を三で割ると、余りは一になる。", "error_description": "誤りは『余りに』。主語にする『は』が正しい。『に』だと『余り』が『一になる』の結果の前にあてはまらず、文として成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66c5ca52-51a7-48b2-bf58-49b55ba482b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35603, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "二十を六で割ると、余りを二になる。", "corrected_sentence": "二十を六で割ると、余りは二になる。", "error_description": "誤りは『余りを』。主語にする『は』が正しい。『を』だと目的語になり、『二になる』と続かない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66c5ca52-51a7-48b2-bf58-49b55ba482b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35604, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "『お金が残らない』の主語を示す『が』。自然な文になる。"}, {"text": "を", "is_correct": false, "explanation": "『残らない』は自動詞なので、『を』では目的語になり文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "『に』は場所や相手を示すので、残るものを示す文には合わない。"}, {"text": "で", "is_correct": false, "explanation": "『で』は手段を示すので、残るお金の主語にはならない。"}], "correct_answer": "が", "explanations": {"が": "『お金が残らない』の主語を示す『が』。自然な文になる。", "を": "『残らない』は自動詞なので、『を』では目的語になり文が成り立たない。", "に": "『に』は場所や相手を示すので、残るものを示す文には合わない。", "で": "『で』は手段を示すので、残るお金の主語にはならない。"}, "error_tags": {"を": "対象", "に": "場所・相手", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66c5ca52-51a7-48b2-bf58-49b55ba482b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35604, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66c5ca52-51a7-48b2-bf58-49b55ba482b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35604, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "お金や物が使われずに、あとでまだあること。", "primary_collocate": null, "pronunciation": "のこる", "ipa": "nokoɾɯ", "syllable_count": 3, "sentences": [{"text": "昼ご飯を買っても、財布にはまだ千円残っている。", "target_word": "残っている", "complexity_tier": "T3", "furigana": "昼[ひる]ご飯[はん]を買[か]っても、財布[さいふ]にはまだ千円[せんえん]残[のこ]っている。", "sentence_source": "generated"}, {"text": "給料から家賃を払うと、ほとんどお金が残らない。", "target_word": "残らない", "complexity_tier": "T3", "furigana": "給料[きゅうりょう]から家賃[やちん]を払[はら]うと、ほとんどお金[かね]が残[のこ]らない。", "sentence_source": "generated"}, {"text": "パーティーの料理が多すぎて、たくさん残った。", "target_word": "残った", "complexity_tier": "T3", "furigana": "パーティーの料理[りょうり]が多[おお]すぎて、たくさん残[のこ]った。", "sentence_source": "generated"}, {"text": "ケーキを食べたが、半分だけ残っている。", "target_word": "残っている", "complexity_tier": "T3", "furigana": "ケーキを食[た]べたが、半分[はんぶん]だけ残[のこ]っている。", "sentence_source": "generated"}, {"text": "旅行の予算が、一万円残った。", "target_word": "残った", "complexity_tier": "T3", "furigana": "旅行[りょこう]の予算[よさん]が、一万円[いちまんえん]残[のこ]った。", "sentence_source": "generated"}, {"text": "冷蔵庫には、昨日の野菜が少し残っている。", "target_word": "残っている", "complexity_tier": "T3", "furigana": "冷蔵庫[れいぞうこ]には、昨日[きのう]の野菜[やさい]が少[すこ]し残[のこ]っている。", "sentence_source": "generated"}, {"text": "全部使ったので、インクは一滴も残らなかった。", "target_word": "残らなかった", "complexity_tier": "T3", "furigana": "全部[ぜんぶ]使[つか]ったので、インクは一滴[いってき]も残[のこ]らなかった。", "sentence_source": "generated"}, {"text": "計算が正しければ、百円残るはずだ。", "target_word": "残る", "complexity_tier": "T3", "furigana": "計算[けいさん]が正[ただ]しければ、百円[ひゃくえん]残[のこ]るはずだ。", "sentence_source": "generated"}, {"text": "使わなかった切符が、かばんに二枚残っていた。", "target_word": "残っていた", "complexity_tier": "T3", "furigana": "使[つか]わなかった切符[きっぷ]が、かばんに二枚[にまい]残[のこ]っていた。", "sentence_source": "generated"}, {"text": "お金が残ったら、新しい本を買うつもりだ。", "target_word": "残ったら", "complexity_tier": "T3", "furigana": "お金[かね]が残[のこ]ったら、新[あたら]しい本[ほん]を買[か]うつもりだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "残る", "label": "終止形"}, {"form": "残った", "label": "過去形"}, {"form": "残って", "label": "て形"}, {"form": "残らない", "label": "否定形"}, {"form": "残ります", "label": "丁寧形"}, {"form": "残れば", "label": "仮定形"}], "register": "中立（普通体）", "sense_fingerprint": "お金・食べ物・材料などが使われずに、あとに余っている。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f59eed6c-7780-4a68-92fd-f9cceeb3a107') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35604, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "残っている", "is_correct": true, "explanation": "正解。使われずに財布に千円がまだある、という意味で合う。"}, {"text": "膨らんでいる", "is_correct": false, "explanation": "膨らむのは物の体積が増えることで、お金の残りを表す文には合わない。"}, {"text": "固まっている", "is_correct": false, "explanation": "固まるのは物の形が硬くなることで、財布の中の千円には当てはまらない。"}, {"text": "届いている", "is_correct": false, "explanation": "届くのは物や知らせが到着することで、財布の中のお金の残りには使えない。"}], "explanations": {"残っている": "正解。使われずに財布に千円がまだある、という意味で合う。", "膨らんでいる": "膨らむのは物の体積が増えることで、お金の残りを表す文には合わない。", "固まっている": "固まるのは物の形が硬くなることで、財布の中の千円には当てはまらない。", "届いている": "届くのは物や知らせが到着することで、財布の中のお金の残りには使えない。"}, "sentence_index": 0, "correct_answer": "残っている"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "放課後も一人だけ教室に残って、本を読んでいた。", "explanation": "ここは〈その場にとどまる〉の意味。お金や食べ物が使われずに余るという意味ではない。"}, {"text": "最終選考には、三人だけが残った。", "explanation": "ここは〈選考を勝ち抜いて次に進む〉の意味。お金や物が余るという意味ではない。"}, {"text": "仕事が終わらず、会社に残って夜遅くまで作業した。", "explanation": "ここは〈会社などに留まる〉の意味。お金や食べ物が余るという意味ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66c5ca52-51a7-48b2-bf58-49b55ba482b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35604, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "残らなかった", "is_correct": true, "explanation": "正解。全部使ってインクが一滴もなかった、という否定の過去形に合う。"}, {"text": "叫ばなかった", "is_correct": false, "explanation": "叫ぶは声を出すことで、インクには当てはまらない。"}, {"text": "踊らなかった", "is_correct": false, "explanation": "踊るは体を動かすことで、インクの残りを表す文には入らない。"}, {"text": "凍らなかった", "is_correct": false, "explanation": "凍るは水などが固まることで、使い切ったインクの残りの文脈には合わない。"}], "explanations": {"残らなかった": "正解。全部使ってインクが一滴もなかった、という否定の過去形に合う。", "叫ばなかった": "叫ぶは声を出すことで、インクには当てはまらない。", "踊らなかった": "踊るは体を動かすことで、インクの残りを表す文には入らない。", "凍らなかった": "凍るは水などが固まることで、使い切ったインクの残りの文脈には合わない。"}, "sentence_index": 6, "correct_answer": "残らなかった"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "終電を逃したので、友達の家に残って泊まった。", "explanation": "ここは〈その場に留まる〉の意味。お金や物が余るという意味ではない。"}, {"text": "二次審査に残ったのは、わずか五人だった。", "explanation": "ここは〈選考を通過する〉の意味。お金や物が余るという意味ではない。"}, {"text": "大会の準備のため、彼はしばらく会場に残った。", "explanation": "ここは〈その場に留まる〉の意味。お金や物が余るという意味ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66c5ca52-51a7-48b2-bf58-49b55ba482b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35604, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "食事代を払っても、財布にはまだ千円を残っている。", "corrected_sentence": "食事代を払っても、財布にはまだ千円が残っている。", "error_description": "誤りは『千円を』。『残っている』は自動詞なので、主語の『千円』には『が』を付ける。『を』は他動詞の目的語を示すので合わない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "残らない", "is_correct": true, "explanation": "正解。『〜ない』の否定形で、お金が残らないという文に合う。"}, {"text": "残れ", "is_correct": false, "explanation": "命令形。『払うと』に続けて文を終えると不自然で、文として成り立たない。"}, {"text": "残って", "is_correct": false, "explanation": "て形。文を終わらせられず、『ない』などの語が続かないと文として成り立たない。"}, {"text": "残ります", "is_correct": false, "explanation": "丁寧形。前後が普通体の文なので、文体が合わない。"}], "correct_form": "残らない", "base_form": "残る", "form_label": "否定形（ない形）", "sentence_index": 1, "explanations": {"残らない": "正解。『〜ない』の否定形で、お金が残らないという文に合う。", "残れ": "命令形。『払うと』に続けて文を終えると不自然で、文として成り立たない。", "残って": "て形。文を終わらせられず、『ない』などの語が続かないと文として成り立たない。", "残ります": "丁寧形。前後が普通体の文なので、文体が合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66c5ca52-51a7-48b2-bf58-49b55ba482b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35604, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "お金を残れば、新しい本を買うつもりだ。", "corrected_sentence": "お金が残れば、新しい本を買うつもりだ。", "error_description": "誤りは『を』。『残る』は自動詞なので、主語の『お金』には『が』を付ける。『を』だと目的語になり、残るという意味が通らない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "残る", "is_correct": true, "explanation": "正解。『計算が正しければ』に続く、基本形で『はずだ』につながる形。"}, {"text": "残れば", "is_correct": false, "explanation": "仮定形。『はずだ』と続けると文が成り立たない。"}, {"text": "残ろう", "is_correct": false, "explanation": "意志形。『はずだ』と続けると意味が通らない。"}, {"text": "残らず", "is_correct": false, "explanation": "『全部』の意味の副詞的な形で、『はずだ』とは続かない。"}], "correct_form": "残る", "base_form": "残る", "form_label": "基本形（辞書形）", "sentence_index": 7, "explanations": {"残る": "正解。『計算が正しければ』に続く、基本形で『はずだ』につながる形。", "残れば": "仮定形。『はずだ』と続けると文が成り立たない。", "残ろう": "意志形。『はずだ』と続けると意味が通らない。", "残らず": "『全部』の意味の副詞的な形で、『はずだ』とは続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66c5ca52-51a7-48b2-bf58-49b55ba482b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35605, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "『落書きが残っている』の主語を示す『が』。自然な文になる。"}, {"text": "を", "is_correct": false, "explanation": "『残っている』は自動詞なので、『を』では目的語になり文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "『で』は手段や場所を示すので、残っているものの主語にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は方向を示すので、残っている状態の主語を表せない。"}], "correct_answer": "が", "explanations": {"が": "『落書きが残っている』の主語を示す『が』。自然な文になる。", "を": "『残っている』は自動詞なので、『を』では目的語になり文が成り立たない。", "で": "『で』は手段や場所を示すので、残っているものの主語にはならない。", "へ": "『へ』は方向を示すので、残っている状態の主語を表せない。"}, "error_tags": {"を": "対象", "で": "手段", "へ": "方向"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "消える", "is_correct": true, "explanation": "残る（跡や物が消えずにまだある）の対義語。跡が見えなくなる意味。"}, {"text": "増える", "is_correct": false, "explanation": "数や量が多くなる意味で、残る（まだある）の対義語ではない。"}, {"text": "進む", "is_correct": false, "explanation": "前へ動くことで、残るとは対になる関係ではない。"}, {"text": "集まる", "is_correct": false, "explanation": "人や物が一か所に寄ることで、残るの対義語ではない。"}], "correct_answer": "消える", "explanations": {"消える": "残る（跡や物が消えずにまだある）の対義語。跡が見えなくなる意味。", "増える": "数や量が多くなる意味で、残る（まだある）の対義語ではない。", "進む": "前へ動くことで、残るとは対になる関係ではない。", "集まる": "人や物が一か所に寄ることで、残るの対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66c5ca52-51a7-48b2-bf58-49b55ba482b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35605, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "『足あとが残っていた』の主語を示す『が』。自然な文になる。"}, {"text": "に", "is_correct": false, "explanation": "『に』は場所を示すので、残っていたものの主語にはならない。"}, {"text": "より", "is_correct": false, "explanation": "『より』は比較を表すので、残っていた状態を示す文には合わない。"}, {"text": "の", "is_correct": false, "explanation": "『の』は名詞をつなぐ助詞なので、残っている動詞の主語を示せない。"}], "correct_answer": "が", "explanations": {"が": "『足あとが残っていた』の主語を示す『が』。自然な文になる。", "に": "『に』は場所を示すので、残っていたものの主語にはならない。", "より": "『より』は比較を表すので、残っていた状態を示す文には合わない。", "の": "『の』は名詞をつなぐ助詞なので、残っている動詞の主語を示せない。"}, "error_tags": {"に": "場所・相手", "より": "比較", "の": "連体修飾"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "消える", "is_correct": true, "explanation": "残る（壊れずにまだある）の対義語。跡や形が見えなくなる意味。"}, {"text": "始まる", "is_correct": false, "explanation": "動きや物事が起こることで、残るの対義語ではない。"}, {"text": "届く", "is_correct": false, "explanation": "物や知らせが到着することで、残るとは対になる関係ではない。"}, {"text": "戻る", "is_correct": false, "explanation": "元の場所や状態に返ることで、残るの対義語ではない。"}], "correct_answer": "消える", "explanations": {"消える": "残る（壊れずにまだある）の対義語。跡や形が見えなくなる意味。", "始まる": "動きや物事が起こることで、残るの対義語ではない。", "届く": "物や知らせが到着することで、残るとは対になる関係ではない。", "戻る": "元の場所や状態に返ることで、残るの対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66c5ca52-51a7-48b2-bf58-49b55ba482b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35605, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ある場所や状態の中に、使い切らずにまだある。", "primary_collocate": null, "pronunciation": "のこる", "ipa": "nokoɾɯ", "syllable_count": 3, "sentences": [{"text": "山の上には、まだ雪が残っている。", "target_word": "残っている", "complexity_tier": "T3", "furigana": "山[やま]の上[うえ]には、まだ雪[ゆき]が残[のこ]っている。", "sentence_source": "generated"}, {"text": "壁に子どもの落書きが残っている。", "target_word": "残っている", "complexity_tier": "T3", "furigana": "壁[かべ]に子[こ]どもの落書[らくが]きが残[のこ]っている。", "sentence_source": "generated"}, {"text": "火事のあとも、古い門だけが残った。", "target_word": "残った", "complexity_tier": "T3", "furigana": "火事[かじ]のあとも、古[ふる]い門[もん]だけが残[のこ]った。", "sentence_source": "generated"}, {"text": "洗っても、シャツにしみが残る。", "target_word": "残る", "complexity_tier": "T3", "furigana": "洗[あら]っても、シャツにしみが残[のこ]る。", "sentence_source": "generated"}, {"text": "村には昔の家がいくつか残っている。", "target_word": "残っている", "complexity_tier": "T3", "furigana": "村[むら]には昔[むかし]の家[いえ]がいくつか残[のこ]っている。", "sentence_source": "generated"}, {"text": "薬を飲んだが、のどの痛みが残っている。", "target_word": "残っている", "complexity_tier": "T3", "furigana": "薬[くすり]を飲[の]んだが、のどの痛[いた]みが残[のこ]っている。", "sentence_source": "generated"}, {"text": "夏が終わっても、暑さが残る日が続いた。", "target_word": "残る", "complexity_tier": "T3", "furigana": "夏[なつ]が終[お]わっても、暑[あつ]さが残[のこ]る日[ひ]が続[つづ]いた。", "sentence_source": "generated"}, {"text": "砂の上に、足あとが残っていた。", "target_word": "残っていた", "complexity_tier": "T3", "furigana": "砂[すな]の上[うえ]に、足[あし]あとが残[のこ]っていた。", "sentence_source": "generated"}, {"text": "古い町並みが残る町を、ゆっくり歩いた。", "target_word": "残る", "complexity_tier": "T3", "furigana": "古[ふる]い町並[まちな]みが残[のこ]る町[まち]を、ゆっくり歩[ある]いた。", "sentence_source": "generated"}, {"text": "地震のあとも、このビルだけは壊れずに残った。", "target_word": "残った", "complexity_tier": "T3", "furigana": "地震[じしん]のあとも、このビルだけは壊[こわ]れずに残[のこ]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "残る", "label": "終止形"}, {"form": "残った", "label": "過去形"}, {"form": "残って", "label": "て形"}, {"form": "残らない", "label": "否定形"}, {"form": "残ります", "label": "丁寧形"}, {"form": "残れば", "label": "仮定形"}], "register": "中立（普通体）", "sense_fingerprint": "ある場所や状態に、跡・物・感覚などが消えずにまだある。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f59eed6c-7780-4a68-92fd-f9cceeb3a107') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35605, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "残っている", "is_correct": true, "explanation": "正解。山の上に雪がまだ消えずにある、という状態に合う。"}, {"text": "走っている", "is_correct": false, "explanation": "走るは人や動物が速く進むことで、雪には使えない。"}, {"text": "鳴いている", "is_correct": false, "explanation": "鳴くは声を出すことで、雪には当てはまらない。"}, {"text": "生えている", "is_correct": false, "explanation": "生えるは植物などが伸びることで、雪には使えない。"}], "explanations": {"残っている": "正解。山の上に雪がまだ消えずにある、という状態に合う。", "走っている": "走るは人や動物が速く進むことで、雪には使えない。", "鳴いている": "鳴くは声を出すことで、雪には当てはまらない。", "生えている": "生えるは植物などが伸びることで、雪には使えない。"}, "sentence_index": 0, "correct_answer": "残っている"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "放課後も、彼女は一人で教室に残って勉強した。", "explanation": "ここは〈その場にとどまる〉の意味。跡や物がまだあるという意味ではない。"}, {"text": "最終選考には、地元のチームだけが残った。", "explanation": "ここは〈選考を勝ち抜く〉の意味。跡や物が残るという意味ではない。"}, {"text": "会社に残って、新しい企画を一人で考えた。", "explanation": "ここは〈会社などに留まる〉の意味。跡や物がまだあるという意味ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66c5ca52-51a7-48b2-bf58-49b55ba482b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35605, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "残る", "is_correct": true, "explanation": "正解。夏が終わっても暑さがまだある、という意味で『残る日』に合う。"}, {"text": "転がる", "is_correct": false, "explanation": "転がるは物が回りながら動くことで、暑さの文には当てはまらない。"}, {"text": "叫ぶ", "is_correct": false, "explanation": "叫ぶは声を大きく出すことで、暑さの状態には使えない。"}, {"text": "眠る", "is_correct": false, "explanation": "眠るは休むことで、暑さを主語にする文としては成り立たない。"}], "explanations": {"残る": "正解。夏が終わっても暑さがまだある、という意味で『残る日』に合う。", "転がる": "転がるは物が回りながら動くことで、暑さの文には当てはまらない。", "叫ぶ": "叫ぶは声を大きく出すことで、暑さの状態には使えない。", "眠る": "眠るは休むことで、暑さを主語にする文としては成り立たない。"}, "sentence_index": 6, "correct_answer": "残る"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "試合のあと、選手たちはしばらく球場に残った。", "explanation": "ここは〈その場にとどまる〉の意味。跡や物がまだあるという意味ではない。"}, {"text": "一次審査に残ったのは、わずか五人だった。", "explanation": "ここは〈選考を通過する〉の意味。跡や物が残るという意味ではない。"}, {"text": "授業のあとも、先生は教室に残って質問に答えた。", "explanation": "ここは〈その場にとどまる〉の意味。跡や物がまだあるという意味ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66c5ca52-51a7-48b2-bf58-49b55ba482b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35605, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "山頂には、まだ雪を残っている。", "corrected_sentence": "山頂には、まだ雪が残っている。", "error_description": "誤りは『雪を』。『残っている』は自動詞なので、主語の『雪』には『が』を付ける。『を』は目的語を示すので合わない。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "残っている", "is_correct": true, "explanation": "正解。落書きがまだ壁にある、という状態を表す形。"}, {"text": "残れ", "is_correct": false, "explanation": "命令形。文を言い切って状態を述べることができず、文として成り立たない。"}, {"text": "残らない", "is_correct": false, "explanation": "否定形。落書きが残っているという文と矛盾する。"}, {"text": "残れば", "is_correct": false, "explanation": "仮定形。文を言い切れず、状態を述べる文として成り立たない。"}], "correct_form": "残っている", "base_form": "残る", "form_label": "〜ている形（状態）", "sentence_index": 1, "explanations": {"残っている": "正解。落書きがまだ壁にある、という状態を表す形。", "残れ": "命令形。文を言い切って状態を述べることができず、文として成り立たない。", "残らない": "否定形。落書きが残っているという文と矛盾する。", "残れば": "仮定形。文を言い切れず、状態を述べる文として成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66c5ca52-51a7-48b2-bf58-49b55ba482b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35605, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夏が終わっても、暑さを残る日々が続いた。", "corrected_sentence": "夏が終わっても、暑さが残る日々が続いた。", "error_description": "誤りは『暑さを』。『残る』は自動詞なので、主語の『暑さ』には『が』を付ける。『を』は目的語を示すので合わない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "残っていた", "is_correct": true, "explanation": "正解。過去の時点で足あとがある状態を表す形。"}, {"text": "残らず", "is_correct": false, "explanation": "『全部』の意味の形で、足あとがあるという状態を表せない。"}, {"text": "残ろう", "is_correct": false, "explanation": "意志の形で、既にある足あとの状態には合わない。"}, {"text": "残らない", "is_correct": false, "explanation": "否定形。足あとがあったという文と矛盾する。"}], "correct_form": "残っていた", "base_form": "残る", "form_label": "〜ていた形（過去の状態）", "sentence_index": 7, "explanations": {"残っていた": "正解。過去の時点で足あとがある状態を表す形。", "残らず": "『全部』の意味の形で、足あとがあるという状態を表せない。", "残ろう": "意志の形で、既にある足あとの状態には合わない。", "残らない": "否定形。足あとがあったという文と矛盾する。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66c5ca52-51a7-48b2-bf58-49b55ba482b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
