INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35607, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "一番小さい正の整数。ひとつ。", "primary_collocate": null, "pronunciation": "いち", "ipa": "itɕi", "syllable_count": 2, "sentences": [{"text": "1 に1を足すと2になります。", "target_word": "1", "complexity_tier": "T3", "furigana": "1[いち] に1[いち]を足[た]すと2[に]になります。", "sentence_source": "generated"}, {"text": "1 から10まで声に出して数えました。", "target_word": "1", "complexity_tier": "T3", "furigana": "1[いち] から10[じゅう]まで声[こえ]に出[だ]して数[かぞ]えました。", "sentence_source": "generated"}, {"text": "3から2を引くと 1 になります。", "target_word": "1", "complexity_tier": "T3", "furigana": "3[さん]から2[に]を引[ひ]くと 1[いち] になります。", "sentence_source": "generated"}, {"text": "出席番号が 1 の人は、列の先頭に並びます。", "target_word": "1", "complexity_tier": "T3", "furigana": "出席番号[しゅっせきばんごう]が 1[いち] の人[ひと]は、列[れつ]の先頭[せんとう]に並[なら]びます。", "sentence_source": "generated"}, {"text": "6から5を引くと、答えは 1 です。", "target_word": "1", "complexity_tier": "T3", "furigana": "6[ろく]から5[ご]を引[ひ]くと、答[こた]えは 1[いち] です。", "sentence_source": "generated"}, {"text": "1 は偶数ではなく、奇数です。", "target_word": "1", "complexity_tier": "T3", "furigana": "1[いち] は偶数[ぐうすう]ではなく、奇数[きすう]です。", "sentence_source": "generated"}, {"text": "数字の 1 は、縦に一本の線を引いて書きます。", "target_word": "1", "complexity_tier": "T3", "furigana": "数字[すうじ]の 1[いち] は、縦[たて]に一本[いっぽん]の線[せん]を引[ひ]いて書[か]きます。", "sentence_source": "generated"}, {"text": "1 を二回足すと、2になります。", "target_word": "1", "complexity_tier": "T3", "furigana": "1[いち] を二回[にかい]足[た]すと、2[に]になります。", "sentence_source": "generated"}, {"text": "1 と2を比べると、小さいのは1です。", "target_word": "1", "complexity_tier": "T3", "furigana": "1[いち] と2[に]を比[くら]べると、小[ちい]さいのは1[いち]です。", "sentence_source": "generated"}, {"text": "テストの問題は 1 から順番に解きます。", "target_word": "1", "complexity_tier": "T3", "furigana": "テストの問題[もんだい]は 1[いち] から順番[じゅんばん]に解[と]きます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "1", "label": "基本形"}], "register": "中立（丁寧体）", "sense_fingerprint": "数字の1。最初の整数で、計算や順番を表す数としての「いち」", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55d77c36-1221-46e8-9ca1-e98c3b3fa4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35607, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "1", "is_correct": true, "explanation": "「1に1を足すと2」が成り立つ。空欄に入るのは1だけ。"}, {"text": "4", "is_correct": false, "explanation": "「4に1を足すと5」になり、2にはならない。"}, {"text": "5", "is_correct": false, "explanation": "「5に1を足すと6」になり、2にはならない。"}, {"text": "8", "is_correct": false, "explanation": "「8に1を足すと9」になり、2にはならない。"}], "explanations": {"1": "「1に1を足すと2」が成り立つ。空欄に入るのは1だけ。", "4": "「4に1を足すと5」になり、2にはならない。", "5": "「5に1を足すと6」になり、2にはならない。", "8": "「8に1を足すと9」になり、2にはならない。"}, "sentence_index": 0, "correct_answer": "1"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "1 も間違えなかった。", "explanation": "ここは〈一つ〉の意味。「一つも」の「一つ」は物を数える言い方で、「1も」とは言わない。"}, {"text": "彼は 1 途に勉強を続けた。", "explanation": "ここは〈一途〉（ひたむき）の意味。「一途に」と言い、数字の1は「途」と結びつかない。"}, {"text": "1 緒に行こう。", "explanation": "ここは〈一緒〉の意味。「一緒」の「一」は数字の1として書かない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75f8b2ea-b1b2-4b0b-bd9b-d6649c858d5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35607, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "1", "is_correct": true, "explanation": "縦に一本の線を引いて書く数字は1。"}, {"text": "2", "is_correct": false, "explanation": "2は曲線を含む形で、一本の線では書けない。"}, {"text": "7", "is_correct": false, "explanation": "7は横線と斜めの線で書くので、縦一本の説明には合わない。"}, {"text": "9", "is_correct": false, "explanation": "9は丸と線で書くので、縦一本の説明には合わない。"}], "explanations": {"1": "縦に一本の線を引いて書く数字は1。", "2": "2は曲線を含む形で、一本の線では書けない。", "7": "7は横線と斜めの線で書くので、縦一本の説明には合わない。", "9": "9は丸と線で書くので、縦一本の説明には合わない。"}, "sentence_index": 6, "correct_answer": "1"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は 1 生懸命に勉強した。", "explanation": "ここは〈一生懸命〉（力を尽くすこと）の意味。「一生懸命に」と言い、数字の1は「生懸命」と結びつかない。"}, {"text": "1 方的に責められた。", "explanation": "ここは〈一方〉（片側）の意味。「一方的」の「一」は接頭語で、数字の1は前につけない。"}, {"text": "1 斉に手を挙げた。", "explanation": "ここは〈一斉〉の意味。「一斉に」は同時に行うことで、数字の1は「斉」と結びつかない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75f8b2ea-b1b2-4b0b-bd9b-d6649c858d5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35607, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "4 から 1 が引くと、答えは 3 です。", "corrected_sentence": "4 から 1 を引くと、答えは 3 です。", "error_description": "「引く」の目的語には助詞「を」が必要。「が」だと1が主語になり、文として合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75f8b2ea-b1b2-4b0b-bd9b-d6649c858d5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35607, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "5 に 1 に足すと、答えは 6 です。", "corrected_sentence": "5 に 1 を足すと、答えは 6 です。", "error_description": "「足す」の目的語には助詞「を」が必要。「に」では足す対象を示せない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75f8b2ea-b1b2-4b0b-bd9b-d6649c858d5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35608, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "「杯から酒を飲む」で、杯が酒の出どころを示す。文に自然に入る。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すため、「杯が酒を飲んだ」となり、杯が飲む主体になってしまう。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は行き先を示すため、「杯へ酒を飲んだ」は意味が合わない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は「酒を」に既に付いており、ここに入れると「杯を酒を」と二重になり不自然。"}], "correct_answer": "から", "explanations": {"から": "「杯から酒を飲む」で、杯が酒の出どころを示す。文に自然に入る。", "が": "「が」は主語を示すため、「杯が酒を飲んだ」となり、杯が飲む主体になってしまう。", "へ": "「へ」は行き先を示すため、「杯へ酒を飲んだ」は意味が合わない。", "を": "「を」は「酒を」に既に付いており、ここに入れると「杯を酒を」と二重になり不自然。"}, "error_tags": {"が": "主語", "へ": "方向", "を": "目的語の重複"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66c5ca52-51a7-48b2-bf58-49b55ba482b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35608, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「杯に注ぐ」で、注ぎ入れる先の器を示す。文に自然に入る。"}, {"text": "と", "is_correct": false, "explanation": "「と」は一緒の相手を示すので、「神社で杯と注いだ酒」は成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較の基準を示すので、注ぐ先を表す文脈には合わない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐため、「杯の注いだ酒」では注ぐ先の関係が示せず不自然。"}], "correct_answer": "に", "explanations": {"に": "「杯に注ぐ」で、注ぎ入れる先の器を示す。文に自然に入る。", "と": "「と」は一緒の相手を示すので、「神社で杯と注いだ酒」は成り立たない。", "より": "「より」は比較の基準を示すので、注ぐ先を表す文脈には合わない。", "の": "「の」は名詞をつなぐため、「杯の注いだ酒」では注ぐ先の関係が示せず不自然。"}, "error_tags": {"と": "並列", "より": "比較", "の": "所属"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66c5ca52-51a7-48b2-bf58-49b55ba482b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35608, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "飲み物を入れるための、小さな入れ物のことです。", "primary_collocate": null, "pronunciation": "さかずき", "ipa": "sakadzɯki", "syllable_count": 4, "sentences": [{"text": "祖父は小さな杯に酒をついで、ゆっくり飲んだ。", "target_word": "杯", "complexity_tier": "T3", "furigana": "祖父[そふ]は小[ちい]さな杯[さかずき]に酒[さけ]をついで、ゆっくり飲[の]んだ。", "sentence_source": "generated"}, {"text": "結婚式で、二人は同じ杯から酒を飲んだ。", "target_word": "杯", "complexity_tier": "T3", "furigana": "結婚式[けっこんしき]で、二人[ふたり]は同[おな]じ杯[さかずき]から酒[さけ]を飲[の]んだ。", "sentence_source": "generated"}, {"text": "食事の前に、父が杯を持ち上げて挨拶した。", "target_word": "杯", "complexity_tier": "T3", "furigana": "食事[しょくじ]の前[まえ]に、父[ちち]が杯[さかずき]を持[も]ち上[あ]げて挨拶[あいさつ]した。", "sentence_source": "generated"}, {"text": "木でできた杯は、軽くて持ちやすい。", "target_word": "杯", "complexity_tier": "T3", "furigana": "木[き]でできた杯[さかずき]は、軽[かる]くて持[も]ちやすい。", "sentence_source": "generated"}, {"text": "杯が空になったので、店の人が酒を足した。", "target_word": "杯", "complexity_tier": "T3", "furigana": "杯[さかずき]が空[から]になったので、店[みせ]の人[ひと]が酒[さけ]を足[た]した。", "sentence_source": "generated"}, {"text": "古い杯を棚から出して、客に出した。", "target_word": "杯", "complexity_tier": "T3", "furigana": "古[ふる]い杯[さかずき]を棚[たな]から出[だ]して、客[きゃく]に出[だ]した。", "sentence_source": "generated"}, {"text": "杯を重ねるうちに、話が盛り上がった。", "target_word": "杯", "complexity_tier": "T3", "furigana": "杯[さかずき]を重[かさ]ねるうちに、話[はなし]が盛[も]り上[あ]がった。", "sentence_source": "generated"}, {"text": "祭りの日、神社で杯に注いだ酒をいただく。", "target_word": "杯", "complexity_tier": "T3", "furigana": "祭[まつ]りの日[ひ]、神社[じんじゃ]で杯[さかずき]に注[そそ]いだ酒[さけ]をいただく。", "sentence_source": "generated"}, {"text": "彼は杯を傾けながら、昔の友達を思い出した。", "target_word": "杯", "complexity_tier": "T3", "furigana": "彼[かれ]は杯[さかずき]を傾[かたむ]けながら、昔[むかし]の友達[ともだち]を思[おも]い出[だ]した。", "sentence_source": "generated"}, {"text": "この杯は、百年前に作られたものだ。", "target_word": "杯", "complexity_tier": "T3", "furigana": "この杯[さかずき]は、百年前[ひゃくねんまえ]に作[つく]られたものだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "杯", "label": "基本形"}], "register": "中立（普通体）", "sense_fingerprint": "酒を飲むための小さな器。杯を交わす・重ねるなど、酒の席で使う。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f59eed6c-7780-4a68-92fd-f9cceeb3a107') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35608, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "杯", "is_correct": true, "explanation": "「小さな杯に酒をつぐ」は自然な言い方で、文の意味に合う。"}, {"text": "皿", "is_correct": false, "explanation": "皿は料理を盛る器で、酒をつぐ対象にはならないので文が成り立たない。"}, {"text": "フォーク", "is_correct": false, "explanation": "フォークは食べ物を刺す道具で、酒を注ぐ器ではない。"}, {"text": "ナイフ", "is_correct": false, "explanation": "ナイフは切る道具で、酒をつぐことはできない。"}], "explanations": {"杯": "「小さな杯に酒をつぐ」は自然な言い方で、文の意味に合う。", "皿": "皿は料理を盛る器で、酒をつぐ対象にはならないので文が成り立たない。", "フォーク": "フォークは食べ物を刺す道具で、酒を注ぐ器ではない。", "ナイフ": "ナイフは切る道具で、酒をつぐことはできない。"}, "sentence_index": 0, "correct_answer": "杯"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "お祝いの料理を、小さな杯に盛りつけた。", "explanation": "ここは〈皿〉の意味。料理を盛るのは皿で、杯は酒を飲むための器なので、料理を盛る使い方はしない。"}, {"text": "豆を杯でつまんで、口に運んだ。", "explanation": "ここは〈箸〉の意味。豆をつまむのは箸で、杯は酒を飲む器なので、物をつまむ道具としては使わない。"}, {"text": "ノートに字を杯で書いた。", "explanation": "ここは〈ペン〉の意味。字を書くのはペンで、杯は字を書く道具ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66c5ca52-51a7-48b2-bf58-49b55ba482b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35608, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "杯", "is_correct": true, "explanation": "「杯を重ねる」は酒を何度も飲むことを表す言い方で、文の意味に合う。"}, {"text": "箸", "is_correct": false, "explanation": "箸は食事の道具で、酒の席で何度も重ねて飲むという意味にはならない。"}, {"text": "スプーン", "is_correct": false, "explanation": "スプーンは食べ物をすくう道具で、「重ねて話が盛り上がる」の流れに合わない。"}, {"text": "包丁", "is_correct": false, "explanation": "包丁は料理に使う刃物で、酒を重ねるという文脈では成り立たない。"}], "explanations": {"杯": "「杯を重ねる」は酒を何度も飲むことを表す言い方で、文の意味に合う。", "箸": "箸は食事の道具で、酒の席で何度も重ねて飲むという意味にはならない。", "スプーン": "スプーンは食べ物をすくう道具で、「重ねて話が盛り上がる」の流れに合わない。", "包丁": "包丁は料理に使う刃物で、酒を重ねるという文脈では成り立たない。"}, "sentence_index": 6, "correct_answer": "杯"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "寝る前に杯を読んで、眠くなるのを待った。", "explanation": "ここは〈本〉の意味。本は読むものだが、杯は読むものではないので、「読む」とは使わない。"}, {"text": "花瓶に杯をいけて、窓辺に飾った。", "explanation": "ここは〈花〉の意味。花をいけるのは花瓶で、杯は花をいける器ではない。"}, {"text": "雨が降ってきたので、杯をさした。", "explanation": "ここは〈傘〉の意味。雨の日にさすのは傘で、杯は雨具ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66c5ca52-51a7-48b2-bf58-49b55ba482b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35608, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父は古い杯が酒をついで、祖母に渡した。", "corrected_sentence": "父は古い杯に酒をついで、祖母に渡した。", "error_description": "「杯」は酒をつぐ先なので「に」を使う。「が」は主語を示すため、ここでは「杯が酒をついで」となり意味が通らない。誤りは「が」で、正しくは「に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66c5ca52-51a7-48b2-bf58-49b55ba482b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35608, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "友人と杯を積むうちに、夜が更けていった。", "corrected_sentence": "友人と杯を重ねるうちに、夜が更けていった。", "error_description": "「杯」に続く動詞が違う。「杯を積む」は不自然で、酒を続けて飲む意味には「杯を重ねる」を使う。誤りは「積む」、正しくは「重ねる」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66c5ca52-51a7-48b2-bf58-49b55ba482b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35609, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66c5ca52-51a7-48b2-bf58-49b55ba482b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35609, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「杯に八分目まで入れる」で、入れる先の器を示す。文に自然に入る。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すため、「杯が八分目まで入れる」では杯が入れる主体になり意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や共同を示すので、「杯と八分目まで入れる」は成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較の基準なので、入れる先を示す文脈には合わない。"}], "correct_answer": "に", "explanations": {"に": "「杯に八分目まで入れる」で、入れる先の器を示す。文に自然に入る。", "が": "「が」は主語を示すため、「杯が八分目まで入れる」では杯が入れる主体になり意味が通らない。", "と": "「と」は並列や共同を示すので、「杯と八分目まで入れる」は成り立たない。", "より": "「より」は比較の基準なので、入れる先を示す文脈には合わない。"}, "error_tags": {"が": "主語", "と": "並列", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66c5ca52-51a7-48b2-bf58-49b55ba482b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35609, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "液体を飲むときに使う小さな容器。また、その容器一杯の量を数える言葉。", "primary_collocate": null, "pronunciation": "さかずき", "ipa": "sakadzɯki", "syllable_count": 4, "sentences": [{"text": "店の人は、小さな杯に冷たい酒を入れて出した。", "target_word": "杯", "complexity_tier": "T3", "furigana": "店[みせ]の人[ひと]は、小[ちい]さな杯[さかずき]に冷[つめ]たい酒[さけ]を入[い]れて出[だ]した。", "sentence_source": "generated"}, {"text": "杯は小さいので、すぐに空になってしまう。", "target_word": "杯", "complexity_tier": "T3", "furigana": "杯[さかずき]は小[ちい]さいので、すぐに空[から]になってしまう。", "sentence_source": "generated"}, {"text": "青い杯に酒を注ぐと、色がきれいに見える。", "target_word": "杯", "complexity_tier": "T3", "furigana": "青[あお]い杯[さかずき]に酒[さけ]を注[そそ]ぐと、色[いろ]がきれいに見[み]える。", "sentence_source": "generated"}, {"text": "杯の底に、少しだけ酒が残っていた。", "target_word": "杯", "complexity_tier": "T3", "furigana": "杯[さかずき]の底[そこ]に、少[すこ]しだけ酒[さけ]が残[のこ]っていた。", "sentence_source": "generated"}, {"text": "落として割れた杯を、紙に包んで捨てた。", "target_word": "杯", "complexity_tier": "T3", "furigana": "落[お]として割[わ]れた杯[さかずき]を、紙[かみ]に包[つつ]んで捨[す]てた。", "sentence_source": "generated"}, {"text": "店には、色や形がちがう杯がたくさん並んでいる。", "target_word": "杯", "complexity_tier": "T3", "furigana": "店[みせ]には、色[いろ]や形[かたち]がちがう杯[さかずき]がたくさん並[なら]んでいる。", "sentence_source": "generated"}, {"text": "杯の縁を指でなぞると、冷たかった。", "target_word": "杯", "complexity_tier": "T3", "furigana": "杯[さかずき]の縁[ふち]を指[ゆび]でなぞると、冷[つめ]たかった。", "sentence_source": "generated"}, {"text": "杯に八分目まで入れるのが、ちょうどいい量だ。", "target_word": "杯", "complexity_tier": "T3", "furigana": "杯[さかずき]に八分目[はちぶんめ]まで入[い]れるのが、ちょうどいい量[りょう]だ。", "sentence_source": "generated"}, {"text": "子どもには、杯ではなくコップで飲み物を出した。", "target_word": "杯", "complexity_tier": "T3", "furigana": "子[こ]どもには、杯[さかずき]ではなくコップで飲み物[のみもの]を出[だ]した。", "sentence_source": "generated"}, {"text": "旅先で、手のひらにのる小さな杯を買った。", "target_word": "杯", "complexity_tier": "T3", "furigana": "旅先[たびさき]で、手[て]のひらにのる小[ちい]さな杯[さかずき]を買[か]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "杯", "label": "基本形"}], "register": "中立（普通体）", "sense_fingerprint": "液体を入れて飲むための小さな容器そのもの。形・色・縁・入る量など物としての杯。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T2: contains vocabulary far above tier T2: 八分目 (Zipf 1.12)']::text[], 'f59eed6c-7780-4a68-92fd-f9cceeb3a107') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35609, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "杯", "is_correct": true, "explanation": "「小さな杯に冷たい酒を入れる」は自然で、文の意味に合う。"}, {"text": "箸置き", "is_correct": false, "explanation": "箸置きは箸を置く台で、酒を入れる容器にはならないので文が成り立たない。"}, {"text": "フォーク", "is_correct": false, "explanation": "フォークは食べ物を刺す道具で、液体を入れる器ではない。"}, {"text": "ナイフ", "is_correct": false, "explanation": "ナイフは切る道具で、酒を入れることはできない。"}], "explanations": {"杯": "「小さな杯に冷たい酒を入れる」は自然で、文の意味に合う。", "箸置き": "箸置きは箸を置く台で、酒を入れる容器にはならないので文が成り立たない。", "フォーク": "フォークは食べ物を刺す道具で、液体を入れる器ではない。", "ナイフ": "ナイフは切る道具で、酒を入れることはできない。"}, "sentence_index": 0, "correct_answer": "杯"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "朝ごはんを杯によそって、家族に出した。", "explanation": "ここは〈茶碗〉の意味。ご飯をよそうのは茶碗で、杯は飲み物を入れる器なので、ご飯をよそう使い方はしない。"}, {"text": "寝る前に、杯のページをゆっくりめくった。", "explanation": "ここは〈本〉の意味。ページをめくるのは本で、杯にはページがないので使わない。"}, {"text": "雨が降ってきたので、杯をさして歩いた。", "explanation": "ここは〈傘〉の意味。雨の日にさすのは傘で、杯は雨具ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66c5ca52-51a7-48b2-bf58-49b55ba482b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35609, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "杯", "is_correct": true, "explanation": "「杯の縁を指でなぞる」は自然で、杯の縁に触れた感覚を表す文に合う。"}, {"text": "箸", "is_correct": false, "explanation": "箸には縁がなく、「箸の縁をなぞる」は成り立たない。"}, {"text": "包丁", "is_correct": false, "explanation": "包丁は刃があり縁はないので、「包丁の縁をなぞる」は不自然。"}, {"text": "串", "is_correct": false, "explanation": "串は細い棒で縁がないので、「串の縁をなぞる」は成り立たない。"}], "explanations": {"杯": "「杯の縁を指でなぞる」は自然で、杯の縁に触れた感覚を表す文に合う。", "箸": "箸には縁がなく、「箸の縁をなぞる」は成り立たない。", "包丁": "包丁は刃があり縁はないので、「包丁の縁をなぞる」は不自然。", "串": "串は細い棒で縁がないので、「串の縁をなぞる」は成り立たない。"}, "sentence_index": 6, "correct_answer": "杯"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "寒い朝、杯を右手にはめて出かけた。", "explanation": "ここは〈手袋〉の意味。手にはめるのは手袋で、杯は手にはめるものではない。"}, {"text": "強い日差しの中、杯をかぶって歩いた。", "explanation": "ここは〈帽子〉の意味。頭にかぶるのは帽子で、杯は頭にかぶるものではない。"}, {"text": "雨の日は、杯を履いて出かけた。", "explanation": "ここは〈靴〉の意味。靴は足に履くものだが、杯は足に履くものではないので、履くという使い方はしない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66c5ca52-51a7-48b2-bf58-49b55ba482b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35609, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "母は、うっかり杯を割れてしまった。", "corrected_sentence": "母は、うっかり杯が割れてしまった。", "error_description": "「割れる」は自動詞なので、目的語の「を」は取れない。主語の「が」を使い「杯が割れる」とするのが正しい。誤りは「を」で、正しくは「が」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66c5ca52-51a7-48b2-bf58-49b55ba482b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35609, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "寝る前に、杯に水を一個入れて飲んだ。", "corrected_sentence": "寝る前に、杯に水を一杯入れて飲んだ。", "error_description": "液体を飲む量は「杯」で数える。「個」は固体や丸いものを数える言葉なので、杯に入れた水には使わない。誤りは「個」、正しくは「杯」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66c5ca52-51a7-48b2-bf58-49b55ba482b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35611, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "存在や立つ位置を表す「に」が合う。"}, {"text": "を", "is_correct": false, "explanation": "「立つ」は目的語を取らないので合わない。"}, {"text": "と", "is_correct": false, "explanation": "「背後と人が立つ」では位置の意味にならない。"}, {"text": "が", "is_correct": false, "explanation": "「が」が重なり、位置を表せず文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "存在や立つ位置を表す「に」が合う。", "を": "「立つ」は目的語を取らないので合わない。", "と": "「背後と人が立つ」では位置の意味にならない。", "が": "「が」が重なり、位置を表せず文が成り立たない。"}, "error_tags": {"を": "object_marker", "と": "comitative", "が": "subject_marker"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "正面", "is_correct": true, "explanation": "物の前の部分を指し、「背後」の反対になる。"}, {"text": "周囲", "is_correct": false, "explanation": "まわり全体を指すので、反対の関係ではない。"}, {"text": "真下", "is_correct": false, "explanation": "真下は上下の関係で、前後の反対ではない。"}, {"text": "隣", "is_correct": false, "explanation": "横に並ぶ位置を指すので、反対の関係ではない。"}], "correct_answer": "正面", "explanations": {"正面": "物の前の部分を指し、「背後」の反対になる。", "周囲": "まわり全体を指すので、反対の関係ではない。", "真下": "真下は上下の関係で、前後の反対ではない。", "隣": "横に並ぶ位置を指すので、反対の関係ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1e263f5-edd4-41a4-8d05-3c8d6085553b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35611, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "出来事が起きた場所を表す「で」が合う。"}, {"text": "を", "is_correct": false, "explanation": "「聞こえる」の主語は足音で、「を」は合わない。"}, {"text": "と", "is_correct": false, "explanation": "「背後と足音が聞こえた」では場所を表せない。"}, {"text": "が", "is_correct": false, "explanation": "「が」が重なり、場所を表せず文が成り立たない。"}], "correct_answer": "で", "explanations": {"で": "出来事が起きた場所を表す「で」が合う。", "を": "「聞こえる」の主語は足音で、「を」は合わない。", "と": "「背後と足音が聞こえた」では場所を表せない。", "が": "「が」が重なり、場所を表せず文が成り立たない。"}, "error_tags": {"を": "object_marker", "と": "comitative", "が": "subject_marker"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "前方", "is_correct": true, "explanation": "前の方向を指し、「背後」の反対になる。"}, {"text": "頭上", "is_correct": false, "explanation": "頭の上を指し、前後の反対ではない。"}, {"text": "遠方", "is_correct": false, "explanation": "遠い所を指し、反対の関係ではない。"}, {"text": "足元", "is_correct": false, "explanation": "足の下あたりを指し、前後の反対ではない。"}], "correct_answer": "前方", "explanations": {"前方": "前の方向を指し、「背後」の反対になる。", "頭上": "頭の上を指し、前後の反対ではない。", "遠方": "遠い所を指し、反対の関係ではない。", "足元": "足の下あたりを指し、前後の反対ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1e263f5-edd4-41a4-8d05-3c8d6085553b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35611, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物の後ろの部分。また、表面に見えない事情や背景。", "primary_collocate": null, "pronunciation": "はいご", "ipa": "haiɡo", "syllable_count": 3, "sentences": [{"text": "この理論的基盤は、建物に込められた作者の意図や固定的な意味を脱構築し、その背後にある社会的な文脈や矛盾を浮き彫りにします。", "target_word": "背後", "complexity_tier": "T6", "furigana": "この理論的基盤[りろんてききばん]は、建物[たてもの]に込[こ]められた作者[さくしゃ]の意図[いと]や固定的[こていてき]な意味[いみ]を脱構築[だつこうちく]し、その背後[はいご]にある社会的[しゃかいてき]な文脈[ぶんみゃく]や矛盾[むじゅん]を浮[う]き彫[ぼ]りにします。", "sentence_source": "mined"}, {"text": "背後に人が立っていた。", "target_word": "背後", "complexity_tier": "T3", "furigana": "背後[はいご]に人[ひと]が立[た]っていた。", "sentence_source": "generated"}, {"text": "犯人は彼の背後から近づいた。", "target_word": "背後", "complexity_tier": "T3", "furigana": "犯人[はんにん]は彼[かれ]の背後[はいご]から近[ちか]づいた。", "sentence_source": "generated"}, {"text": "山を背後にして、家が建っている。", "target_word": "背後", "complexity_tier": "T3", "furigana": "山[やま]を背後[はいご]にして、家[いえ]が建[た]っている。", "sentence_source": "generated"}, {"text": "事件の背後には、大きな問題がある。", "target_word": "背後", "complexity_tier": "T3", "furigana": "事件[じけん]の背後[はいご]には、大[おお]きな問題[もんだい]がある。", "sentence_source": "generated"}, {"text": "彼は驚いて背後を振り返った。", "target_word": "背後", "complexity_tier": "T3", "furigana": "彼[かれ]は驚[おどろ]いて背後[はいご]を振[ふ]り返[かえ]った。", "sentence_source": "generated"}, {"text": "彼の発言の背後にある考えを知りたい。", "target_word": "背後", "complexity_tier": "T3", "furigana": "彼[かれ]の発言[はつげん]の背後[はいご]にある考[かんが]えを知[し]りたい。", "sentence_source": "generated"}, {"text": "背後で足音が聞こえた。", "target_word": "背後", "complexity_tier": "T3", "furigana": "背後[はいご]で足音[あしおと]が聞[き]こえた。", "sentence_source": "generated"}, {"text": "この政策の背後には、経済的な理由がある。", "target_word": "背後", "complexity_tier": "T4", "furigana": "この政策[せいさく]の背後[はいご]には、経済的[けいざいてき]な理由[りゆう]がある。", "sentence_source": "generated"}, {"text": "背後から誰かに名前を呼ばれた。", "target_word": "背後", "complexity_tier": "T3", "furigana": "背後[はいご]から誰[だれ]かに名前[なまえ]を呼[よ]ばれた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "背後関係", "label": "派生"}, {"form": "背後霊", "label": "派生"}, {"form": "背後地", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 物の後ろ、また見えない事情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c32dd9f-f08f-4e2d-bcb5-5d9708f30642') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35611, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "背後", "is_correct": true, "explanation": "「はいご」で、聞かせた語と一致する。"}, {"text": "介護", "is_correct": false, "explanation": "「かいご」で、最初の音だけが違う。"}, {"text": "迷子", "is_correct": false, "explanation": "「まいご」で、最初の音だけが違う。"}, {"text": "俳句", "is_correct": false, "explanation": "「はいく」で、最後の音だけが違う。"}, {"text": "廃止", "is_correct": false, "explanation": "「はいし」で、最後の音だけが違う。"}], "explanations": {"背後": "「はいご」で、聞かせた語と一致する。", "介護": "「かいご」で、最初の音だけが違う。", "迷子": "「まいご」で、最初の音だけが違う。", "俳句": "「はいく」で、最後の音だけが違う。", "廃止": "「はいし」で、最後の音だけが違う。"}, "sentence_index": null, "correct_answer": "背後"}, "level_3": {"options": [{"text": "背後", "is_correct": true, "explanation": "表に見えない事情や背景を指し、文脈や矛盾がその奥にあるという意味に合う。"}, {"text": "台所", "is_correct": false, "explanation": "形は合うが、社会的な文脈が台所にあるという意味にならない。"}, {"text": "屋根", "is_correct": false, "explanation": "形は合うが、建物の部分を指すので意味が合わない。"}, {"text": "表紙", "is_correct": false, "explanation": "形は合うが、本の表紙を指すので意味が合わない。"}], "explanations": {"背後": "表に見えない事情や背景を指し、文脈や矛盾がその奥にあるという意味に合う。", "台所": "形は合うが、社会的な文脈が台所にあるという意味にならない。", "屋根": "形は合うが、建物の部分を指すので意味が合わない。", "表紙": "形は合うが、本の表紙を指すので意味が合わない。"}, "sentence_index": 0, "correct_answer": "背後"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は背後が高くて、電車でも目立った。", "explanation": "「背後」は物の後ろや裏の事情で、身長の意味では使えない。"}, {"text": "私は朝ごはんの背後にパンを食べた。", "explanation": "「背後」は場所や背景を表し、時間の「あと」の意味では使えない。"}, {"text": "この箱の背後は、とても甘くておいしい。", "explanation": "「背後」は味を表す語ではなく、味の説明には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1e263f5-edd4-41a4-8d05-3c8d6085553b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35611, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "背後", "is_correct": true, "explanation": "「はいご」で、聞かせた語と一致する。"}, {"text": "最後", "is_correct": false, "explanation": "「さいご」で、最初の音だけが違う。"}, {"text": "廃棄", "is_correct": false, "explanation": "「はいき」で、最後の音だけが違う。"}, {"text": "配布", "is_correct": false, "explanation": "「はいふ」で、最後の音だけが違う。"}, {"text": "胚芽", "is_correct": false, "explanation": "「はいが」で、最後の音だけが違う。"}], "explanations": {"背後": "「はいご」で、聞かせた語と一致する。", "最後": "「さいご」で、最初の音だけが違う。", "廃棄": "「はいき」で、最後の音だけが違う。", "配布": "「はいふ」で、最後の音だけが違う。", "胚芽": "「はいが」で、最後の音だけが違う。"}, "sentence_index": null, "correct_answer": "背後"}, "level_3": {"options": [{"text": "背後", "is_correct": true, "explanation": "発言の裏にある考えという、見えない事情の意味に合う。"}, {"text": "天井", "is_correct": false, "explanation": "形は合うが、発言と天井は意味がつながらない。"}, {"text": "靴底", "is_correct": false, "explanation": "形は合うが、発言に靴底があるという意味にならない。"}, {"text": "値段", "is_correct": false, "explanation": "形は合うが、発言の値段にある考えでは意味が合わない。"}], "explanations": {"背後": "発言の裏にある考えという、見えない事情の意味に合う。", "天井": "形は合うが、発言と天井は意味がつながらない。", "靴底": "形は合うが、発言に靴底があるという意味にならない。", "値段": "形は合うが、発言の値段にある考えでは意味が合わない。"}, "sentence_index": 6, "correct_answer": "背後"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は背後が速くて、いつも一番に着く。", "explanation": "「背後」は後ろの位置や背景で、速さを表す語ではない。"}, {"text": "試合の背後は三対二で終わった。", "explanation": "「背後」は試合の結果や得点を表す語ではない。"}, {"text": "今日の背後は晴れでも雨でもなかった。", "explanation": "「背後」は天気を表す語ではなく、意味が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1e263f5-edd4-41a4-8d05-3c8d6085553b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35611, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先生は私の背後を立って、見守っていた。", "corrected_sentence": "先生は私の背後に立って、見守っていた。", "error_description": "「背後」で立つ位置を表すには、「を」ではなく「に」を使う。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1e263f5-edd4-41a4-8d05-3c8d6085553b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35611, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この事件の背後を複雑な事情がある。", "corrected_sentence": "この事件の背後には複雑な事情がある。", "error_description": "「背後」にある事情を言うときは、「を」ではなく「には」を使う。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1e263f5-edd4-41a4-8d05-3c8d6085553b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35612, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「友だちに協力してもらう」の形で、協力の相手を示す。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示す。ここでは「友だち」を協力の対象として示せず、不自然になる。"}, {"text": "の", "is_correct": false, "explanation": "所属や所有を示す。協力の相手を示すには使えない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す。協力の相手を示す形としては合わない。"}], "correct_answer": "に", "explanations": {"に": "「友だちに協力してもらう」の形で、協力の相手を示す。", "を": "「を」は目的語を示す。ここでは「友だち」を協力の対象として示せず、不自然になる。", "の": "所属や所有を示す。協力の相手を示すには使えない。", "へ": "方向を示す。協力の相手を示す形としては合わない。"}, "error_tags": {"を": "目的語", "の": "連体修飾", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a44a7561-7d0d-43e7-9fe6-3e10407f9092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
