INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35612, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "みんなで力を合わせて、何かをすることです。", "primary_collocate": null, "pronunciation": "きょうりょく", "ipa": "kʲoːɾʲokɯ", "syllable_count": 4, "sentences": [{"text": "みんなが協力したので、教室の掃除はすぐに終わりました。", "target_word": "協力", "complexity_tier": "T3", "furigana": "みんなが協力(きょうりょく)したので、教室(きょうしつ)の掃除(そうじ)はすぐに終(お)わりました。", "sentence_source": "generated"}, {"text": "友だちに協力してもらって、文化祭の準備を間に合わせました。", "target_word": "協力", "complexity_tier": "T3", "furigana": "友(とも)だちに協力(きょうりょく)してもらって、文化祭(ぶんかさい)の準備(じゅんび)を間(ま)に合(あ)わせました。", "sentence_source": "generated"}, {"text": "この仕事は一人では無理なので、あなたの協力が必要です。", "target_word": "協力", "complexity_tier": "T3", "furigana": "この仕事(しごと)は一人(ひとり)では無理(むり)なので、あなたの協力(きょうりょく)が必要(ひつよう)です。", "sentence_source": "generated"}, {"text": "町の人たちは協力して、川のごみを拾いました。", "target_word": "協力", "complexity_tier": "T3", "furigana": "町(まち)の人(ひと)たちは協力(きょうりょく)して、川(かわ)のごみを拾(ひろ)いました。", "sentence_source": "generated"}, {"text": "先生は、クラスのみんなに協力をお願いしました。", "target_word": "協力", "complexity_tier": "T3", "furigana": "先生(せんせい)は、クラスのみんなに協力(きょうりょく)をお願(ねが)いしました。", "sentence_source": "generated"}, {"text": "兄と協力すれば、重い机も運べます。", "target_word": "協力", "complexity_tier": "T3", "furigana": "兄(あに)と協力(きょうりょく)すれば、重(おも)い机(つくえ)も運(はこ)べます。", "sentence_source": "generated"}, {"text": "調査にご協力いただき、ありがとうございました。", "target_word": "協力", "complexity_tier": "T3", "furigana": "調査(ちょうさ)にご協力(きょうりょく)いただき、ありがとうございました。", "sentence_source": "generated"}, {"text": "二つの会社が協力して、新しい電車を作りました。", "target_word": "協力", "complexity_tier": "T3", "furigana": "二(ふた)つの会社(かいしゃ)が協力(きょうりょく)して、新(あたら)しい電車(でんしゃ)を作(つく)りました。", "sentence_source": "generated"}, {"text": "彼は忙しいのに、いつも喜んで協力してくれます。", "target_word": "協力", "complexity_tier": "T3", "furigana": "彼(かれ)は忙(いそが)しいのに、いつも喜(よろこ)んで協力(きょうりょく)してくれます。", "sentence_source": "generated"}, {"text": "協力しない人がいると、チームはうまく進みません。", "target_word": "協力", "complexity_tier": "T3", "furigana": "協力(きょうりょく)しない人(ひと)がいると、チームはうまく進(すす)みません。", "sentence_source": "generated"}], "morphological_forms": [{"form": "協力する", "label": "辞書形"}, {"form": "協力します", "label": "丁寧形"}, {"form": "協力した", "label": "過去形"}, {"form": "協力して", "label": "て形"}, {"form": "協力しない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "力を合わせて一緒に物事を行うこと(協力する)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bfeb8eaf-a2e4-432a-a0a2-3afa20c9c998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35612, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "協力", "is_correct": true, "explanation": "「みんなが協力したので掃除が早く終わった」と、力を合わせた結果として自然につながる。"}, {"text": "欠席", "is_correct": false, "explanation": "授業や行事に出ないこと。みんなが欠席して掃除が早く終わる理由にはならない。"}, {"text": "解散", "is_correct": false, "explanation": "集まりをやめること。掃除が早く終わる理由として成り立たない。"}, {"text": "見学", "is_correct": false, "explanation": "見て学ぶこと。掃除をする人の行為としては合わない。"}], "explanations": {"協力": "「みんなが協力したので掃除が早く終わった」と、力を合わせた結果として自然につながる。", "欠席": "授業や行事に出ないこと。みんなが欠席して掃除が早く終わる理由にはならない。", "解散": "集まりをやめること。掃除が早く終わる理由として成り立たない。", "見学": "見て学ぶこと。掃除をする人の行為としては合わない。"}, "sentence_index": 0, "correct_answer": "協力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "二つの組織は予算をめぐって、激しく協力した。", "explanation": "ここは〈対立〉の意味。協力は力を合わせることなので、争う場面では使わない。"}, {"text": "あの部下は、部長にとって大切な協力だ。", "explanation": "ここは〈協力者〉の意味。協力は人を指す語ではなく、力を出し合う行為なので、人のことは言えない。"}, {"text": "その会社は市場で協力を独占している。", "explanation": "ここは〈独占〉の意味。協力は独り占めできるものではないので、この使い方は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a44a7561-7d0d-43e7-9fe6-3e10407f9092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35612, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "協力", "is_correct": true, "explanation": "「ご協力いただき」は、相手に力を貸してもらったことへの感謝として自然。"}, {"text": "撮影", "is_correct": false, "explanation": "写真や映像を撮ること。調査に対する感謝の表現としては合わない。"}, {"text": "延期", "is_correct": false, "explanation": "予定を後にずらすこと。感謝の文脈に合わない。"}, {"text": "録音", "is_correct": false, "explanation": "音を記録すること。調査に対する感謝の文として成り立たない。"}], "explanations": {"協力": "「ご協力いただき」は、相手に力を貸してもらったことへの感謝として自然。", "撮影": "写真や映像を撮ること。調査に対する感謝の表現としては合わない。", "延期": "予定を後にずらすこと。感謝の文脈に合わない。", "録音": "音を記録すること。調査に対する感謝の文として成り立たない。"}, "sentence_index": 6, "correct_answer": "協力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "二つのチームは試合で協力して、互いに得点を競い合った。", "explanation": "ここは〈競争〉の意味。協力は力を合わせることで、競い合いには使わない。"}, {"text": "彼は重い荷物を持つとき、誰よりも協力が強かった。", "explanation": "ここは〈力〉の意味。協力は複数の人が力を合わせることで、個人の体の強さは指さない。"}, {"text": "地域の施設に寄付を協力した。", "explanation": "ここは〈寄付〉の意味。寄付は物やお金を贈ることで、協力とは結びつかない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a44a7561-7d0d-43e7-9fe6-3e10407f9092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35612, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "仲間と協力するで、ごみ袋を集めました。", "corrected_sentence": "仲間と協力して、ごみ袋を集めました。", "error_description": "「協力」に続くのは「して」。「するで」は誤った接続で、「協力して」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a44a7561-7d0d-43e7-9fe6-3e10407f9092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35612, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新しい計画に協力しくれて、ありがとう。", "corrected_sentence": "新しい計画に協力してくれて、ありがとう。", "error_description": "「協力してくれて」が正しい形。「協力しくれて」は動詞の活用が誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a44a7561-7d0d-43e7-9fe6-3e10407f9092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
