INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35613, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「警察の捜査に協力する」の形で、協力する相手や対象を示す。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す。「捜査を協力する」は成り立たず、協力の対象は「に」で示す。"}, {"text": "の", "is_correct": false, "explanation": "所属や連体修飾を示す。「捜査の協力する」は文として成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示す。ここでは協力の対象を導けない。"}], "correct_answer": "に", "explanations": {"に": "「警察の捜査に協力する」の形で、協力する相手や対象を示す。", "を": "目的語を示す。「捜査を協力する」は成り立たず、協力の対象は「に」で示す。", "の": "所属や連体修飾を示す。「捜査の協力する」は文として成り立たない。", "より": "比較を示す。ここでは協力の対象を導けない。"}, "error_tags": {"を": "目的語", "の": "連体修飾", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a44a7561-7d0d-43e7-9fe6-3e10407f9092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35613, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "複数の人が目的を同じにして、互いに力を出し合うこと。", "primary_collocate": null, "pronunciation": "きょうりょく", "ipa": "kʲoːɾʲokɯ", "syllable_count": 4, "sentences": [{"text": "特に多色印刷の場合、色ごとに異なる版木を使い分ける必要があり、職人たちの高度な技術と協力が不可欠です。", "target_word": "協力", "complexity_tier": "T3", "furigana": "特[とく]に多色[たしょく]印刷[いんさつ]の場合[ばあい]、色[いろ]ごとに異[こと]なる版木[はんぎ]を使[つか]い分[わ]ける必要[ひつよう]があり、職人[しょくにん]たちの高度[こうど]な技術[ぎじゅつ]と協力[きょうりょく]が不可欠[ふかけつ]です。", "sentence_source": "mined"}, {"text": "町の人々が協力して、公園のごみを拾いました。", "target_word": "協力", "complexity_tier": "T3", "furigana": "町[まち]の人々[ひとびと]が協力[きょうりょく]して、公園[こうえん]のごみを拾[ひろ]いました。", "sentence_source": "generated"}, {"text": "協力してくれたみなさんに、心からお礼を言います。", "target_word": "協力", "complexity_tier": "T3", "furigana": "協力[きょうりょく]してくれたみなさんに、心[こころ]からお礼[れい]を言[い]います。", "sentence_source": "generated"}, {"text": "実験が成功したのは、チーム全員の協力のおかげです。", "target_word": "協力", "complexity_tier": "T3", "furigana": "実験[じっけん]が成功[せいこう]したのは、チーム全員[ぜんいん]の協力[きょうりょく]のおかげです。", "sentence_source": "generated"}, {"text": "兄と協力すれば、重い机も二階まで運べます。", "target_word": "協力", "complexity_tier": "T3", "furigana": "兄[あに]と協力[きょうりょく]すれば、重[おも]い机[つくえ]も二階[にかい]まで運[はこ]べます。", "sentence_source": "generated"}, {"text": "両国は災害の際に協力する約束をしました。", "target_word": "協力", "complexity_tier": "T3", "furigana": "両国[りょうこく]は災害[さいがい]の際[さい]に協力[きょうりょく]する約束[やくそく]をしました。", "sentence_source": "generated"}, {"text": "一人では無理でも、協力すれば短い時間で終わります。", "target_word": "協力", "complexity_tier": "T3", "furigana": "一人[ひとり]では無理[むり]でも、協力[きょうりょく]すれば短[みじか]い時間[じかん]で終[お]わります。", "sentence_source": "generated"}, {"text": "警察の捜査に協力するため、見たことを詳しく話しました。", "target_word": "協力", "complexity_tier": "T3", "furigana": "警察[けいさつ]の捜査[そうさ]に協力[きょうりょく]するため、見[み]たことを詳[くわ]しく話[はな]しました。", "sentence_source": "generated"}, {"text": "みんなの協力が足りなかったので、準備は予定より遅れました。", "target_word": "協力", "complexity_tier": "T3", "furigana": "みんなの協力[きょうりょく]が足[た]りなかったので、準備[じゅんび]は予定[よてい]より遅[おく]れました。", "sentence_source": "generated"}, {"text": "隣の人たちとの協力で、文化祭の準備が早く進みました。", "target_word": "協力", "complexity_tier": "T3", "furigana": "隣[となり]の人[ひと]たちとの協力[きょうりょく]で、文化祭[ぶんかさい]の準備[じゅんび]が早[はや]く進[すす]みました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "協力", "label": "基本形"}, {"form": "協力する", "label": "終止形"}, {"form": "協力した", "label": "夕形"}, {"form": "協力して", "label": "テ形"}, {"form": "協力しない", "label": "否定形"}], "register": "標準", "sense_fingerprint": "同じ目的のために力を出し合うこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: contains vocabulary far above tier T1: 版木 (Zipf 2.03)']::text[], 'bfeb8eaf-a2e4-432a-a0a2-3afa20c9c998') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35613, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "協力", "is_correct": true, "explanation": "「技術と協力が不可欠」は、互いに力を出し合う意味の協力で自然につながる。"}, {"text": "包装", "is_correct": false, "explanation": "商品を包むこと。版木の技術と並べても、不可欠な要素にはならない。"}, {"text": "発酵", "is_correct": false, "explanation": "微生物の働きで物質が変わること。版木を彫る工程とは結びつかない。"}, {"text": "目印", "is_correct": false, "explanation": "場所を示すしるし。職人の技術と並べて不可欠とは言えない。"}], "explanations": {"協力": "「技術と協力が不可欠」は、互いに力を出し合う意味の協力で自然につながる。", "包装": "商品を包むこと。版木の技術と並べても、不可欠な要素にはならない。", "発酵": "微生物の働きで物質が変わること。版木を彫る工程とは結びつかない。", "目印": "場所を示すしるし。職人の技術と並べて不可欠とは言えない。"}, "sentence_index": 0, "correct_answer": "協力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は一人で協力して、庭の草を三時間かけて全部抜いた。", "explanation": "ここは〈独力〉の意味。協力は複数の人が力を出し合うことなので、一人の作業には合わない。"}, {"text": "二つの組織は予算をめぐって、激しく協力した。", "explanation": "ここは〈対立〉の意味。協力は力を合わせることで、争う場面には使わない。"}, {"text": "彼は会社にとって欠かせない協力だ。", "explanation": "ここは〈協力者〉の意味。協力は人を指さず、力を出し合う行為を表すので、人を表す使い方は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a44a7561-7d0d-43e7-9fe6-3e10407f9092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35613, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "協力", "is_correct": true, "explanation": "「協力すれば短い時間で終わる」は、力を出し合うことで作業が早く済む意味に合う。"}, {"text": "中断", "is_correct": false, "explanation": "途中でやめること。作業を早く終わらせる条件にはならない。"}, {"text": "放置", "is_correct": false, "explanation": "そのままにしておくこと。短い時間で終わる理由にはならない。"}, {"text": "撤退", "is_correct": false, "explanation": "引き下がること。一人では無理な作業を終える手段にはならない。"}], "explanations": {"協力": "「協力すれば短い時間で終わる」は、力を出し合うことで作業が早く済む意味に合う。", "中断": "途中でやめること。作業を早く終わらせる条件にはならない。", "放置": "そのままにしておくこと。短い時間で終わる理由にはならない。", "撤退": "引き下がること。一人では無理な作業を終える手段にはならない。"}, "sentence_index": 6, "correct_answer": "協力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "二つの店は客を取り合い、毎日協力して値段を競い合った。", "explanation": "ここは〈競争〉の意味。協力は力を合わせることで、互いに競い合う場面では使わない。"}, {"text": "その会社は市場で協力を独占している。", "explanation": "ここは〈独占〉の意味。協力は独り占めできるものではないので、この使い方は合わない。"}, {"text": "彼は練習で誰よりも協力が強く、重い荷物を軽々と持ち上げた。", "explanation": "ここは〈力〉の意味。協力は複数の人が力を合わせることで、個人の体の強さは指さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a44a7561-7d0d-43e7-9fe6-3e10407f9092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35613, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "友だちを協力して、重い箱を運びました。", "corrected_sentence": "友だちと協力して、重い箱を運びました。", "error_description": "協力する相手には「と」を使う。「を」は誤りで、正しくは「と」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a44a7561-7d0d-43e7-9fe6-3e10407f9092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35613, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先生の指示に協力で、教室を片づけました。", "corrected_sentence": "先生の指示に協力して、教室を片づけました。", "error_description": "「協力」の後ろは「して」の形が必要。「協力で」は形が合わず、誤りになる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a44a7561-7d0d-43e7-9fe6-3e10407f9092') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
