INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35614, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "いろいろなことがあって、わかりにくいこと。", "primary_collocate": null, "pronunciation": "ふくざつ", "ipa": "ɸɯkɯdzatsɯ", "syllable_count": 4, "sentences": [{"text": "この地図は道が複雑で、初めて来た人はよく迷う。", "target_word": "複雑", "complexity_tier": "T3", "furigana": "この地図[ちず]は道[みち]が複雑[ふくざつ]で、初[はじ]めて来[き]た人[ひと]はよく迷[まよ]う。", "sentence_source": "generated"}, {"text": "説明書の手順が複雑なので、父は組み立てをあきらめた。", "target_word": "複雑", "complexity_tier": "T3", "furigana": "説明書[せつめいしょ]の手順[てじゅん]が複雑[ふくざつ]なので、父[ちち]は組[く]み立[た]てをあきらめた。", "sentence_source": "generated"}, {"text": "彼の家は家族の関係が複雑で、説明するのが難しい。", "target_word": "複雑", "complexity_tier": "T3", "furigana": "彼[かれ]の家[いえ]は家族[かぞく]の関係[かんけい]が複雑[ふくざつ]で、説明[せつめい]するのが難[むずか]しい。", "sentence_source": "generated"}, {"text": "このゲームはルールが複雑だから、子どもには向いていない。", "target_word": "複雑", "complexity_tier": "T3", "furigana": "このゲームはルールが複雑[ふくざつ]だから、子[こ]どもには向[む]いていない。", "sentence_source": "generated"}, {"text": "駅の中は複雑な作りで、出口を探すのに十分かかった。", "target_word": "複雑", "complexity_tier": "T3", "furigana": "駅[えき]の中[なか]は複雑[ふくざつ]な作[つく]りで、出口[でぐち]を探[さが]すのに十分[じゅっぷん]かかった。", "sentence_source": "generated"}, {"text": "問題は思ったより複雑で、すぐには答えが出なかった。", "target_word": "複雑", "complexity_tier": "T3", "furigana": "問題[もんだい]は思[おも]ったより複雑[ふくざつ]で、すぐには答[こた]えが出[で]なかった。", "sentence_source": "generated"}, {"text": "先生は複雑な話をやさしい言葉で説明してくれた。", "target_word": "複雑", "complexity_tier": "T3", "furigana": "先生[せんせい]は複雑[ふくざつ]な話[はなし]をやさしい言葉[ことば]で説明[せつめい]してくれた。", "sentence_source": "generated"}, {"text": "電車の乗りかえが複雑なので、地図を見ながら行こう。", "target_word": "複雑", "complexity_tier": "T3", "furigana": "電車[でんしゃ]の乗[の]りかえが複雑[ふくざつ]なので、地図[ちず]を見[み]ながら行[い]こう。", "sentence_source": "generated"}, {"text": "手続きが複雑すぎて、役所の人に何度も聞いた。", "target_word": "複雑", "complexity_tier": "T3", "furigana": "手続[てつづ]きが複雑[ふくざつ]すぎて、役所[やくしょ]の人[ひと]に何度[なんど]も聞[き]いた。", "sentence_source": "generated"}, {"text": "簡単に見えるが、実際の仕組みは複雑だ。", "target_word": "複雑", "complexity_tier": "T3", "furigana": "簡単[かんたん]に見[み]えるが、実際[じっさい]の仕組[しく]みは複雑[ふくざつ]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "複雑だ", "label": "断定形"}, {"form": "複雑な", "label": "連体形"}, {"form": "複雑に", "label": "連用形"}, {"form": "複雑で", "label": "連用形（で）"}, {"form": "複雑だった", "label": "過去形"}], "register": "neutral", "sense_fingerprint": "物事の仕組みや関係が入り組んでいて、理解や処理がむずかしい様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T2: contains vocabulary far above tier T2: 乗りかえ (Zipf 2.08)']::text[], 'f59eed6c-7780-4a68-92fd-f9cceeb3a107') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35614, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "複雑", "is_correct": true, "explanation": "「道が複雑で迷う」は、道の仕組みがわかりにくいという意味に合う。"}, {"text": "同様", "is_correct": false, "explanation": "「同様」は似ていることを表し、「道が同様で迷う」は意味が通らない。"}, {"text": "豊富", "is_correct": false, "explanation": "「豊富」は量が多いことを表し、「道が豊富で迷う」は道の性質として合わない。"}, {"text": "正確", "is_correct": false, "explanation": "「正確」は間違いがないことを表し、「道が正確で迷う」は成り立たない。"}], "explanations": {"複雑": "「道が複雑で迷う」は、道の仕組みがわかりにくいという意味に合う。", "同様": "「同様」は似ていることを表し、「道が同様で迷う」は意味が通らない。", "豊富": "「豊富」は量が多いことを表し、「道が豊富で迷う」は道の性質として合わない。", "正確": "「正確」は間違いがないことを表し、「道が正確で迷う」は成り立たない。"}, "sentence_index": 0, "correct_answer": "複雑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "朝獲れの複雑な魚が、店先にきれいに並んでいる。", "explanation": "ここは〈新鮮〉の意味。魚の状態には新鮮が合い、複雑（仕組みや事情がわかりにくい）は魚には使わない。"}, {"text": "公園の桜が複雑で、花見の人がたくさん集まっている。", "explanation": "ここは〈満開〉の意味。花がよく咲いた様子には満開が合い、複雑は桜の様子には使わない。"}, {"text": "注文を受けたら、複雑に届けてくれた。", "explanation": "ここは〈すぐ〉の意味。届ける早さには「すぐに」が合い、複雑は動作の速さを表さない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66c5ca52-51a7-48b2-bf58-49b55ba482b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35614, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "複雑", "is_correct": true, "explanation": "「複雑な話をやさしい言葉で説明」は自然で、話が入り組んでいることを表す。"}, {"text": "高価", "is_correct": false, "explanation": "「高価」は値段が高いことで、「高価な話」は意味が通らない。"}, {"text": "丈夫", "is_correct": false, "explanation": "「丈夫」は壊れにくい様子で、「丈夫な話」は成り立たない。"}, {"text": "不格好", "is_correct": false, "explanation": "「不格好」は見た目がぶかっこうなことで、話の内容には使わない。"}], "explanations": {"複雑": "「複雑な話をやさしい言葉で説明」は自然で、話が入り組んでいることを表す。", "高価": "「高価」は値段が高いことで、「高価な話」は意味が通らない。", "丈夫": "「丈夫」は壊れにくい様子で、「丈夫な話」は成り立たない。", "不格好": "「不格好」は見た目がぶかっこうなことで、話の内容には使わない。"}, "sentence_index": 6, "correct_answer": "複雑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "朝から足が複雑で、うまく歩けなかった。", "explanation": "ここは〈痛い〉の意味。体の痛みには痛いが合い、複雑（事情や仕組みがわかりにくい）は体の状態には使わない。"}, {"text": "庭の木に複雑なりんごがたくさん実っている。", "explanation": "ここは〈赤い〉の意味。りんごの色には赤いが合い、複雑（仕組みがわかりにくい）は見た目の色には使わない。"}, {"text": "雨が複雑に降った。", "explanation": "ここは〈激しく〉の意味。雨の勢いには激しくが合い、複雑（仕組みや事情がわかりにくい）は降り方の強さを表せないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66c5ca52-51a7-48b2-bf58-49b55ba482b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35614, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この複雑の手続きは、初めての人には難しい。", "corrected_sentence": "この複雑な手続きは、初めての人には難しい。", "error_description": "「複雑」はナ形容詞なので、名詞を修飾するときは「な」を付ける。「の」は誤りで、正しくは「な」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "複雑", "is_correct": true, "explanation": "「複雑なので」は語幹の後に「なので」が続く正しい形。"}, {"text": "複雑だ", "is_correct": false, "explanation": "「複雑だなので」は「だ」の後に「なので」が続かず不自然。"}, {"text": "複雑に", "is_correct": false, "explanation": "「複雑になので」は副詞の形が「なので」とつながらない。"}, {"text": "複雑で", "is_correct": false, "explanation": "「複雑でなので」は「で」の後に「なので」が続かず不自然。"}], "correct_form": "複雑", "base_form": "複雑", "form_label": "語幹（「なので」の前）", "sentence_index": 1, "explanations": {"複雑": "「複雑なので」は語幹の後に「なので」が続く正しい形。", "複雑だ": "「複雑だなので」は「だ」の後に「なので」が続かず不自然。", "複雑に": "「複雑になので」は副詞の形が「なので」とつながらない。", "複雑で": "「複雑でなので」は「で」の後に「なので」が続かず不自然。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66c5ca52-51a7-48b2-bf58-49b55ba482b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35614, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "話が複雑くなって、皆が混乱した。", "corrected_sentence": "話が複雑になって、皆が混乱した。", "error_description": "「複雑」はナ形容詞なので、「なる」につなぐときは「に」を付ける。「く」は形容詞の活用で誤り。誤りは「く」、正しくは「に」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "複雑", "is_correct": true, "explanation": "「複雑なので」は語幹の後に「なので」が続く正しい形。"}, {"text": "複雑な", "is_correct": false, "explanation": "「複雑ななので」は「な」の後に「なので」が重なり、不自然。"}, {"text": "複雑だった", "is_correct": false, "explanation": "「複雑だったなので」は過去形の後に「なので」が続かず不自然。"}, {"text": "複雑じゃない", "is_correct": false, "explanation": "「複雑じゃないなので」は否定形の後に「なので」が続かず不自然。"}], "correct_form": "複雑", "base_form": "複雑", "form_label": "語幹（「なので」の前）", "sentence_index": 7, "explanations": {"複雑": "「複雑なので」は語幹の後に「なので」が続く正しい形。", "複雑な": "「複雑ななので」は「な」の後に「なので」が重なり、不自然。", "複雑だった": "「複雑だったなので」は過去形の後に「なので」が続かず不自然。", "複雑じゃない": "「複雑じゃないなので」は否定形の後に「なので」が続かず不自然。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66c5ca52-51a7-48b2-bf58-49b55ba482b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35616, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "正解。「経済が悪くなる」の主語を示す「が」。"}, {"text": "を", "is_correct": false, "explanation": "「悪くなる」は自動詞で目的語を取らないため、「経済を悪くなる」は成立しない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すので、「経済と悪くなる」は成立しない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示すため、「経済で悪くなる」は成立しない。"}], "correct_answer": "が", "explanations": {"が": "正解。「経済が悪くなる」の主語を示す「が」。", "を": "「悪くなる」は自動詞で目的語を取らないため、「経済を悪くなる」は成立しない。", "と": "「と」は並列や相手を示すので、「経済と悪くなる」は成立しない。", "で": "「で」は場所や手段を示すため、「経済で悪くなる」は成立しない。"}, "error_tags": {"を": "目的語", "と": "並列・相手", "で": "場所・手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '196c77a7-afc3-481c-87f3-1ba8dda84301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35616, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "正解。「経済は大きな打撃を受けた」の主題を示す「は」。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すので、「経済と大きな打撃を受けた」は成立しない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「経済へ打撃を受けた」は不自然。"}, {"text": "を", "is_correct": false, "explanation": "「を」を二つ重ねると「経済を大きな打撃を受けた」となり、目的語が二つ並んで不自然。"}], "correct_answer": "は", "explanations": {"は": "正解。「経済は大きな打撃を受けた」の主題を示す「は」。", "と": "「と」は並列や相手を示すので、「経済と大きな打撃を受けた」は成立しない。", "へ": "「へ」は方向を示すので、「経済へ打撃を受けた」は不自然。", "を": "「を」を二つ重ねると「経済を大きな打撃を受けた」となり、目的語が二つ並んで不自然。"}, "error_tags": {"と": "並列・相手", "へ": "方向", "を": "目的語の重複"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '196c77a7-afc3-481c-87f3-1ba8dda84301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35616, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "お金や物の流れ、国や会社のしくみのこと。", "primary_collocate": null, "pronunciation": "けいざい", "ipa": "keːzai", "syllable_count": 4, "sentences": [{"text": "この国の経済は、ここ数年ゆっくり成長している。", "target_word": "経済", "complexity_tier": "T3", "furigana": "この国[くに]の経済[けいざい]は、ここ数年[すうねん]ゆっくり成長[せいちょう]している。", "sentence_source": "generated"}, {"text": "経済が悪くなると、仕事を探すのが難しくなる。", "target_word": "経済", "complexity_tier": "T3", "furigana": "経済[けいざい]が悪[わる]くなると、仕事[しごと]を探[さが]すのが難[むずか]しくなる。", "sentence_source": "generated"}, {"text": "大学で経済のしくみを学んで、銀行に入りたい。", "target_word": "経済", "complexity_tier": "T3", "furigana": "大学[だいがく]で経済[けいざい]のしくみを学[まな]んで、銀行[ぎんこう]に入[はい]りたい。", "sentence_source": "generated"}, {"text": "円安は日本の経済に大きな影響を与える。", "target_word": "経済", "complexity_tier": "T3", "furigana": "円安[えんやす]は日本[にほん]の経済[けいざい]に大[おお]きな影響[えいきょう]を与[あた]える。", "sentence_source": "generated"}, {"text": "新しい工場ができて、町の経済が元気になった。", "target_word": "経済", "complexity_tier": "T3", "furigana": "新[あたら]しい工場[こうじょう]ができて、町[まち]の経済[けいざい]が元気[げんき]になった。", "sentence_source": "generated"}, {"text": "世界の経済は、お互いにつながっている。", "target_word": "経済", "complexity_tier": "T3", "furigana": "世界[せかい]の経済[けいざい]は、お互[たが]いにつながっている。", "sentence_source": "generated"}, {"text": "経済のニュースを見ると、物の値段がわかる。", "target_word": "経済", "complexity_tier": "T3", "furigana": "経済[けいざい]のニュースを見[み]ると、物[もの]の値段[ねだん]がわかる。", "sentence_source": "generated"}, {"text": "台風の被害で、地域の経済は大きな打撃を受けた。", "target_word": "経済", "complexity_tier": "T3", "furigana": "台風[たいふう]の被害[ひがい]で、地域[ちいき]の経済[けいざい]は大[おお]きな打撃[だげき]を受[う]けた。", "sentence_source": "generated"}, {"text": "先生は、お金の流れが経済のしくみだと説明した。", "target_word": "経済", "complexity_tier": "T3", "furigana": "先生[せんせい]は、お金[かね]の流[なが]れが経済[けいざい]のしくみだと説明[せつめい]した。", "sentence_source": "generated"}, {"text": "景気が良くなれば、国の経済も安定するだろう。", "target_word": "経済", "complexity_tier": "T3", "furigana": "景気[けいき]が良[よ]くなれば、国[くに]の経済[けいざい]も安定[あんてい]するだろう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "経済", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "お金や物の生産・流通・消費など、国や社会のお金のしくみ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2bd11da-41e2-49c8-8a73-9a8a84891b15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35616, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "経済", "is_correct": true, "explanation": "正解。国のお金や物の仕組みが成長するという文になり、自然。"}, {"text": "天気", "is_correct": false, "explanation": "天気は移り変わるもので、国全体が成長する主語にはならないので合わない。"}, {"text": "料理", "is_correct": false, "explanation": "料理は作って楽しむもので、国の成長を表す主語としては不自然。"}, {"text": "教科書", "is_correct": false, "explanation": "教科書は学習に使う本で、国が成長するという文の主語とは合わない。"}], "explanations": {"経済": "正解。国のお金や物の仕組みが成長するという文になり、自然。", "天気": "天気は移り変わるもので、国全体が成長する主語にはならないので合わない。", "料理": "料理は作って楽しむもので、国の成長を表す主語としては不自然。", "教科書": "教科書は学習に使う本で、国が成長するという文の主語とは合わない。"}, "sentence_index": 0, "correct_answer": "経済"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "出張の経済は、会社がすべて払うことになっている。", "explanation": "ここは〈経費〉の意味。会社が支払う費用は経費と言い、経済（国や社会のお金の仕組み）とは合わない。"}, {"text": "祖父は残した経済を、すべて息子に譲った。", "explanation": "ここは〈財産〉の意味。個人が持つ資産は財産と言い、経済（社会のお金の仕組み）とは合わない。"}, {"text": "毎月の経済を、三万円に増やした。", "explanation": "ここは〈貯金〉の意味。手元に蓄えるお金は貯金と言い、経済は仕組みを指すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '196c77a7-afc3-481c-87f3-1ba8dda84301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35616, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "経済", "is_correct": true, "explanation": "正解。「経済のニュース」は、お金や物の流れを伝える報道として自然。"}, {"text": "教育", "is_correct": false, "explanation": "教育のニュースは学校や教育制度が中心で、物の値段はわからないので合わない。"}, {"text": "時計", "is_correct": false, "explanation": "時計のニュースでは物の値段の情報は得られず、文の内容と合わない。"}, {"text": "音楽", "is_correct": false, "explanation": "音楽のニュースでは物の値段は分からず、文の内容と合わない。"}], "explanations": {"経済": "正解。「経済のニュース」は、お金や物の流れを伝える報道として自然。", "教育": "教育のニュースは学校や教育制度が中心で、物の値段はわからないので合わない。", "時計": "時計のニュースでは物の値段の情報は得られず、文の内容と合わない。", "音楽": "音楽のニュースでは物の値段は分からず、文の内容と合わない。"}, "sentence_index": 6, "correct_answer": "経済"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "駅までの経済を、地図で一度確認しておこう。", "explanation": "ここは〈経路〉の意味。道筋は経路と言い、経済（お金や物の仕組み）とは合わない。"}, {"text": "彼は留学の経済を、クラスの前で語った。", "explanation": "ここは〈経験〉の意味。自分が体験したことは経験と言い、経済とは合わない。"}, {"text": "警察は事件の経済を、順番に説明した。", "explanation": "ここは〈経緯〉の意味。物事の成り行きは経緯と言い、経済では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '196c77a7-afc3-481c-87f3-1ba8dda84301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35616, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "円高が続くと、経済を影響が出る。", "corrected_sentence": "円高が続くと、経済に影響が出る。", "error_description": "「影響が出る」は「に」で相手を示す。「経済を」は誤りで、正しくは「経済に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '196c77a7-afc3-481c-87f3-1ba8dda84301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35616, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新しい空港ができて、地域の経済が活気づかれた。", "corrected_sentence": "新しい空港ができて、地域の経済が活気づいた。", "error_description": "「活気づく」は自動詞なので受け身にしない。「活気づかれた」は誤りで、「活気づいた」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '196c77a7-afc3-481c-87f3-1ba8dda84301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
