INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35618, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "二つのものがつながっていること。", "primary_collocate": null, "pronunciation": "かんけい", "ipa": "kaŋkeː", "syllable_count": 4, "sentences": [{"text": "天気と野菜の値段には関係がある。", "target_word": "関係", "complexity_tier": "T3", "furigana": "天気[てんき]と野菜[やさい]の値段[ねだん]には関係[かんけい]がある。", "sentence_source": "generated"}, {"text": "兄とはとても仲のよい関係だ。", "target_word": "関係", "complexity_tier": "T3", "furigana": "兄[あに]とはとても仲[なか]のよい関係[かんけい]だ。", "sentence_source": "generated"}, {"text": "彼は事件に関係がないと言っている。", "target_word": "関係", "complexity_tier": "T3", "furigana": "彼[かれ]は事件[じけん]に関係[かんけい]がないと言[い]っている。", "sentence_source": "generated"}, {"text": "運動と健康の関係について、先生が話してくれた。", "target_word": "関係", "complexity_tier": "T3", "furigana": "運動[うんどう]と健康[けんこう]の関係[かんけい]について、先生[せんせい]が話[はな]してくれた。", "sentence_source": "generated"}, {"text": "親と子の関係は、年とともに少しずつ変わる。", "target_word": "関係", "complexity_tier": "T3", "furigana": "親[おや]と子[こ]の関係[かんけい]は、年[とし]とともに少[すこ]しずつ変[か]わる。", "sentence_source": "generated"}, {"text": "この二つの言葉の関係がよくわからない。", "target_word": "関係", "complexity_tier": "T3", "furigana": "この二[ふた]つの言葉[ことば]の関係[かんけい]がよくわからない。", "sentence_source": "generated"}, {"text": "二人は兄弟ではなく、親せきの関係だ。", "target_word": "関係", "complexity_tier": "T3", "furigana": "二人[ふたり]は兄弟[きょうだい]ではなく、親[しん]せきの関係[かんけい]だ。", "sentence_source": "generated"}, {"text": "睡眠不足は成績に関係するのだろうか。", "target_word": "関係", "complexity_tier": "T3", "furigana": "睡眠不足[すいみんぶそく]は成績[せいせき]に関係[かんけい]するのだろうか。", "sentence_source": "generated"}, {"text": "国と国の関係がよくなるように、学生が交流している。", "target_word": "関係", "complexity_tier": "T3", "furigana": "国[くに]と国[くに]の関係[かんけい]がよくなるように、学生[がくせい]が交流[こうりゅう]している。", "sentence_source": "generated"}, {"text": "この会社とは長い取引の関係があるので、安心して頼める。", "target_word": "関係", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]とは長[なが]い取引[とりひき]の関係[かんけい]があるので、安心[あんしん]して頼[たの]める。", "sentence_source": "generated"}], "morphological_forms": [{"form": "関係", "label": "基本形"}, {"form": "関係する", "label": "サ変動詞形"}, {"form": "関係が", "label": "主格"}, {"form": "関係の", "label": "連体修飾（の）"}], "register": "neutral", "sense_fingerprint": "人や物事のあいだにあるつながりやかかわり", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T1: contains vocabulary far above tier T1: 親せき (Zipf 2.05)']::text[], 'f59eed6c-7780-4a68-92fd-f9cceeb3a107') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35618, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "関係", "is_correct": true, "explanation": "「値段には関係がある」は、二つのものの間につながりがあることを表し、文に合う。"}, {"text": "予定", "is_correct": false, "explanation": "「値段には予定がある」は意味が通らない。"}, {"text": "性格", "is_correct": false, "explanation": "「値段には性格がある」は、値段に性格があるという意味になり成り立たない。"}, {"text": "寿命", "is_correct": false, "explanation": "「値段には寿命がある」は、値段に寿命があるという意味になり成り立たない。"}], "explanations": {"関係": "「値段には関係がある」は、二つのものの間につながりがあることを表し、文に合う。", "予定": "「値段には予定がある」は意味が通らない。", "性格": "「値段には性格がある」は、値段に性格があるという意味になり成り立たない。", "寿命": "「値段には寿命がある」は、値段に寿命があるという意味になり成り立たない。"}, "sentence_index": 0, "correct_answer": "関係"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "友達に関係を送った。", "explanation": "ここは〈手紙〉の意味。手紙は送るものだが、関係（人や物事のつながり）は送れない。"}, {"text": "おいしい関係を食べた。", "explanation": "ここは〈ごはん〉の意味。食べるのはごはんで、関係（つながり）は食べ物ではない。"}, {"text": "二つの駅の関係は三キロだ。", "explanation": "ここは〈距離〉の意味。二つの駅の間の長さは距離で表すもので、関係（つながり）は数字では表せないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66c5ca52-51a7-48b2-bf58-49b55ba482b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35618, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "関係", "is_correct": true, "explanation": "「親せきの関係だ」は、人と人のつながりを表す文に合う。"}, {"text": "期限", "is_correct": false, "explanation": "「親せきの期限だ」は意味が通らない。"}, {"text": "音量", "is_correct": false, "explanation": "「親せきの音量だ」は意味が通らない。"}, {"text": "温度", "is_correct": false, "explanation": "「親せきの温度だ」は意味が通らない。"}], "explanations": {"関係": "「親せきの関係だ」は、人と人のつながりを表す文に合う。", "期限": "「親せきの期限だ」は意味が通らない。", "音量": "「親せきの音量だ」は意味が通らない。", "温度": "「親せきの温度だ」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "関係"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "庭の関係が一面に咲いた。", "explanation": "ここは〈花〉の意味。花は咲くものだが、関係（人や物事のつながり）は咲かない。"}, {"text": "帰りの電車で関係を聴いた。", "explanation": "ここは〈音楽〉の意味。音楽は聴くものだが、関係（つながり）は聴けない。"}, {"text": "朝から関係が降っていた。", "explanation": "ここは〈雨〉の意味。雨は降るものだが、関係（つながり）は降らない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66c5ca52-51a7-48b2-bf58-49b55ba482b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35618, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "家族の関係をよくなった。", "corrected_sentence": "家族の関係がよくなった。", "error_description": "「よくなる」の主語は「関係」なので、「が」を使う。「を」は目的語を示すため、「関係をよくなる」は不自然。誤りは「を」、正しくは「が」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66c5ca52-51a7-48b2-bf58-49b55ba482b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35618, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "両国は新しい関係が結ぶため、会談した。", "corrected_sentence": "両国は新しい関係を結ぶため、会談した。", "error_description": "「結ぶ」の目的語は「を」で示す。「関係が結ぶ」は他動詞の目的語に「が」を使っており誤り。誤りは「が」、正しくは「を」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66c5ca52-51a7-48b2-bf58-49b55ba482b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35624, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「好きだ」の対象は「が」で示す。「地理が好きで」の形になる。"}, {"text": "を", "is_correct": false, "explanation": "「好きだ」は対象を「が」で示すので、「を」は合わない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は位置や相手を示すので、「好き」の対象には使わない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示すので、「地理で好き」は文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「好きだ」の対象は「が」で示す。「地理が好きで」の形になる。", "を": "「好きだ」は対象を「が」で示すので、「を」は合わない。", "に": "「に」は位置や相手を示すので、「好き」の対象には使わない。", "で": "「で」は場所や手段を示すので、「地理で好き」は文が成り立たない。"}, "error_tags": {"を": "目的語", "に": "位置・相手", "で": "場所・手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66c5ca52-51a7-48b2-bf58-49b55ba482b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35624, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「専攻する」は専攻する分野を「を」で示す。「地理を専攻して」の形になる。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すので、「地理が専攻して」は成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、専攻の対象には使わない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すので、専攻の対象には使わない。"}], "correct_answer": "を", "explanations": {"を": "「専攻する」は専攻する分野を「を」で示す。「地理を専攻して」の形になる。", "が": "「が」は主語を示すので、「地理が専攻して」は成り立たない。", "へ": "「へ」は方向を示すので、専攻の対象には使わない。", "より": "「より」は比較を示すので、専攻の対象には使わない。"}, "error_tags": {"が": "主語", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66c5ca52-51a7-48b2-bf58-49b55ba482b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35624, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "地球の上にある、山や川、国や町などの場所や、その様子についての学問です。", "primary_collocate": null, "pronunciation": "ちり", "ipa": "tɕiɾi", "syllable_count": 2, "sentences": [{"text": "地理の授業で、日本の川や山の名前を覚えた。", "target_word": "地理", "complexity_tier": "T3", "furigana": "地理[ちり]の授業[じゅぎょう]で、日本[にほん]の川[かわ]や山[やま]の名前[なまえ]を覚[おぼ]えた。", "sentence_source": "generated"}, {"text": "兄は地理が好きで、世界の国の場所をほとんど知っている。", "target_word": "地理", "complexity_tier": "T3", "furigana": "兄[あに]は地理[ちり]が好[す]きで、世界[せかい]の国[くに]の場所[ばしょ]をほとんど知[し]っている。", "sentence_source": "generated"}, {"text": "明日の地理のテストに備えて、地図を見ながら勉強した。", "target_word": "地理", "complexity_tier": "T3", "furigana": "明日[あした]の地理[ちり]のテストに備[そな]えて、地図[ちず]を見[み]ながら勉強[べんきょう]した。", "sentence_source": "generated"}, {"text": "地理の先生は、旅行の写真を使って国の様子を教えてくれる。", "target_word": "地理", "complexity_tier": "T3", "furigana": "地理[ちり]の先生[せんせい]は、旅行[りょこう]の写真[しゃしん]を使[つか]って国[くに]の様子[ようす]を教[おし]えてくれる。", "sentence_source": "generated"}, {"text": "私は歴史より地理のほうが得意だ。", "target_word": "地理", "complexity_tier": "T3", "furigana": "私[わたし]は歴史[れきし]より地理[ちり]のほうが得意[とくい]だ。", "sentence_source": "generated"}, {"text": "地理の宿題で、自分の町の地図を作った。", "target_word": "地理", "complexity_tier": "T3", "furigana": "地理[ちり]の宿題[しゅくだい]で、自分[じぶん]の町[まち]の地図[ちず]を作[つく]った。", "sentence_source": "generated"}, {"text": "地理を学ぶと、ニュースで聞く外国の場所がわかるようになる。", "target_word": "地理", "complexity_tier": "T3", "furigana": "地理[ちり]を学[まな]ぶと、ニュースで聞[き]く外国[がいこく]の場所[ばしょ]がわかるようになる。", "sentence_source": "generated"}, {"text": "大学では地理を専攻して、川と町の関係を調べたい。", "target_word": "地理", "complexity_tier": "T3", "furigana": "大学[だいがく]では地理[ちり]を専攻[せんこう]して、川[かわ]と町[まち]の関係[かんけい]を調[しら]べたい。", "sentence_source": "generated"}, {"text": "地理の教科書には、国ごとの人口や産業が書いてある。", "target_word": "地理", "complexity_tier": "T3", "furigana": "地理[ちり]の教科書[きょうかしょ]には、国[くに]ごとの人口[じんこう]や産業[さんぎょう]が書[か]いてある。", "sentence_source": "generated"}, {"text": "地理の本を読んでから、世界の地図を見るのが楽しくなった。", "target_word": "地理", "complexity_tier": "T3", "furigana": "地理[ちり]の本[ほん]を読[よ]んでから、世界[せかい]の地図[ちず]を見[み]るのが楽[たの]しくなった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "地理", "label": "基本形"}, {"form": "地理の", "label": "連体修飾（の）"}, {"form": "地理が", "label": "主格"}], "register": "neutral", "sense_fingerprint": "学校で学ぶ教科や学問としての、場所や地形・国についての勉強", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f59eed6c-7780-4a68-92fd-f9cceeb3a107') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35624, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地理", "is_correct": true, "explanation": "学校の教科としての「地理」。授業で川や山の名前を覚える、という文に合う。"}, {"text": "音楽", "is_correct": false, "explanation": "音楽は音や曲を学ぶ教科で、川や山の名前を覚える授業には合わない。"}, {"text": "美術", "is_correct": false, "explanation": "美術は絵や造形を学ぶ教科で、地名を覚える授業の内容とは合わない。"}, {"text": "体育", "is_correct": false, "explanation": "体育は運動の授業で、川や山の名前を覚える内容ではない。"}], "explanations": {"地理": "学校の教科としての「地理」。授業で川や山の名前を覚える、という文に合う。", "音楽": "音楽は音や曲を学ぶ教科で、川や山の名前を覚える授業には合わない。", "美術": "美術は絵や造形を学ぶ教科で、地名を覚える授業の内容とは合わない。", "体育": "体育は運動の授業で、川や山の名前を覚える内容ではない。"}, "sentence_index": 0, "correct_answer": "地理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "明日の地理は雨が降るらしい。", "explanation": "ここは〈天気〉の意味。〈地理〉は土地の様子や学問を指し、天候の予報には使えないので合わない。"}, {"text": "地理を広げて、行き先を確認した。", "explanation": "ここは〈地図〉の意味。〈地図〉は広げて使うものだが、〈地理〉は学問なので広げられない。"}, {"text": "この町の地理は、毎年夏に大きな祭りを開く。", "explanation": "ここは〈祭り〉の意味。地理は土地の様子や学問で、祭りを開くことはできないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66c5ca52-51a7-48b2-bf58-49b55ba482b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35624, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地理", "is_correct": true, "explanation": "学問としての「地理」。学ぶと外国の場所がわかるようになる、という文に合う。"}, {"text": "数学", "is_correct": false, "explanation": "数学は計算や証明を学ぶ教科で、外国の場所がわかるようになる話には合わない。"}, {"text": "書道", "is_correct": false, "explanation": "書道は文字を書く技術で、外国の場所を学ぶ内容とは合わない。"}, {"text": "家庭科", "is_correct": false, "explanation": "家庭科は生活の技能を学ぶ教科で、外国の場所がわかる話とは合わない。"}], "explanations": {"地理": "学問としての「地理」。学ぶと外国の場所がわかるようになる、という文に合う。", "数学": "数学は計算や証明を学ぶ教科で、外国の場所がわかるようになる話には合わない。", "書道": "書道は文字を書く技術で、外国の場所を学ぶ内容とは合わない。", "家庭科": "家庭科は生活の技能を学ぶ教科で、外国の場所がわかる話とは合わない。"}, "sentence_index": 6, "correct_answer": "地理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今朝は地理が重くて、山道を登れなかった。", "explanation": "ここは〈体の調子〉の意味。〈地理〉は土地の様子や学問を指すので、体がだるい話には使えないので合わない。"}, {"text": "この地理の住民は、毎年祭りを開く。", "explanation": "ここは〈地域〉の意味。〈地理〉は学問や土地の特徴を指し、人々の集まりである住民には使えない。"}, {"text": "地理は太陽の周りを回っている。", "explanation": "ここは〈地球〉の意味。〈地理〉は学問を指すので、天体が回るという話には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66c5ca52-51a7-48b2-bf58-49b55ba482b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35624, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私は地理を好きだ。", "corrected_sentence": "私は地理が好きだ。", "error_description": "「好きだ」の対象は「が」で示す。「を」は誤りで、正しくは「地理が好きだ」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66c5ca52-51a7-48b2-bf58-49b55ba482b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35624, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大学では地理を専攻で、山の成り立ちを調べたい。", "corrected_sentence": "大学では地理を専攻して、山の成り立ちを調べたい。", "error_description": "「専攻する」を「専攻で」と活用させたのが誤り。動詞は「専攻して」の形で続けるので、正しくは「専攻して」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66c5ca52-51a7-48b2-bf58-49b55ba482b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35625, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「わからない」の対象は「が」で示す。「地理がわからず」の形になる。"}, {"text": "を", "is_correct": false, "explanation": "「わからない」は対象を「が」で示すので、「を」は合わない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は位置や相手を示すので、「地理にわからず」は成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示すので、「地理でわからず」は成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「わからない」の対象は「が」で示す。「地理がわからず」の形になる。", "を": "「わからない」は対象を「が」で示すので、「を」は合わない。", "に": "「に」は位置や相手を示すので、「地理にわからず」は成り立たない。", "で": "「で」は場所や手段を示すので、「地理でわからず」は成り立たない。"}, "error_tags": {"を": "目的語", "に": "位置・相手", "で": "場所・手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66c5ca52-51a7-48b2-bf58-49b55ba482b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35625, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「調べる」の対象は「を」で示す。「地理を調べてから」の形になる。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すので、「地理が調べてから」は成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、調べる対象には使わない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すので、調べる対象には使わない。"}], "correct_answer": "を", "explanations": {"を": "「調べる」の対象は「を」で示す。「地理を調べてから」の形になる。", "が": "「が」は主語を示すので、「地理が調べてから」は成り立たない。", "へ": "「へ」は方向を示すので、調べる対象には使わない。", "より": "「より」は比較を示すので、調べる対象には使わない。"}, "error_tags": {"が": "主語", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66c5ca52-51a7-48b2-bf58-49b55ba482b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35625, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある土地の地形や道、位置など、場所そのものの特徴や様子。", "primary_collocate": null, "pronunciation": "ちり", "ipa": "tɕiɾi", "syllable_count": 2, "sentences": [{"text": "この町の地理にくわしい人に、近道を教えてもらった。", "target_word": "地理", "complexity_tier": "T3", "furigana": "この町[まち]の地理[ちり]にくわしい人[ひと]に、近道[ちかみち]を教[おし]えてもらった。", "sentence_source": "generated"}, {"text": "初めての土地で地理がわからず、地図アプリを使った。", "target_word": "地理", "complexity_tier": "T3", "furigana": "初[はじ]めての土地[とち]で地理[ちり]がわからず、地図[ちず]アプリを使[つか]った。", "sentence_source": "generated"}, {"text": "引っ越したばかりで、まだこのあたりの地理に慣れていない。", "target_word": "地理", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]したばかりで、まだこのあたりの地理[ちり]に慣[な]れていない。", "sentence_source": "generated"}, {"text": "日本は山が多いという地理の特徴が、人々の暮らしに影響している。", "target_word": "地理", "complexity_tier": "T3", "furigana": "日本[にほん]は山[やま]が多[おお]いという地理[ちり]の特徴[とくちょう]が、人々[ひとびと]の暮[く]らしに影響[えいきょう]している。", "sentence_source": "generated"}, {"text": "港町は海に近い地理を生かして、魚の取引で栄えた。", "target_word": "地理", "complexity_tier": "T3", "furigana": "港町[みなとまち]は海[うみ]に近[ちか]い地理[ちり]を生[い]かして、魚[さかな]の取引[とりひき]で栄[さか]えた。", "sentence_source": "generated"}, {"text": "配達員は地理をよく知っているので、細い道でも迷わない。", "target_word": "地理", "complexity_tier": "T3", "furigana": "配達員[はいたついん]は地理[ちり]をよく知[し]っているので、細[ほそ]い道[みち]でも迷[まよ]わない。", "sentence_source": "generated"}, {"text": "農業が盛んなのは、この地域の地理と気候に合っているからだ。", "target_word": "地理", "complexity_tier": "T3", "furigana": "農業[のうぎょう]が盛[さか]んなのは、この地域[ちいき]の地理[ちり]と気候[きこう]に合[あ]っているからだ。", "sentence_source": "generated"}, {"text": "地理を調べてから、この町の道を歩いた。", "target_word": "地理", "complexity_tier": "T3", "furigana": "地理[ちり]を調[しら]べてから、この町[まち]の道[みち]を歩[ある]いた。", "sentence_source": "generated"}, {"text": "地理に明るい友人が、旅行の道順を決めてくれた。", "target_word": "地理", "complexity_tier": "T3", "furigana": "地理[ちり]に明[あか]るい友人[ゆうじん]が、旅行[りょこう]の道順[みちじゅん]を決[き]めてくれた。", "sentence_source": "generated"}, {"text": "山に囲まれた地理のため、冬は雪で村へ行けなくなる。", "target_word": "地理", "complexity_tier": "T3", "furigana": "山[やま]に囲[かこ]まれた地理[ちり]のため、冬[ふゆ]は雪[ゆき]で村[むら]へ行[い]けなくなる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "地理", "label": "基本形"}, {"form": "地理に", "label": "位格"}, {"form": "地理が", "label": "主格"}], "register": "neutral", "sense_fingerprint": "ある土地の地形や道・位置など、場所そのものの特徴や様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f59eed6c-7780-4a68-92fd-f9cceeb3a107') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35625, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地理", "is_correct": true, "explanation": "「地理にくわしい」は土地の様子や道を知っている、の意味。近道を教えてもらう文に合う。"}, {"text": "数学", "is_correct": false, "explanation": "数学にくわしい人が近道を教える、という内容にはならない。"}, {"text": "料理", "is_correct": false, "explanation": "料理にくわしい人が近道を教える、という内容は合わない。"}, {"text": "美術", "is_correct": false, "explanation": "美術にくわしい人が近道を教える、という内容は合わない。"}], "explanations": {"地理": "「地理にくわしい」は土地の様子や道を知っている、の意味。近道を教えてもらう文に合う。", "数学": "数学にくわしい人が近道を教える、という内容にはならない。", "料理": "料理にくわしい人が近道を教える、という内容は合わない。", "美術": "美術にくわしい人が近道を教える、という内容は合わない。"}, "sentence_index": 0, "correct_answer": "地理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今は地理の変わり目で、朝晩が冷える。", "explanation": "ここは〈季節〉の意味。〈地理〉は土地の特徴や学問を指すので、季節の移り変わりには使えないので合わない。"}, {"text": "地理を広げて、道を確かめた。", "explanation": "ここは〈地図〉の意味。〈地図〉は広げて使う物だが、〈地理〉は土地の特徴なので広げられない。"}, {"text": "地理は一日に一回、自転している。", "explanation": "ここは〈地球〉の意味。土地の特徴を表す〈地理〉は自転するものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66c5ca52-51a7-48b2-bf58-49b55ba482b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35625, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地理", "is_correct": true, "explanation": "「地理と気候に合う」は土地の特徴が気候に合う、の意味。農業が盛んな理由の文に合う。"}, {"text": "教科書", "is_correct": false, "explanation": "教科書と気候が合う、という文にはならない。"}, {"text": "宿題", "is_correct": false, "explanation": "宿題と気候が合う、という文にはならない。"}, {"text": "絵画", "is_correct": false, "explanation": "絵画と気候が合う、という文にはならない。"}], "explanations": {"地理": "「地理と気候に合う」は土地の特徴が気候に合う、の意味。農業が盛んな理由の文に合う。", "教科書": "教科書と気候が合う、という文にはならない。", "宿題": "宿題と気候が合う、という文にはならない。", "絵画": "絵画と気候が合う、という文にはならない。"}, "sentence_index": 6, "correct_answer": "地理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "毎朝ジョギングを続けて、地理を保っている。", "explanation": "ここは〈健康〉の意味。〈地理〉は土地の特徴や学問を指すので、体の状態を保つ対象にはならない。"}, {"text": "この地理の住民は、冬に雪かきを手伝う。", "explanation": "ここは〈地域〉の意味。〈地理〉は土地の特徴なので、人々の集まりを指す住民には使えない。"}, {"text": "明日の地理を予報で確かめた。", "explanation": "ここは〈天気〉の意味。〈地理〉は土地の特徴で、日々変わる予報の対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66c5ca52-51a7-48b2-bf58-49b55ba482b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35625, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この辺りの地理を慣れるのに、少し時間がかかった。", "corrected_sentence": "この辺りの地理に慣れるのに、少し時間がかかった。", "error_description": "「慣れる」は「に」を取る。「を」は誤りで、正しくは「地理に慣れる」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66c5ca52-51a7-48b2-bf58-49b55ba482b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35625, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "海に面した地理を生きて、この町は栄えた。", "corrected_sentence": "海に面した地理を生かして、この町は栄えた。", "error_description": "「地理を生かす」の動詞を「生きる」にしたのが誤り。正しくは「生かして」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66c5ca52-51a7-48b2-bf58-49b55ba482b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35627, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '815f5587-2a9c-42ca-9db8-5f13ee1b65f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35627, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「経験を有する」で、有するの対象を示す。正しい。"}, {"text": "と", "is_correct": false, "explanation": "「経験と有する」は相手や共同を表す「と」で、有する対象にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "「経験へ有する」は方向を表す「へ」で、持つ対象を示せない。"}, {"text": "から", "is_correct": false, "explanation": "「経験から有する」は起点を表す「から」で、持つ対象を示す文にならない。"}], "correct_answer": "を", "explanations": {"を": "「経験を有する」で、有するの対象を示す。正しい。", "と": "「経験と有する」は相手や共同を表す「と」で、有する対象にはならない。", "へ": "「経験へ有する」は方向を表す「へ」で、持つ対象を示せない。", "から": "「経験から有する」は起点を表す「から」で、持つ対象を示す文にならない。"}, "error_tags": {"と": "相手", "へ": "方向", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '815f5587-2a9c-42ca-9db8-5f13ee1b65f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35627, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "abstract", "definition": "所有する、持つという意味の動詞。形式ばった表現で、物や性質、構造などを有していることを表す。", "primary_collocate": null, "pronunciation": "ゆうする", "ipa": "jɯːsɯɾɯ", "syllable_count": 4, "sentences": [{"text": "それは、誰しもが生涯唯一無二の隆線パターンを有するという生体認証の絶対性に拠る。", "target_word": "有する", "complexity_tier": "T3", "furigana": "それは、誰[だれ]しもが生涯[しょうがい]唯一無二[ゆいいつむに]の隆線[りゅうせん]パターンを有[ゆう]するという生体[せいたい]認証[にんしょう]の絶対性[ぜったいせい]に拠[よ]る。", "sentence_source": "mined"}, {"text": "議会は法律を改正する権限を有する。", "target_word": "有する", "complexity_tier": "T3", "furigana": "議会[ぎかい]は法律[ほうりつ]を改正[かいせい]する権限[けんげん]を有[ゆう]する。", "sentence_source": "generated"}, {"text": "この製品は高い耐久性を有している。", "target_word": "有している", "complexity_tier": "T3", "furigana": "この製品[せいひん]は高[たか]い耐久性[たいきゅうせい]を有[ゆう]している。", "sentence_source": "generated"}, {"text": "申請者は、資格を有することを証明しなければならない。", "target_word": "有する", "complexity_tier": "T3", "furigana": "申請者[しんせいしゃ]は、資格[しかく]を有[ゆう]することを証明[しょうめい]しなければならない。", "sentence_source": "generated"}, {"text": "その寺院は千年を超える歴史を有する。", "target_word": "有する", "complexity_tier": "T3", "furigana": "その寺院[じいん]は千年[せんねん]を超[こ]える歴史[れきし]を有[ゆう]する。", "sentence_source": "generated"}, {"text": "日本国民は、等しく教育を受ける権利を有する。", "target_word": "有する", "complexity_tier": "T3", "furigana": "日本[にほん]国民[こくみん]は、等[ひと]しく教育[きょういく]を受[う]ける権利[けんり]を有[ゆう]する。", "sentence_source": "generated"}, {"text": "この菌は強い毒性を有しているため、取り扱いに注意が必要だ。", "target_word": "有している", "complexity_tier": "T3", "furigana": "この菌[きん]は強[つよ]い毒性[どくせい]を有[ゆう]しているため、取[と]り扱[あつか]いに注意[ちゅうい]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "十分な経験を有する人材を募集している。", "target_word": "有する", "complexity_tier": "T3", "furigana": "十分[じゅうぶん]な経験[けいけん]を有[ゆう]する人材[じんざい]を募集[ぼしゅう]している。", "sentence_source": "generated"}, {"text": "新しい素材は、水を通さない性質を有している。", "target_word": "有している", "complexity_tier": "T3", "furigana": "新[あたら]しい素材[そざい]は、水[みず]を通[とお]さない性質[せいしつ]を有[ゆう]している。", "sentence_source": "generated"}, {"text": "会員は、総会で投票する権利を有します。", "target_word": "有します", "complexity_tier": "T3", "furigana": "会員[かいいん]は、総会[そうかい]で投票[とうひょう]する権利[けんり]を有[ゆう]します。", "sentence_source": "generated"}], "morphological_forms": [{"form": "有する", "label": "dictionary form"}, {"form": "有し", "label": "continuative (masu-stem)"}, {"form": "有して", "label": "te-form"}, {"form": "有した", "label": "past"}, {"form": "有しない", "label": "negative"}, {"form": "有すれば", "label": "conditional (ba)"}], "register": "formal", "sense_fingerprint": "権利・性質・特徴などを形式ばった書き言葉で「持っている」と述べる動詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bf4c2f4-d106-46cc-9bb1-e6df9b77d143') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35627, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有する", "is_correct": true, "explanation": "隆線パターンを持っていることを表し、誰もが唯一無二のパターンを持つという文脈に合う。"}, {"text": "削除する", "is_correct": false, "explanation": "隆線パターンを削除するでは、生体認証の前提と逆の意味になる。"}, {"text": "配達する", "is_correct": false, "explanation": "隆線パターンを配達するという言い方は文として成り立たない。"}, {"text": "翻訳する", "is_correct": false, "explanation": "隆線パターンを翻訳するは意味が通らない。"}], "explanations": {"有する": "隆線パターンを持っていることを表し、誰もが唯一無二のパターンを持つという文脈に合う。", "削除する": "隆線パターンを削除するでは、生体認証の前提と逆の意味になる。", "配達する": "隆線パターンを配達するという言い方は文として成り立たない。", "翻訳する": "隆線パターンを翻訳するは意味が通らない。"}, "sentence_index": 0, "correct_answer": "有する"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この作業には、少なくとも三日を有する。", "explanation": "ここは〈要する〉の意味。時間や費用がかかる場合に要するを使う。有するは持っている状態を表すので合わない。"}, {"text": "彼は友人のために料理を有した。", "explanation": "ここは〈作る〉の意味。料理を作る動作には作るを使う。有するは持つ状態を表す語で、料理を作る意味では使わない。"}, {"text": "その発言は、組織に大きな混乱を有した。", "explanation": "ここは〈招く〉の意味。好ましくない結果を引き起こす場合に招くを使う。有するは持つ状態を表す語で、結果を生じさせる意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '815f5587-2a9c-42ca-9db8-5f13ee1b65f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35627, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有している", "is_correct": true, "explanation": "毒性を持っていることを表し、取り扱いに注意が必要という理由として文脈に合う。"}, {"text": "削除している", "is_correct": false, "explanation": "毒性を削除しているでは、注意が必要という理由にならない。"}, {"text": "配達している", "is_correct": false, "explanation": "毒性を配達しているは文として成り立たない。"}, {"text": "翻訳している", "is_correct": false, "explanation": "毒性を翻訳しているは意味が通らない。"}], "explanations": {"有している": "毒性を持っていることを表し、取り扱いに注意が必要という理由として文脈に合う。", "削除している": "毒性を削除しているでは、注意が必要という理由にならない。", "配達している": "毒性を配達しているは文として成り立たない。", "翻訳している": "毒性を翻訳しているは意味が通らない。"}, "sentence_index": 6, "correct_answer": "有している"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会員は、総会で議案を有します。", "explanation": "ここは〈提出〉の意味。議案を出す動作は提出するで、有するは持つ状態を表す。"}, {"text": "会員は、理事会に説明を有します。", "explanation": "ここは〈求める〉の意味。相手に説明を求める動作で、有するは持つ状態を表す語。"}, {"text": "会員は、総会で採決を有します。", "explanation": "ここは〈行う〉の意味。採決などの動作を実際に行う場合に行うを使う。有するは持つ状態を表すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '815f5587-2a9c-42ca-9db8-5f13ee1b65f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35627, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この寺院は千年を超える歴史が有する。", "corrected_sentence": "この寺院は千年を超える歴史を有する。", "error_description": "誤: 歴史が有する / 正: 歴史を有する。有するは「〜を」で対象を取るので、「が」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '815f5587-2a9c-42ca-9db8-5f13ee1b65f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35627, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この部屋は広い窓で有している。", "corrected_sentence": "この部屋は広い窓を有している。", "error_description": "誤: 窓で有している / 正: 窓を有している。有するの対象は「を」で示すので、「で」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '815f5587-2a9c-42ca-9db8-5f13ee1b65f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35628, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「熱帯に行く」の「に」は到着点を示し、正しい。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すので、「熱帯が行くなら」では行き先の意味が出ない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は同行者を示すので、「熱帯と行くなら」では行き先にならない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞を修飾するので、「熱帯の行くなら」は動詞の行き先にならない。"}], "correct_answer": "に", "explanations": {"に": "「熱帯に行く」の「に」は到着点を示し、正しい。", "が": "「が」は主語を示すので、「熱帯が行くなら」では行き先の意味が出ない。", "と": "「と」は同行者を示すので、「熱帯と行くなら」では行き先にならない。", "の": "「の」は名詞を修飾するので、「熱帯の行くなら」は動詞の行き先にならない。"}, "error_tags": {"が": "主語", "と": "同行・相手", "の": "所属・修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c087fde-8a23-4107-9fdc-2f977c77c827') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35628, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「熱帯の国」の「の」は国の所属を示し、正しい。"}, {"text": "が", "is_correct": false, "explanation": "「熱帯が国で」は熱帯そのものを国とする意味になり、場所の関係を表せない。"}, {"text": "に", "is_correct": false, "explanation": "「熱帯に国で」は場所の関係が成り立たず、誤り。"}, {"text": "を", "is_correct": false, "explanation": "「熱帯を国で」は目的語にならず、文が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「熱帯の国」の「の」は国の所属を示し、正しい。", "が": "「熱帯が国で」は熱帯そのものを国とする意味になり、場所の関係を表せない。", "に": "「熱帯に国で」は場所の関係が成り立たず、誤り。", "を": "「熱帯を国で」は目的語にならず、文が成り立たない。"}, "error_tags": {"が": "主語", "に": "場所・相手", "を": "目的語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c087fde-8a23-4107-9fdc-2f977c77c827') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35628, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "一年中あたたかくて、植物がよく育つ場所のこと。", "primary_collocate": null, "pronunciation": "ねったい", "ipa": "nettai", "syllable_count": 4, "sentences": [{"text": "熱帯は一年中暑いので、大きな木がよく育つ。", "target_word": "熱帯", "complexity_tier": "T3", "furigana": "熱帯[ねったい]は一年中[いちねんじゅう]暑[あつ]いので、大[おお]きな木[き]がよく育[そだ]つ。", "sentence_source": "generated"}, {"text": "熱帯に行くなら、うすい服を持っていくといい。", "target_word": "熱帯", "complexity_tier": "T3", "furigana": "熱帯[ねったい]に行[い]くなら、うすい服[ふく]を持[も]っていくといい。", "sentence_source": "generated"}, {"text": "私は寒い国で生まれたので、熱帯の暑さになかなか慣れなかった。", "target_word": "熱帯", "complexity_tier": "T3", "furigana": "私[わたし]は寒[さむ]い国[くに]で生[う]まれたので、熱帯[ねったい]の暑[あつ]さになかなか慣[な]れなかった。", "sentence_source": "generated"}, {"text": "熱帯の森には、日本では見られない花が咲いている。", "target_word": "熱帯", "complexity_tier": "T3", "furigana": "熱帯[ねったい]の森[もり]には、日本[にほん]では見[み]られない花[はな]が咲[さ]いている。", "sentence_source": "generated"}, {"text": "バナナは熱帯でよく育つ果物だ。", "target_word": "熱帯", "complexity_tier": "T3", "furigana": "バナナは熱帯[ねったい]でよく育[そだ]つ果物[くだもの]だ。", "sentence_source": "generated"}, {"text": "熱帯と違って、日本には冬がある。", "target_word": "熱帯", "complexity_tier": "T3", "furigana": "熱帯[ねったい]と違[ちが]って、日本[にほん]には冬[ふゆ]がある。", "sentence_source": "generated"}, {"text": "熱帯に近い島では、冬でもコートはいらない。", "target_word": "熱帯", "complexity_tier": "T3", "furigana": "熱帯[ねったい]に近[ちか]い島[しま]では、冬[ふゆ]でもコートはいらない。", "sentence_source": "generated"}, {"text": "祖父は熱帯の国で、長く農業をしていた。", "target_word": "熱帯", "complexity_tier": "T3", "furigana": "祖父[そふ]は熱帯[ねったい]の国[くに]で、長[なが]く農業[のうぎょう]をしていた。", "sentence_source": "generated"}, {"text": "この植物は熱帯から来たので、寒さに弱い。", "target_word": "熱帯", "complexity_tier": "T3", "furigana": "この植物[しょくぶつ]は熱帯[ねったい]から来[き]たので、寒[さむ]さに弱[よわ]い。", "sentence_source": "generated"}, {"text": "熱帯に住む人々は、強い日ざしを避けて昼に休む。", "target_word": "熱帯", "complexity_tier": "T3", "furigana": "熱帯[ねったい]に住[す]む人々[ひとびと]は、強[つよ]い日[ひ]ざしを避[さ]けて昼[ひる]に休[やす]む。", "sentence_source": "generated"}], "morphological_forms": [{"form": "熱帯", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "赤道に近い、一年中暑くて植物が育つ場所としての熱帯。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e9d0569-35c2-4591-8d48-a8dee00aafec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35628, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "熱帯", "is_correct": true, "explanation": "熱帯は一年中暑く植物がよく育つ地域で、文の内容に合う。"}, {"text": "寝室", "is_correct": false, "explanation": "寝室は部屋の名前で、一年中暑くて木がよく育つ場所としては文が通らない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "冷蔵庫は食品を冷やす家電で、木が育つ場所にはならない。"}, {"text": "玄関", "is_correct": false, "explanation": "玄関は家の出入り口で、木がよく育つ土地を指さない。"}], "explanations": {"熱帯": "熱帯は一年中暑く植物がよく育つ地域で、文の内容に合う。", "寝室": "寝室は部屋の名前で、一年中暑くて木がよく育つ場所としては文が通らない。", "冷蔵庫": "冷蔵庫は食品を冷やす家電で、木が育つ場所にはならない。", "玄関": "玄関は家の出入り口で、木がよく育つ土地を指さない。"}, "sentence_index": 0, "correct_answer": "熱帯"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏の午後、熱帯が吹きつけて、汗が止まらない。", "explanation": "ここは〈熱風〉の意味。熱帯は地域の名前で、吹きつけてくる暑い風は表せない。"}, {"text": "熱帯のせいで、電車が遅れた。", "explanation": "ここは〈猛暑〉の意味。熱帯は地域名で、その時の激しい暑さを言う言葉ではない。"}, {"text": "カップに熱帯を注いだ。", "explanation": "ここは〈熱湯〉の意味。熱帯は地域の名前で、カップに注ぐ液体には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c087fde-8a23-4107-9fdc-2f977c77c827') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35628, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "熱帯", "is_correct": true, "explanation": "「熱帯に近い」は赤道近くの地域を指し、冬でも暖かい島の説明に合う。"}, {"text": "歯磨き", "is_correct": false, "explanation": "歯磨きは歯を磨く行為で、島の場所を表す言葉として文が通らない。"}, {"text": "寝袋", "is_correct": false, "explanation": "寝袋は眠るための道具で、島の位置を表す言葉にはならない。"}, {"text": "掃除機", "is_correct": false, "explanation": "掃除機はごみを吸う機械で、島の場所を示す語として意味が通らない。"}], "explanations": {"熱帯": "「熱帯に近い」は赤道近くの地域を指し、冬でも暖かい島の説明に合う。", "歯磨き": "歯磨きは歯を磨く行為で、島の場所を表す言葉として文が通らない。", "寝袋": "寝袋は眠るための道具で、島の位置を表す言葉にはならない。", "掃除機": "掃除機はごみを吸う機械で、島の場所を示す語として意味が通らない。"}, "sentence_index": 6, "correct_answer": "熱帯"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会場は熱帯に包まれていた。", "explanation": "ここは〈熱気〉の意味。熱帯は地域の名前で、会場の盛り上がりや雰囲気には使わない。"}, {"text": "エンジンの熱帯で、車が止まった。", "explanation": "ここは〈過熱〉の意味。熱帯は地域名で、機械が熱くなりすぎた状態は表せない。"}, {"text": "工場の熱帯で機械が壊れた。", "explanation": "ここは〈高温〉の意味。熱帯は地域の名前で、機械の温度が高すぎることは表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c087fde-8a23-4107-9fdc-2f977c77c827') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35628, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖母は熱帯を暮らしたことがある。", "corrected_sentence": "祖母は熱帯で暮らしたことがある。", "error_description": "「暮らす」の場所を示すのは「で」。「を」は誤りで、正しくは「で」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c087fde-8a23-4107-9fdc-2f977c77c827') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35628, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "熱帯に寒帯を比べると、雨の量が大きく違う。", "corrected_sentence": "熱帯と寒帯を比べると、雨の量が大きく違う。", "error_description": "「比べる」は「と」で比べる相手を示す。「に」は誤りで、正しくは「と」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c087fde-8a23-4107-9fdc-2f977c77c827') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35629, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c087fde-8a23-4107-9fdc-2f977c77c827') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35629, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「熱帯と寒帯」の「と」は二つを並べて比べる意味を示し、正しい。"}, {"text": "の", "is_correct": false, "explanation": "「熱帯の寒帯では」は名詞をつなぐ形で、二つを並べる意味にならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「熱帯へ寒帯では」は比べる関係を表せない。"}, {"text": "を", "is_correct": false, "explanation": "「熱帯を寒帯では」は目的語の形で、比べる相手を示せない。"}], "correct_answer": "と", "explanations": {"と": "「熱帯と寒帯」の「と」は二つを並べて比べる意味を示し、正しい。", "の": "「熱帯の寒帯では」は名詞をつなぐ形で、二つを並べる意味にならない。", "へ": "「へ」は方向を示すので、「熱帯へ寒帯では」は比べる関係を表せない。", "を": "「熱帯を寒帯では」は目的語の形で、比べる相手を示せない。"}, "error_tags": {"の": "所属・修飾", "へ": "方向", "を": "目的語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c087fde-8a23-4107-9fdc-2f977c77c827') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35629, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "一年を通して気温が高く、雨も多い気候の地域。", "primary_collocate": null, "pronunciation": "ねったい", "ipa": "nettai", "syllable_count": 4, "sentences": [{"text": "熱帯では、毎日のように強い雨が降る。", "target_word": "熱帯", "complexity_tier": "T3", "furigana": "熱帯[ねったい]では、毎日[まいにち]のように強[つよ]い雨[あめ]が降[ふ]る。", "sentence_source": "generated"}, {"text": "熱帯は気温が高くて、雨も多い地域だ。", "target_word": "熱帯", "complexity_tier": "T3", "furigana": "熱帯[ねったい]は気温[きおん]が高[たか]くて、雨[あめ]も多[おお]い地域[ちいき]だ。", "sentence_source": "generated"}, {"text": "熱帯の気候は、一年を通して大きく変わらない。", "target_word": "熱帯", "complexity_tier": "T3", "furigana": "熱帯[ねったい]の気候[きこう]は、一年[いちねん]を通[とお]して大[おお]きく変[か]わらない。", "sentence_source": "generated"}, {"text": "地図で見ると、熱帯は赤道の近くに広がっている。", "target_word": "熱帯", "complexity_tier": "T3", "furigana": "地図[ちず]で見[み]ると、熱帯[ねったい]は赤道[せきどう]の近[ちか]くに広[ひろ]がっている。", "sentence_source": "generated"}, {"text": "熱帯のスコールは、急に降って急にやむ。", "target_word": "熱帯", "complexity_tier": "T3", "furigana": "熱帯[ねったい]のスコールは、急[きゅう]に降[ふ]って急[きゅう]にやむ。", "sentence_source": "generated"}, {"text": "熱帯に属する国では、四季の変化が小さい。", "target_word": "熱帯", "complexity_tier": "T3", "furigana": "熱帯[ねったい]に属[ぞく]する国[くに]では、四季[しき]の変化[へんか]が小[ちい]さい。", "sentence_source": "generated"}, {"text": "熱帯の川は、雨が多いので水の量が多い。", "target_word": "熱帯", "complexity_tier": "T3", "furigana": "熱帯[ねったい]の川[かわ]は、雨[あめ]が多[おお]いので水[みず]の量[りょう]が多[おお]い。", "sentence_source": "generated"}, {"text": "熱帯と寒帯では、気温も雨の量も大きく違う。", "target_word": "熱帯", "complexity_tier": "T3", "furigana": "熱帯[ねったい]と寒帯[かんたい]では、気温[きおん]も雨[あめ]の量[りょう]も大[おお]きく違[ちが]う。", "sentence_source": "generated"}, {"text": "熱帯の天気は、朝は晴れて午後に雨になることが多い。", "target_word": "熱帯", "complexity_tier": "T3", "furigana": "熱帯[ねったい]の天気[てんき]は、朝[あさ]は晴[は]れて午後[ごご]に雨[あめ]になることが多[おお]い。", "sentence_source": "generated"}, {"text": "先生は、熱帯が雨の多い地域である理由を説明した。", "target_word": "熱帯", "complexity_tier": "T3", "furigana": "先生[せんせい]は、熱帯[ねったい]が雨[あめ]の多[おお]い地域[ちいき]である理由[りゆう]を説明[せつめい]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "熱帯", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "気温が高く雨も多い気候区分としての熱帯。寒帯・温帯と対比される。", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e9d0569-35c2-4591-8d48-a8dee00aafec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35629, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "熱帯", "is_correct": true, "explanation": "「熱帯では」は雨の多い気候の地域を指し、毎日雨が降る説明に合う。"}, {"text": "教科書", "is_correct": false, "explanation": "教科書は学ぶための本で、雨が降る場所としては文が通らない。"}, {"text": "冷蔵庫", "is_correct": false, "explanation": "冷蔵庫は食品を冷やす家電で、雨が降る場所にはならない。"}, {"text": "掃除機", "is_correct": false, "explanation": "掃除機はごみを吸う機械で、雨が降る場所を表さない。"}], "explanations": {"熱帯": "「熱帯では」は雨の多い気候の地域を指し、毎日雨が降る説明に合う。", "教科書": "教科書は学ぶための本で、雨が降る場所としては文が通らない。", "冷蔵庫": "冷蔵庫は食品を冷やす家電で、雨が降る場所にはならない。", "掃除機": "掃除機はごみを吸う機械で、雨が降る場所を表さない。"}, "sentence_index": 0, "correct_answer": "熱帯"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "優勝争いは熱帯が続いた。", "explanation": "ここは〈熱戦〉の意味。熱帯は地域の名前で、激しい試合の展開には使わない。"}, {"text": "彼は熱帯をもって、夢を語った。", "explanation": "ここは〈熱意〉の意味。熱帯は地域の名前で、ひたむきな気持ちは表せない。"}, {"text": "夏は熱帯が高く、冷房が欠かせない。", "explanation": "ここは〈気温〉の意味。熱帯は地域名で、その時の温度の高さは表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c087fde-8a23-4107-9fdc-2f977c77c827') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35629, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "熱帯", "is_correct": true, "explanation": "「熱帯の川」は雨の多い気候の地域にある川を指し、水の量が多い説明に合う。"}, {"text": "歌手", "is_correct": false, "explanation": "歌手は歌う人のことで、川を修飾する語としては意味が通らない。"}, {"text": "寝袋", "is_correct": false, "explanation": "寝袋は眠るための道具で、川の説明として文が成り立たない。"}, {"text": "天井", "is_correct": false, "explanation": "天井は部屋の上の面で、川を修飾する語として意味が通らない。"}], "explanations": {"熱帯": "「熱帯の川」は雨の多い気候の地域にある川を指し、水の量が多い説明に合う。", "歌手": "歌手は歌う人のことで、川を修飾する語としては意味が通らない。", "寝袋": "寝袋は眠るための道具で、川の説明として文が成り立たない。", "天井": "天井は部屋の上の面で、川を修飾する語として意味が通らない。"}, "sentence_index": 6, "correct_answer": "熱帯"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会議は熱帯が冷めず、夜まで続いた。", "explanation": "ここは〈熱気〉の意味。熱帯は地域の名前で、議論の盛り上がりは表せない。"}, {"text": "熱帯が変わると、木の葉の色も変わる。", "explanation": "ここは〈季節〉の意味。熱帯は地域を指す語で、季節の移り変わりには使わない。"}, {"text": "熱帯を止めると、お湯はさめていく。", "explanation": "ここは〈熱源〉の意味。熱帯は地域の名前で、熱を出すものを指す語ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c087fde-8a23-4107-9fdc-2f977c77c827') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35629, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "熱帯を、一年中温かい空気が流れる地域だ。", "corrected_sentence": "熱帯は、一年中温かい空気が流れる地域だ。", "error_description": "「地域だ」の主題を示すのは「は」。「を」は目的語の形で、ここでは誤り（正しくは「は」）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c087fde-8a23-4107-9fdc-2f977c77c827') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35629, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "熱帯を発生した雨雲が、日本まで流れてくる。", "corrected_sentence": "熱帯で発生した雨雲が、日本まで流れてくる。", "error_description": "「熱帯を発生した」は誤り。「発生する」は目的語の「を」を取らないので、場所を示す「で」にする（正しくは「で」）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c087fde-8a23-4107-9fdc-2f977c77c827') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35630, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「変える」は対象に「を」をとる。「位置を変えるだけで」が正しい。"}, {"text": "に", "is_correct": false, "explanation": "「変える」の対象には「に」は使えず、「位置に変える」では文が成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すので、変える対象にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、変える対象としては使えない。"}], "correct_answer": "を", "explanations": {"を": "「変える」は対象に「を」をとる。「位置を変えるだけで」が正しい。", "に": "「変える」の対象には「に」は使えず、「位置に変える」では文が成り立たない。", "が": "「が」は主語を示すので、変える対象にはならない。", "へ": "「へ」は方向を示すので、変える対象としては使えない。"}, "error_tags": {"に": "change_target", "が": "subject_marker", "へ": "direction"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ea9fa82-6a8e-445f-8c7b-21bcfdb23706') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35630, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「決める」の対象は「を」で示す。「位置を決める前に」が正しい。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すので、「決める」の対象にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、決める対象としては使えない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示し、「決める」の対象にはならない。"}], "correct_answer": "を", "explanations": {"を": "「決める」の対象は「を」で示す。「位置を決める前に」が正しい。", "が": "「が」は主語を示すので、「決める」の対象にはならない。", "へ": "「へ」は方向を示すので、決める対象としては使えない。", "と": "「と」は並列や相手を示し、「決める」の対象にはならない。"}, "error_tags": {"が": "subject_marker", "へ": "direction", "と": "coordinate"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ea9fa82-6a8e-445f-8c7b-21bcfdb23706') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35630, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かがある場所を表す言葉です。", "primary_collocate": null, "pronunciation": "いち", "ipa": "itɕi", "syllable_count": 2, "sentences": [{"text": "地図に、学校の位置が赤い丸で示されている。", "target_word": "位置", "complexity_tier": "T2", "furigana": "地図(ちず)に、学校(がっこう)の位置(いち)が赤(あか)い丸(まる)で示(しめ)されている。", "sentence_source": "generated"}, {"text": "家具の位置を変えるだけで、部屋の印象が大きく変わった。", "target_word": "位置", "complexity_tier": "T3", "furigana": "家具(かぐ)の位置(いち)を変(か)えるだけで、部屋(へや)の印象(いんしょう)が大(おお)きく変(か)わった。", "sentence_source": "generated"}, {"text": "星は毎晩、少しずつ位置が変わって見える。", "target_word": "位置", "complexity_tier": "T3", "furigana": "星(ほし)は毎晩(まいばん)、少(すこ)しずつ位置(いち)が変(か)わって見(み)える。", "sentence_source": "generated"}, {"text": "宝物が埋められた位置を、古い地図から読み取った。", "target_word": "位置", "complexity_tier": "T4", "furigana": "宝物(たからもの)が埋(う)められた位置(いち)を、古(ふる)い地図(ちず)から読(よ)み取(と)った。", "sentence_source": "generated"}, {"text": "トイレの位置がわからなくて、駅員に聞いた。", "target_word": "位置", "complexity_tier": "T2", "furigana": "トイレの位置(いち)がわからなくて、駅員(えきいん)に聞(き)いた。", "sentence_source": "generated"}, {"text": "文字を入れたい位置にカーソルを合わせた。", "target_word": "位置", "complexity_tier": "T3", "furigana": "文字(もじ)を入(い)れたい位置(いち)にカーソルを合(あ)わせた。", "sentence_source": "generated"}, {"text": "公園は高い位置にあるので、町全体がよく見渡せる。", "target_word": "位置", "complexity_tier": "T3", "furigana": "公園(こうえん)は高(たか)い位置(いち)にあるので、町(まち)全体(ぜんたい)がよく見渡(みわた)せる。", "sentence_source": "generated"}, {"text": "ピアノの位置を決める前に、部屋の広さを測った。", "target_word": "位置", "complexity_tier": "T3", "furigana": "ピアノの位置(いち)を決(き)める前(まえ)に、部屋(へや)の広(ひろ)さを測(はか)った。", "sentence_source": "generated"}, {"text": "痛む位置を医者に指で示した。", "target_word": "位置", "complexity_tier": "T3", "furigana": "痛(いた)む位置(いち)を医者(いしゃ)に指(ゆび)で示(しめ)した。", "sentence_source": "generated"}, {"text": "地震の震源の位置は、海の底の深いところだと発表された。", "target_word": "位置", "complexity_tier": "T4", "furigana": "地震(じしん)の震源(しんげん)の位置(いち)は、海(うみ)の底(そこ)の深(ふか)いところだと発表(はっぴょう)された。", "sentence_source": "generated"}], "morphological_forms": [{"form": "位置する", "label": "サ変動詞"}, {"form": "位置づける", "label": "複合動詞"}, {"form": "位置づけ", "label": "名詞形"}], "register": "neutral", "sense_fingerprint": "何かがある地点・ありかを表す場所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '32b69eeb-98c8-40d8-b5f5-d42b8a81ba55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35630, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "位置", "is_correct": true, "explanation": "学校の所在を示す文脈に合い、「位置が示される」と自然につながる。"}, {"text": "天気", "is_correct": false, "explanation": "天気は地図に示す対象にはならず、学校の所在と合わない。"}, {"text": "人数", "is_correct": false, "explanation": "人数は地図上で赤い丸で示す対象として文脈に合わない。"}, {"text": "年齢", "is_correct": false, "explanation": "学校に年齢は当てはまらず、地図上の示し方と合わない。"}], "explanations": {"位置": "学校の所在を示す文脈に合い、「位置が示される」と自然につながる。", "天気": "天気は地図に示す対象にはならず、学校の所在と合わない。", "人数": "人数は地図上で赤い丸で示す対象として文脈に合わない。", "年齢": "学校に年齢は当てはまらず、地図上の示し方と合わない。"}, "sentence_index": 0, "correct_answer": "位置"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女の位置はとても穏やかで、みんなに慕われている。", "explanation": "ここは〈性格〉の意味。位置は所在を指すので、人の気質を表す語としては使わない。"}, {"text": "宿題の位置は、来週の月曜日までだ。", "explanation": "ここは〈期限〉の意味。位置は時間の区切りを表さないので、提出の締め切りには使わない。"}, {"text": "この料理は、塩の位置が強すぎる。", "explanation": "ここは〈味〉の意味。位置は味の濃さを表さないので、塩味の強さには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ea9fa82-6a8e-445f-8c7b-21bcfdb23706') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35630, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "位置", "is_correct": true, "explanation": "「高い位置にある」は場所の高さを表し、文に合う。"}, {"text": "天気", "is_correct": false, "explanation": "「高い天気にある」は成り立たず、公園の所在を示す文脈に合わない。"}, {"text": "気温", "is_correct": false, "explanation": "「高い気温にある」は成り立たず、場所を表す文脈と合わない。"}, {"text": "体重", "is_correct": false, "explanation": "「高い体重にある」は意味が通らず、公園の位置とは合わない。"}], "explanations": {"位置": "「高い位置にある」は場所の高さを表し、文に合う。", "天気": "「高い天気にある」は成り立たず、公園の所在を示す文脈に合わない。", "気温": "「高い気温にある」は成り立たず、場所を表す文脈と合わない。", "体重": "「高い体重にある」は意味が通らず、公園の位置とは合わない。"}, "sentence_index": 6, "correct_answer": "位置"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このアイドルは、今年の人気の位置が急上昇した。", "explanation": "ここは〈人気〉の意味。位置は場所や所在を指すので、評判の高さには使わない。"}, {"text": "このパンは位置がふわふわで、とても食べやすい。", "explanation": "ここは〈食感〉の意味。位置は所在を表すので、食べ物のやわらかさには使えない。"}, {"text": "この作業は、位置がかかって大変だ。", "explanation": "ここは〈手間〉の意味。位置は手間の多さを表さないので、「手間がかかる」の代わりにはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ea9fa82-6a8e-445f-8c7b-21bcfdb23706') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35630, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ポスターは、目立つ位置が貼ってください。", "corrected_sentence": "ポスターは、目立つ位置に貼ってください。", "error_description": "誤りは「位置が」。「貼る」の場所は「に」で示し、「が」は主語を示すので、ここでは文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ea9fa82-6a8e-445f-8c7b-21bcfdb23706') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35630, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は人混みの中で友達の位置が見つけた。", "corrected_sentence": "彼は人混みの中で友達の位置を見つけた。", "error_description": "誤りは「位置が」。「見つける」の目的語には「を」が必要で、「が」は主語を示すため文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ea9fa82-6a8e-445f-8c7b-21bcfdb23706') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35631, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「確かめる」は対象に「を」をとる。「位置を確かめて」が正しい。"}, {"text": "に", "is_correct": false, "explanation": "「に」は対象を示すが、「確かめる」の目的語は「を」が必要で、「位置に確かめて」は成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すので、確かめる対象にはならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、確かめる対象としては使えない。"}], "correct_answer": "を", "explanations": {"を": "「確かめる」は対象に「を」をとる。「位置を確かめて」が正しい。", "に": "「に」は対象を示すが、「確かめる」の目的語は「を」が必要で、「位置に確かめて」は成り立たない。", "が": "「が」は主語を示すので、確かめる対象にはならない。", "へ": "「へ」は方向を示すので、確かめる対象としては使えない。"}, "error_tags": {"に": "target_marker", "が": "subject_marker", "へ": "direction"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ea9fa82-6a8e-445f-8c7b-21bcfdb23706') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35631, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ea9fa82-6a8e-445f-8c7b-21bcfdb23706') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35631, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物や人が存在する場所や、ある場所にあることを示す言葉です。", "primary_collocate": null, "pronunciation": "いち", "ipa": "itɕi", "syllable_count": 2, "sentences": [{"text": "この店は、駅から見て便利な位置にある。", "target_word": "位置", "complexity_tier": "T2", "furigana": "この店(みせ)は、駅(えき)から見(み)て便利(べんり)な位置(いち)にある。", "sentence_source": "generated"}, {"text": "地図で自分のいる位置を確かめてから、駅へ歩き出した。", "target_word": "位置", "complexity_tier": "T3", "furigana": "地図(ちず)で自分(じぶん)のいる位置(いち)を確(たし)かめてから、駅(えき)へ歩(ある)き出(だ)した。", "sentence_source": "generated"}, {"text": "このカメラは、窓に近い位置に置くと、明るい写真が撮れる。", "target_word": "位置", "complexity_tier": "T3", "furigana": "このカメラは、窓(まど)に近(ちか)い位置(いち)に置(お)くと、明(あか)るい写真(しゃしん)が撮(と)れる。", "sentence_source": "generated"}, {"text": "先生は、生徒全員の顔が見える位置に立って話した。", "target_word": "位置", "complexity_tier": "T3", "furigana": "先生(せんせい)は、生徒(せいと)全員(ぜんいん)の顔(かお)が見(み)える位置(いち)に立(た)って話(はな)した。", "sentence_source": "generated"}, {"text": "地震のあと、棚の位置がずれていたので、もとに戻した。", "target_word": "位置", "complexity_tier": "T3", "furigana": "地震(じしん)のあと、棚(たな)の位置(いち)がずれていたので、もとに戻(もど)した。", "sentence_source": "generated"}, {"text": "船は嵐のせいで、予定の位置から大きく流されてしまった。", "target_word": "位置", "complexity_tier": "T4", "furigana": "船(ふね)は嵐(あらし)のせいで、予定(よてい)の位置(いち)から大(おお)きく流(なが)されてしまった。", "sentence_source": "generated"}, {"text": "スマートフォンの地図アプリで、友達の現在の位置を知ることができる。", "target_word": "位置", "complexity_tier": "T3", "furigana": "スマートフォンの地図(ちず)アプリで、友達(ともだち)の現在(げんざい)の位置(いち)を知(し)ることができる。", "sentence_source": "generated"}, {"text": "私の席は教室の後ろにあり、黒板からは遠い位置だ。", "target_word": "位置", "complexity_tier": "T2", "furigana": "私(わたし)の席(せき)は教室(きょうしつ)の後(うし)ろにあり、黒板(こくばん)からは遠(とお)い位置(いち)だ。", "sentence_source": "generated"}, {"text": "火事のとき、非常口の位置を前もって知っておくことが大切だ。", "target_word": "位置", "complexity_tier": "T4", "furigana": "火事(かじ)のとき、非常口(ひじょうぐち)の位置(いち)を前(まえ)もって知(し)っておくことが大切(たいせつ)だ。", "sentence_source": "generated"}, {"text": "ゴールキーパーは、ボールの動きに合わせて立つ位置を変えた。", "target_word": "位置", "complexity_tier": "T3", "furigana": "ゴールキーパーは、ボールの動(うご)きに合(あ)わせて立(た)つ位置(いち)を変(か)えた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "位置する", "label": "サ変動詞"}, {"form": "位置づける", "label": "複合動詞"}, {"form": "位置づけ", "label": "名詞形"}], "register": "neutral", "sense_fingerprint": "物や人がどこにあるかを示す場所・ありか", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '32b69eeb-98c8-40d8-b5f5-d42b8a81ba55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35631, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "位置", "is_correct": true, "explanation": "「便利な位置にある」は店の所在を表し、文の流れに合う。"}, {"text": "天気", "is_correct": false, "explanation": "「便利な天気にある」は成り立たず、所在を示す文脈に合わない。"}, {"text": "年齢", "is_correct": false, "explanation": "「便利な年齢にある」は意味が通らず、店の場所とは合わない。"}, {"text": "音量", "is_correct": false, "explanation": "「便利な音量にある」は成り立たず、場所を表す文脈と合わない。"}], "explanations": {"位置": "「便利な位置にある」は店の所在を表し、文の流れに合う。", "天気": "「便利な天気にある」は成り立たず、所在を示す文脈に合わない。", "年齢": "「便利な年齢にある」は意味が通らず、店の場所とは合わない。", "音量": "「便利な音量にある」は成り立たず、場所を表す文脈と合わない。"}, "sentence_index": 0, "correct_answer": "位置"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "来週の発表会の位置は、市民ホールに決まった。", "explanation": "ここは〈会場〉の意味。位置は物や人の所在を指すので、催しを行う会場には使わない。"}, {"text": "試合の途中で、チームの位置が三点増えた。", "explanation": "ここは〈得点〉の意味。位置は場所を指すので、試合の点数が増えることは表せない。"}, {"text": "会議の位置は、午後三時からです。", "explanation": "ここは〈時刻〉の意味。位置は時間の区切りを表さないので、開始時間には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ea9fa82-6a8e-445f-8c7b-21bcfdb23706') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35631, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "位置", "is_correct": true, "explanation": "「現在の位置」は地図アプリで相手の居場所を表すので、文に合う。"}, {"text": "音程", "is_correct": false, "explanation": "音程は音の高さを表し、友達の居場所を知る文脈とは合わない。"}, {"text": "気温", "is_correct": false, "explanation": "気温は気象の数値で、友達の居場所を知る文脈とは合わない。"}, {"text": "音量", "is_correct": false, "explanation": "音量は音の大きさを表し、居場所の情報とは別の内容になる。"}], "explanations": {"位置": "「現在の位置」は地図アプリで相手の居場所を表すので、文に合う。", "音程": "音程は音の高さを表し、友達の居場所を知る文脈とは合わない。", "気温": "気温は気象の数値で、友達の居場所を知る文脈とは合わない。", "音量": "音量は音の大きさを表し、居場所の情報とは別の内容になる。"}, "sentence_index": 6, "correct_answer": "位置"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この製品は位置が高く、長く使える。", "explanation": "ここは〈水準〉の意味。位置は所在を指す語なので、品質の高さの評価には使わない。"}, {"text": "この雑誌は読者の位置が若い年代に広がっている。", "explanation": "ここは〈年齢層〉の意味。位置は人の属性や世代を表さないので、読者層には使わない。"}, {"text": "彼は試験の前に、気分の位置を整えた。", "explanation": "ここは〈気持ち〉の意味。位置は心の状態を指さないので、「気分を整える」の代わりにはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ea9fa82-6a8e-445f-8c7b-21bcfdb23706') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35631, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この家具は、直射日光が当たらない位置が置いてください。", "corrected_sentence": "この家具は、直射日光が当たらない位置に置いてください。", "error_description": "誤りは「位置が」。「置く」の置き場所は「に」で示し、「が」は主語を示すので、ここでは文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ea9fa82-6a8e-445f-8c7b-21bcfdb23706') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35631, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "私の席は、黒板から遠い位置へある。", "corrected_sentence": "私の席は、黒板から遠い位置にある。", "error_description": "誤りは「位置へ」。存在を表す「ある」の場所は「に」で示す。「へ」は移動の方向を示すので、ここでは合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ea9fa82-6a8e-445f-8c7b-21bcfdb23706') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35632, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "少数", "is_correct": true, "explanation": "対義語。「多数」の反対は「少数」。"}, {"text": "単独", "is_correct": false, "explanation": "ひとりだけ、ひとつだけという意味で、数の反対語ではない。"}, {"text": "平均", "is_correct": false, "explanation": "ならした値を表す語で、数の多さの対義語ではない。"}, {"text": "最低", "is_correct": false, "explanation": "程度の下限を表す語で、「多数」の対義語ではない。"}], "correct_answer": "少数", "explanations": {"少数": "対義語。「多数」の反対は「少数」。", "単独": "ひとりだけ、ひとつだけという意味で、数の反対語ではない。", "平均": "ならした値を表す語で、数の多さの対義語ではない。", "最低": "程度の下限を表す語で、「多数」の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33441540-5e68-48c9-ab4d-7372add938d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35632, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "少数", "is_correct": true, "explanation": "対義語。「多数」の反対は「少数」。"}, {"text": "余剰", "is_correct": false, "explanation": "使い残しの余り。数の多さの対義語ではない。"}, {"text": "水準", "is_correct": false, "explanation": "基準となる程度のこと。対義語ではない。"}, {"text": "平常", "is_correct": false, "explanation": "いつもの普通の状態のこと。数の反対語ではない。"}], "correct_answer": "少数", "explanations": {"少数": "対義語。「多数」の反対は「少数」。", "余剰": "使い残しの余り。数の多さの対義語ではない。", "水準": "基準となる程度のこと。対義語ではない。", "平常": "いつもの普通の状態のこと。数の反対語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33441540-5e68-48c9-ab4d-7372add938d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35632, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "たくさんあること", "primary_collocate": null, "pronunciation": "たすう", "ipa": "tasɯː", "syllable_count": 3, "sentences": [{"text": "会場には多数の人が集まり、入り口まで列ができていた。", "target_word": "多数", "complexity_tier": "T3", "furigana": "会場[かいじょう]には多数[たすう]の人[ひと]が集[あつ]まり、入[い]り口[ぐち]まで列[れつ]ができていた。", "sentence_source": "generated"}, {"text": "この図書館には、古い本が多数ある。", "target_word": "多数", "complexity_tier": "T3", "furigana": "この図書館[としょかん]には、古[ふる]い本[ほん]が多数[たすう]ある。", "sentence_source": "generated"}, {"text": "事故の原因について、多数の意見が出された。", "target_word": "多数", "complexity_tier": "T3", "furigana": "事故[じこ]の原因[げんいん]について、多数[たすう]の意見[いけん]が出[だ]された。", "sentence_source": "generated"}, {"text": "駅の近くに多数の店が並んでいて、買い物に便利だ。", "target_word": "多数", "complexity_tier": "T3", "furigana": "駅[えき]の近[ちか]くに多数[たすう]の店[みせ]が並[なら]んでいて、買[か]い物[もの]に便利[べんり]だ。", "sentence_source": "generated"}, {"text": "春になると、公園に多数の鳥が来る。", "target_word": "多数", "complexity_tier": "T3", "furigana": "春[はる]になると、公園[こうえん]に多数[たすう]の鳥[とり]が来[く]る。", "sentence_source": "generated"}, {"text": "講演会の後、多数の質問が寄せられたので、時間が足りなくなった。", "target_word": "多数", "complexity_tier": "T3", "furigana": "講演会[こうえんかい]の後[あと]、多数[たすう]の質問[しつもん]が寄[よ]せられたので、時間[じかん]が足[た]りなくなった。", "sentence_source": "generated"}, {"text": "その博物館には、世界中から集めた多数の絵が飾られている。", "target_word": "多数", "complexity_tier": "T3", "furigana": "その博物館[はくぶつかん]には、世界中[せかいじゅう]から集[あつ]めた多数[たすう]の絵[え]が飾[かざ]られている。", "sentence_source": "generated"}, {"text": "昨夜の雨で、道に多数の落ち葉が散らばった。", "target_word": "多数", "complexity_tier": "T3", "furigana": "昨夜[さくや]の雨[あめ]で、道[みち]に多数[たすう]の落[お]ち葉[ば]が散[ち]らばった。", "sentence_source": "generated"}, {"text": "応募者が多数いたため、選ぶのに時間がかかった。", "target_word": "多数", "complexity_tier": "T3", "furigana": "応募者[おうぼしゃ]が多数[たすう]いたため、選[えら]ぶのに時間[じかん]がかかった。", "sentence_source": "generated"}, {"text": "海岸で多数の貝がらを拾って、家に持って帰った。", "target_word": "多数", "complexity_tier": "T3", "furigana": "海岸[かいがん]で多数[たすう]の貝[かい]がらを拾[ひろ]って、家[いえ]に持[も]って帰[かえ]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "多数", "label": "基本形"}, {"form": "多数の", "label": "連体修飾(の)"}, {"form": "多数を", "label": "を格"}], "register": "neutral (plain form)", "sense_fingerprint": "物や人がたくさんある・いるという量の多さを表す「多数」(多数の〜、〜が多数ある)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T2: contains vocabulary far above tier T2: 貝がら (Zipf 1.93)']::text[], '07e99574-5a76-414c-a8d8-98dc1fc98f23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35632, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "多数", "is_correct": true, "explanation": "「多数の人」は人の数が多いという意味で、ここに自然に入る。"}, {"text": "機会", "is_correct": false, "explanation": "機会は好機のこと。「機会の人」とは言えず、人の数の多さを表せない。"}, {"text": "役割", "is_correct": false, "explanation": "役割は担当する任務のこと。「役割の人」は成り立たず、数を表せない。"}, {"text": "方針", "is_correct": false, "explanation": "方針は計画の方向性のこと。「方針の人」は成り立たない。"}], "explanations": {"多数": "「多数の人」は人の数が多いという意味で、ここに自然に入る。", "機会": "機会は好機のこと。「機会の人」とは言えず、人の数の多さを表せない。", "役割": "役割は担当する任務のこと。「役割の人」は成り立たず、数を表せない。", "方針": "方針は計画の方向性のこと。「方針の人」は成り立たない。"}, "sentence_index": 0, "correct_answer": "多数"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は貯金が多数あるので、お金の心配はない。", "explanation": "ここは〈多額〉の意味。お金の額の大きさは「多額」で言い、個数を表す「多数」は使わない。"}, {"text": "台風で多数の雨が降り、川が増水した。", "explanation": "ここは〈大量〉の意味。雨のように量で捉えるものには「大量」を使い、「多数」は個数に使う。"}, {"text": "出血が多数だったため、すぐに病院へ行った。", "explanation": "ここは〈多量〉の意味。液体の量を言う場面で、個数を表す「多数」は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33441540-5e68-48c9-ab4d-7372add938d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35632, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "多数", "is_correct": true, "explanation": "「世界中から集めた多数の絵」で、数の多さを表し文に合う。"}, {"text": "予算", "is_correct": false, "explanation": "使える金額のこと。「予算の絵」とは言わず、数を表せない。"}, {"text": "規則", "is_correct": false, "explanation": "決まりのこと。「規則の絵」は成り立たない。"}, {"text": "作法", "is_correct": false, "explanation": "礼儀の仕方のこと。「作法の絵」は成り立たない。"}], "explanations": {"多数": "「世界中から集めた多数の絵」で、数の多さを表し文に合う。", "予算": "使える金額のこと。「予算の絵」とは言わず、数を表せない。", "規則": "決まりのこと。「規則の絵」は成り立たない。", "作法": "礼儀の仕方のこと。「作法の絵」は成り立たない。"}, "sentence_index": 6, "correct_answer": "多数"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この地域は水資源が多数で、農業が盛んだ。", "explanation": "ここは〈豊富〉の意味。水資源のように量で捉えるものには「豊富」を使い、「多数」は個数に使う。"}, {"text": "この炉からは多数の熱が放出される。", "explanation": "ここは〈莫大〉の意味。熱のような量には「莫大」を使い、数えられない量に「多数」は不自然。"}, {"text": "工場では多数の燃料を消費する。", "explanation": "ここは〈膨大〉の意味。燃料のような量は「膨大」で表し、数えられない物に「多数」は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33441540-5e68-48c9-ab4d-7372add938d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35632, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その大学には、多数な留学生がいる。", "corrected_sentence": "その大学には、多数の留学生がいる。", "error_description": "誤りは「多数な」。「多数」は名詞なので、名詞を修飾するには「多数の」を使う。「多数な」は形容動詞の語尾で、成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33441540-5e68-48c9-ab4d-7372add938d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35632, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "台風の後、庭に多数を枝が落ちていた。", "corrected_sentence": "台風の後、庭に多数の枝が落ちていた。", "error_description": "誤りは「多数を」の助詞。「多数」の後は「の」で連体修飾にする。「を」を続けると「多数を枝」となり、文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33441540-5e68-48c9-ab4d-7372add938d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35633, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「多数の国民」の「の」。「多数」が後ろの「国民」を修飾する連体修飾で、文に合う。"}, {"text": "を", "is_correct": false, "explanation": "目的格の「を」。「多数を国民が」では名詞同士がつながらず、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "位置・相手の「に」。「多数に国民が」では修飾関係が作れず、文に合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」。「多数へ国民が」は成り立たず、ここには入らない。"}], "correct_answer": "の", "explanations": {"の": "「多数の国民」の「の」。「多数」が後ろの「国民」を修飾する連体修飾で、文に合う。", "を": "目的格の「を」。「多数を国民が」では名詞同士がつながらず、文が成り立たない。", "に": "位置・相手の「に」。「多数に国民が」では修飾関係が作れず、文に合わない。", "へ": "方向の「へ」。「多数へ国民が」は成り立たず、ここには入らない。"}, "error_tags": {"を": "目的格（動詞の目的語）", "に": "位置・相手", "へ": "方向"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "少数", "is_correct": true, "explanation": "対義語。「多数」の反対は「少数」で、割合の多い少ないの反対。"}, {"text": "平均", "is_correct": false, "explanation": "ならした値を表す語で、割合の反対語ではない。"}, {"text": "解答", "is_correct": false, "explanation": "問題に対する答えのこと。対義語ではない。"}, {"text": "所在", "is_correct": false, "explanation": "ある場所がどこにあるかを表す語。対義語ではない。"}], "correct_answer": "少数", "explanations": {"少数": "対義語。「多数」の反対は「少数」で、割合の多い少ないの反対。", "平均": "ならした値を表す語で、割合の反対語ではない。", "解答": "問題に対する答えのこと。対義語ではない。", "所在": "ある場所がどこにあるかを表す語。対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33441540-5e68-48c9-ab4d-7372add938d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35633, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "主格の「が」。「町の人の多数が賛成した」で、多数が賛成する主語になる。"}, {"text": "を", "is_correct": false, "explanation": "目的格の「を」。「多数を賛成した」では目的語が不自然で、文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "並列・相手の「と」。「多数と賛成した」では主語の位置に合わず、文の意味が変わる。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」。「多数へ賛成した」は成り立たず、文に合わない。"}], "correct_answer": "が", "explanations": {"が": "主格の「が」。「町の人の多数が賛成した」で、多数が賛成する主語になる。", "を": "目的格の「を」。「多数を賛成した」では目的語が不自然で、文が成り立たない。", "と": "並列・相手の「と」。「多数と賛成した」では主語の位置に合わず、文の意味が変わる。", "へ": "方向の「へ」。「多数へ賛成した」は成り立たず、文に合わない。"}, "error_tags": {"を": "目的格（動詞の目的語）", "と": "並列・相手", "へ": "方向"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "少数", "is_correct": true, "explanation": "対義語。「多数」の反対は「少数」。"}, {"text": "平常", "is_correct": false, "explanation": "いつもの普通の状態のこと。対義語ではない。"}, {"text": "水準", "is_correct": false, "explanation": "基準となる程度のこと。対義語ではない。"}, {"text": "余剰", "is_correct": false, "explanation": "使い残しの余り。対義語ではない。"}], "correct_answer": "少数", "explanations": {"少数": "対義語。「多数」の反対は「少数」。", "平常": "いつもの普通の状態のこと。対義語ではない。", "水準": "基準となる程度のこと。対義語ではない。", "余剰": "使い残しの余り。対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33441540-5e68-48c9-ab4d-7372add938d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35633, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "全体の中で人や物が大部分を占めていること。", "primary_collocate": null, "pronunciation": "たすう", "ipa": "tasɯː", "syllable_count": 3, "sentences": [{"text": "会議では、賛成する人が多数を占めた。", "target_word": "多数", "complexity_tier": "T3", "furigana": "会議[かいぎ]では、賛成[さんせい]する人[ひと]が多数[たすう]を占[し]めた。", "sentence_source": "generated"}, {"text": "多数の国民が、その新しい法律に反対している。", "target_word": "多数", "complexity_tier": "T3", "furigana": "多数[たすう]の国民[こくみん]が、その新[あたら]しい法律[ほうりつ]に反対[はんたい]している。", "sentence_source": "generated"}, {"text": "クラスの多数は、遠足を来月にしたいと考えている。", "target_word": "多数", "complexity_tier": "T3", "furigana": "クラスの多数[たすう]は、遠足[えんそく]を来月[らいげつ]にしたいと考[かんが]えている。", "sentence_source": "generated"}, {"text": "調査によると、若者の多数がスマホで地図を見ている。", "target_word": "多数", "complexity_tier": "T3", "furigana": "調査[ちょうさ]によると、若者[わかもの]の多数[たすう]がスマホで地図[ちず]を見[み]ている。", "sentence_source": "generated"}, {"text": "この地域では、お年寄りが多数を占めている。", "target_word": "多数", "complexity_tier": "T3", "furigana": "この地域[ちいき]では、お年寄[としよ]りが多数[たすう]を占[し]めている。", "sentence_source": "generated"}, {"text": "観客の多数が見守る中、選手はゴールを決めた。", "target_word": "多数", "complexity_tier": "T3", "furigana": "観客[かんきゃく]の多数[たすう]が見守[みまも]る中[なか]、選手[せんしゅ]はゴールを決[き]めた。", "sentence_source": "generated"}, {"text": "小さな村に観光客の多数が訪れて、宿が足りなくなった。", "target_word": "多数", "complexity_tier": "T3", "furigana": "小[ちい]さな村[むら]に観光客[かんこうきゃく]の多数[たすう]が訪[おとず]れて、宿[やど]が足[た]りなくなった。", "sentence_source": "generated"}, {"text": "町の人の多数が、新しい橋の建設に賛成した。", "target_word": "多数", "complexity_tier": "T3", "furigana": "町[まち]の人[ひと]の多数[たすう]が、新[あたら]しい橋[はし]の建設[けんせつ]に賛成[さんせい]した。", "sentence_source": "generated"}, {"text": "参加者の多数は学生で、社会人は少なかった。", "target_word": "多数", "complexity_tier": "T3", "furigana": "参加者[さんかしゃ]の多数[たすう]は学生[がくせい]で、社会人[しゃかいじん]は少[すく]なかった。", "sentence_source": "generated"}, {"text": "台風の影響で、電車の多数が止まってしまった。", "target_word": "多数", "complexity_tier": "T3", "furigana": "台風[たいふう]の影響[えいきょう]で、電車[でんしゃ]の多数[たすう]が止[と]まってしまった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "多数", "label": "基本形"}, {"form": "多数の", "label": "連体修飾(の)"}, {"form": "多数を", "label": "を格"}, {"form": "多数は", "label": "は格"}], "register": "neutral (plain form)", "sense_fingerprint": "全体の中で人や物の数が多いこと、多くを占めること(多数を占める、〜の多数)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07e99574-5a76-414c-a8d8-98dc1fc98f23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35633, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "多数", "is_correct": true, "explanation": "「賛成する人が多数を占めた」は、大半を占めたという意味で文に合う。"}, {"text": "規則", "is_correct": false, "explanation": "決まりのこと。「規則を占めた」とは言わず、文が成り立たない。"}, {"text": "手順", "is_correct": false, "explanation": "作業の順序のこと。「手順を占めた」は不自然で、ここには入らない。"}, {"text": "理由", "is_correct": false, "explanation": "わけのこと。「理由を占めた」は成り立たない。"}], "explanations": {"多数": "「賛成する人が多数を占めた」は、大半を占めたという意味で文に合う。", "規則": "決まりのこと。「規則を占めた」とは言わず、文が成り立たない。", "手順": "作業の順序のこと。「手順を占めた」は不自然で、ここには入らない。", "理由": "わけのこと。「理由を占めた」は成り立たない。"}, "sentence_index": 0, "correct_answer": "多数"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雨の多数は夜に降った。", "explanation": "ここは〈大半〉の意味。雨のように数えられないものの大部分は「大半」で言い、「多数」は人や物の数に使う。"}, {"text": "作業の多数は終わった。", "explanation": "ここは〈大部分〉の意味。作業の大部分が済んだという言い方で、「多数」は数えられる人や物に使う。"}, {"text": "話の多数は理解できた。", "explanation": "ここは〈大筋〉の意味。話の要点を大まかに捉える言い方で、「多数」は話の内容には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33441540-5e68-48c9-ab4d-7372add938d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35633, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "多数", "is_correct": true, "explanation": "「小さな村に観光客の多数が訪れて」で、観光客の大半が訪れたという意味に合う。"}, {"text": "季節", "is_correct": false, "explanation": "季節のこと。「観光客の季節が訪れて」は成り立たない。"}, {"text": "手紙", "is_correct": false, "explanation": "文書のこと。「観光客の手紙が訪れて」は成り立たない。"}, {"text": "機嫌", "is_correct": false, "explanation": "気分のこと。「観光客の機嫌が訪れて」は成り立たない。"}], "explanations": {"多数": "「小さな村に観光客の多数が訪れて」で、観光客の大半が訪れたという意味に合う。", "季節": "季節のこと。「観光客の季節が訪れて」は成り立たない。", "手紙": "文書のこと。「観光客の手紙が訪れて」は成り立たない。", "機嫌": "気分のこと。「観光客の機嫌が訪れて」は成り立たない。"}, "sentence_index": 6, "correct_answer": "多数"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この土地に降った水の多数は、地下に染み込む。", "explanation": "ここは〈過半〉の意味。水の割合が半分を超えることは「過半」で言い、「多数」は人や物の数に使う。"}, {"text": "準備は多数終わった。", "explanation": "ここは〈大方〉の意味。準備がほぼ済んだという程度を表す語で、「多数」は合わない。"}, {"text": "燃料の多数を輸入している。", "explanation": "ここは〈半数〉の意味。燃料の割合が半分程度のことは「半数」で言い、「多数」では表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33441540-5e68-48c9-ab4d-7372add938d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35633, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "アンケートでは、ペットを飼う人が多数に占めた。", "corrected_sentence": "アンケートでは、ペットを飼う人が多数を占めた。", "error_description": "誤りは「多数に」の助詞。「占める」は目的語に「を」を取るので「多数を占めた」が正しい。「に」では動詞と結びつかない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33441540-5e68-48c9-ab4d-7372add938d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35633, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "このクラスでは、女子が多数を占めるている。", "corrected_sentence": "このクラスでは、女子が多数を占めている。", "error_description": "誤りは「占めるている」の動詞の活用。「占めている」が正しい形で、「占める」の後に「る」を挿入すると活用が崩れて成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33441540-5e68-48c9-ab4d-7372add938d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35634, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「マラソンの起点」の「の」。「マラソン」が「起点」を修飾する所属を表し、文に合う。"}, {"text": "を", "is_correct": false, "explanation": "目的格の「を」。「マラソンを起点は」では名詞同士がつながらず、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」。「マラソンへ起点は」では修飾関係が作れず、文に合わない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」。「マラソンより起点は」は比べる文にならず、ここには入らない。"}], "correct_answer": "の", "explanations": {"の": "「マラソンの起点」の「の」。「マラソン」が「起点」を修飾する所属を表し、文に合う。", "を": "目的格の「を」。「マラソンを起点は」では名詞同士がつながらず、文が成り立たない。", "へ": "方向の「へ」。「マラソンへ起点は」では修飾関係が作れず、文に合わない。", "より": "比較の「より」。「マラソンより起点は」は比べる文にならず、ここには入らない。"}, "error_tags": {"を": "目的格（動詞の目的語）", "へ": "方向", "より": "比較"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "終点", "is_correct": true, "explanation": "対義語。出発点（起点）の反対は終わりの地点（終点）。"}, {"text": "中心", "is_correct": false, "explanation": "真ん中の部分のこと。起点の反対語ではない。"}, {"text": "地点", "is_correct": false, "explanation": "場所の一つを表す語で、起点と対になる語ではない。"}, {"text": "所在", "is_correct": false, "explanation": "ある場所がどこにあるかを表す語。対義語ではない。"}], "correct_answer": "終点", "explanations": {"終点": "対義語。出発点（起点）の反対は終わりの地点（終点）。", "中心": "真ん中の部分のこと。起点の反対語ではない。", "地点": "場所の一つを表す語で、起点と対になる語ではない。", "所在": "ある場所がどこにあるかを表す語。対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33441540-5e68-48c9-ab4d-7372add938d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35634, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "「起点からの距離」の「から」。起点を基準とする距離を表し、文に合う。"}, {"text": "を", "is_correct": false, "explanation": "目的格の「を」。「起点を距離」では名詞同士がつながらず、文が成り立たない。"}, {"text": "が", "is_correct": false, "explanation": "主格の「が」。「起点が距離」では修飾関係が作れず、文に合わない。"}, {"text": "に", "is_correct": false, "explanation": "位置・相手の「に」。「起点に距離」では修飾関係が作れず、文に合わない。"}], "correct_answer": "から", "explanations": {"から": "「起点からの距離」の「から」。起点を基準とする距離を表し、文に合う。", "を": "目的格の「を」。「起点を距離」では名詞同士がつながらず、文が成り立たない。", "が": "主格の「が」。「起点が距離」では修飾関係が作れず、文に合わない。", "に": "位置・相手の「に」。「起点に距離」では修飾関係が作れず、文に合わない。"}, "error_tags": {"を": "目的格（動詞の目的語）", "が": "主格", "に": "位置・相手"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "終点", "is_correct": true, "explanation": "対義語。起点の反対は終点。"}, {"text": "天井", "is_correct": false, "explanation": "部屋の上面のこと。対義語ではない。"}, {"text": "玄関", "is_correct": false, "explanation": "建物の出入り口のこと。対義語ではない。"}, {"text": "布団", "is_correct": false, "explanation": "寝具のこと。対義語ではない。"}], "correct_answer": "終点", "explanations": {"終点": "対義語。起点の反対は終点。", "天井": "部屋の上面のこと。対義語ではない。", "玄関": "建物の出入り口のこと。対義語ではない。", "布団": "寝具のこと。対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33441540-5e68-48c9-ab4d-7372add938d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35634, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "道路・路線・行列などが始まる出発の場所のこと。", "primary_collocate": null, "pronunciation": "きてん", "ipa": "kiteɴ", "syllable_count": 3, "sentences": [{"text": "この道は、町の北にある駅を起点にして南へ続いている。", "target_word": "起点", "complexity_tier": "T3", "furigana": "この道[みち]は、町[まち]の北[きた]にある駅[えき]を起点[きてん]にして南[みなみ]へ続[つづ]いている。", "sentence_source": "generated"}, {"text": "マラソンの起点は市役所前で、午前九時に走り出す。", "target_word": "起点", "complexity_tier": "T3", "furigana": "マラソンの起点[きてん]は市役所前[しやくしょまえ]で、午前[ごぜん]九時[くじ]に走[はし]り出[だ]す。", "sentence_source": "generated"}, {"text": "旅行の計画は、まず起点と終点を決めることから始まる。", "target_word": "起点", "complexity_tier": "T3", "furigana": "旅行[りょこう]の計画[けいかく]は、まず起点[きてん]と終点[しゅうてん]を決[き]めることから始[はじ]まる。", "sentence_source": "generated"}, {"text": "バスの路線図を見ると、起点は駅の西口だと分かる。", "target_word": "起点", "complexity_tier": "T3", "furigana": "バスの路線図[ろせんず]を見[み]ると、起点[きてん]は駅[えき]の西口[にしぐち]だと分[わ]かる。", "sentence_source": "generated"}, {"text": "私たちは公園を起点に、川沿いの道を歩いた。", "target_word": "起点", "complexity_tier": "T3", "furigana": "私[わたし]たちは公園[こうえん]を起点[きてん]に、川沿[かわぞ]いの道[みち]を歩[ある]いた。", "sentence_source": "generated"}, {"text": "この線路は、東京を起点として北へ伸びている。", "target_word": "起点", "complexity_tier": "T3", "furigana": "この線路[せんろ]は、東京[とうきょう]を起点[きてん]として北[きた]へ伸[の]びている。", "sentence_source": "generated"}, {"text": "地図の上に、起点から終点までの道を赤い線で描いた。", "target_word": "起点", "complexity_tier": "T3", "furigana": "地図[ちず]の上[うえ]に、起点[きてん]から終点[しゅうてん]までの道[みち]を赤[あか]い線[せん]で描[えが]いた。", "sentence_source": "generated"}, {"text": "道路の工事では、起点からの距離をメートル単位で記録する。", "target_word": "起点", "complexity_tier": "T3", "furigana": "道路[どうろ]の工事[こうじ]では、起点[きてん]からの距離[きょり]をメートル単位[たんい]で記録[きろく]する。", "sentence_source": "generated"}, {"text": "祭りの行列は神社を起点に、商店街を通って進む。", "target_word": "起点", "complexity_tier": "T3", "furigana": "祭[まつ]りの行列[ぎょうれつ]は神社[じんじゃ]を起点[きてん]に、商店街[しょうてんがい]を通[とお]って進[すす]む。", "sentence_source": "generated"}, {"text": "登山道の起点には、小さな案内板が立っている。", "target_word": "起点", "complexity_tier": "T3", "furigana": "登山道[とざんどう]の起点[きてん]には、小[ちい]さな案内板[あんないばん]が立[た]っている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "起点", "label": "基本形"}, {"form": "起点に", "label": "に格"}, {"form": "起点として", "label": "として"}, {"form": "起点となる", "label": "となる"}], "register": "neutral (plain form)", "sense_fingerprint": "道・路線・行列・距離計測などが始まる出発の場所(〜を起点に、起点から終点まで)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07e99574-5a76-414c-a8d8-98dc1fc98f23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35634, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "起点", "is_correct": true, "explanation": "「町の北にある駅を起点にして南へ続く」は、出発地点として文に合う。"}, {"text": "材料", "is_correct": false, "explanation": "素材のこと。「材料にして南へ続く」は成り立たない。"}, {"text": "教室", "is_correct": false, "explanation": "授業を行う部屋のこと。道の出発地点とは結びつかない。"}, {"text": "天気", "is_correct": false, "explanation": "空模様のこと。「駅を天気にして南へ続く」は成り立たない。"}], "explanations": {"起点": "「町の北にある駅を起点にして南へ続く」は、出発地点として文に合う。", "材料": "素材のこと。「材料にして南へ続く」は成り立たない。", "教室": "授業を行う部屋のこと。道の出発地点とは結びつかない。", "天気": "空模様のこと。「駅を天気にして南へ続く」は成り立たない。"}, "sentence_index": 0, "correct_answer": "起点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この建物の起点は、正面の出口だ。", "explanation": "ここは〈出口〉の意味。人の出入りする所は「出口」で言い、物事の始まる場所を表す「起点」とは言わない。"}, {"text": "成績の起点は、点数で決まる。", "explanation": "ここは〈基準〉の意味。評価の目安を言うときは「基準」で、出発地点の「起点」とは別。"}, {"text": "この報告の起点は、結論の部分だ。", "explanation": "ここは〈要点〉の意味。話の中心になる部分は「要点」で言い、始まりを表す「起点」とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33441540-5e68-48c9-ab4d-7372add938d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35634, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "起点", "is_correct": true, "explanation": "「起点から終点までの道」は、道の出発地点を表し文に合う。"}, {"text": "季節", "is_correct": false, "explanation": "季のこと。「季節から終点までの道」は成り立たない。"}, {"text": "手紙", "is_correct": false, "explanation": "文書のこと。「手紙から終点までの道」は成り立たない。"}, {"text": "機嫌", "is_correct": false, "explanation": "気分のこと。「機嫌から終点までの道」は成り立たない。"}], "explanations": {"起点": "「起点から終点までの道」は、道の出発地点を表し文に合う。", "季節": "季のこと。「季節から終点までの道」は成り立たない。", "手紙": "文書のこと。「手紙から終点までの道」は成り立たない。", "機嫌": "気分のこと。「機嫌から終点までの道」は成り立たない。"}, "sentence_index": 6, "correct_answer": "起点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "このチームの起点は、三位の成績だ。", "explanation": "ここは〈順位〉の意味。成績の位置は「順位」で言い、物事の始まりを表す「起点」とは言わない。"}, {"text": "距離の起点はメートルだ。", "explanation": "ここは〈単位〉の意味。距離を測る尺度は「単位」で、「起点」は測り始めの場所を指すので合わない。"}, {"text": "この船の起点は、白く塗られた船体だ。", "explanation": "ここは〈外見〉の意味。見た目の特徴は「外見」で言い、出発地点の「起点」とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33441540-5e68-48c9-ab4d-7372add938d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35634, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この鉄道は、東京駅を起点を西へ伸びている。", "corrected_sentence": "この鉄道は、東京駅を起点に西へ伸びている。", "error_description": "誤りは「起点を」の助詞。「〜を起点に」と、起点には「に」で受けて「〜に伸びる」と続ける。「を」では動詞の目的語になり、文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33441540-5e68-48c9-ab4d-7372add938d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35634, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この路線の起点とな駅は、朝から混雑する。", "corrected_sentence": "この路線の起点となる駅は、朝から混雑する。", "error_description": "誤りは「とな」。「となる」の「る」が抜けている。「起点となる駅」の連体形「となる」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33441540-5e68-48c9-ab4d-7372add938d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35635, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "終点", "is_correct": true, "explanation": "「起点」の対義語。始まりの地点に対して、終わりの地点を表す。"}, {"text": "中心", "is_correct": false, "explanation": "「中心」は物事の真ん中を指す語で、始まりの反対の意味ではない。"}, {"text": "頂点", "is_correct": false, "explanation": "「頂点」は最も高い所や最高の段階を指し、始まりと対になる語ではない。"}, {"text": "手本", "is_correct": false, "explanation": "「手本」は見習うべき模範を指し、起点と対義の関係にはない。"}], "correct_answer": "終点", "explanations": {"終点": "「起点」の対義語。始まりの地点に対して、終わりの地点を表す。", "中心": "「中心」は物事の真ん中を指す語で、始まりの反対の意味ではない。", "頂点": "「頂点」は最も高い所や最高の段階を指し、始まりと対になる語ではない。", "手本": "「手本」は見習うべき模範を指し、起点と対義の関係にはない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33441540-5e68-48c9-ab4d-7372add938d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35635, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「今日を起点に」の形で、基準となる時点を示す。文の意味に合う。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を表すので、「起点で」では時点を基準にする意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "「起点と」だけでは文が続かず、「起点として」の形にする必要があるので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「起点へ」では始まりの時点を基準にする意味にならない。"}], "correct_answer": "に", "explanations": {"に": "「今日を起点に」の形で、基準となる時点を示す。文の意味に合う。", "で": "「で」は場所や手段を表すので、「起点で」では時点を基準にする意味が通らない。", "と": "「起点と」だけでは文が続かず、「起点として」の形にする必要があるので合わない。", "へ": "「へ」は方向を示すので、「起点へ」では始まりの時点を基準にする意味にならない。"}, "error_tags": {"で": "場所・手段", "と": "並列・引用", "へ": "方向"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "終点", "is_correct": true, "explanation": "「起点」の対義語。始まりの地点に対して、終わりの地点を表す。"}, {"text": "目標", "is_correct": false, "explanation": "「目標」は達成しようとする到達点で、始まりと対になる語ではない。"}, {"text": "核心", "is_correct": false, "explanation": "「核心」は物事の中心となる要点で、起点の対義語ではない。"}, {"text": "原動力", "is_correct": false, "explanation": "「原動力」は物事を動かす力を指し、起点とは対義の関係にない。"}], "correct_answer": "終点", "explanations": {"終点": "「起点」の対義語。始まりの地点に対して、終わりの地点を表す。", "目標": "「目標」は達成しようとする到達点で、始まりと対になる語ではない。", "核心": "「核心」は物事の中心となる要点で、起点の対義語ではない。", "原動力": "「原動力」は物事を動かす力を指し、起点とは対義の関係にない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33441540-5e68-48c9-ab4d-7372add938d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35635, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の始まりとなる地点や時点。", "primary_collocate": null, "pronunciation": "きてん", "ipa": "kiteɴ", "syllable_count": 3, "sentences": [{"text": "去年の春の出会いが、二人の友情の起点になった。", "target_word": "起点", "complexity_tier": "T3", "furigana": "去年[きょねん]の春[はる]の出会[であ]いが、二人[ふたり]の友情[ゆうじょう]の起点[きてん]になった。", "sentence_source": "generated"}, {"text": "今月の一日を起点として、新しい料金が適用される。", "target_word": "起点", "complexity_tier": "T3", "furigana": "今月[こんげつ]の一日[ついたち]を起点[きてん]として、新[あたら]しい料金[りょうきん]が適用[てきよう]される。", "sentence_source": "generated"}, {"text": "昭和の終わりを起点に、この町は大きく変わり始めた。", "target_word": "起点", "complexity_tier": "T3", "furigana": "昭和[しょうわ]の終[お]わりを起点[きてん]に、この町[まち]は大[おお]きく変[か]わり始[はじ]めた。", "sentence_source": "generated"}, {"text": "その事故を起点に、会社の安全対策が見直された。", "target_word": "起点", "complexity_tier": "T3", "furigana": "その事故[じこ]を起点[きてん]に、会社[かいしゃ]の安全対策[あんぜんたいさく]が見直[みなお]された。", "sentence_source": "generated"}, {"text": "契約した日を起点にして、三か月間は無料で使える。", "target_word": "起点", "complexity_tier": "T3", "furigana": "契約[けいやく]した日[ひ]を起点[きてん]にして、三[さん]か月間[げつかん]は無料[むりょう]で使[つか]える。", "sentence_source": "generated"}, {"text": "彼は留学を起点に、自分の将来を真剣に考えるようになった。", "target_word": "起点", "complexity_tier": "T3", "furigana": "彼[かれ]は留学[りゅうがく]を起点[きてん]に、自分[じぶん]の将来[しょうらい]を真剣[しんけん]に考[かんが]えるようになった。", "sentence_source": "generated"}, {"text": "研究の起点は、一つの小さな疑問だった。", "target_word": "起点", "complexity_tier": "T3", "furigana": "研究[けんきゅう]の起点[きてん]は、一[ひと]つの小[ちい]さな疑問[ぎもん]だった。", "sentence_source": "generated"}, {"text": "今日を起点に、毎朝ジョギングを続けるつもりだ。", "target_word": "起点", "complexity_tier": "T3", "furigana": "今日[きょう]を起点[きてん]に、毎朝[まいあさ]ジョギングを続[つづ]けるつもりだ。", "sentence_source": "generated"}, {"text": "日数は、申し込みの日を起点として数える。", "target_word": "起点", "complexity_tier": "T3", "furigana": "日数[にっすう]は、申[もう]し込[こ]みの日[ひ]を起点[きてん]として数[かぞ]える。", "sentence_source": "generated"}, {"text": "あの優勝が起点となり、チームは強くなっていった。", "target_word": "起点", "complexity_tier": "T3", "furigana": "あの優勝[ゆうしょう]が起点[きてん]となり、チームは強[つよ]くなっていった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "起点", "label": "基本形"}, {"form": "起点に", "label": "に格"}, {"form": "起点として", "label": "として"}, {"form": "起点となり", "label": "連用形(となり)"}], "register": "neutral (plain form)", "sense_fingerprint": "出来事・変化・日数の数え始めなど、物事が始まるきっかけとなる時点(〜を起点に、起点となる)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07e99574-5a76-414c-a8d8-98dc1fc98f23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35635, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "起点", "is_correct": true, "explanation": "「起点」は物事の始まりとなる時点や地点。出会いが友情の始まりになったという文に合う。"}, {"text": "天気", "is_correct": false, "explanation": "「友情の天気」は文として意味が通らず、出会いが友情を始めたという内容にも合わない。"}, {"text": "辞書", "is_correct": false, "explanation": "「友情の辞書」は意味が通らず、出会いが友情の始まりになったという文脈と合わない。"}, {"text": "誤解", "is_correct": false, "explanation": "「誤解」は友情の始まりを表す語ではなく、「友情の誤解になった」は文の内容に合わない。"}], "explanations": {"起点": "「起点」は物事の始まりとなる時点や地点。出会いが友情の始まりになったという文に合う。", "天気": "「友情の天気」は文として意味が通らず、出会いが友情を始めたという内容にも合わない。", "辞書": "「友情の辞書」は意味が通らず、出会いが友情の始まりになったという文脈と合わない。", "誤解": "「誤解」は友情の始まりを表す語ではなく、「友情の誤解になった」は文の内容に合わない。"}, "sentence_index": 0, "correct_answer": "起点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この店は売上がこの起点を超えると、ボーナスが出る。", "explanation": "ここは〈基準〉の意味。起点は物事の始まりの地点や時点で、超えるべき数値の目安ではないので合わない。"}, {"text": "彼女は起点を利かせて、その場を切り抜けた。", "explanation": "ここは〈機転〉の意味。起点は地点や時点を指すので、「利かせる」とは結びつかない。"}, {"text": "てこの起点を変えると、小さな力で重い物が持ち上がる。", "explanation": "ここは〈支点〉の意味。起点は物事の始まりの地点や時点で、てこを支えて回転させる点（支点）の意味では使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33441540-5e68-48c9-ab4d-7372add938d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35635, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "起点", "is_correct": true, "explanation": "「起点」は物事の始まりとなる点。研究の始まりが小さな疑問だったという文に合う。"}, {"text": "食卓", "is_correct": false, "explanation": "「研究の食卓」は意味が通らず、研究の始まりを表す文に合わない。"}, {"text": "切符", "is_correct": false, "explanation": "「研究の切符」は文として成り立たず、研究の始まりを述べる文脈とも合わない。"}, {"text": "歌声", "is_correct": false, "explanation": "「研究の歌声」は意味が通らず、疑問が研究の始まりだったという内容に合わない。"}], "explanations": {"起点": "「起点」は物事の始まりとなる点。研究の始まりが小さな疑問だったという文に合う。", "食卓": "「研究の食卓」は意味が通らず、研究の始まりを表す文に合わない。", "切符": "「研究の切符」は文として成り立たず、研究の始まりを述べる文脈とも合わない。", "歌声": "「研究の歌声」は意味が通らず、疑問が研究の始まりだったという内容に合わない。"}, "sentence_index": 6, "correct_answer": "起点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は相手の起点をうかがいながら話した。", "explanation": "ここは〈機嫌〉の意味。起点は地点や時点で、人の気分を「うかがう」対象にはならないので合わない。"}, {"text": "文の終わりには、起点を打つ。", "explanation": "ここは〈句点〉の意味。句点は文の終わりに打つ記号で、物事の始まりを表す起点とは意味が違うので合わない。"}, {"text": "町の子ども食堂のために、起点を募った。", "explanation": "ここは〈寄付〉の意味。「募る」の対象は寄付や参加者で、起点を募ることはできないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33441540-5e68-48c9-ab4d-7372add938d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35635, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この店は開店日を起点で、ポイントを配り始めた。", "corrected_sentence": "この店は開店日を起点に、ポイントを配り始めた。", "error_description": "「起点」に続く助詞は「に」が正しく、「〜を起点に」の形で使う。「で」は場所や手段を表すので、ここでは合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33441540-5e68-48c9-ab4d-7372add938d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35635, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その発見が起点となる、新薬の研究が進んだ。", "corrected_sentence": "その発見が起点となり、新薬の研究が進んだ。", "error_description": "「起点となり」と連用形で続ける必要がある。「となる」のままでは、後ろの「、新薬の研究が進んだ」につながらない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33441540-5e68-48c9-ab4d-7372add938d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
