INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35638, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "海面を基準にして、山や土地の高さを数字で表したもの。", "primary_collocate": null, "pronunciation": "ひょうこう", "ipa": "çoːkoː", "syllable_count": 4, "sentences": [{"text": "この山の標高は三千メートルを超えている。", "target_word": "標高", "complexity_tier": "T3", "furigana": "この山[やま]の標高[ひょうこう]は三千[さんぜん]メートルを超[こ]えている。", "sentence_source": "generated"}, {"text": "標高が高い場所では、空気がうすくなる。", "target_word": "標高", "complexity_tier": "T3", "furigana": "標高[ひょうこう]が高[たか]い場所[ばしょ]では、空気[くうき]がうすくなる。", "sentence_source": "generated"}, {"text": "富士山は日本で標高がいちばん高い山だ。", "target_word": "標高", "complexity_tier": "T3", "furigana": "富士山[ふじさん]は日本[にほん]で標高[ひょうこう]がいちばん高[たか]い山[やま]だ。", "sentence_source": "generated"}, {"text": "標高が百メートル上がるごとに、気温は少し下がる。", "target_word": "標高", "complexity_tier": "T3", "furigana": "標高[ひょうこう]が百[ひゃく]メートル上[あ]がるごとに、気温[きおん]は少[すこ]し下[さ]がる。", "sentence_source": "generated"}, {"text": "標高の低い山では、冬でも雪があまり積もらない。", "target_word": "標高", "complexity_tier": "T3", "furigana": "標高[ひょうこう]の低[ひく]い山[やま]では、冬[ふゆ]でも雪[ゆき]があまり積[つ]もらない。", "sentence_source": "generated"}, {"text": "地図には、山の標高が小さな数字で書いてある。", "target_word": "標高", "complexity_tier": "T3", "furigana": "地図[ちず]には、山[やま]の標高[ひょうこう]が小[ちい]さな数字[すうじ]で書[か]いてある。", "sentence_source": "generated"}, {"text": "標高二千メートルの山小屋で、涼しい夏を過ごした。", "target_word": "標高", "complexity_tier": "T3", "furigana": "標高[ひょうこう]二千[にせん]メートルの山小屋[やまごや]で、涼[すず]しい夏[なつ]を過[す]ごした。", "sentence_source": "generated"}, {"text": "登山者は、標高が上がるにつれて息が苦しくなった。", "target_word": "標高", "complexity_tier": "T3", "furigana": "登山者[とざんしゃ]は、標高[ひょうこう]が上[あ]がるにつれて息[いき]が苦[くる]しくなった。", "sentence_source": "generated"}, {"text": "この山は標高が低いので、大雨のあとは山道がぬかるみやすい。", "target_word": "標高", "complexity_tier": "T3", "furigana": "この山[やま]は標高[ひょうこう]が低[ひく]いので、大雨[おおあめ]のあとは山道[やまみち]がぬかるみやすい。", "sentence_source": "generated"}, {"text": "標高の高い山では、七月でも雪が残っていることがある。", "target_word": "標高", "complexity_tier": "T3", "furigana": "標高[ひょうこう]の高[たか]い山[やま]では、七月[しちがつ]でも雪[ゆき]が残[のこ]っていることがある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "標高", "label": "基本形"}, {"form": "標高が", "label": "が格"}, {"form": "標高の", "label": "連体修飾(の)"}, {"form": "標高は", "label": "は格"}], "register": "neutral (plain form)", "sense_fingerprint": "海面などを基準とした土地や山の高さを数字で表したもの(標高が高い・低い、標高〇メートル)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07e99574-5a76-414c-a8d8-98dc1fc98f23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35638, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "標高", "is_correct": true, "explanation": "「標高」は海面からの高さ。山の高さを数値で表し、三千メートルを超えているという文に合う。"}, {"text": "人口", "is_correct": false, "explanation": "「人口」は人の数を表し、「三千メートルを超える」とは結びつかない。"}, {"text": "気温", "is_correct": false, "explanation": "「気温」は空気の温度で、距離の単位であるメートルと合わない。"}, {"text": "体重", "is_correct": false, "explanation": "「体重」は人や物の重さで、山の数値を表す文には合わない。"}], "explanations": {"標高": "「標高」は海面からの高さ。山の高さを数値で表し、三千メートルを超えているという文に合う。", "人口": "「人口」は人の数を表し、「三千メートルを超える」とは結びつかない。", "気温": "「気温」は空気の温度で、距離の単位であるメートルと合わない。", "体重": "「体重」は人や物の重さで、山の数値を表す文には合わない。"}, "sentence_index": 0, "correct_answer": "標高"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この塔の標高は五十メートルだ。", "explanation": "ここは〈高さ〉の意味。標高は海面を基準にした高さなので、建物の高さには使わない。"}, {"text": "兄は十年で標高が十センチ伸びた。", "explanation": "ここは〈身長〉の意味。標高は山や土地の高さを表すので、人の背の高さには使わない。"}, {"text": "飛行機の標高が下がり、着陸の準備を始めた。", "explanation": "ここは〈高度〉の意味。標高は地面や海面からの高さで、飛行中の機体の高さには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33441540-5e68-48c9-ab4d-7372add938d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35638, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "標高", "is_correct": true, "explanation": "「標高」は海面からの高さ。山小屋の高さを示す語として、二千メートルという数値に合う。"}, {"text": "座席", "is_correct": false, "explanation": "「座席二千メートル」は意味が通らず、山小屋の高さを示す文に合わない。"}, {"text": "歌声", "is_correct": false, "explanation": "「歌声二千メートル」は文として成り立たず、高さを表す語にはならない。"}, {"text": "砂糖", "is_correct": false, "explanation": "「砂糖二千メートル」は意味が通らず、山小屋の高さを示す文に合わない。"}], "explanations": {"標高": "「標高」は海面からの高さ。山小屋の高さを示す語として、二千メートルという数値に合う。", "座席": "「座席二千メートル」は意味が通らず、山小屋の高さを示す文に合わない。", "歌声": "「歌声二千メートル」は文として成り立たず、高さを表す語にはならない。", "砂糖": "「砂糖二千メートル」は意味が通らず、山小屋の高さを示す文に合わない。"}, "sentence_index": 6, "correct_answer": "標高"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "熱が出て、標高が三十八度まで上がった。", "explanation": "ここは〈体温〉の意味。標高は土地の高さを表すので、人の熱には使わない。"}, {"text": "先月から、標高が三キロ増えた。", "explanation": "ここは〈体重〉の意味。標高は海面からの高さなので、人の体の重さには使わない。"}, {"text": "この工場の製品は、標高の大きさで作られている。", "explanation": "ここは〈標準〉の意味。標高は高さの数値を表すので、規格の大きさを示す語としては使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33441540-5e68-48c9-ab4d-7372add938d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35638, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この村は標高を低いので、冬でも雪がほとんど降らない。", "corrected_sentence": "この村は標高が低いので、冬でも雪がほとんど降らない。", "error_description": "「低い」の主語を示すには「が」を使う（「標高が低い」）。「を」は目的語を示すので、ここでは「低い」の主語として合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33441540-5e68-48c9-ab4d-7372add938d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35638, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この村は標高が高きて、冬はとても寒い。", "corrected_sentence": "この村は標高が高くて、冬はとても寒い。", "error_description": "形容詞「高い」の連用形は「高くて」。「高きて」は活用の誤りで、「て」で文を続けられない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33441540-5e68-48c9-ab4d-7372add938d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
