INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35639, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "高さを海面からの数値で表したもの。特に、山や土地の高さを示す。", "primary_collocate": null, "pronunciation": "ひょうこう", "ipa": "çoːkoː", "syllable_count": 4, "sentences": [{"text": "富士山の標高は3776メートルです。", "target_word": "標高", "complexity_tier": "T3", "furigana": "富士山[ふじさん]の標高[ひょうこう]は3776メートルです。", "sentence_source": "generated"}, {"text": "標高が高くなると、空気がうすくなります。", "target_word": "標高", "complexity_tier": "T3", "furigana": "標高[ひょうこう]が高[たか]くなると、空気[くうき]がうすくなります。", "sentence_source": "generated"}, {"text": "この町は標高が高いので、夏でもすずしいです。", "target_word": "標高", "complexity_tier": "T3", "furigana": "この町[まち]は標高[ひょうこう]が高[たか]いので、夏[なつ]でもすずしいです。", "sentence_source": "generated"}, {"text": "地図には、山の標高が小さな数字で書いてあります。", "target_word": "標高", "complexity_tier": "T3", "furigana": "地図[ちず]には、山[やま]の標高[ひょうこう]が小[ちい]さな数字[すうじ]で書[か]いてあります。", "sentence_source": "generated"}, {"text": "標高2000メートルをこえると、木がほとんど見えなくなる。", "target_word": "標高", "complexity_tier": "T3", "furigana": "標高[ひょうこう]2000メートルをこえると、木[き]がほとんど見[み]えなくなる。", "sentence_source": "generated"}, {"text": "標高の低い土地では、雨のあとに水がたまりやすい。", "target_word": "標高", "complexity_tier": "T3", "furigana": "標高[ひょうこう]の低[ひく]い土地[とち]では、雨[あめ]のあとに水[みず]がたまりやすい。", "sentence_source": "generated"}, {"text": "彼は標高の高い村で生まれ育ち、寒さには強い。", "target_word": "標高", "complexity_tier": "T3", "furigana": "彼[かれ]は標高[ひょうこう]の高[たか]い村[むら]で生[う]まれ育[そだ]ち、寒[さむ]さには強[つよ]い。", "sentence_source": "generated"}, {"text": "頂上に着くと、標高を示す石の柱が立っていた。", "target_word": "標高", "complexity_tier": "T3", "furigana": "頂上[ちょうじょう]に着[つ]くと、標高[ひょうこう]を示[しめ]す石[いし]の柱[はしら]が立[た]っていた。", "sentence_source": "generated"}, {"text": "標高が100メートル上がるごとに、気温は約0.6度下がる。", "target_word": "標高", "complexity_tier": "T3", "furigana": "標高[ひょうこう]が100メートル上[あ]がるごとに、気温[きおん]は約[やく]0.6度[ど]下[さ]がる。", "sentence_source": "generated"}, {"text": "この道は標高の差が大きく、自転車ではかなりきつい。", "target_word": "標高", "complexity_tier": "T3", "furigana": "この道[みち]は標高[ひょうこう]の差[さ]が大[おお]きく、自転車[じてんしゃ]ではかなりきつい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "標高", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "海面を基準にした山や土地の高さの数値", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07e99574-5a76-414c-a8d8-98dc1fc98f23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35639, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "標高", "is_correct": true, "explanation": "「標高」は海面を基準にした高さ。富士山の高さを数値で表す語として、文に合う。"}, {"text": "人口", "is_correct": false, "explanation": "「富士山の人口は3776メートル」は意味が通らず、山の高さを述べる文に合わない。"}, {"text": "座席", "is_correct": false, "explanation": "「富士山の座席」は文として成り立たず、高さを表す語にはならない。"}, {"text": "体重", "is_correct": false, "explanation": "「体重」は人や物の重さで、富士山の高さを表す文には合わない。"}], "explanations": {"標高": "「標高」は海面を基準にした高さ。富士山の高さを数値で表す語として、文に合う。", "人口": "「富士山の人口は3776メートル」は意味が通らず、山の高さを述べる文に合わない。", "座席": "「富士山の座席」は文として成り立たず、高さを表す語にはならない。", "体重": "「体重」は人や物の重さで、富士山の高さを表す文には合わない。"}, "sentence_index": 0, "correct_answer": "標高"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "パイロットは飛行機の標高を計器で確かめた。", "explanation": "ここは〈高度〉の意味。標高は地面や海面からの高さを示す土地の数値で、飛行中の機体には使わない。"}, {"text": "熱が出て、標高が一度上がった。", "explanation": "ここは〈体温〉の意味。標高は山や土地の高さを表すので、人の体には使わない。"}, {"text": "後半に標高が入り、チームが勝った。", "explanation": "ここは〈得点〉の意味。標高は土地の高さを表す語で、試合で入る点数には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33441540-5e68-48c9-ab4d-7372add938d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35639, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "標高", "is_correct": true, "explanation": "「標高の高い村」は土地の高さを表す言い方で、寒さに強いという文脈に合う。"}, {"text": "砂糖", "is_correct": false, "explanation": "「砂糖の高い村」は意味が通らず、村で育ったという文脈に合わない。"}, {"text": "音量", "is_correct": false, "explanation": "音の大きさのこと。「音量の高い村」は成り立たず、村の場所を表せない。"}, {"text": "切手", "is_correct": false, "explanation": "郵便に使う紙片のこと。「切手の高い村」は成り立たず、村の寒さを述べる文に合わない。"}], "explanations": {"標高": "「標高の高い村」は土地の高さを表す言い方で、寒さに強いという文脈に合う。", "砂糖": "「砂糖の高い村」は意味が通らず、村で育ったという文脈に合わない。", "音量": "音の大きさのこと。「音量の高い村」は成り立たず、村の場所を表せない。", "切手": "郵便に使う紙片のこと。「切手の高い村」は成り立たず、村の寒さを述べる文に合わない。"}, "sentence_index": 6, "correct_answer": "標高"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先月の検診で、標高が三キロ増えたと言われた。", "explanation": "ここは〈体重〉の意味。標高は海面からの高さなので、人の体重には使わない。"}, {"text": "スマホの電池の標高が少なくなってきた。", "explanation": "ここは〈残量〉の意味。標高は高さの数値を表すので、電池の残り量には使わない。"}, {"text": "この部品は標高の規格に合わせて作られている。", "explanation": "ここは〈標準〉の意味。標高は高さを表す数値で、規格や基準の意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33441540-5e68-48c9-ab4d-7372add938d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35639, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この湖の標高を高くて、冬は雪が多い。", "corrected_sentence": "この湖の標高が高くて、冬は雪が多い。", "error_description": "「標高」の後には「が」が入る（「標高が高い」）。「を」は目的語を示すので、「高くて」の主語として合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33441540-5e68-48c9-ab4d-7372add938d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35639, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "あの峠の標高は高いくて、車で登るのが大変だ。", "corrected_sentence": "あの峠の標高は高くて、車で登るのが大変だ。", "error_description": "形容詞「高い」の連用形は「高くて」。「高いくて」は活用の誤りで、「て」で文を続けられない形になっている。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33441540-5e68-48c9-ab4d-7372add938d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35640, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「山地では」の「で」。場面・地域を表す助詞で、天気に注意という状況を述べる文の主題を作る。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示す。「山地がは」と「は」が続かず、文として成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は動作の対象を示す。山地は天気が変わる対象ではないので合わない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐ助詞で、後ろに名詞が続かないため文が成り立たない。"}], "correct_answer": "で", "explanations": {"で": "「山地では」の「で」。場面・地域を表す助詞で、天気に注意という状況を述べる文の主題を作る。", "が": "「が」は主語を示す。「山地がは」と「は」が続かず、文として成り立たない。", "を": "「を」は動作の対象を示す。山地は天気が変わる対象ではないので合わない。", "の": "「の」は名詞をつなぐ助詞で、後ろに名詞が続かないため文が成り立たない。"}, "error_tags": {"が": "subject", "を": "object", "の": "attributive"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c087fde-8a23-4107-9fdc-2f977c77c827') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35640, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c087fde-8a23-4107-9fdc-2f977c77c827') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35640, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "山がたくさんある土地のことです。", "primary_collocate": null, "pronunciation": "さんち", "ipa": "sant͡ɕi", "syllable_count": 3, "sentences": [{"text": "この国の北半分は、ほとんどが山地で、人があまり住んでいない。", "target_word": "山地", "complexity_tier": "T3", "furigana": "この国[くに]の北半分[きたはんぶん]は、ほとんどが山地[さんち]で、人[ひと]があまり住[す]んでいない。", "sentence_source": "generated"}, {"text": "山地では、天気が急に変わることがあるので注意が必要だ。", "target_word": "山地", "complexity_tier": "T3", "furigana": "山地[さんち]では、天気[てんき]が急[きゅう]に変[か]わることがあるので注意[ちゅうい]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "山地にある村へ行くバスは、一日に二本しかない。", "target_word": "山地", "complexity_tier": "T3", "furigana": "山地[さんち]にある村[むら]へ行[い]くバスは、一日[いちにち]に二本[にほん]しかない。", "sentence_source": "generated"}, {"text": "山地が多い県では、トンネルや橋をたくさん作らなければならない。", "target_word": "山地", "complexity_tier": "T3", "furigana": "山地[さんち]が多[おお]い県[けん]では、トンネルや橋[はし]をたくさん作[つく]らなければならない。", "sentence_source": "generated"}, {"text": "私が生まれたのは、深い山地に囲まれた小さな町だ。", "target_word": "山地", "complexity_tier": "T3", "furigana": "私[わたし]が生[う]まれたのは、深[ふか]い山地[さんち]に囲[かこ]まれた小[ちい]さな町[まち]だ。", "sentence_source": "generated"}, {"text": "山地の斜面には、茶畑が階段のように広がっている。", "target_word": "山地", "complexity_tier": "T3", "furigana": "山地[さんち]の斜面[しゃめん]には、茶畑[ちゃばたけ]が階段[かいだん]のように広[ひろ]がっている。", "sentence_source": "generated"}, {"text": "日本は山地が国土の大部分を占めている。", "target_word": "山地", "complexity_tier": "T3", "furigana": "日本[にほん]は山地[さんち]が国土[こくど]の大部分[だいぶぶん]を占[し]めている。", "sentence_source": "generated"}, {"text": "山地を車で走ると、カーブが続いて酔いやすい。", "target_word": "山地", "complexity_tier": "T3", "furigana": "山地[さんち]を車[くるま]で走[はし]ると、カーブが続[つづ]いて酔[よ]いやすい。", "sentence_source": "generated"}, {"text": "川は山地から流れ出て、海へ向かう。", "target_word": "山地", "complexity_tier": "T3", "furigana": "川[かわ]は山地[さんち]から流[なが]れ出[で]て、海[うみ]へ向[む]かう。", "sentence_source": "generated"}, {"text": "この山地には、冬になると雪がたくさん積もる。", "target_word": "山地", "complexity_tier": "T3", "furigana": "この山地[さんち]には、冬[ふゆ]になると雪[ゆき]がたくさん積[つ]もる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "山地", "label": "base form"}, {"form": "山地の", "label": "attributive (の)"}, {"form": "山地で", "label": "locative (で)"}, {"form": "山地に", "label": "locative (に)"}], "register": "neutral", "sense_fingerprint": "山が連なっている地域・土地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e9d0569-35c2-4591-8d48-a8dee00aafec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35640, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "山地", "is_correct": true, "explanation": "「山地」は山が多い土地の意味。「国の北半分のほとんどが山地」と、山が大半を占める文脈に合う。"}, {"text": "住宅地", "is_correct": false, "explanation": "住宅地は人が多く住む土地なので、後半の「人があまり住んでいない」と矛盾する。"}, {"text": "繁華街", "is_correct": false, "explanation": "繁華街は人通りの多い商業地なので、「人があまり住んでいない」と合わない。"}, {"text": "大都市", "is_correct": false, "explanation": "大都市は人口が集中する場所なので、「ほとんどが大都市で人があまり住んでいない」は成り立たない。"}], "explanations": {"山地": "「山地」は山が多い土地の意味。「国の北半分のほとんどが山地」と、山が大半を占める文脈に合う。", "住宅地": "住宅地は人が多く住む土地なので、後半の「人があまり住んでいない」と矛盾する。", "繁華街": "繁華街は人通りの多い商業地なので、「人があまり住んでいない」と合わない。", "大都市": "大都市は人口が集中する場所なので、「ほとんどが大都市で人があまり住んでいない」は成り立たない。"}, "sentence_index": 0, "correct_answer": "山地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "山地の浜辺で、朝の貝拾いが始まる。", "explanation": "ここは〈海岸〉の意味。海岸は海に面した陸の端を指す。山が多い土地の「山地」は海に面していないので、浜辺の場所には合わない。"}, {"text": "富士山は、日本でいちばん高い山地だ。", "explanation": "ここは〈峰〉の意味。峰は尖った一つの山頂を指す。山が多い土地を表す「山地」は、単独の峰には使えない。"}, {"text": "山地の沖合で、網を引く人が魚を獲っている。", "explanation": "ここは〈海〉の意味。海は魚を獲る場所だが、「山地」は山の土地なので沖合の意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c087fde-8a23-4107-9fdc-2f977c77c827') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35640, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "山地", "is_correct": true, "explanation": "山が多い土地を指し、「国土の大部分を占めている」という文脈に合う。"}, {"text": "河川", "is_correct": false, "explanation": "河川は川の流れを指し、国土の大部分を占めるとは言わない。"}, {"text": "海岸線", "is_correct": false, "explanation": "海岸線は細長い線であり、国土の大部分を占める面積の語としては成り立たない。"}, {"text": "人口", "is_correct": false, "explanation": "人口は人の数を表すので、土地が国土を占めるという文脈に合わない。"}], "explanations": {"山地": "山が多い土地を指し、「国土の大部分を占めている」という文脈に合う。", "河川": "河川は川の流れを指し、国土の大部分を占めるとは言わない。", "海岸線": "海岸線は細長い線であり、国土の大部分を占める面積の語としては成り立たない。", "人口": "人口は人の数を表すので、土地が国土を占めるという文脈に合わない。"}, "sentence_index": 6, "correct_answer": "山地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "山地の砂丘で、ラクダの列がゆっくり進む。", "explanation": "ここは〈砂漠〉の意味。砂漠は雨が少なく砂が一面に広がる土地を指す。山が多い「山地」は砂丘の地形を表さないので、この場面には合わない。"}, {"text": "この山地は平らで、どこまでも見渡せる。", "explanation": "ここは〈平野〉の意味。平野は平らに広がる土地を指す。起伏の多い「山地」は平らという性質と逆なので合わない。"}, {"text": "山地には大きな船が並び、荷物を積んでいる。", "explanation": "ここは〈港〉の意味。港は船が停泊して荷物を積む場所。山の土地である「山地」に船が並ぶことはなく、この使い方はできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c087fde-8a23-4107-9fdc-2f977c77c827') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35640, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夏の山地を、朝は霧が出やすい。", "corrected_sentence": "夏の山地では、朝は霧が出やすい。", "error_description": "「出る」は場所を「では」で示すため、「を」は場所には合わない。「山地」に付く助詞を「では」に直す。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c087fde-8a23-4107-9fdc-2f977c77c827') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35640, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "山地を、橋よりトンネルを作ることが多い。", "corrected_sentence": "山地では、橋よりトンネルを作ることが多い。", "error_description": "「山地」は作る対象ではなく場所なので、「を」ではなく「では」（場面・地域）が正しい。「を」を付けると山地そのものを作る対象にしてしまう。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c087fde-8a23-4107-9fdc-2f977c77c827') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35641, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「山地の多い」の「の」。名詞をつなぐ連体の助詞で、「山地」が「多い」を修飾している。"}, {"text": "を", "is_correct": false, "explanation": "「を」は動作の対象を示す。「山地を多い地域」では修飾関係が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示す。「山地と多い地域」は形容詞につながらず、文として不自然。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示す。「山地で多い」は文法的につながらない。"}], "correct_answer": "の", "explanations": {"の": "「山地の多い」の「の」。名詞をつなぐ連体の助詞で、「山地」が「多い」を修飾している。", "を": "「を」は動作の対象を示す。「山地を多い地域」では修飾関係が成り立たない。", "と": "「と」は並列や相手を示す。「山地と多い地域」は形容詞につながらず、文として不自然。", "で": "「で」は手段や場所を示す。「山地で多い」は文法的につながらない。"}, "error_tags": {"を": "object", "と": "coordination", "で": "means/location"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c087fde-8a23-4107-9fdc-2f977c77c827') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35641, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c087fde-8a23-4107-9fdc-2f977c77c827') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35641, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "山や丘が多く、平地が少ない土地のことです。", "primary_collocate": null, "pronunciation": "さんち", "ipa": "sant͡ɕi", "syllable_count": 3, "sentences": [{"text": "平地が少ない山地では、畑を斜面に作るしかない。", "target_word": "山地", "complexity_tier": "T3", "furigana": "平地[へいち]が少[すく]ない山地[さんち]では、畑[はたけ]を斜面[しゃめん]に作[つく]るしかない。", "sentence_source": "generated"}, {"text": "山地の多い地域は、家を建てられる場所が限られている。", "target_word": "山地", "complexity_tier": "T3", "furigana": "山地[さんち]の多[おお]い地域[ちいき]は、家[いえ]を建[た]てられる場所[ばしょ]が限[かぎ]られている。", "sentence_source": "generated"}, {"text": "平野と違って、山地は広い道路や大きな工場を作りにくい。", "target_word": "山地", "complexity_tier": "T3", "furigana": "平野[へいや]と違[ちが]って、山地[さんち]は広[ひろ]い道路[どうろ]や大[おお]きな工場[こうじょう]を作[つく]りにくい。", "sentence_source": "generated"}, {"text": "山や丘が続く山地では、町と町の間も遠く感じる。", "target_word": "山地", "complexity_tier": "T3", "furigana": "山[やま]や丘[おか]が続[つづ]く山地[さんち]では、町[まち]と町[まち]の間[あいだ]も遠[とお]く感[かん]じる。", "sentence_source": "generated"}, {"text": "この山地の人々は、わずかな平地を大切に使って米を作ってきた。", "target_word": "山地", "complexity_tier": "T3", "furigana": "この山地[さんち]の人々[ひとびと]は、わずかな平地[へいち]を大切[たいせつ]に使[つか]って米[こめ]を作[つく]ってきた。", "sentence_source": "generated"}, {"text": "山地が広がるこの地方では、大きな町は川沿いにしかない。", "target_word": "山地", "complexity_tier": "T3", "furigana": "山地[さんち]が広[ひろ]がるこの地方[ちほう]では、大[おお]きな町[まち]は川沿[かわぞ]いにしかない。", "sentence_source": "generated"}, {"text": "山地は平地が少ないので、人口も多くない。", "target_word": "山地", "complexity_tier": "T3", "furigana": "山地[さんち]は平地[へいち]が少[すく]ないので、人口[じんこう]も多[おお]くない。", "sentence_source": "generated"}, {"text": "空港を作ろうとしたが、山地ばかりで広い土地が見つからなかった。", "target_word": "山地", "complexity_tier": "T3", "furigana": "空港[くうこう]を作[つく]ろうとしたが、山地[さんち]ばかりで広[ひろ]い土地[とち]が見[み]つからなかった。", "sentence_source": "generated"}, {"text": "山地の村では、田んぼが小さく、段になって並んでいる。", "target_word": "山地", "complexity_tier": "T3", "furigana": "山地[さんち]の村[むら]では、田[た]んぼが小[ちい]さく、段[だん]になって並[なら]んでいる。", "sentence_source": "generated"}, {"text": "丘と山ばかりの山地を歩くと、平らな道がほとんどない。", "target_word": "山地", "complexity_tier": "T3", "furigana": "丘[おか]と山[やま]ばかりの山地[さんち]を歩[ある]くと、平[たい]らな道[みち]がほとんどない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "山地", "label": "base form"}, {"form": "山地の", "label": "attributive (の)"}, {"form": "山地で", "label": "locative (で)"}, {"form": "山地は", "label": "topic (は)"}], "register": "neutral", "sense_fingerprint": "山や丘が多くて平地が少ない地形・地域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e9d0569-35c2-4591-8d48-a8dee00aafec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35641, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "山地", "is_correct": true, "explanation": "山や丘が多く平地が少ない土地を指す。「平地が少ない〜では」と、斜面に畑を作る後半に合う。"}, {"text": "平野", "is_correct": false, "explanation": "平野は平らな土地を指す。「平地が少ない平野」は前後で矛盾する。"}, {"text": "大通り", "is_correct": false, "explanation": "大通りは道路の一種で、斜面に畑を作る場所としては成り立たない。"}, {"text": "教室", "is_correct": false, "explanation": "教室は建物の中の部屋なので、斜面に畑を作る場所として文が成り立たない。"}], "explanations": {"山地": "山や丘が多く平地が少ない土地を指す。「平地が少ない〜では」と、斜面に畑を作る後半に合う。", "平野": "平野は平らな土地を指す。「平地が少ない平野」は前後で矛盾する。", "大通り": "大通りは道路の一種で、斜面に畑を作る場所としては成り立たない。", "教室": "教室は建物の中の部屋なので、斜面に畑を作る場所として文が成り立たない。"}, "sentence_index": 0, "correct_answer": "山地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "山地では、田んぼが一面に広がり、どこまでも見渡せる。", "explanation": "ここは〈平野〉の意味。平野は平らで見渡せる土地を指す。「山地」は起伏が多く、一面に広がる田んぼを遠くまで見渡せるとは言えないので合わない。"}, {"text": "山地の海水浴場は、夏になると人でいっぱいになる。", "explanation": "ここは〈海辺〉の意味。海辺は海に面した砂浜を指す。山や丘が多い「山地」は海に面しないので、海水浴の場所としては合わない。"}, {"text": "山地の川口で、大きな船が荷をおろしている。", "explanation": "ここは〈港〉の意味。港は船が停泊して荷をおろす場所。山の土地である「山地」は、船の出入りする港の場所には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c087fde-8a23-4107-9fdc-2f977c77c827') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35641, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "山地", "is_correct": true, "explanation": "山や丘が多い土地を指し、「平地が少ないので人口も多くない」という理由の文脈に合う。"}, {"text": "砂漠", "is_correct": false, "explanation": "砂漠は雨が少ない乾いた土地を指し、「平地が少ない」という特徴とは結びつかない。"}, {"text": "海底", "is_correct": false, "explanation": "海底は海の底で、人口を述べる土地としては文が成り立たない。"}, {"text": "氷河", "is_correct": false, "explanation": "氷河は氷の塊で、人口の多少を述べる土地として不自然。"}], "explanations": {"山地": "山や丘が多い土地を指し、「平地が少ないので人口も多くない」という理由の文脈に合う。", "砂漠": "砂漠は雨が少ない乾いた土地を指し、「平地が少ない」という特徴とは結びつかない。", "海底": "海底は海の底で、人口を述べる土地としては文が成り立たない。", "氷河": "氷河は氷の塊で、人口の多少を述べる土地として不自然。"}, "sentence_index": 6, "correct_answer": "山地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この山地では、どこまでも続く砂丘が風で形を変える。", "explanation": "ここは〈砂漠〉の意味。砂漠は雨が少なく砂が一面に広がる土地を指す。山が多い「山地」は、砂丘が風で形を変えるような場所ではないので合わない。"}, {"text": "山地は周りを山に囲まれ、底が平らな土地だ。", "explanation": "ここは〈盆地〉の意味。盆地は周囲を山に囲まれた、底の平らな地形を指す。「山地」は起伏のある広い山の土地なので、この説明には合わない。"}, {"text": "山地が風にゆれ、どこまでも平らに広がっている。", "explanation": "ここは〈草原〉の意味。草原は草がどこまでも平らに広がる土地を指す。起伏のある「山地」には、平らに広がる様子は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c087fde-8a23-4107-9fdc-2f977c77c827') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35641, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "谷間の山地を、夕方は冷え込みがきつい。", "corrected_sentence": "谷間の山地では、夕方は冷え込みがきつい。", "error_description": "「冷え込む」は場所を「では」で示すため、「を」は合わない。「山地」に付く助詞の誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c087fde-8a23-4107-9fdc-2f977c77c827') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35641, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "山地を、平地が少ないので畑を作りにくい。", "corrected_sentence": "山地では、平地が少ないので畑を作りにくい。", "error_description": "「山地」は場所を示すので「では」が必要。「を」は動作の対象を示すため、畑を作るという行為の対象として山地を置く文は不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c087fde-8a23-4107-9fdc-2f977c77c827') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35643, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「栽培を超え」で、他動詞「超える」の目的語になる。"}, {"text": "が", "is_correct": false, "explanation": "「栽培が超え」では文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は「超える」の目的語に使えない。"}, {"text": "に", "is_correct": false, "explanation": "「超える」は対象を「を」で取る。「栽培に超え」とは言えない。"}], "correct_answer": "を", "explanations": {"を": "「栽培を超え」で、他動詞「超える」の目的語になる。", "が": "「栽培が超え」では文が成り立たない。", "へ": "方向を表す「へ」は「超える」の目的語に使えない。", "に": "「超える」は対象を「を」で取る。「栽培に超え」とは言えない。"}, "error_tags": {"が": "subject_marker", "へ": "direction", "に": "target_of_action"}, "sentence_index": 0}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "自生", "is_correct": true, "explanation": "人が育てず自然に生えることで、栽培の反対。"}, {"text": "耕作", "is_correct": false, "explanation": "畑を耕して作物を作ることで、栽培に近い。"}, {"text": "育成", "is_correct": false, "explanation": "育てることで、栽培と近い意味。"}, {"text": "養殖", "is_correct": false, "explanation": "魚などを育てることで、栽培の反対ではない。"}], "correct_answer": "自生", "explanations": {"自生": "人が育てず自然に生えることで、栽培の反対。", "耕作": "畑を耕して作物を作ることで、栽培に近い。", "育成": "育てることで、栽培と近い意味。", "養殖": "魚などを育てることで、栽培の反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd294d06f-130c-4a48-9148-a42e60f247cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35643, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「栽培には」で、「栽培のためには」の意味になる。"}, {"text": "が", "is_correct": false, "explanation": "「栽培がは」とは言えない。"}, {"text": "を", "is_correct": false, "explanation": "「栽培をは」は不自然で、文が成り立たない。"}, {"text": "か", "is_correct": false, "explanation": "「栽培かは」は文法的に合わない。"}], "correct_answer": "に", "explanations": {"に": "「栽培には」で、「栽培のためには」の意味になる。", "が": "「栽培がは」とは言えない。", "を": "「栽培をは」は不自然で、文が成り立たない。", "か": "「栽培かは」は文法的に合わない。"}, "error_tags": {"が": "subject_marker", "を": "object_marker", "か": "question_particle"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "野生", "is_correct": true, "explanation": "人が育てず自然のまま生きることで、栽培の反対。"}, {"text": "園芸", "is_correct": false, "explanation": "草花などを育てることで、栽培に近い。"}, {"text": "農耕", "is_correct": false, "explanation": "農作物を作ることで、栽培に近い。"}, {"text": "飼育", "is_correct": false, "explanation": "動物を育てることで、栽培の反対ではない。"}], "correct_answer": "野生", "explanations": {"野生": "人が育てず自然のまま生きることで、栽培の反対。", "園芸": "草花などを育てることで、栽培に近い。", "農耕": "農作物を作ることで、栽培に近い。", "飼育": "動物を育てることで、栽培の反対ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd294d06f-130c-4a48-9148-a42e60f247cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35643, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "植物を育てて収穫（しゅうかく）するために、種（たね）や苗（なえ）を植（う）えて世話（せわ）をすること。", "primary_collocate": null, "pronunciation": "さいばい", "ipa": "saibai", "syllable_count": 4, "sentences": [{"text": "この取り組みは、単なる植物の栽培を超え、環境再生と社会的結束の醸成を同時に企図する点に特徴がある。", "target_word": "栽培", "complexity_tier": "T6", "furigana": "この取り組みは、単[たん]なる植物[しょくぶつ]の栽培[さいばい]を超[こ]え、環境[かんきょう]再生[さいせい]と社会的[しゃかいてき]結束[けっそく]の醸成[じょうせい]を同時[どうじ]に企図[きと]する点[てん]に特徴[とくちょう]がある。", "sentence_source": "mined"}, {"text": "野菜を栽培する。", "target_word": "栽培", "complexity_tier": "T1", "furigana": "野菜[やさい]を栽培[さいばい]する。", "sentence_source": "generated"}, {"text": "トマトの栽培は簡単だ。", "target_word": "栽培", "complexity_tier": "T2", "furigana": "トマトの栽培[さいばい]は簡単[かんたん]だ。", "sentence_source": "generated"}, {"text": "祖父は庭で花を栽培しています。", "target_word": "栽培", "complexity_tier": "T2", "furigana": "祖父[そふ]は庭[にわ]で花[はな]を栽培[さいばい]しています。", "sentence_source": "generated"}, {"text": "この地域ではお茶の栽培が盛んだ。", "target_word": "栽培", "complexity_tier": "T2", "furigana": "この地域[ちいき]ではお茶[ちゃ]の栽培[さいばい]が盛[さか]んだ。", "sentence_source": "generated"}, {"text": "栽培を始めて三年目に、初めて実がなった。", "target_word": "栽培", "complexity_tier": "T3", "furigana": "栽培[さいばい]を始[はじ]めて三年目[さんねんめ]に、初[はじ]めて実[み]がなった。", "sentence_source": "generated"}, {"text": "無農薬で栽培された米は、少し値段が高い。", "target_word": "栽培", "complexity_tier": "T4", "furigana": "無農薬[むのうやく]で栽培[さいばい]された米[こめ]は、少[すこ]し値段[ねだん]が高[たか]い。", "sentence_source": "generated"}, {"text": "寒さに弱い果物なので、栽培には温室が必要だ。", "target_word": "栽培", "complexity_tier": "T3", "furigana": "寒[さむ]さに弱[よわ]い果物[くだもの]なので、栽培[さいばい]には温室[おんしつ]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "栽培の方法を本で調べてから、種をまいた。", "target_word": "栽培", "complexity_tier": "T3", "furigana": "栽培[さいばい]の方法[ほうほう]を本[ほん]で調[しら]べてから、種[たね]をまいた。", "sentence_source": "generated"}, {"text": "農家は、病気に強い品種を栽培することにした。", "target_word": "栽培", "complexity_tier": "T4", "furigana": "農家[のうか]は、病気[びょうき]に強[つよ]い品種[ひんしゅ]を栽培[さいばい]することにした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "栽培する", "label": "活用"}, {"form": "栽培される", "label": "活用"}, {"form": "栽培方法", "label": "派生"}, {"form": "栽培植物", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 植物を育てて収穫する世話", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57ac3fe2-6ce0-4a2e-b7a6-92b185db239c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35643, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "栽培", "is_correct": true, "explanation": "見出し語「さいばい」。"}, {"text": "災害", "is_correct": false, "explanation": "「さいがい」で、ば→がの一音違い。"}, {"text": "再開", "is_correct": false, "explanation": "「さいかい」で、ば→かの一音違い。"}, {"text": "最大", "is_correct": false, "explanation": "「さいだい」で、ば→だの一音違い。"}, {"text": "裁判", "is_correct": false, "explanation": "「さいばん」で、最後のい→んの一音違い。"}], "explanations": {"栽培": "見出し語「さいばい」。", "災害": "「さいがい」で、ば→がの一音違い。", "再開": "「さいかい」で、ば→かの一音違い。", "最大": "「さいだい」で、ば→だの一音違い。", "裁判": "「さいばん」で、最後のい→んの一音違い。"}, "sentence_index": null, "correct_answer": "栽培"}, "level_3": {"options": [{"text": "栽培", "is_correct": true, "explanation": "「植物の栽培」で、植物を育てることを表す。"}, {"text": "演奏", "is_correct": false, "explanation": "形は合うが意味が合わない。植物を演奏することはできない。"}, {"text": "計算", "is_correct": false, "explanation": "形は合うが意味が合わない。植物の計算では文脈に合わない。"}, {"text": "洗濯", "is_correct": false, "explanation": "形は合うが意味が合わない。植物の洗濯では意味が通らない。"}], "explanations": {"栽培": "「植物の栽培」で、植物を育てることを表す。", "演奏": "形は合うが意味が合わない。植物を演奏することはできない。", "計算": "形は合うが意味が合わない。植物の計算では文脈に合わない。", "洗濯": "形は合うが意味が合わない。植物の洗濯では意味が通らない。"}, "sentence_index": 0, "correct_answer": "栽培"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "祖父は庭で石を栽培しています。", "explanation": "「栽培」は植物を育てることで、石は育てられないので対象の選び方が誤り。"}, {"text": "祖父は庭で犬を栽培しています。", "explanation": "動物には「飼育」を使う。「栽培」は植物にしか使えない。"}, {"text": "祖父は毎朝、新聞を栽培しています。", "explanation": "新聞は植物ではないので、「栽培」の対象として誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd294d06f-130c-4a48-9148-a42e60f247cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35643, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "栽培", "is_correct": true, "explanation": "見出し語「さいばい」。"}, {"text": "成敗", "is_correct": false, "explanation": "「せいばい」で、さ→せの一音違い。"}, {"text": "幸い", "is_correct": false, "explanation": "「さいわい」で、ば→わの一音違い。"}, {"text": "采配", "is_correct": false, "explanation": "「さいはい」で、ば→はの清濁の違い。"}, {"text": "最愛", "is_correct": false, "explanation": "「さいあい」で、ば→あの一音違い。"}], "explanations": {"栽培": "見出し語「さいばい」。", "成敗": "「せいばい」で、さ→せの一音違い。", "幸い": "「さいわい」で、ば→わの一音違い。", "采配": "「さいはい」で、ば→はの清濁の違い。", "最愛": "「さいあい」で、ば→あの一音違い。"}, "sentence_index": null, "correct_answer": "栽培"}, "level_3": {"options": [{"text": "栽培", "is_correct": true, "explanation": "「無農薬で栽培された米」で、育てられた米を表す。"}, {"text": "運搬", "is_correct": false, "explanation": "形は合うが意味が合わない。「無農薬」との組み合わせが不自然。"}, {"text": "洗濯", "is_correct": false, "explanation": "形は合うが意味が合わない。米を洗濯するとは言わない。"}, {"text": "印刷", "is_correct": false, "explanation": "形は合うが意味が合わない。米を印刷することはない。"}], "explanations": {"栽培": "「無農薬で栽培された米」で、育てられた米を表す。", "運搬": "形は合うが意味が合わない。「無農薬」との組み合わせが不自然。", "洗濯": "形は合うが意味が合わない。米を洗濯するとは言わない。", "印刷": "形は合うが意味が合わない。米を印刷することはない。"}, "sentence_index": 6, "correct_answer": "栽培"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "農家は、病気に強い電話を栽培することにした。", "explanation": "電話は植物ではなく、「栽培」の対象として誤り。"}, {"text": "農家は、毎日牛乳を栽培することにした。", "explanation": "牛乳は植物ではないので、「栽培」は使えない。"}, {"text": "農家は、田んぼの水を栽培することにした。", "explanation": "水は育てて収穫する植物ではないので、「栽培」の対象に合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd294d06f-130c-4a48-9148-a42e60f247cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
