INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35644, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「特定の病気」となり、『特定』が『病気』を修飾する連体修飾の『の』。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す。「特定が病気」は修飾の場面に合わず、文の成分として成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す。「特定を病気」では名詞同士を正しくつなげられない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す。「特定へ病気」は意味が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「特定の病気」となり、『特定』が『病気』を修飾する連体修飾の『の』。", "が": "主語を示す。「特定が病気」は修飾の場面に合わず、文の成分として成り立たない。", "を": "目的語を示す。「特定を病気」では名詞同士を正しくつなげられない。", "へ": "方向を示す。「特定へ病気」は意味が成り立たない。"}, "error_tags": {"が": "主語を示す", "を": "目的語を示す", "へ": "方向を示す"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不特定", "is_correct": true, "explanation": "『特定』の対義語。区別して決めた対象に対し、区別のない対象を指す。"}, {"text": "全体", "is_correct": false, "explanation": "全部をまとめた範囲を指す語で、区別の対義語にはならない。"}, {"text": "共通", "is_correct": false, "explanation": "複数のものに当てはまる性質を指し、特定の反対語ではない。"}, {"text": "平均", "is_correct": false, "explanation": "数量を均等にならした値を指し、特定の対義語とはされない。"}], "correct_answer": "不特定", "explanations": {"不特定": "『特定』の対義語。区別して決めた対象に対し、区別のない対象を指す。", "全体": "全部をまとめた範囲を指す語で、区別の対義語にはならない。", "共通": "複数のものに当てはまる性質を指し、特定の反対語ではない。", "平均": "数量を均等にならした値を指し、特定の対義語とはされない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '816badd2-2b50-4e3f-a98a-f685001f1828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35644, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「特定の人」となり、『特定』が『人』を修飾する連体修飾の『の』。"}, {"text": "で", "is_correct": false, "explanation": "場所・手段を示す。「特定で人だけが」では文の意味が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "相手・並列を示す。「特定と人だけ」と並べる意味にならない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す。「特定から人」とは言えず、修飾の場面に合わない。"}], "correct_answer": "の", "explanations": {"の": "「特定の人」となり、『特定』が『人』を修飾する連体修飾の『の』。", "で": "場所・手段を示す。「特定で人だけが」では文の意味が成り立たない。", "と": "相手・並列を示す。「特定と人だけ」と並べる意味にならない。", "から": "起点を示す。「特定から人」とは言えず、修飾の場面に合わない。"}, "error_tags": {"で": "場所・手段を示す", "と": "相手・並列を示す", "から": "起点・理由を示す"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不特定", "is_correct": true, "explanation": "『特定』の対義語。『特定の時間帯』に対し、区別のない時間を指す。"}, {"text": "一括", "is_correct": false, "explanation": "まとめて扱う意味で、特定の対義語ではない。"}, {"text": "平凡", "is_correct": false, "explanation": "ありふれて目立たない意味で、区別の対義語にはならない。"}, {"text": "混合", "is_correct": false, "explanation": "いくつものものを混ぜ合わせることを指し、特定の対義語ではない。"}], "correct_answer": "不特定", "explanations": {"不特定": "『特定』の対義語。『特定の時間帯』に対し、区別のない時間を指す。", "一括": "まとめて扱う意味で、特定の対義語ではない。", "平凡": "ありふれて目立たない意味で、区別の対義語にはならない。", "混合": "いくつものものを混ぜ合わせることを指し、特定の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '816badd2-2b50-4e3f-a98a-f685001f1828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35644, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "あるものだけが持つ、ちがうものと区別するための大切な性質のこと。", "primary_collocate": null, "pronunciation": "とくてい", "ipa": "tokɯtei", "syllable_count": 4, "sentences": [{"text": "この店は特定のお客さんにだけ割引券を配っている。", "target_word": "特定", "complexity_tier": "T3", "furigana": "この店は特定[とくてい]のお客さんにだけ割引券を配っている。", "sentence_source": "generated"}, {"text": "この薬は特定の病気にだけ効きます。", "target_word": "特定", "complexity_tier": "T3", "furigana": "この薬[くすり]は特定[とくてい]の病気[びょうき]にだけ効[き]きます。", "sentence_source": "generated"}, {"text": "特定の人だけが入れる部屋なので、鍵がかかっています。", "target_word": "特定", "complexity_tier": "T3", "furigana": "特定[とくてい]の人[ひと]だけが入[はい]れる部屋[へや]なので、鍵[かぎ]がかかっています。", "sentence_source": "generated"}, {"text": "この地図アプリは特定の地域の店だけを表示する。", "target_word": "特定", "complexity_tier": "T3", "furigana": "この地図アプリは特定[とくてい]の地域の店だけを表示する。", "sentence_source": "generated"}, {"text": "特定の条件を満たさない人は、このサービスを使えない。", "target_word": "特定", "complexity_tier": "T3", "furigana": "特定[とくてい]の条件を満たさない人は、このサービスを使えない。", "sentence_source": "generated"}, {"text": "彼女は特定の店でしか服を買わない。", "target_word": "特定", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は特定[とくてい]の店[みせ]でしか服[ふく]を買[か]わない。", "sentence_source": "generated"}, {"text": "このアレルギーは特定の食べ物を食べたときに出ます。", "target_word": "特定", "complexity_tier": "T3", "furigana": "このアレルギーは特定[とくてい]の食[た]べ物[もの]を食[た]べたときに出[で]ます。", "sentence_source": "generated"}, {"text": "特定の人だけが読めるように、手紙に暗号を書いた。", "target_word": "特定", "complexity_tier": "T3", "furigana": "特定[とくてい]の人だけが読めるように、手紙に暗号を書いた。", "sentence_source": "generated"}, {"text": "私は特定の歌手が好きで、その人のコンサートには必ず行きます。", "target_word": "特定", "complexity_tier": "T3", "furigana": "私[わたし]は特定[とくてい]の歌手[かしゅ]が好[す]きで、その人[ひと]のコンサートには必[かなら]ず行[い]きます。", "sentence_source": "generated"}, {"text": "特定の時間帯にだけ、この道は混みます。", "target_word": "特定", "complexity_tier": "T3", "furigana": "特定[とくてい]の時間帯[じかんたい]にだけ、この道[みち]は混[こ]みます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "特定する", "label": "辞書形"}, {"form": "特定した", "label": "過去形"}, {"form": "特定される", "label": "受身形"}, {"form": "特定できる", "label": "可能形"}, {"form": "特定の", "label": "連体形"}], "register": "中立", "sense_fingerprint": "他と区別できるように、これと決まっていること。特定の〜、〜を特定する", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9a56563-cdf2-4fe2-ab54-3ae3af9e93b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35644, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "特定", "is_correct": true, "explanation": "「特定のお客さん」となり、ほかと区別された客の範囲を示す。空所に入る正解。"}, {"text": "天候", "is_correct": false, "explanation": "天気の傾向を表す名詞で、「天候のお客さん」とは言えないので空所に入らない。"}, {"text": "疲労", "is_correct": false, "explanation": "疲れの意味の名詞で、客の範囲を修飾できないので文が成り立たない。"}, {"text": "味覚", "is_correct": false, "explanation": "味を感じる感覚のことで、「味覚のお客さん」とは言えないので合わない。"}], "explanations": {"特定": "「特定のお客さん」となり、ほかと区別された客の範囲を示す。空所に入る正解。", "天候": "天気の傾向を表す名詞で、「天候のお客さん」とは言えないので空所に入らない。", "疲労": "疲れの意味の名詞で、客の範囲を修飾できないので文が成り立たない。", "味覚": "味を感じる感覚のことで、「味覚のお客さん」とは言えないので合わない。"}, "sentence_index": 0, "correct_answer": "特定"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "気温は特定のまま、夜になっても変わらなかった。", "explanation": "ここは〈一定〉の意味。特定は『ほかと区別して決まったもの』を指し、変わらない状態を表す語ではないので合わない。"}, {"text": "行き先は特定のまま、まだ決まっていない。", "explanation": "ここは〈未定〉の意味。『まだ決まっていない』と矛盾する文になり、決まっていることを指す特定とは合わない。"}, {"text": "警察は事故の原因をまだ特定できていない。", "explanation": "ここは動詞〈特定する〉（見分けて明らかにする）の意味。名詞の『特定の』はほかと区別される性質を指すので、原因を見分けるという文では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '816badd2-2b50-4e3f-a98a-f685001f1828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35644, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "特定", "is_correct": true, "explanation": "「特定の食べ物」となり、ほかと区別された食べ物の範囲を示す。空所に入る正解。"}, {"text": "香水", "is_correct": false, "explanation": "香りをつける液体で、「香水の食べ物」とは言えないので文が成り立たない。"}, {"text": "紙幣", "is_correct": false, "explanation": "お金の札を指し、食べ物を修飾できないので合わない。"}, {"text": "時刻", "is_correct": false, "explanation": "時間の一点を表す語で、食べ物の範囲を示せないので合わない。"}], "explanations": {"特定": "「特定の食べ物」となり、ほかと区別された食べ物の範囲を示す。空所に入る正解。", "香水": "香りをつける液体で、「香水の食べ物」とは言えないので文が成り立たない。", "紙幣": "お金の札を指し、食べ物を修飾できないので合わない。", "時刻": "時間の一点を表す語で、食べ物の範囲を示せないので合わない。"}, "sentence_index": 6, "correct_answer": "特定"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その日の天気は特定で、いつ雨が降るかわからない。", "explanation": "ここは〈不定〉の意味。『いつ降るかわからない』は決まっていないことなので、決まりを示す特定とは合わない。"}, {"text": "この割引は特定の誰でも使えます。", "explanation": "ここは〈不特定〉（だれでも対象になる）の意味。特定は限られた対象を指すので、限定のない文とは合わない。"}, {"text": "会議の日程は特定で、まだ誰にも伝えていない。", "explanation": "ここは〈確定〉の意味。特定は『ほかと区別される性質』を指し、日程が決まったという意味では使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '816badd2-2b50-4e3f-a98a-f685001f1828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35644, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この番組は特定を年齢層だけを対象にしている。", "corrected_sentence": "この番組は特定の年齢層だけを対象にしている。", "error_description": "『特定』の後には連体修飾の『の』が必要。『を』は目的語を示すため、『年齢層』を修飾できず、文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '816badd2-2b50-4e3f-a98a-f685001f1828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35644, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この割引は特定に会員にだけ適用されます。", "corrected_sentence": "この割引は特定の会員にだけ適用されます。", "error_description": "『特定』は名詞なので、後ろの名詞を修飾するには『の』が必要。『に』は場所や方向を示す助詞で、名詞を修飾できない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '816badd2-2b50-4e3f-a98a-f685001f1828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35646, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「気候があたたかく」となり、『気候』が『あたたかい』の主語になる『が』。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す。『気候をあたたかく』では主語と述語の関係が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "場所・手段を示す。『気候であたたかく』は不自然で、状態の主語にならない。"}, {"text": "と", "is_correct": false, "explanation": "相手・並列を示す。『気候とあたたかく』は意味が通らない。"}], "correct_answer": "が", "explanations": {"が": "「気候があたたかく」となり、『気候』が『あたたかい』の主語になる『が』。", "を": "目的語を示す。『気候をあたたかく』では主語と述語の関係が成り立たない。", "で": "場所・手段を示す。『気候であたたかく』は不自然で、状態の主語にならない。", "と": "相手・並列を示す。『気候とあたたかく』は意味が通らない。"}, "error_tags": {"を": "目的語を示す", "で": "場所・手段を示す", "と": "相手・並列を示す"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '816badd2-2b50-4e3f-a98a-f685001f1828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35646, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「乾燥した気候に合う」となり、『気候』に『合う』が続く相手を示す『に』。"}, {"text": "から", "is_correct": false, "explanation": "起点・理由を示す。『気候から合う』とは言えず、文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示す。『気候より合う』は意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す。『気候へ合う』は不自然で、合う相手を表せない。"}], "correct_answer": "に", "explanations": {"に": "「乾燥した気候に合う」となり、『気候』に『合う』が続く相手を示す『に』。", "から": "起点・理由を示す。『気候から合う』とは言えず、文が成り立たない。", "より": "比較を示す。『気候より合う』は意味が通らない。", "へ": "方向を示す。『気候へ合う』は不自然で、合う相手を表せない。"}, "error_tags": {"から": "起点・理由を示す", "より": "比較を示す", "へ": "方向を示す"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '816badd2-2b50-4e3f-a98a-f685001f1828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35646, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "その場所の、長い間にわたる天気のようすのことです。", "primary_collocate": null, "pronunciation": "きこう", "ipa": "kikoː", "syllable_count": 3, "sentences": [{"text": "北海道は気候が涼しいので、夏でも過ごしやすいです。", "target_word": "気候", "complexity_tier": "T3", "furigana": "北海道[ほっかいどう]は気候[きこう]が涼[すず]しいので、夏[なつ]でも過[す]ごしやすいです。", "sentence_source": "generated"}, {"text": "この地方は気候があたたかく、冬でも雪がほとんど降りません。", "target_word": "気候", "complexity_tier": "T3", "furigana": "この地方[ちほう]は気候[きこう]があたたかく、冬[ふゆ]でも雪[ゆき]がほとんど降[ふ]りません。", "sentence_source": "generated"}, {"text": "気候が変わると、育てられる野菜も変わります。", "target_word": "気候", "complexity_tier": "T3", "furigana": "気候[きこう]が変[か]わると、育[そだ]てられる野菜[やさい]も変[か]わります。", "sentence_source": "generated"}, {"text": "沖縄の気候は日本の他の地域とかなりちがいます。", "target_word": "気候", "complexity_tier": "T3", "furigana": "沖縄[おきなわ]の気候[きこう]は日本[にほん]の他[ほか]の地域[ちいき]とかなりちがいます。", "sentence_source": "generated"}, {"text": "私は暑い気候が苦手なので、夏は涼しい山で過ごします。", "target_word": "気候", "complexity_tier": "T3", "furigana": "私[わたし]は暑[あつ]い気候[きこう]が苦手[にがて]なので、夏[なつ]は涼[すず]しい山[やま]で過[す]ごします。", "sentence_source": "generated"}, {"text": "気候のよい春になったら、みんなで公園に行きたいです。", "target_word": "気候", "complexity_tier": "T3", "furigana": "気候[きこう]のよい春[はる]になったら、みんなで公園[こうえん]に行[い]きたいです。", "sentence_source": "generated"}, {"text": "地球の気候が変化して、世界の各地で大雨が増えています。", "target_word": "気候", "complexity_tier": "T3", "furigana": "地球[ちきゅう]の気候[きこう]が変化[へんか]して、世界[せかい]の各地[かくち]で大雨[おおあめ]が増[ふ]えています。", "sentence_source": "generated"}, {"text": "乾燥した気候に合う植物だけが、この砂漠で育ちます。", "target_word": "気候", "complexity_tier": "T3", "furigana": "乾燥[かんそう]した気候[きこう]に合[あ]う植物[しょくぶつ]だけが、この砂漠[さばく]で育[そだ]ちます。", "sentence_source": "generated"}, {"text": "旅行の前に、行き先の気候を調べて服を選びました。", "target_word": "気候", "complexity_tier": "T3", "furigana": "旅行[りょこう]の前[まえ]に、行[い]き先[さき]の気候[きこう]を調[しら]べて服[ふく]を選[えら]びました。", "sentence_source": "generated"}, {"text": "この国は雨が少ない気候なので、水を大切に使っています。", "target_word": "気候", "complexity_tier": "T3", "furigana": "この国[くに]は雨[あめ]が少[すく]ない気候[きこう]なので、水[みず]を大切[たいせつ]に使[つか]っています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "気候", "label": "基本形"}, {"form": "気候の", "label": "連体形"}], "register": "中立", "sense_fingerprint": "ある地域の、一年を通した長い期間の天気の傾向。その日の天気ではない", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9a56563-cdf2-4fe2-ab54-3ae3af9e93b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35646, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "気候", "is_correct": true, "explanation": "「北海道は気候が涼しい」となり、その地方の長い期間の天気の傾向を主語にする。空所に入る正解。"}, {"text": "体温", "is_correct": false, "explanation": "人の体の温度を指し、地域の涼しさを表す言い方として合わない。"}, {"text": "旋律", "is_correct": false, "explanation": "メロディーの意味で、土地の様子を言う文には合わない。"}, {"text": "感情", "is_correct": false, "explanation": "心の動きを指し、地域が涼しいとは言わないので合わない。"}], "explanations": {"気候": "「北海道は気候が涼しい」となり、その地方の長い期間の天気の傾向を主語にする。空所に入る正解。", "体温": "人の体の温度を指し、地域の涼しさを表す言い方として合わない。", "旋律": "メロディーの意味で、土地の様子を言う文には合わない。", "感情": "心の動きを指し、地域が涼しいとは言わないので合わない。"}, "sentence_index": 0, "correct_answer": "気候"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今日の気候は朝から雨で、夕方には晴れる。", "explanation": "ここは〈天気〉の意味。気候は長い期間の傾向なので、一日の移り変わりには使わないため合わない。"}, {"text": "今日の気候は三十度だった。", "explanation": "ここは〈気温〉の意味。今の温度の数値を言う語で、長期の傾向を表す気候とは違う。"}, {"text": "この地域は気候が険しく、登山道が少ない。", "explanation": "ここは〈地形〉の意味。山や谷のかたちを指す語で、天気の傾向である気候とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '816badd2-2b50-4e3f-a98a-f685001f1828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35646, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "気候", "is_correct": true, "explanation": "「地球の気候が変化して」となり、地球全体の長期的な天気の傾向を主語にする。空所に入る正解。"}, {"text": "衣服", "is_correct": false, "explanation": "身につけるものを指し、地球の変化を主語にする文には合わない。"}, {"text": "眠気", "is_correct": false, "explanation": "眠たい感覚を指し、地球の変化を表す主語にはならない。"}, {"text": "指紋", "is_correct": false, "explanation": "指の模様を指し、地球全体の変化を言う文には合わない。"}], "explanations": {"気候": "「地球の気候が変化して」となり、地球全体の長期的な天気の傾向を主語にする。空所に入る正解。", "衣服": "身につけるものを指し、地球の変化を主語にする文には合わない。", "眠気": "眠たい感覚を指し、地球の変化を表す主語にはならない。", "指紋": "指の模様を指し、地球全体の変化を言う文には合わない。"}, "sentence_index": 6, "correct_answer": "気候"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女の気候は穏やかで、怒ることはない。", "explanation": "ここは〈性格〉の意味。人の性質を言う語で、天気の傾向を表す気候とは合わない。"}, {"text": "この店は気候が広く、客が多い。", "explanation": "ここは〈面積〉の意味。『広い』は場所の大きさを言う語で、天気の傾向を表す気候には使えないので合わない。"}, {"text": "この町は気候が高く、買い物が大変だ。", "explanation": "ここは〈物価〉の意味。ものの値段の高さを言う語で、気候の高低とは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '816badd2-2b50-4e3f-a98a-f685001f1828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35646, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この島は気候を温暖で、一年中過ごしやすい。", "corrected_sentence": "この島は気候が温暖で、一年中過ごしやすい。", "error_description": "『気候』は主語になるので『が』が正しい。『を』は目的語を示すため、『温暖だ』の主語にはできない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '816badd2-2b50-4e3f-a98a-f685001f1828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35646, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "近年、この町の気候が増えて、雪の日が減った。", "corrected_sentence": "近年、この町の気候が寒冷化して、雪の日が減った。", "error_description": "『気候』の変化は『寒冷化する』などで表す。『増える』は数量を表す語で、気候の変化には使えない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '816badd2-2b50-4e3f-a98a-f685001f1828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
