INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35648, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「条件をつける」で、「つける」の目的語として「条件」を示す。"}, {"text": "が", "is_correct": false, "explanation": "「つける」は他動詞なので、「条件がつける」と条件を主語にはできない。"}, {"text": "で", "is_correct": false, "explanation": "「条件でつける」は手段の意味になり、「つける」の目的語を示せない。"}, {"text": "と", "is_correct": false, "explanation": "「条件とつける」は並列・相手の意味になり、目的語として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "正解。「条件をつける」で、「つける」の目的語として「条件」を示す。", "が": "「つける」は他動詞なので、「条件がつける」と条件を主語にはできない。", "で": "「条件でつける」は手段の意味になり、「つける」の目的語を示せない。", "と": "「条件とつける」は並列・相手の意味になり、目的語として成り立たない。"}, "error_tags": {"が": "主語", "で": "手段", "と": "並列・相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '041781df-7a43-4b3a-ab10-d05bb4a56140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35648, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かをするために必要なことや、決まりのこと。", "primary_collocate": null, "pronunciation": "じょうけん", "ipa": "dʑoːkeɴ", "syllable_count": 4, "sentences": [{"text": "公園で遊んでもいいが、宿題を終わらせるという条件がある。", "target_word": "条件", "complexity_tier": "T3", "furigana": "公園[こうえん]で遊[あそ]んでもいいが、宿題[しゅくだい]を終[お]わらせるという条件[じょうけん]がある。", "sentence_source": "generated"}, {"text": "このクーポンを使う条件は、千円以上買うことだ。", "target_word": "条件", "complexity_tier": "T3", "furigana": "このクーポンを使[つか]う条件[じょうけん]は、千円[せんえん]以上[いじょう]買[か]うことだ。", "sentence_source": "generated"}, {"text": "先生は、静かにするという条件で、教室を使わせてくれた。", "target_word": "条件", "complexity_tier": "T3", "furigana": "先生[せんせい]は、静[しず]かにするという条件[じょうけん]で、教室[きょうしつ]を使[つか]わせてくれた。", "sentence_source": "generated"}, {"text": "犬を飼う条件として、毎日散歩に行く約束をした。", "target_word": "条件", "complexity_tier": "T3", "furigana": "犬[いぬ]を飼[か]う条件[じょうけん]として、毎日[まいにち]散歩[さんぽ]に行[い]く約束[やくそく]をした。", "sentence_source": "generated"}, {"text": "条件が変わったので、旅行の計画をやり直した。", "target_word": "条件", "complexity_tier": "T3", "furigana": "条件[じょうけん]が変[か]わったので、旅行[りょこう]の計画[けいかく]をやり直[なお]した。", "sentence_source": "generated"}, {"text": "大きな会社に入るには、いくつか条件を満たす必要がある。", "target_word": "条件", "complexity_tier": "T3", "furigana": "大[おお]きな会社[かいしゃ]に入[はい]るには、いくつか条件[じょうけん]を満[み]たす必要[ひつよう]がある。", "sentence_source": "generated"}, {"text": "兄は、家賃が安いことを一番の条件にして、部屋を探した。", "target_word": "条件", "complexity_tier": "T3", "furigana": "兄[あに]は、家賃[やちん]が安[やす]いことを一番[いちばん]の条件[じょうけん]にして、部屋[へや]を探[さが]した。", "sentence_source": "generated"}, {"text": "彼女は条件をつけずに、手伝ってくれた。", "target_word": "条件", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は条件[じょうけん]をつけずに、手伝[てつだ]ってくれた。", "sentence_source": "generated"}, {"text": "参加する条件は、十八歳以上であることだ。", "target_word": "条件", "complexity_tier": "T3", "furigana": "参加[さんか]する条件[じょうけん]は、十八歳[じゅうはっさい]以上[いじょう]であることだ。", "sentence_source": "generated"}, {"text": "条件を読まないでサインすると、あとで困ることがある。", "target_word": "条件", "complexity_tier": "T3", "furigana": "条件[じょうけん]を読[よ]まないでサインすると、あとで困[こま]ることがある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "条件", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "何かをする・認めてもらうために守るべきことや決まり", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b8e48ae-ce80-40b8-bedd-e93621d51cd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35648, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "条件", "is_correct": true, "explanation": "正解。「宿題を終わらせるという条件」で、遊ぶために守るべき決まりを表す。"}, {"text": "季節", "is_correct": false, "explanation": "「〜という季節がある」は決まりの意味にならず、文が通らない。"}, {"text": "色", "is_correct": false, "explanation": "色は決まりを表さないので、「〜という色がある」は意味が通らない。"}, {"text": "時計", "is_correct": false, "explanation": "時計は決まりを表さないので、「〜という時計がある」は不自然。"}], "explanations": {"条件": "正解。「宿題を終わらせるという条件」で、遊ぶために守るべき決まりを表す。", "季節": "「〜という季節がある」は決まりの意味にならず、文が通らない。", "色": "色は決まりを表さないので、「〜という色がある」は意味が通らない。", "時計": "時計は決まりを表さないので、「〜という時計がある」は不自然。"}, "sentence_index": 0, "correct_answer": "条件"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は条件が美しく、みんなに好かれる。", "explanation": "ここは〈外見〉の意味。条件は決まりや取り決めを指すので、人の容姿には使えない。"}, {"text": "彼女は条件が悲しくて、ずっと泣いていた。", "explanation": "ここは〈感情〉の意味。条件は感情を持たないので、悲しみで泣く話には合わない。"}, {"text": "この茶は、条件がよく香る。", "explanation": "ここは〈香り〉の意味。条件は香りを出さないので、お茶の香りを表す文には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '041781df-7a43-4b3a-ab10-d05bb4a56140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35648, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "条件", "is_correct": true, "explanation": "正解。「一番の条件にして」で、部屋選びで重視する決まりや基準を表す。"}, {"text": "天気", "is_correct": false, "explanation": "「一番の天気にして部屋を探した」は意味が通らない。"}, {"text": "歌", "is_correct": false, "explanation": "「一番の歌にして部屋を探した」は意味が通らない。"}, {"text": "名前", "is_correct": false, "explanation": "「一番の名前にして部屋を探した」は意味が通らない。"}], "explanations": {"条件": "正解。「一番の条件にして」で、部屋選びで重視する決まりや基準を表す。", "天気": "「一番の天気にして部屋を探した」は意味が通らない。", "歌": "「一番の歌にして部屋を探した」は意味が通らない。", "名前": "「一番の名前にして部屋を探した」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "条件"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この箱は、条件が四角い。", "explanation": "ここは〈形〉の意味。条件には形がないので、箱の形を表す文には合わない。"}, {"text": "この部屋は、条件がよく響く。", "explanation": "ここは〈音〉の意味。条件は響くものではないので、部屋の音の話には合わない。"}, {"text": "このスープは、条件が濃い。", "explanation": "ここは〈味〉の意味。条件は濃い薄いを持たないので、スープの味には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '041781df-7a43-4b3a-ab10-d05bb4a56140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35648, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "犬を飼うという条件が、マンションに入れてもらった。", "corrected_sentence": "犬を飼うという条件で、マンションに入れてもらった。", "error_description": "「条件」に続く助詞の誤り。正しくは「〜という条件で」で、「条件が」では主語になれず、入れてもらう動作の主体にならない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '041781df-7a43-4b3a-ab10-d05bb4a56140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35648, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "安全性を条件から加えて、この車を選んだ。", "corrected_sentence": "安全性を条件に加えて、この車を選んだ。", "error_description": "「条件」に続く助詞の誤り。正しくは「条件に加える」（判断材料に入れる）で、「条件から」は起点の意味になり不自然になる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '041781df-7a43-4b3a-ab10-d05bb4a56140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35649, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '041781df-7a43-4b3a-ab10-d05bb4a56140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35649, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。「条件に合う」で、基準となる条件に適合することを示す。"}, {"text": "から", "is_correct": false, "explanation": "「条件から合う」は起点を示し、適合の意味にならない。"}, {"text": "より", "is_correct": false, "explanation": "「条件より合う」は比較を示すので、適合を表せない。"}, {"text": "へ", "is_correct": false, "explanation": "「条件へ合う」は方向を示すが、適合の意味にはならない。"}], "correct_answer": "に", "explanations": {"に": "正解。「条件に合う」で、基準となる条件に適合することを示す。", "から": "「条件から合う」は起点を示し、適合の意味にならない。", "より": "「条件より合う」は比較を示すので、適合を表せない。", "へ": "「条件へ合う」は方向を示すが、適合の意味にはならない。"}, "error_tags": {"から": "起点", "より": "比較", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '041781df-7a43-4b3a-ab10-d05bb4a56140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35649, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ある事柄が成り立つために必要な状況や取り決め。", "primary_collocate": null, "pronunciation": "じょうけん", "ipa": "dʑoːkeɴ", "syllable_count": 4, "sentences": [{"text": "日の出と共に目覚める鶏の健康こそが、栄養豊富な卵を産んでもらうための条件だからである。", "target_word": "条件", "complexity_tier": "T4", "furigana": "日[ひ]の出[で]と共[とも]に目覚[めざ]める鶏[にわとり]の健康[けんこう]こそが、栄養豊富[えいようほうふ]な卵[たまご]を産[う]んでもらうための条件[じょうけん]だからである。", "sentence_source": "mined"}, {"text": "給料は高いが、仕事の条件が厳しくて、応募する人が少ない。", "target_word": "条件", "complexity_tier": "T3", "furigana": "給料[きゅうりょう]は高[たか]いが、仕事[しごと]の条件[じょうけん]が厳[きび]しくて、応募[おうぼ]する人[ひと]が少[すく]ない。", "sentence_source": "generated"}, {"text": "私は駅に近いという条件で、新しい家を探している。", "target_word": "条件", "complexity_tier": "T3", "furigana": "私[わたし]は駅[えき]に近[ちか]いという条件[じょうけん]で、新[あたら]しい家[いえ]を探[さが]している。", "sentence_source": "generated"}, {"text": "試験に受かることが、入学するための条件だ。", "target_word": "条件", "complexity_tier": "T3", "furigana": "試験[しけん]に受[う]かることが、入学[にゅうがく]するための条件[じょうけん]だ。", "sentence_source": "generated"}, {"text": "会社は、毎日残業しないという条件で、彼を雇った。", "target_word": "条件", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は、毎日[まいにち]残業[ざんぎょう]しないという条件[じょうけん]で、彼[かれ]を雇[やと]った。", "sentence_source": "generated"}, {"text": "二つの店の条件を比べてから、契約する店を決めた。", "target_word": "条件", "complexity_tier": "T3", "furigana": "二[ふた]つの店[みせ]の条件[じょうけん]を比[くら]べてから、契約[けいやく]する店[みせ]を決[き]めた。", "sentence_source": "generated"}, {"text": "山田さんが出した条件を、私たちは全部受け入れた。", "target_word": "条件", "complexity_tier": "T3", "furigana": "山田[やまだ]さんが出[だ]した条件[じょうけん]を、私[わたし]たちは全部[ぜんぶ]受[う]け入[い]れた。", "sentence_source": "generated"}, {"text": "条件に合う人が見つからず、募集は来月まで続くことになった。", "target_word": "条件", "complexity_tier": "T3", "furigana": "条件[じょうけん]に合[あ]う人[ひと]が見[み]つからず、募集[ぼしゅう]は来月[らいげつ]まで続[つづ]くことになった。", "sentence_source": "generated"}, {"text": "必要な条件を満たしていないので、申し込みは受け付けられない。", "target_word": "条件", "complexity_tier": "T3", "furigana": "必要[ひつよう]な条件[じょうけん]を満[み]たしていないので、申[もう]し込[こ]みは受[う]け付[つ]けられない。", "sentence_source": "generated"}, {"text": "自由に使える時間があることを、仕事を選ぶ条件にしている。", "target_word": "条件", "complexity_tier": "T3", "furigana": "自由[じゆう]に使[つか]える時間[じかん]があることを、仕事[しごと]を選[えら]ぶ条件[じょうけん]にしている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "条件", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "物事が成り立つために満たすべき要件や取り決め", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b8e48ae-ce80-40b8-bedd-e93621d51cd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35649, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "条件", "is_correct": true, "explanation": "正解。「健康こそが…条件」で、鶏の健康が卵を産んでもらう前提になるため「条件」が入る。"}, {"text": "教科書", "is_correct": false, "explanation": "「〜ための教科書だからである」は前提の意味にならず、文が通らない。"}, {"text": "歌", "is_correct": false, "explanation": "歌は前提を表さないので、「〜ための歌だからである」は意味が通らない。"}, {"text": "名前", "is_correct": false, "explanation": "名前は前提の意味にならず、「〜ための名前」は不自然な文になる。"}], "explanations": {"条件": "正解。「健康こそが…条件」で、鶏の健康が卵を産んでもらう前提になるため「条件」が入る。", "教科書": "「〜ための教科書だからである」は前提の意味にならず、文が通らない。", "歌": "歌は前提を表さないので、「〜ための歌だからである」は意味が通らない。", "名前": "名前は前提の意味にならず、「〜ための名前」は不自然な文になる。"}, "sentence_index": 0, "correct_answer": "条件"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会議が延期された条件は、社長が海外へ出張していたからだ。", "explanation": "ここは〈理由〉の意味。条件は成り立つための前提を表すので、延期の原因を説明する文には合わない。"}, {"text": "彼は英語の条件を持っているので、この仕事を任された。", "explanation": "ここは〈資格〉の意味。人が持つ能力や免許は資格と言い、条件を持つとは言わないので合わない。"}, {"text": "彼女は条件が派手なので、いつも明るい色の服を選ぶ。", "explanation": "ここは〈好み〉の意味。条件は必要な状況を指すので、人の服の好みを表すのには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '041781df-7a43-4b3a-ab10-d05bb4a56140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35649, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "条件", "is_correct": true, "explanation": "正解。「山田さんが出した条件を受け入れた」で、相手が示した取り決めの条件を指す。"}, {"text": "時計", "is_correct": false, "explanation": "「出した時計を受け入れた」は意味が通らない。"}, {"text": "季節", "is_correct": false, "explanation": "「出した季節を受け入れた」は意味が通らない。"}, {"text": "色", "is_correct": false, "explanation": "「出した色を受け入れた」は不自然で、受け入れる対象にならない。"}], "explanations": {"条件": "正解。「山田さんが出した条件を受け入れた」で、相手が示した取り決めの条件を指す。", "時計": "「出した時計を受け入れた」は意味が通らない。", "季節": "「出した季節を受け入れた」は意味が通らない。", "色": "「出した色を受け入れた」は不自然で、受け入れる対象にならない。"}, "sentence_index": 6, "correct_answer": "条件"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この花は、条件が赤い。", "explanation": "ここは〈色〉の意味。条件には色がないので、花の色を表す文には合わない。"}, {"text": "犬は条件が鋭いので、遠くの匂いも分かる。", "explanation": "ここは〈嗅覚〉の意味。条件には鋭さという性質がないので、感覚の鋭さには使えない。"}, {"text": "この棚は、条件が二メートルある。", "explanation": "ここは〈高さ〉の意味。条件は数値で測れる寸法を持たないので、棚の高さには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '041781df-7a43-4b3a-ab10-d05bb4a56140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35649, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会社は、経験者という条件を新人を募集している。", "corrected_sentence": "会社は、経験者という条件で新人を募集している。", "error_description": "「条件」に続く助詞の誤り。正しくは「〜という条件で」（〜の条件のもとで）で、「条件を」では目的語が重なり文として不自然になる。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '041781df-7a43-4b3a-ab10-d05bb4a56140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35649, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "試験に合格することを条件で、奨学金が出る。", "corrected_sentence": "試験に合格することを条件に、奨学金が出る。", "error_description": "「条件」に続く助詞の誤り。正しくは「〜を条件に」（〜を前提として）で、「条件で」は手段・場所の意味になり不自然になる。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '041781df-7a43-4b3a-ab10-d05bb4a56140') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
