INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35652, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "周りのものや様子のこと。", "primary_collocate": null, "pronunciation": "かんきょう", "ipa": "kaŋkʲoː", "syllable_count": 4, "sentences": [{"text": "新しい環境になれるまで、少し時間がかかった。", "target_word": "環境", "complexity_tier": "T3", "furigana": "新[あたら]しい環境[かんきょう]になれるまで、少[すこ]し時間[じかん]がかかった。", "sentence_source": "generated"}, {"text": "子どもが育つ環境は、できるだけ静かなほうがいい。", "target_word": "環境", "complexity_tier": "T3", "furigana": "子[こ]どもが育[そだ]つ環境[かんきょう]は、できるだけ静[しず]かなほうがいい。", "sentence_source": "generated"}, {"text": "工場の排水が、川の環境を悪くしている。", "target_word": "環境", "complexity_tier": "T3", "furigana": "工場[こうじょう]の排水[はいすい]が、川[かわ]の環境[かんきょう]を悪[わる]くしている。", "sentence_source": "generated"}, {"text": "家の環境が変わって、彼は勉強に集中できなくなった。", "target_word": "環境", "complexity_tier": "T3", "furigana": "家[いえ]の環境[かんきょう]が変[か]わって、彼[かれ]は勉強[べんきょう]に集中[しゅうちゅう]できなくなった。", "sentence_source": "generated"}, {"text": "引っ越しをして、通勤の環境がずいぶんよくなった。", "target_word": "環境", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]しをして、通勤[つうきん]の環境[かんきょう]がずいぶんよくなった。", "sentence_source": "generated"}, {"text": "動物園では、動物がくらす環境を自然に近づけている。", "target_word": "環境", "complexity_tier": "T3", "furigana": "動物園[どうぶつえん]では、動物[どうぶつ]がくらす環境[かんきょう]を自然[しぜん]に近[ちか]づけている。", "sentence_source": "generated"}, {"text": "環境が合わなかったので、彼女は一年で会社をやめた。", "target_word": "環境", "complexity_tier": "T3", "furigana": "環境[かんきょう]が合[あ]わなかったので、彼女[かのじょ]は一年[いちねん]で会社[かいしゃ]をやめた。", "sentence_source": "generated"}, {"text": "ごみを減らすことは、地球の環境を守る第一歩だ。", "target_word": "環境", "complexity_tier": "T3", "furigana": "ごみを減[へ]らすことは、地球[ちきゅう]の環境[かんきょう]を守[まも]る第一歩[だいいっぽ]だ。", "sentence_source": "generated"}, {"text": "勉強しやすい環境をつくるため、机を窓の近くに置いた。", "target_word": "環境", "complexity_tier": "T3", "furigana": "勉強[べんきょう]しやすい環境[かんきょう]をつくるため、机[つくえ]を窓[まど]の近[ちか]くに置[お]いた。", "sentence_source": "generated"}, {"text": "暑い環境で働くときは、水をこまめに飲むべきだ。", "target_word": "環境", "complexity_tier": "T3", "furigana": "暑[あつ]い環境[かんきょう]で働[はたら]くときは、水[みず]をこまめに飲[の]むべきだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "環境", "label": "基本形"}], "register": "標準・常体", "sense_fingerprint": "人や生き物を取り巻く周りの物や状況", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T1: contains vocabulary far above tier T1: くらす (Zipf 2.39)']::text[], '1b41b00e-bd5b-4a04-9778-a8d726c80abd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35652, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "環境", "is_correct": true, "explanation": "「新しい環境になれる」は、周りの状況に慣れるという意味で自然に続く。"}, {"text": "理由", "is_correct": false, "explanation": "「新しい理由になれる」は意味が通らない。理由は慣れる対象ではない。"}, {"text": "目的", "is_correct": false, "explanation": "「新しい目的になれる」は不自然。目的は身体や感覚で慣れるものではない。"}, {"text": "根拠", "is_correct": false, "explanation": "「新しい根拠になれる」は意味が合わない。根拠は慣れる対象にならない。"}], "explanations": {"環境": "「新しい環境になれる」は、周りの状況に慣れるという意味で自然に続く。", "理由": "「新しい理由になれる」は意味が通らない。理由は慣れる対象ではない。", "目的": "「新しい目的になれる」は不自然。目的は身体や感覚で慣れるものではない。", "根拠": "「新しい根拠になれる」は意味が合わない。根拠は慣れる対象にならない。"}, "sentence_index": 0, "correct_answer": "環境"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は課長に昇進して、環境がぐんと上がった。", "explanation": "ここは〈地位〉の意味。環境は周りの場や条件を指し、社内での地位が上がるという意味では使わない。"}, {"text": "この仕事は環境が豊富で、即戦力になる。", "explanation": "ここは〈経験〉の意味。環境は周りの場や条件を指し、積んできた経験の多さを言うときには使わない。"}, {"text": "彼女は環境が高いので、どの仕事も任されている。", "explanation": "ここは〈能力〉の意味。環境は高い・低いで測るものではないので、能力の代わりには使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121da1a8-0ab0-4409-b06d-231fafdff7b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35652, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "環境", "is_correct": true, "explanation": "「環境が合わなかった」は、住む場所や職場の状況が自分に合わないという意味で自然。"}, {"text": "結論", "is_correct": false, "explanation": "「結論が合わなかった」は、ここでは不自然。結論は合う・合わないで語る対象ではない。"}, {"text": "寿命", "is_correct": false, "explanation": "「寿命が合わなかった」は意味が通らない。寿命は合う・合わないの対象ではない。"}, {"text": "誤算", "is_correct": false, "explanation": "「誤算が合わなかった」は不自然。誤算は合わせるものではない。"}], "explanations": {"環境": "「環境が合わなかった」は、住む場所や職場の状況が自分に合わないという意味で自然。", "結論": "「結論が合わなかった」は、ここでは不自然。結論は合う・合わないで語る対象ではない。", "寿命": "「寿命が合わなかった」は意味が通らない。寿命は合う・合わないの対象ではない。", "誤算": "「誤算が合わなかった」は不自然。誤算は合わせるものではない。"}, "sentence_index": 6, "correct_answer": "環境"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この作品は環境が深く、物語にすっと入り込める。", "explanation": "ここは〈背景〉の意味。環境は周りの場や条件を指し、物語の裏にある事情の深さを言うときには使わない。"}, {"text": "ボーナスの環境が増えた。", "explanation": "ここは〈金額〉の意味。環境は数で増減するものではないので、金額の代わりには使えない。"}, {"text": "彼は環境が弱いので、風邪をひきやすい。", "explanation": "ここは〈体質〉の意味。環境は強い・弱いで評価する性質ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121da1a8-0ab0-4409-b06d-231fafdff7b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35652, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この会社は働きやすい環境で用意している。", "corrected_sentence": "この会社は働きやすい環境を用意している。", "error_description": "「用意する」の対象は「を」で示す。「で」は場所や手段を表すため誤り。正しくは「環境を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121da1a8-0ab0-4409-b06d-231fafdff7b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35652, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この施設は、子どもが安心して遊べる環境が整えている。", "corrected_sentence": "この施設は、子どもが安心して遊べる環境を整えている。", "error_description": "「整える」の対象は「を」で示す。「が」は主語を表すため誤り。正しくは「環境を」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121da1a8-0ab0-4409-b06d-231fafdff7b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35654, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "弱い", "is_correct": true, "explanation": "頑丈さが小さく、壊れやすいという意味で、「強い（頑丈）」の対義語。"}, {"text": "高い", "is_correct": false, "explanation": "高さや値段を表し、頑丈さの反対語にはならない。"}, {"text": "明るい", "is_correct": false, "explanation": "光や性格の明るさを表し、「強い」の対義語ではない。"}, {"text": "優しい", "is_correct": false, "explanation": "穏やかな性格を表し、頑丈さの反対語にはならない。"}], "correct_answer": "弱い", "explanations": {"弱い": "頑丈さが小さく、壊れやすいという意味で、「強い（頑丈）」の対義語。", "高い": "高さや値段を表し、頑丈さの反対語にはならない。", "明るい": "光や性格の明るさを表し、「強い」の対義語ではない。", "優しい": "穏やかな性格を表し、頑丈さの反対語にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9297dc18-f5ac-4488-a97e-eae535564182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35654, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "弱い", "is_correct": true, "explanation": "頑丈さが小さく、破れやすいという意味で、「強い（頑丈）」の対義語。"}, {"text": "軽い", "is_correct": false, "explanation": "重さが小さいことを表し、頑丈さの反対語ではない。"}, {"text": "大きい", "is_correct": false, "explanation": "大きさを表し、頑丈さの反対語にはならない。"}, {"text": "温かい", "is_correct": false, "explanation": "温度を表し、頑丈さの反対語にはならない。"}], "correct_answer": "弱い", "explanations": {"弱い": "頑丈さが小さく、破れやすいという意味で、「強い（頑丈）」の対義語。", "軽い": "重さが小さいことを表し、頑丈さの反対語ではない。", "大きい": "大きさを表し、頑丈さの反対語にはならない。", "温かい": "温度を表し、頑丈さの反対語にはならない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9297dc18-f5ac-4488-a97e-eae535564182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35654, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "何かがとてもしっかりしていることです。", "primary_collocate": null, "pronunciation": "つよい", "ipa": "tsɯjoi", "syllable_count": 3, "sentences": [{"text": "登山用のロープは強いので、人の体重を支えても切れない。", "target_word": "強い", "complexity_tier": "T3", "furigana": "登山用[とざんよう]のロープは強[つよ]いので、人[ひと]の体重[たいじゅう]を支[ささ]えても切[き]れない。", "sentence_source": "generated"}, {"text": "この橋は鉄でできていて、とても強いので大きなトラックも渡れる。", "target_word": "強い", "complexity_tier": "T3", "furigana": "この橋[はし]は鉄[てつ]でできていて、とても強[つよ]いので大[おお]きなトラックも渡[わた]れる。", "sentence_source": "generated"}, {"text": "地震に強い建物なので、大きな揺れでも壊れにくい。", "target_word": "強い", "complexity_tier": "T3", "furigana": "地震[じしん]に強[つよ]い建物[たてもの]なので、大[おお]きな揺[ゆ]れでも壊[こわ]れにくい。", "sentence_source": "generated"}, {"text": "この糸は細いのに強いから、重い荷物を縛っても切れない。", "target_word": "強い", "complexity_tier": "T3", "furigana": "この糸[いと]は細[ほそ]いのに強[つよ]いから、重[おも]い荷物[にもつ]を縛[しば]っても切[き]れない。", "sentence_source": "generated"}, {"text": "この靴は革が厚くて強いので、三年はいても破れない。", "target_word": "強い", "complexity_tier": "T3", "furigana": "この靴[くつ]は革[かわ]が厚[あつ]くて強[つよ]いので、三年[さんねん]はいても破[やぶ]れない。", "sentence_source": "generated"}, {"text": "強い箱に入れて送ったので、荷物は壊れずに届いた。", "target_word": "強い", "complexity_tier": "T3", "furigana": "強[つよ]い箱[はこ]に入[い]れて送[おく]ったので、荷物[にもつ]は壊[こわ]れずに届[とど]いた。", "sentence_source": "generated"}, {"text": "この机は天板が厚くて強いので、上に乗っても大丈夫だ。", "target_word": "強い", "complexity_tier": "T3", "furigana": "この机は天板[てんいた]が厚[あつ]くて強[つよ]いので、上[うえ]に乗[の]っても大丈夫[だいじょうぶ]だ。", "sentence_source": "generated"}, {"text": "土台が強い家は、風が吹いても倒れにくい。", "target_word": "強い", "complexity_tier": "T3", "furigana": "土台[どだい]が強[つよ]い家[いえ]は、風[かぜ]が吹[ふ]いても倒[たお]れにくい。", "sentence_source": "generated"}, {"text": "このガラスはとても強く、ボールが当たっても割れなかった。", "target_word": "強く", "complexity_tier": "T3", "furigana": "このガラスはとても強[つよ]く、ボールが当[あ]たっても割[わ]れなかった。", "sentence_source": "generated"}, {"text": "この紙は水に濡れても破れないほど強い。", "target_word": "強い", "complexity_tier": "T3", "furigana": "この紙[かみ]は水[みず]に濡[ぬ]れても破[やぶ]れないほど強[つよ]い。", "sentence_source": "generated"}], "morphological_forms": [{"form": "強い", "label": "終止形"}, {"form": "強く", "label": "連用形"}, {"form": "強くて", "label": "て形"}, {"form": "強かった", "label": "過去形"}, {"form": "強くない", "label": "否定形"}, {"form": "強ければ", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "物がしっかりしていて壊れにくい(頑丈さ)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T1: contains vocabulary far above tier T1: 渡れる (Zipf 2.36)','sentence 4 above tier T1: 3 words above tier T1 (max 2): 革 (Zipf 3.93), 厚く (Zipf 3.57), 破れ (Zipf 3.81)']::text[], 'd0118fb7-8c88-4730-aa9e-d75a197e3036') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35654, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "強い", "is_correct": true, "explanation": "終止形で、理由を表す「ので」に続く。「強いので」となる。"}, {"text": "強く", "is_correct": false, "explanation": "連用形のため、「ので」に続かない。「強くので」は不自然。"}, {"text": "強ければ", "is_correct": false, "explanation": "仮定形のため、「ので」に続かない。"}, {"text": "強め", "is_correct": false, "explanation": "「強める」の連用形で、形容詞として「ので」につながらない。"}], "explanations": {"強い": "終止形で、理由を表す「ので」に続く。「強いので」となる。", "強く": "連用形のため、「ので」に続かない。「強くので」は不自然。", "強ければ": "仮定形のため、「ので」に続かない。", "強め": "「強める」の連用形で、形容詞として「ので」につながらない。"}, "sentence_index": 0, "correct_answer": "強い"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "駅から家までは距離が強いので、毎朝バスで通っている。", "explanation": "ここは〈遠い〉の意味。距離の遠さは「強い」では表さず、「遠い」と言う。"}, {"text": "このパンは強いので、スープに浸して食べよう。", "explanation": "ここは〈硬い〉の意味。パンの硬さは「強い」では表さず、「硬い」と言う。"}, {"text": "夏は部屋の温度が強いので、エアコンが欠かせない。", "explanation": "ここは〈高い〉の意味。温度の高さは「強い」では表さず、「高い」と言う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9297dc18-f5ac-4488-a97e-eae535564182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35654, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "強い", "is_correct": true, "explanation": "終止形で、理由を表す「ので」に続く。「強いので」となる。"}, {"text": "強さ", "is_correct": false, "explanation": "名詞のため、「ので」に直接続かない。"}, {"text": "強み", "is_correct": false, "explanation": "名詞のため、「ので」に直接続かない。"}, {"text": "強そう", "is_correct": false, "explanation": "様態の形のため、「ので」に続かない。"}], "explanations": {"強い": "終止形で、理由を表す「ので」に続く。「強いので」となる。", "強さ": "名詞のため、「ので」に直接続かない。", "強み": "名詞のため、「ので」に直接続かない。", "強そう": "様態の形のため、「ので」に続かない。"}, "sentence_index": 6, "correct_answer": "強い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会議は時間が強くて、昼過ぎまでかかった。", "explanation": "ここは〈長い〉の意味。時間の長さは「強い」では表さず、「長い」と言う。"}, {"text": "この靴は値段が強いので、なかなか買えない。", "explanation": "ここは〈高い〉の意味。値段の高さを「強い」で表すことはない。"}, {"text": "この会社は規模が強いので、社員が多い。", "explanation": "ここは〈大きい〉の意味。規模の大きさを「強い」で表すことはない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9297dc18-f5ac-4488-a97e-eae535564182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35654, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この金具は鉄でできていて、とても強くので重い扉も支えられる。", "corrected_sentence": "この金具は鉄でできていて、とても強いので重い扉も支えられる。", "error_description": "理由を表す「ので」の前では終止形「強い」を使う。「強く」は連用形で、「強くので」は誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "強い", "is_correct": true, "explanation": "終止形で、理由を表す「ので」の前に置かれている。"}, {"text": "強く", "is_correct": false, "explanation": "連用形のため、「ので」に続かない。"}, {"text": "強くて", "is_correct": false, "explanation": "て形のため、「ので」に続かない。"}, {"text": "強ければ", "is_correct": false, "explanation": "仮定形のため、「ので」に続かない。"}], "correct_form": "強い", "base_form": "強い", "form_label": "終止形", "sentence_index": 1, "explanations": {"強い": "終止形で、理由を表す「ので」の前に置かれている。", "強く": "連用形のため、「ので」に続かない。", "強くて": "て形のため、「ので」に続かない。", "強ければ": "仮定形のため、「ので」に続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9297dc18-f5ac-4488-a97e-eae535564182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35654, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この棚は板が厚くて重さが強いので、本をたくさん載せても平気だ。", "corrected_sentence": "この棚は板が厚くて重さに強いので、本をたくさん載せても平気だ。", "error_description": "「重さに強い」は荷重に耐えるという意味。「重さが強い」は誤りで、助詞は「に」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "強い", "is_correct": true, "explanation": "連体形で、名詞「家」を修飾している。「強い家」となる。"}, {"text": "強さ", "is_correct": false, "explanation": "名詞「強さ」は連体修飾に使えず、「強さ家」とは続かない。"}, {"text": "強そう", "is_correct": false, "explanation": "様態の「そう」は「強そう」で言い切れず、「強そう家」とは続かない。"}, {"text": "強め", "is_correct": false, "explanation": "「強め」は名詞的に使う語で、「強め家」とは続かない。"}], "correct_form": "強い", "base_form": "強い", "form_label": "連体形", "sentence_index": 7, "explanations": {"強い": "連体形で、名詞「家」を修飾している。「強い家」となる。", "強さ": "名詞「強さ」は連体修飾に使えず、「強さ家」とは続かない。", "強そう": "様態の「そう」は「強そう」で言い切れず、「強そう家」とは続かない。", "強め": "「強め」は名詞的に使う語で、「強め家」とは続かない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9297dc18-f5ac-4488-a97e-eae535564182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35655, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "弱い", "is_correct": true, "explanation": "程度が小さく、影響を受けやすいという意味で、「強い（程度が大きい）」の対義語。"}, {"text": "高い", "is_correct": false, "explanation": "程度の高さを表すが、「強い」の対義語ではない。値段や高さの意味で使われる。"}, {"text": "明るい", "is_correct": false, "explanation": "光の明るさや性格を表し、「強い」の対義語にはならない。"}, {"text": "優しい", "is_correct": false, "explanation": "穏やかな性格を表し、程度や強さの反対語にはならない。"}], "correct_answer": "弱い", "explanations": {"弱い": "程度が小さく、影響を受けやすいという意味で、「強い（程度が大きい）」の対義語。", "高い": "程度の高さを表すが、「強い」の対義語ではない。値段や高さの意味で使われる。", "明るい": "光の明るさや性格を表し、「強い」の対義語にはならない。", "優しい": "穏やかな性格を表し、程度や強さの反対語にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9297dc18-f5ac-4488-a97e-eae535564182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35655, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "弱い", "is_correct": true, "explanation": "程度が小さいという意味で、「不安が強い」の対義語。"}, {"text": "速い", "is_correct": false, "explanation": "速さを表し、不安の強さの反対語にはならない。"}, {"text": "大きい", "is_correct": false, "explanation": "大きさを表し、程度の大小の反対語ではない。"}, {"text": "温かい", "is_correct": false, "explanation": "温度を表し、「強い」の対義語にはならない。"}], "correct_answer": "弱い", "explanations": {"弱い": "程度が小さいという意味で、「不安が強い」の対義語。", "速い": "速さを表し、不安の強さの反対語にはならない。", "大きい": "大きさを表し、程度の大小の反対語ではない。", "温かい": "温度を表し、「強い」の対義語にはならない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9297dc18-f5ac-4488-a97e-eae535564182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35655, 3, 'prompt1_core', '{"pos": "形容詞", "semantic_class": "property", "definition": "物事の程度が大きいこと。他からの影響を受けにくい様子。", "primary_collocate": null, "pronunciation": "つよい", "ipa": "tsɯjoi", "syllable_count": 3, "sentences": [{"text": "変化に適応し、自らの価値を高め続ける姿勢が、これからの職場では強く求められる。", "target_word": "強く", "complexity_tier": "T4", "furigana": "変化[へんか]に適応[てきおう]し、自[みずか]らの価値[かち]を高[たか]め続[つづ]ける姿勢[しせい]が、これからの職場[しょくば]では強[つよ]く求[もと]められる。", "sentence_source": "mined"}, {"text": "彼は誘惑に強い人で、甘い物を目の前にしても我慢できる。", "target_word": "強い", "complexity_tier": "T3", "furigana": "彼[かれ]は誘惑[ゆうわく]に強[つよ]い人[ひと]で、甘[あま]い物[もの]を目[め]の前[まえ]にしても我慢[がまん]できる。", "sentence_source": "generated"}, {"text": "台風が近づき、夜から風が強くなってきた。", "target_word": "強く", "complexity_tier": "T3", "furigana": "台風[たいふう]が近[ちか]づき、夜[よる]から風[かぜ]が強[つよ]くなってきた。", "sentence_source": "generated"}, {"text": "この薬は効果が強いので、飲む量を守ってください。", "target_word": "強い", "complexity_tier": "T3", "furigana": "この薬[くすり]は効果[こうか]が強[つよ]いので、飲[の]む量[りょう]を守[まも]ってください。", "sentence_source": "generated"}, {"text": "彼女は意志が強く、一度決めたことは最後までやり通す。", "target_word": "強く", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は意志[いし]が強[つよ]く、一度[いちど]決[き]めたことは最後[さいご]までやり通[とお]す。", "sentence_source": "generated"}, {"text": "寒さに強い植物なので、冬でも庭で育てられる。", "target_word": "強い", "complexity_tier": "T3", "furigana": "寒[さむ]さに強[つよ]い植物[しょくぶつ]なので、冬[ふゆ]でも庭[にわ]で育[そだ]てられる。", "sentence_source": "generated"}, {"text": "強い日差しの中を歩いたため、帰ってから頭が痛くなった。", "target_word": "強い", "complexity_tier": "T3", "furigana": "強[つよ]い日差[ひざ]しの中[なか]を歩[ある]いたため、帰[かえ]ってから頭[あたま]が痛[いた]くなった。", "sentence_source": "generated"}, {"text": "母は私の計画に強く反対したが、最後には応援してくれた。", "target_word": "強く", "complexity_tier": "T3", "furigana": "母[はは]は私[わたし]の計画[けいかく]に強[つよ]く反対[はんたい]したが、最後[さいご]には応援[おうえん]してくれた。", "sentence_source": "generated"}, {"text": "この洗剤は匂いが強いから、使うときは窓を開けましょう。", "target_word": "強い", "complexity_tier": "T3", "furigana": "この洗剤[せんざい]は匂[にお]いが強[つよ]いから、使[つか]うときは窓[まど]を開[あ]けましょう。", "sentence_source": "generated"}, {"text": "試験の前は不安が強くて、夜によく眠れなかった。", "target_word": "強く", "complexity_tier": "T3", "furigana": "試験[しけん]の前[まえ]は不安[ふあん]が強[つよ]くて、夜[よる]によく眠[ねむ]れなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "強い", "label": "終止形"}, {"form": "強く", "label": "連用形"}, {"form": "強くて", "label": "て形"}, {"form": "強かった", "label": "過去形"}, {"form": "強くない", "label": "否定形"}, {"form": "強ければ", "label": "仮定形"}], "register": "neutral", "sense_fingerprint": "程度が大きい・影響や刺激に屈しにくい(強度・耐性)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0118fb7-8c88-4730-aa9e-d75a197e3036') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35655, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "強く", "is_correct": true, "explanation": "連用形で、後ろの「求められる」を修飾できる。「強く求められる」となる。"}, {"text": "強かった", "is_correct": false, "explanation": "過去形のため文が続かない。「強かった求められる」は不自然。"}, {"text": "強ければ", "is_correct": false, "explanation": "仮定形のため、「求められる」に続かない。"}, {"text": "強さ", "is_correct": false, "explanation": "名詞なので、助詞なしで動詞「求められる」に直接続かない。"}], "explanations": {"強く": "連用形で、後ろの「求められる」を修飾できる。「強く求められる」となる。", "強かった": "過去形のため文が続かない。「強かった求められる」は不自然。", "強ければ": "仮定形のため、「求められる」に続かない。", "強さ": "名詞なので、助詞なしで動詞「求められる」に直接続かない。"}, "sentence_index": 0, "correct_answer": "強く"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このリュックは荷物が強くて、肩が痛くなる。", "explanation": "ここは〈重い〉の意味。荷物の重さは「強い」では表さず、「重い」と言う。"}, {"text": "この肉は強いので、よく煮込んでから食べよう。", "explanation": "ここは〈硬い〉の意味。肉の硬さは「強い」では表せず、「固い」と言う。"}, {"text": "この店の料理は値段が強いので、学生にはなかなか手が出ない。", "explanation": "ここは〈高い〉の意味。値段の高さを「強い」で表すことはない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9297dc18-f5ac-4488-a97e-eae535564182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35655, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "強い", "is_correct": true, "explanation": "連体形で、後ろの名詞「日差し」を修飾する。"}, {"text": "強く", "is_correct": false, "explanation": "連用形は名詞を直接修飾できない。「強く日差し」は不自然。"}, {"text": "強め", "is_correct": false, "explanation": "「強めの日差し」なら可能だが、「の」がなければ名詞を修飾できない。"}, {"text": "強くて", "is_correct": false, "explanation": "て形のため、名詞を修飾できない。"}], "explanations": {"強い": "連体形で、後ろの名詞「日差し」を修飾する。", "強く": "連用形は名詞を直接修飾できない。「強く日差し」は不自然。", "強め": "「強めの日差し」なら可能だが、「の」がなければ名詞を修飾できない。", "強くて": "て形のため、名詞を修飾できない。"}, "sentence_index": 6, "correct_answer": "強い"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この会社は社員の数が強いので、毎年たくさんの新人を採用している。", "explanation": "ここは〈多い〉の意味。人数の多さは「強い」では表さず、「多い」と言う。"}, {"text": "このお湯は強いので、手を入れないでください。", "explanation": "ここは〈熱い〉の意味。温度の高さを「強い」で表すことはない。"}, {"text": "この部屋は窓が強いので、昼間も明るい。", "explanation": "ここは〈大きい〉の意味。窓の大きさを「強い」で表すことはない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9297dc18-f5ac-4488-a97e-eae535564182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35655, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明日は朝から雨風が強いくなるでしょう。", "corrected_sentence": "明日は朝から雨風が強くなるでしょう。", "error_description": "「強くなる」の「強く」は連用形。「強いく」は存在しない誤った活用形。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "強い", "is_correct": true, "explanation": "連体形で、名詞「人」を修飾している。「強い人」となる。"}, {"text": "強く", "is_correct": false, "explanation": "連用形のため、名詞「人」を直接修飾できない。「強く人」は不自然。"}, {"text": "強くて", "is_correct": false, "explanation": "て形のため、名詞「人」を修飾できない。"}, {"text": "強ければ", "is_correct": false, "explanation": "仮定形のため、名詞「人」を直接修飾できない。"}], "correct_form": "強い", "base_form": "強い", "form_label": "連体形", "sentence_index": 1, "explanations": {"強い": "連体形で、名詞「人」を修飾している。「強い人」となる。", "強く": "連用形のため、名詞「人」を直接修飾できない。「強く人」は不自然。", "強くて": "て形のため、名詞「人」を修飾できない。", "強ければ": "仮定形のため、名詞「人」を直接修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9297dc18-f5ac-4488-a97e-eae535564182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35655, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この薬は効き目が強いだから、子どもには使えない。", "corrected_sentence": "この薬は効き目が強いから、子どもには使えない。", "error_description": "い形容詞「強い」には「だ」を付けず、理由は「強いから」と言う。「強いだから」は誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "強く", "is_correct": true, "explanation": "連用形で、動詞「反対した」を修飾している。"}, {"text": "強さ", "is_correct": false, "explanation": "名詞のため、動詞「反対した」を直接修飾できない。「強さ反対した」は不自然。"}, {"text": "強くて", "is_correct": false, "explanation": "て形のため、「反対した」を修飾できない。"}, {"text": "強くなかった", "is_correct": false, "explanation": "否定過去形のため、「反対した」を修飾できない。"}], "correct_form": "強く", "base_form": "強い", "form_label": "連用形", "sentence_index": 7, "explanations": {"強く": "連用形で、動詞「反対した」を修飾している。", "強さ": "名詞のため、動詞「反対した」を直接修飾できない。「強さ反対した」は不自然。", "強くて": "て形のため、「反対した」を修飾できない。", "強くなかった": "否定過去形のため、「反対した」を修飾できない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9297dc18-f5ac-4488-a97e-eae535564182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35656, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「お酒への依存」と、「へ」の後ろで名詞「依存」につなぐ。"}, {"text": "を", "is_correct": false, "explanation": "「へを」は続けられず、非文になる。"}, {"text": "と", "is_correct": false, "explanation": "「へと依存」では名詞を修飾できず、意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "「へで」は続けられず、非文になる。"}], "correct_answer": "の", "explanations": {"の": "「お酒への依存」と、「へ」の後ろで名詞「依存」につなぐ。", "を": "「へを」は続けられず、非文になる。", "と": "「へと依存」では名詞を修飾できず、意味が通らない。", "で": "「へで」は続けられず、非文になる。"}, "error_tags": {"を": "object_marker", "と": "comitative", "で": "location_means"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "自立", "is_correct": true, "explanation": "他に頼らず自分でやることで、「依存」の反対。"}, {"text": "信頼", "is_correct": false, "explanation": "人を信じることで、反対の関係ではない。"}, {"text": "利用", "is_correct": false, "explanation": "ものを使うことで、反対の関係ではない。"}, {"text": "活用", "is_correct": false, "explanation": "うまく使うことで、反対の関係ではない。"}], "correct_answer": "自立", "explanations": {"自立": "他に頼らず自分でやることで、「依存」の反対。", "信頼": "人を信じることで、反対の関係ではない。", "利用": "ものを使うことで、反対の関係ではない。", "活用": "うまく使うことで、反対の関係ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2252bf06-8630-4788-8291-815a1c1960b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35656, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「依存する」は頼る対象を「に」で示す。"}, {"text": "を", "is_correct": false, "explanation": "「コーヒーを依存する」とは言えず、非文になる。"}, {"text": "と", "is_correct": false, "explanation": "「コーヒーと依存する」では意味が通らない。"}, {"text": "で", "is_correct": false, "explanation": "「コーヒーで依存する」とは言えず、非文になる。"}], "correct_answer": "に", "explanations": {"に": "「依存する」は頼る対象を「に」で示す。", "を": "「コーヒーを依存する」とは言えず、非文になる。", "と": "「コーヒーと依存する」では意味が通らない。", "で": "「コーヒーで依存する」とは言えず、非文になる。"}, "error_tags": {"を": "object_marker", "と": "comitative", "で": "location_means"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "独立", "is_correct": true, "explanation": "他に頼らず一人でやっていくことで、「依存」の反対。"}, {"text": "協力", "is_correct": false, "explanation": "力を合わせることで、反対の関係ではない。"}, {"text": "信用", "is_correct": false, "explanation": "人を信じることで、反対の関係ではない。"}, {"text": "関係", "is_correct": false, "explanation": "つながりのことで、反対の関係ではない。"}], "correct_answer": "独立", "explanations": {"独立": "他に頼らず一人でやっていくことで、「依存」の反対。", "協力": "力を合わせることで、反対の関係ではない。", "信用": "人を信じることで、反対の関係ではない。", "関係": "つながりのことで、反対の関係ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2252bf06-8630-4788-8291-815a1c1960b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35656, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かがなくてはできないこと。", "primary_collocate": null, "pronunciation": "いぞん", "ipa": "izoɴ", "syllable_count": 3, "sentences": [{"text": "私はスマホに依存している。", "target_word": "依存", "complexity_tier": "T3", "furigana": "私[わたし]はスマホに依存[いぞん]している。", "sentence_source": "generated"}, {"text": "彼はお酒への依存が強い。", "target_word": "依存", "complexity_tier": "T3", "furigana": "彼[かれ]はお酒[さけ]への依存[いぞん]が強[つよ]い。", "sentence_source": "generated"}, {"text": "依存は心配な問題だ。", "target_word": "依存", "complexity_tier": "T2", "furigana": "依存[いぞん]は心配[しんぱい]な問題[もんだい]だ。", "sentence_source": "generated"}, {"text": "薬に依存してはいけない。", "target_word": "依存", "complexity_tier": "T3", "furigana": "薬[くすり]に依存[いぞん]してはいけない。", "sentence_source": "generated"}, {"text": "ゲームへの依存をやめたい。", "target_word": "依存", "complexity_tier": "T2", "furigana": "ゲームへの依存[いぞん]をやめたい。", "sentence_source": "generated"}, {"text": "子どもの依存を減らす方法を考えた。", "target_word": "依存", "complexity_tier": "T3", "furigana": "子[こ]どもの依存[いぞん]を減[へ]らす方法[ほうほう]を考[かんが]えた。", "sentence_source": "generated"}, {"text": "私たちは電気に依存した生活をしている。", "target_word": "依存", "complexity_tier": "T3", "furigana": "私[わたし]たちは電気[でんき]に依存[いぞん]した生活[せいかつ]をしている。", "sentence_source": "generated"}, {"text": "彼女はコーヒーに依存していると言う。", "target_word": "依存", "complexity_tier": "T3", "furigana": "彼女[かのじょ]はコーヒーに依存[いぞん]していると言[い]う。", "sentence_source": "generated"}, {"text": "依存すると、自分で決められなくなる。", "target_word": "依存", "complexity_tier": "T4", "furigana": "依存[いぞん]すると、自分[じぶん]で決[き]められなくなる。", "sentence_source": "generated"}, {"text": "人は誰かに少し依存して生きている。", "target_word": "依存", "complexity_tier": "T3", "furigana": "人[ひと]は誰[だれ]かに少[すこ]し依存[いぞん]して生[い]きている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "依存する", "label": "活用"}, {"form": "依存して", "label": "活用"}, {"form": "依存症", "label": "派生"}, {"form": "依存度", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | それなしではできないこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24217c32-83c6-4579-9e1d-cf4f10e2dc79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35656, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "依存", "is_correct": true, "explanation": "見出し語そのもの（いぞん）。"}, {"text": "以前", "is_correct": false, "explanation": "いぜん。「ぞ」が「ぜ」に変わる別の語。"}, {"text": "遺族", "is_correct": false, "explanation": "いぞく。最後の「ん」が「く」に変わる別の語。"}, {"text": "遺贈", "is_correct": false, "explanation": "いぞう。最後の「ん」が「う」に変わる別の語。"}, {"text": "遺産", "is_correct": false, "explanation": "いさん。「ぞ」が「さ」に変わる別の語。"}], "explanations": {"依存": "見出し語そのもの（いぞん）。", "以前": "いぜん。「ぞ」が「ぜ」に変わる別の語。", "遺族": "いぞく。最後の「ん」が「く」に変わる別の語。", "遺贈": "いぞう。最後の「ん」が「う」に変わる別の語。", "遺産": "いさん。「ぞ」が「さ」に変わる別の語。"}, "sentence_index": null, "correct_answer": "依存"}, "level_3": {"options": [{"text": "依存", "is_correct": true, "explanation": "スマホがないと困る状態を表し、文意に合う。"}, {"text": "出席", "is_correct": false, "explanation": "形は合うが、スマホに出席するという意味が合わない。"}, {"text": "就職", "is_correct": false, "explanation": "形は合うが、スマホに就職するという意味が合わない。"}, {"text": "到着", "is_correct": false, "explanation": "形は合うが、スマホに到着するという意味が合わない。"}], "explanations": {"依存": "スマホがないと困る状態を表し、文意に合う。", "出席": "形は合うが、スマホに出席するという意味が合わない。", "就職": "形は合うが、スマホに就職するという意味が合わない。", "到着": "形は合うが、スマホに到着するという意味が合わない。"}, "sentence_index": 0, "correct_answer": "依存"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "依存の日は雨が降るでしょう。", "explanation": "「依存」は「日」を修飾する語ではなく、天気や日付の意味では使えない。"}, {"text": "彼は毎朝、公園を依存して走っている。", "explanation": "「依存」は動作の場所や方法を表す語ではなく、「走る」意味では使えない。"}, {"text": "このケーキは依存で、とてもおいしい。", "explanation": "「依存」は味や品質をほめる語ではないので、おいしさの説明には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2252bf06-8630-4788-8291-815a1c1960b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35656, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "依存", "is_correct": true, "explanation": "見出し語そのもの（いぞん）。"}, {"text": "依然", "is_correct": false, "explanation": "いぜん。「ぞ」が「ぜ」に変わる別の語。"}, {"text": "遺恨", "is_correct": false, "explanation": "いこん。「ぞ」が「こ」に変わる別の語。"}, {"text": "維新", "is_correct": false, "explanation": "いしん。「ぞ」が「し」に変わる別の語。"}, {"text": "威厳", "is_correct": false, "explanation": "いげん。「ぞ」が「げ」に変わる別の語。"}], "explanations": {"依存": "見出し語そのもの（いぞん）。", "依然": "いぜん。「ぞ」が「ぜ」に変わる別の語。", "遺恨": "いこん。「ぞ」が「こ」に変わる別の語。", "維新": "いしん。「ぞ」が「し」に変わる別の語。", "威厳": "いげん。「ぞ」が「げ」に変わる別の語。"}, "sentence_index": null, "correct_answer": "依存"}, "level_3": {"options": [{"text": "依存", "is_correct": true, "explanation": "「電気に依存した生活」で、電気がないと困る生活を表し、文意に合う。"}, {"text": "読書", "is_correct": false, "explanation": "形は合うが、「電気に読書した生活」では意味が通らない。"}, {"text": "結婚", "is_correct": false, "explanation": "形は合うが、「電気に結婚した生活」では意味が通らない。"}, {"text": "出張", "is_correct": false, "explanation": "形は合うが、「電気に出張した生活」では意味が通らない。"}], "explanations": {"依存": "「電気に依存した生活」で、電気がないと困る生活を表し、文意に合う。", "読書": "形は合うが、「電気に読書した生活」では意味が通らない。", "結婚": "形は合うが、「電気に結婚した生活」では意味が通らない。", "出張": "形は合うが、「電気に出張した生活」では意味が通らない。"}, "sentence_index": 6, "correct_answer": "依存"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この問題の答えを依存して書いてください。", "explanation": "「依存」は「書く」方法を表す語ではなく、答えの書き方には使えない。"}, {"text": "彼は私に依存を貸してくれた。", "explanation": "「依存」は貸し借りできる物ではなく、物の名前として使えない。"}, {"text": "駅まで依存で行くと十分かかる。", "explanation": "「依存」は移動の手段を表す語ではなく、交通手段としては使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2252bf06-8630-4788-8291-815a1c1960b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EX