INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35657, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「輸入に依存する」で、頼る先を示す。"}, {"text": "を", "is_correct": false, "explanation": "「依存する」は頼る先に「を」を取らない。"}, {"text": "が", "is_correct": false, "explanation": "「輸入が依存している」は頼る先の示し方として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「輸入と依存している」は文として成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「輸入に依存する」で、頼る先を示す。", "を": "「依存する」は頼る先に「を」を取らない。", "が": "「輸入が依存している」は頼る先の示し方として成り立たない。", "と": "「輸入と依存している」は文として成り立たない。"}, "error_tags": {"を": "wrong_case", "が": "wrong_case", "と": "wrong_case"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "自立", "is_correct": true, "explanation": "他に頼らず自分で立つ「自立」は依存の反対。"}, {"text": "依頼", "is_correct": false, "explanation": "「依頼」は人に頼むことで、依存の反対ではない。"}, {"text": "信頼", "is_correct": false, "explanation": "「信頼」は信じることで、反対ではない。"}, {"text": "協力", "is_correct": false, "explanation": "「協力」は力を合わせることで、反対ではない。"}], "correct_answer": "自立", "explanations": {"自立": "他に頼らず自分で立つ「自立」は依存の反対。", "依頼": "「依頼」は人に頼むことで、依存の反対ではない。", "信頼": "「信頼」は信じることで、反対ではない。", "協力": "「協力」は力を合わせることで、反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2252bf06-8630-4788-8291-815a1c1960b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35657, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「依存が大きい」で、依存が主語になる。"}, {"text": "を", "is_correct": false, "explanation": "「大きい」は形容詞なので「を」は使えない。"}, {"text": "に", "is_correct": false, "explanation": "「依存に大きい」は文として成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「依存で大きい」は文として成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「依存が大きい」で、依存が主語になる。", "を": "「大きい」は形容詞なので「を」は使えない。", "に": "「依存に大きい」は文として成り立たない。", "で": "「依存で大きい」は文として成り立たない。"}, "error_tags": {"を": "wrong_case", "に": "wrong_case", "で": "wrong_case"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "独立", "is_correct": true, "explanation": "他に頼らず成り立つ「独立」は依存の反対。"}, {"text": "従属", "is_correct": false, "explanation": "「従属」は他に従う状態で、依存に近い。"}, {"text": "共存", "is_correct": false, "explanation": "「共存」はともに存在することで、反対ではない。"}, {"text": "信頼", "is_correct": false, "explanation": "「信頼」は信じることで、反対ではない。"}], "correct_answer": "独立", "explanations": {"独立": "他に頼らず成り立つ「独立」は依存の反対。", "従属": "「従属」は他に従う状態で、依存に近い。", "共存": "「共存」はともに存在することで、反対ではない。", "信頼": "「信頼」は信じることで、反対ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2252bf06-8630-4788-8291-815a1c1960b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35657, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "自分だけでは十分に機能できず、他のものに頼っている状態。", "primary_collocate": null, "pronunciation": "いぞん", "ipa": "izoɴ", "syllable_count": 3, "sentences": [{"text": "既製品への安易な依存を排し、自らの手でカスタマイズを通じて素材と対話する行為は、DIYファッションの本質的な愉楽であり、自己効力感の再確認でもある。", "target_word": "依存", "complexity_tier": "T6", "furigana": "既製品[きせいひん]への安易[あんい]な依存[いぞん]を排[はい]し、自[みずか]らの手[て]でカスタマイズを通[つう]じて素材[そざい]と対話[たいわ]する行為[こうい]は、DIYファッションの本質的[ほんしつてき]な愉楽[ゆらく]であり、自己[じこ]効力感[こうりょくかん]の再確認[さいかくにん]でもある。", "sentence_source": "mined"}, {"text": "日本はエネルギーを輸入に依存している。", "target_word": "依存", "complexity_tier": "T3", "furigana": "日本[にほん]はエネルギーを輸入[ゆにゅう]に依存[いぞん]している。", "sentence_source": "generated"}, {"text": "親への依存をやめたい。", "target_word": "依存", "complexity_tier": "T2", "furigana": "親[おや]への依存[いぞん]をやめたい。", "sentence_source": "generated"}, {"text": "子どもは親に依存して生活している。", "target_word": "依存", "complexity_tier": "T3", "furigana": "子[こ]どもは親[おや]に依存[いぞん]して生活[せいかつ]している。", "sentence_source": "generated"}, {"text": "一つの会社への依存は危ない。", "target_word": "依存", "complexity_tier": "T2", "furigana": "一[ひと]つの会社[かいしゃ]への依存[いぞん]は危[あぶ]ない。", "sentence_source": "generated"}, {"text": "彼は友達に依存しすぎている。", "target_word": "依存", "complexity_tier": "T3", "furigana": "彼[かれ]は友達[ともだち]に依存[いぞん]しすぎている。", "sentence_source": "generated"}, {"text": "農家は天気に依存する仕事だ。", "target_word": "依存", "complexity_tier": "T3", "furigana": "農家[のうか]は天気[てんき]に依存[いぞん]する仕事[しごと]だ。", "sentence_source": "generated"}, {"text": "町の経済は観光への依存が大きい。", "target_word": "依存", "complexity_tier": "T3", "furigana": "町[まち]の経済[けいざい]は観光[かんこう]への依存[いぞん]が大[おお]きい。", "sentence_source": "generated"}, {"text": "依存から抜け出すには、まず自分を知ることだ。", "target_word": "依存", "complexity_tier": "T4", "furigana": "依存[いぞん]から抜[ぬ]け出[だ]すには、まず自分[じぶん]を知[し]ることだ。", "sentence_source": "generated"}, {"text": "機械に依存した生活が、人の力を弱くしている。", "target_word": "依存", "complexity_tier": "T4", "furigana": "機械[きかい]に依存[いぞん]した生活[せいかつ]が、人[ひと]の力[ちから]を弱[よわ]くしている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "依存する", "label": "活用"}, {"form": "依存して", "label": "活用"}, {"form": "依存的", "label": "派生"}, {"form": "依存度", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 他に頼って成り立つ状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: 愉楽 (Zipf 1.65)']::text[], '24217c32-83c6-4579-9e1d-cf4f10e2dc79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35657, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "依存", "is_correct": true, "explanation": "見出し語「いぞん」。"}, {"text": "意見", "is_correct": false, "explanation": "「いけん」は2拍目だけが違う。"}, {"text": "緯線", "is_correct": false, "explanation": "「いせん」は2拍目だけが違う。"}, {"text": "遺恨", "is_correct": false, "explanation": "「いこん」は2拍目だけが違う。"}, {"text": "移転", "is_correct": false, "explanation": "「いてん」は2拍目だけが違う。"}], "explanations": {"依存": "見出し語「いぞん」。", "意見": "「いけん」は2拍目だけが違う。", "緯線": "「いせん」は2拍目だけが違う。", "遺恨": "「いこん」は2拍目だけが違う。", "移転": "「いてん」は2拍目だけが違う。"}, "sentence_index": null, "correct_answer": "依存"}, "level_3": {"options": [{"text": "依存", "is_correct": true, "explanation": "「安易な依存を排し」で、頼り切る状態を指す。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、「安易な天気を排し」では意味が合わない。"}, {"text": "地図", "is_correct": false, "explanation": "形は合うが、既製品への地図では意味が合わない。"}, {"text": "季節", "is_correct": false, "explanation": "形は合うが、「安易な季節を排す」では意味が合わない。"}], "explanations": {"依存": "「安易な依存を排し」で、頼り切る状態を指す。", "天気": "形は合うが、「安易な天気を排し」では意味が合わない。", "地図": "形は合うが、既製品への地図では意味が合わない。", "季節": "形は合うが、「安易な季節を排す」では意味が合わない。"}, "sentence_index": 0, "correct_answer": "依存"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "依存は朝六時に起きる習慣のことだ。", "explanation": "依存は他に頼る状態で、早起きの習慣ではない。"}, {"text": "この歌は依存がきれいで、よく聞く。", "explanation": "依存は状態を表す語で、歌の美しさを表さない。"}, {"text": "彼は依存を食べて、元気になった。", "explanation": "依存は状態を表す語で、食べ物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2252bf06-8630-4788-8291-815a1c1960b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35657, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "依存", "is_correct": true, "explanation": "見出し語「いぞん」。"}, {"text": "異端", "is_correct": false, "explanation": "「いたん」は2拍目だけが違う。"}, {"text": "維新", "is_correct": false, "explanation": "「いしん」は2拍目だけが違う。"}, {"text": "依然", "is_correct": false, "explanation": "「いぜん」は2拍目だけが違う。"}, {"text": "遺贈", "is_correct": false, "explanation": "「いぞう」は最後の1拍だけが違う。"}], "explanations": {"依存": "見出し語「いぞん」。", "異端": "「いたん」は2拍目だけが違う。", "維新": "「いしん」は2拍目だけが違う。", "依然": "「いぜん」は2拍目だけが違う。", "遺贈": "「いぞう」は最後の1拍だけが違う。"}, "sentence_index": null, "correct_answer": "依存"}, "level_3": {"options": [{"text": "依存", "is_correct": true, "explanation": "「天気に依存する」で、天気に頼る意味になる。"}, {"text": "反対", "is_correct": false, "explanation": "形は合うが、「天気に反対する仕事」では意味が合わない。"}, {"text": "出席", "is_correct": false, "explanation": "形は合うが、「天気に出席する仕事」では意味が合わない。"}, {"text": "質問", "is_correct": false, "explanation": "形は合うが、「天気に質問する仕事」では意味が合わない。"}], "explanations": {"依存": "「天気に依存する」で、天気に頼る意味になる。", "反対": "形は合うが、「天気に反対する仕事」では意味が合わない。", "出席": "形は合うが、「天気に出席する仕事」では意味が合わない。", "質問": "形は合うが、「天気に質問する仕事」では意味が合わない。"}, "sentence_index": 6, "correct_answer": "依存"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は一人で全部できるので、いつも人に依存している。", "explanation": "依存は他に頼ることで、一人でできる人には合わない。"}, {"text": "この机は木に依存でできている。", "explanation": "「依存でできている」は材料の説明に使えない。"}, {"text": "依存を三回に分けて食べた。", "explanation": "依存は状態を表す語で、食べ物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2252bf06-8630-4788-8291-815a1c1960b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
