INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35658, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「小さな規模の店」となり、『規模』が『店』を修飾する連体修飾の『の』。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す。「小さな規模を店」では名詞を正しくつなげられない。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す。「小さな規模が店」は修飾の場面に合わず文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す。「小さな規模へ店」は意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「小さな規模の店」となり、『規模』が『店』を修飾する連体修飾の『の』。", "を": "目的語を示す。「小さな規模を店」では名詞を正しくつなげられない。", "が": "主語を示す。「小さな規模が店」は修飾の場面に合わず文が成り立たない。", "へ": "方向を示す。「小さな規模へ店」は意味が通らない。"}, "error_tags": {"を": "目的語を示す", "が": "主語を示す", "へ": "方向を示す"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '816badd2-2b50-4e3f-a98a-f685001f1828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35658, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「これまでにない規模の展覧会」となり、『規模』が『展覧会』を修飾する連体修飾の『の』。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す。「規模を展覧会を」と二つ続き、名詞を正しくつなげられない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示す。「規模から展覧会」は意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示す。「規模より展覧会」は修飾の関係にならず文が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「これまでにない規模の展覧会」となり、『規模』が『展覧会』を修飾する連体修飾の『の』。", "を": "目的語を示す。「規模を展覧会を」と二つ続き、名詞を正しくつなげられない。", "から": "起点を示す。「規模から展覧会」は意味が通らない。", "より": "比較を示す。「規模より展覧会」は修飾の関係にならず文が成り立たない。"}, "error_tags": {"から": "起点・理由を示す", "より": "比較を示す", "を": "目的語を示す"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '816badd2-2b50-4e3f-a98a-f685001f1828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35658, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の大きさや、広がりの度合いのこと。", "primary_collocate": null, "pronunciation": "きぼ", "ipa": "kibo", "syllable_count": 2, "sentences": [{"text": "この祭りは規模が大きく、毎年十万人以上が集まります。", "target_word": "規模", "complexity_tier": "T3", "furigana": "この祭[まつ]りは規模[きぼ]が大[おお]きく、毎年[まいとし]十万人[じゅうまんにん]以上[いじょう]が集[あつ]まります。", "sentence_source": "generated"}, {"text": "小さな規模の店でも、工夫すれば人気が出ます。", "target_word": "規模", "complexity_tier": "T3", "furigana": "小[ちい]さな規模[きぼ]の店[みせ]でも、工夫[くふう]すれば人気[にんき]が出[で]ます。", "sentence_source": "generated"}, {"text": "工事の規模が思ったより大きくて、完成まで三年かかります。", "target_word": "規模", "complexity_tier": "T3", "furigana": "工事[こうじ]の規模[きぼ]が思[おも]ったより大[おお]きくて、完成[かんせい]まで三年[さんねん]かかります。", "sentence_source": "generated"}, {"text": "世界的な規模で、新しい感染症の調査が始まりました。", "target_word": "規模", "complexity_tier": "T3", "furigana": "世界的[せかいてき]な規模[きぼ]で、新[あたら]しい感染症[かんせんしょう]の調査[ちょうさ]が始[はじ]まりました。", "sentence_source": "generated"}, {"text": "会社の規模は小さいが、技術では大手に負けない。", "target_word": "規模", "complexity_tier": "T3", "furigana": "会社[かいしゃ]の規模[きぼ]は小[ちい]さいが、技術[ぎじゅつ]では大手[おおて]に負[ま]けない。", "sentence_source": "generated"}, {"text": "地震の被害の規模を知るために、役所は現地を調べた。", "target_word": "規模", "complexity_tier": "T3", "furigana": "地震[じしん]の被害[ひがい]の規模[きぼ]を知[し]るために、役所[やくしょ]は現地[げんち]を調[しら]べた。", "sentence_source": "generated"}, {"text": "今年の花火大会は規模を広げて、場所も二つになりました。", "target_word": "規模", "complexity_tier": "T3", "furigana": "今年[ことし]の花火大会[はなびたいかい]は規模[きぼ]を広[ひろ]げて、場所[ばしょ]も二[ふた]つになりました。", "sentence_source": "generated"}, {"text": "彼はこれまでにない規模の展覧会を開く計画を立てた。", "target_word": "規模", "complexity_tier": "T3", "furigana": "彼[かれ]はこれまでにない規模[きぼ]の展覧会[てんらんかい]を開[ひら]く計画[けいかく]を立[た]てた。", "sentence_source": "generated"}, {"text": "参加者が少なかったので、イベントの規模を小さくしました。", "target_word": "規模", "complexity_tier": "T3", "furigana": "参加者[さんかしゃ]が少[すく]なかったので、イベントの規模[きぼ]を小[ちい]さくしました。", "sentence_source": "generated"}, {"text": "山火事は規模が大きく、消すのに五日もかかった。", "target_word": "規模", "complexity_tier": "T3", "furigana": "山火事[やまかじ]は規模[きぼ]が大[おお]きく、消[け]すのに五日[いつか]もかかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "規模", "label": "基本形"}, {"form": "規模の", "label": "連体形"}], "register": "中立", "sense_fingerprint": "事業・工事・行事・被害などの、大きさや広がりの程度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9a56563-cdf2-4fe2-ab54-3ae3af9e93b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35658, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "規模", "is_correct": true, "explanation": "「祭りは規模が大きく」となり、祭りの大きさの程度を主語にする。空所に入る正解。"}, {"text": "味", "is_correct": false, "explanation": "食べ物の味を指し、祭りの大きさを表す主語にはならないので合わない。"}, {"text": "湿度", "is_correct": false, "explanation": "空気中の水分の割合を指し、祭りの大きさを言う文には合わない。"}, {"text": "寿命", "is_correct": false, "explanation": "生きている期間を指し、祭りの大きさの話には合わない。"}], "explanations": {"規模": "「祭りは規模が大きく」となり、祭りの大きさの程度を主語にする。空所に入る正解。", "味": "食べ物の味を指し、祭りの大きさを表す主語にはならないので合わない。", "湿度": "空気中の水分の割合を指し、祭りの大きさを言う文には合わない。", "寿命": "生きている期間を指し、祭りの大きさの話には合わない。"}, "sentence_index": 0, "correct_answer": "規模"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は規模が若くて、まだ学生だ。", "explanation": "ここは〈年齢〉の意味。若さを表す語で、大きさの程度である規模とは合わないため誤り。"}, {"text": "この町は規模が多く、人が大勢住んでいる。", "explanation": "ここは〈人口〉の意味。住む人の数を言う語で、規模の多さとは言わないので合わない。"}, {"text": "この国では規模をよく守る人が多い。", "explanation": "ここは〈規則〉の意味。守る対象は規則で、大きさの程度の規模は守れないため合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '816badd2-2b50-4e3f-a98a-f685001f1828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35658, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "規模", "is_correct": true, "explanation": "「規模を広げて」となり、花火大会の大きさの程度を対象にする。空所に入る正解。"}, {"text": "寝息", "is_correct": false, "explanation": "眠っている人の呼吸を指し、広げるものにはならないので合わない。"}, {"text": "午後", "is_correct": false, "explanation": "時間帯を指し、「午後を広げて」とは言えないので合わない。"}, {"text": "眠気", "is_correct": false, "explanation": "眠たい感覚を指し、広げるという動詞の対象にはならない。"}], "explanations": {"規模": "「規模を広げて」となり、花火大会の大きさの程度を対象にする。空所に入る正解。", "寝息": "眠っている人の呼吸を指し、広げるものにはならないので合わない。", "午後": "時間帯を指し、「午後を広げて」とは言えないので合わない。", "眠気": "眠たい感覚を指し、広げるという動詞の対象にはならない。"}, "sentence_index": 6, "correct_answer": "規模"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工事の規模が思ったより長くて、完成まで三年かかります。", "explanation": "ここは〈期間〉の意味。長さを言う語で、大きさの程度の規模は長さには使えないため合わない。"}, {"text": "彼は規模が穏やかで、怒ったところを見たことがない。", "explanation": "ここは〈性格〉の意味。人の性質を言う語で、大きさを表す規模とは合わないため誤り。"}, {"text": "その台風は規模が強く、家が壊れた。", "explanation": "ここは〈勢力〉の意味。強さを言う語で、大きさの程度を表す規模とは言い方が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '816badd2-2b50-4e3f-a98a-f685001f1828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35658, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この会社は規模を小さくて、社員が少ない。", "corrected_sentence": "この会社は規模が小さくて、社員が少ない。", "error_description": "『規模』は主語になるので『が』が正しい。『を』は目的語を示すため、形容詞『小さい』の主語にはできない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '816badd2-2b50-4e3f-a98a-f685001f1828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35658, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この地震は規模が多く、被害が広がった。", "corrected_sentence": "この地震は規模が大きく、被害が広がった。", "error_description": "『規模』に続く形容詞は『大きい』が正しい。『多い』は数量の多さを表す語で、規模の大きさには合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '816badd2-2b50-4e3f-a98a-f685001f1828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35660, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「長い労働のあとで」の形で、「労働の後」と後ろの「あと」をつなぐ。文の意味に合う。"}, {"text": "が", "is_correct": false, "explanation": "「労働が」では後の「あとで」につながらず、主語を示すので、ここでは合わない。"}, {"text": "を", "is_correct": false, "explanation": "「労働を」は動作の対象を示すが、後に目的語を取る動詞がないので合わない。"}, {"text": "に", "is_correct": false, "explanation": "「労働に」は方向や対象を示すが、「長い労働にあとで」は不自然で文の意味に合わない。"}], "correct_answer": "の", "explanations": {"の": "「長い労働のあとで」の形で、「労働の後」と後ろの「あと」をつなぐ。文の意味に合う。", "が": "「労働が」では後の「あとで」につながらず、主語を示すので、ここでは合わない。", "を": "「労働を」は動作の対象を示すが、後に目的語を取る動詞がないので合わない。", "に": "「労働に」は方向や対象を示すが、「長い労働にあとで」は不自然で文の意味に合わない。"}, "error_tags": {"が": "主語", "を": "目的語", "に": "方向・対象"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "休息", "is_correct": true, "explanation": "「労働」の対義語。働くことをやめて体や頭を休める意味を表す。"}, {"text": "食事", "is_correct": false, "explanation": "「食事」は食べることを指し、働くことの反対語ではない。"}, {"text": "会話", "is_correct": false, "explanation": "「会話」は言葉を交わすことを指し、労働の対義語ではない。"}, {"text": "読書", "is_correct": false, "explanation": "「読書」は本を読むことを指し、労働の反対語ではない。"}], "correct_answer": "休息", "explanations": {"休息": "「労働」の対義語。働くことをやめて体や頭を休める意味を表す。", "食事": "「食事」は食べることを指し、働くことの反対語ではない。", "会話": "「会話」は言葉を交わすことを指し、労働の対義語ではない。", "読書": "「読書」は本を読むことを指し、労働の反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33441540-5e68-48c9-ab4d-7372add938d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35660, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "休息", "is_correct": true, "explanation": "「労働」の対義語。働くことをやめて体や頭を休める意味を表す。"}, {"text": "散歩", "is_correct": false, "explanation": "「散歩」は気晴らしに歩くことで、労働の反対語ではない。"}, {"text": "買い物", "is_correct": false, "explanation": "「買い物」は物を買う行為で、労働の対義語ではない。"}, {"text": "演説", "is_correct": false, "explanation": "「演説」は人前で話をすることで、労働の反対語ではない。"}], "correct_answer": "休息", "explanations": {"休息": "「労働」の対義語。働くことをやめて体や頭を休める意味を表す。", "散歩": "「散歩」は気晴らしに歩くことで、労働の反対語ではない。", "買い物": "「買い物」は物を買う行為で、労働の対義語ではない。", "演説": "「演説」は人前で話をすることで、労働の反対語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33441540-5e68-48c9-ab4d-7372add938d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35660, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "体や頭を使って仕事をすること。", "primary_collocate": null, "pronunciation": "ろうどう", "ipa": "ɾoːdoː", "syllable_count": 4, "sentences": [{"text": "この工場では、一日八時間の労働が決まりです。", "target_word": "労働", "complexity_tier": "T3", "furigana": "この工場[こうじょう]では、一日[いちにち]八時間[はちじかん]の労働[ろうどう]が決[き]まりです。", "sentence_source": "generated"}, {"text": "長い労働のあとで、父はすぐに寝てしまった。", "target_word": "労働", "complexity_tier": "T3", "furigana": "長[なが]い労働[ろうどう]のあとで、父[ちち]はすぐに寝[ね]てしまった。", "sentence_source": "generated"}, {"text": "子どもに危険な労働をさせてはいけません。", "target_word": "労働", "complexity_tier": "T3", "furigana": "子[こ]どもに危険[きけん]な労働[ろうどう]をさせてはいけません。", "sentence_source": "generated"}, {"text": "労働の時間が短くなって、家族と過ごす時間がふえた。", "target_word": "労働", "complexity_tier": "T3", "furigana": "労働[ろうどう]の時間[じかん]が短[みじか]くなって、家族[かぞく]と過[す]ごす時間[じかん]がふえた。", "sentence_source": "generated"}, {"text": "彼は毎日の重い労働で、体をこわしてしまった。", "target_word": "労働", "complexity_tier": "T3", "furigana": "彼[かれ]は毎日[まいにち]の重[おも]い労働[ろうどう]で、体[からだ]をこわしてしまった。", "sentence_source": "generated"}, {"text": "働いた分のお金をもらうのは、労働の正しい対価です。", "target_word": "労働", "complexity_tier": "T3", "furigana": "働[はたら]いた分[ぶん]のお金[かね]をもらうのは、労働[ろうどう]の正[ただ]しい対価[たいか]です。", "sentence_source": "generated"}, {"text": "農家の労働は朝早くから始まります。", "target_word": "労働", "complexity_tier": "T3", "furigana": "農家[のうか]の労働[ろうどう]は朝早[あさはや]くから始[はじ]まります。", "sentence_source": "generated"}, {"text": "夜おそくまでの労働は、体にも心にも負担が大きい。", "target_word": "労働", "complexity_tier": "T3", "furigana": "夜[よる]おそくまでの労働[ろうどう]は、体[からだ]にも心[こころ]にも負担[ふたん]が大[おお]きい。", "sentence_source": "generated"}, {"text": "この国では、15歳未満の子どもの労働が法律で禁じられている。", "target_word": "労働", "complexity_tier": "T3", "furigana": "この国[くに]では、15歳[さい]未満[みまん]の子[こ]どもの労働[ろうどう]が法律[ほうりつ]で禁[きん]じられている。", "sentence_source": "generated"}, {"text": "機械が入って、人の労働がだいぶ楽になった。", "target_word": "労働", "complexity_tier": "T3", "furigana": "機械[きかい]が入[はい]って、人[ひと]の労働[ろうどう]がだいぶ楽[らく]になった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "労働", "label": "基本形"}, {"form": "労働する", "label": "サ変動詞形"}], "register": "neutral", "sense_fingerprint": "体や頭を使って働くこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T2: contains vocabulary far above tier T2: おそく (Zipf 2.34)']::text[], '07e99574-5a76-414c-a8d8-98dc1fc98f23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35660, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "労働", "is_correct": true, "explanation": "「労働」は体や頭を使って仕事をすること。工場の一日の勤務時間の決まりを述べる文に合う。"}, {"text": "天気", "is_correct": false, "explanation": "「一日八時間の天気」は意味が通らず、勤務時間の決まりを述べる文に合わない。"}, {"text": "辞書", "is_correct": false, "explanation": "「一日八時間の辞書」は文として成り立たず、工場の決まりとは合わない。"}, {"text": "写真", "is_correct": false, "explanation": "「一日八時間の写真」は意味が通らず、勤務時間の決まりを表す文に合わない。"}], "explanations": {"労働": "「労働」は体や頭を使って仕事をすること。工場の一日の勤務時間の決まりを述べる文に合う。", "天気": "「一日八時間の天気」は意味が通らず、勤務時間の決まりを述べる文に合わない。", "辞書": "「一日八時間の辞書」は文として成り立たず、工場の決まりとは合わない。", "写真": "「一日八時間の写真」は意味が通らず、勤務時間の決まりを表す文に合わない。"}, "sentence_index": 0, "correct_answer": "労働"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "やっと労働が見つかって、ほっとした。", "explanation": "ここは〈職〉の意味。労働は働くという行為を指し、就く職そのものを「見つける」対象にはしないので合わない。"}, {"text": "寝る前に、好きな労働を聴く。", "explanation": "ここは〈音楽〉の意味。「聴く」の対象は音楽で、働くことは聴けないので合わない。"}, {"text": "毎晩、英語の労働を二時間することにした。", "explanation": "ここは〈勉強〉の意味。英語を学ぶ行為は「勉強」で表し、「労働」では表さないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33441540-5e68-48c9-ab4d-7372add938d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35660, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "労働", "is_correct": true, "explanation": "「労働」は体や頭を使って働くこと。農家の朝早くからの仕事を述べる文に合う。"}, {"text": "雑誌", "is_correct": false, "explanation": "「農家の雑誌」は意味が通らず、仕事の始まりを述べる文に合わない。"}, {"text": "切符", "is_correct": false, "explanation": "「農家の切符」は文として成り立たず、朝早くからの仕事とは合わない。"}, {"text": "歌声", "is_correct": false, "explanation": "「農家の歌声」は意味が通らず、仕事の始まりを表す文には合わない。"}], "explanations": {"労働": "「労働」は体や頭を使って働くこと。農家の朝早くからの仕事を述べる文に合う。", "雑誌": "「農家の雑誌」は意味が通らず、仕事の始まりを述べる文に合わない。", "切符": "「農家の切符」は文として成り立たず、朝早くからの仕事とは合わない。", "歌声": "「農家の歌声」は意味が通らず、仕事の始まりを表す文には合わない。"}, "sentence_index": 6, "correct_answer": "労働"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は毎晩、家族のために労働を作る。", "explanation": "ここは〈料理〉の意味。食べ物を作る行為は「料理を作る」と言い、「労働を作る」とは言わないので合わない。"}, {"text": "今年は昇給して、月の労働が二万円上がった。", "explanation": "ここは〈給料〉の意味。金額は給料の話で、労働が金額として上がるとは言わないので合わない。"}, {"text": "昼休みに十五分の労働をとる。", "explanation": "ここは〈休憩〉の意味。労働は働くことを指し、体を休める時間の「休憩」とは意味が違うので、「とる」の対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33441540-5e68-48c9-ab4d-7372add938d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35660, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この会社では、週四十時間の労働を決まりです。", "corrected_sentence": "この会社では、週四十時間の労働が決まりです。", "error_description": "「決まりです」の前には主語を示す「が」が入る。「を」は目的語を示すので、「決まり」の主語として合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33441540-5e68-48c9-ab4d-7372add938d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35660, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "休みなく労働すれ、体をこわした。", "corrected_sentence": "休みなく労働して、体をこわした。", "error_description": "「労働して」とて形で文を続ける。「労働すれ」は仮定形で、後ろの「体をこわした」とつながらない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33441540-5e68-48c9-ab4d-7372add938d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35662, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「集約すると」の形で、ひとまとめにした結果の条件を示す。"}, {"text": "を", "is_correct": false, "explanation": "「集約するを」とは続かない。「する」に直接つく格助詞として不自然。"}, {"text": "に", "is_correct": false, "explanation": "「集約するに」は続かない。この位置で文を成立させられない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」は「集約するへ」と続かず、文の流れに合わない。"}], "correct_answer": "と", "explanations": {"と": "「集約すると」の形で、ひとまとめにした結果の条件を示す。", "を": "「集約するを」とは続かない。「する」に直接つく格助詞として不自然。", "に": "「集約するに」は続かない。この位置で文を成立させられない。", "へ": "方向を表す「へ」は「集約するへ」と続かず、文の流れに合わない。"}, "error_tags": {"を": "格", "に": "格", "へ": "方向"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分散", "is_correct": true, "explanation": "集約の対義語で、まとまったものをばらばらに散らすという意味。"}, {"text": "拡大", "is_correct": false, "explanation": "規模を広げる意味で、まとめることの反対の関係として辞書には載らない。"}, {"text": "配布", "is_correct": false, "explanation": "配る意味で、集約の対義語ではない。"}, {"text": "配置", "is_correct": false, "explanation": "並べて置く意味で、まとめることの反対の関係ではない。"}], "correct_answer": "分散", "explanations": {"分散": "集約の対義語で、まとまったものをばらばらに散らすという意味。", "拡大": "規模を広げる意味で、まとめることの反対の関係として辞書には載らない。", "配布": "配る意味で、集約の対義語ではない。", "配置": "並べて置く意味で、まとめることの反対の関係ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616496e4-4d0a-47ad-b093-14a19d5697f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35662, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分散", "is_correct": true, "explanation": "集約の対義語で、まとまったものを別々に分けて広げるという意味。"}, {"text": "縮小", "is_correct": false, "explanation": "規模を小さくする意味で、まとめることの反対の関係ではない。"}, {"text": "撤去", "is_correct": false, "explanation": "取り除く意味で、集約の対義語として挙がる語ではない。"}, {"text": "拡張", "is_correct": false, "explanation": "広げる意味で、まとめることの反対の関係ではない。"}], "correct_answer": "分散", "explanations": {"分散": "集約の対義語で、まとまったものを別々に分けて広げるという意味。", "縮小": "規模を小さくする意味で、まとめることの反対の関係ではない。", "撤去": "取り除く意味で、集約の対義語として挙がる語ではない。", "拡張": "広げる意味で、まとめることの反対の関係ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616496e4-4d0a-47ad-b093-14a19d5697f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35662, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "たくさんのものを一つにまとめること。", "primary_collocate": null, "pronunciation": "しゅうやく", "ipa": "ɕɯːjakɯ", "syllable_count": 4, "sentences": [{"text": "全員の意見を集約して、一つの案にまとめた。", "target_word": "集約", "complexity_tier": "T3", "furigana": "全員[ぜんいん]の意見[いけん]を集約[しゅうやく]して、一[ひと]つの案[あん]にまとめた。", "sentence_source": "generated"}, {"text": "各店の売り上げを集約すると、会社の全体が見える。", "target_word": "集約", "complexity_tier": "T3", "furigana": "各店[かくてん]の売[う]り上[あ]げを集約[しゅうやく]すると、会社[かいしゃ]の全体[ぜんたい]が見[み]える。", "sentence_source": "generated"}, {"text": "集めたアンケートは、今週中に集約する予定だ。", "target_word": "集約", "complexity_tier": "T3", "furigana": "集[あつ]めたアンケートは、今週中[こんしゅうちゅう]に集約[しゅうやく]する予定[よてい]だ。", "sentence_source": "generated"}, {"text": "たくさんの資料を集約したので、探す手間が省けた。", "target_word": "集約", "complexity_tier": "T3", "furigana": "たくさんの資料[しりょう]を集約[しゅうやく]したので、探[さが]す手間[てま]が省[はぶ]けた。", "sentence_source": "generated"}, {"text": "部署ごとの報告を集約するのが、私の仕事だ。", "target_word": "集約", "complexity_tier": "T3", "furigana": "部署[ぶしょ]ごとの報告[ほうこく]を集約[しゅうやく]するのが、私[わたし]の仕事[しごと]だ。", "sentence_source": "generated"}, {"text": "分かれていた倉庫を一つに集約して、費用を減らした。", "target_word": "集約", "complexity_tier": "T3", "furigana": "分[わ]かれていた倉庫[そうこ]を一[ひと]つに集約[しゅうやく]して、費用[ひよう]を減[へ]らした。", "sentence_source": "generated"}, {"text": "ばらばらの要望を集約しないと、会議で話が進まない。", "target_word": "集約", "complexity_tier": "T3", "furigana": "ばらばらの要望[ようぼう]を集約[しゅうやく]しないと、会議[かいぎ]で話[はなし]が進[すす]まない。", "sentence_source": "generated"}, {"text": "町の小さな病院を集約する計画に、住民は反対した。", "target_word": "集約", "complexity_tier": "T3", "furigana": "町[まち]の小[ちい]さな病院[びょういん]を集約[しゅうやく]する計画[けいかく]に、住民[じゅうみん]は反対[はんたい]した。", "sentence_source": "generated"}, {"text": "山のようなメモを集約すると、たった三つの結論になった。", "target_word": "集約", "complexity_tier": "T3", "furigana": "山[やま]のようなメモを集約[しゅうやく]すると、たった三[みっ]つの結論[けつろん]になった。", "sentence_source": "generated"}, {"text": "データの集約には、思ったより時間がかかった。", "target_word": "集約", "complexity_tier": "T3", "furigana": "データの集約[しゅうやく]には、思[おも]ったより時間[じかん]がかかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "集約", "label": "基本形"}, {"form": "集約する", "label": "辞書形"}, {"form": "集約した", "label": "過去形"}, {"form": "集約して", "label": "て形"}, {"form": "集約しない", "label": "否定形"}], "register": "neutral to formal", "sense_fingerprint": "集約: gathering many scattered items, opinions or figures and putting them into one (意見・データ・数字を集約する)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e19b2205-6e13-41a2-a86e-2a42bff0feea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35662, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "集約", "is_correct": true, "explanation": "「集約して」と続き、全員の意見をまとめる意味になる。"}, {"text": "拡大", "is_correct": false, "explanation": "規模を広げる意味で、意見を一つの案にまとめる文脈とは逆になる。"}, {"text": "解散", "is_correct": false, "explanation": "組織をやめる意味で、意見をまとめる流れに合わない。"}, {"text": "配布", "is_correct": false, "explanation": "配る意味で、意見を一つの案にまとめるという内容と合わない。"}], "explanations": {"集約": "「集約して」と続き、全員の意見をまとめる意味になる。", "拡大": "規模を広げる意味で、意見を一つの案にまとめる文脈とは逆になる。", "解散": "組織をやめる意味で、意見をまとめる流れに合わない。", "配布": "配る意味で、意見を一つの案にまとめるという内容と合わない。"}, "sentence_index": 0, "correct_answer": "集約"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "まとまっていた資料を、一つずつ集約して、ばらばらにした。", "explanation": "ここは〈分散させる〉の意味。〈集約〉は別々のものを一つにまとめる語なので、ばらばらにする意味にはならない。"}, {"text": "海水を集約して、塩を作った。", "explanation": "ここは「濃縮する」の意味。「集約」は数や物を一つにまとめる語で、水分を減らして濃くする意味ではない。"}, {"text": "その大きな雲を集約して、雨を止めた。", "explanation": "ここは〈制御する・止める〉の意味。〈集約〉は別々のものを一つにまとめる語で、雨を止める意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616496e4-4d0a-47ad-b093-14a19d5697f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35662, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "集約", "is_correct": true, "explanation": "「集約しないと」と続き、要望をまとめる必要があることを示す。"}, {"text": "拡散", "is_correct": false, "explanation": "広がる意味で、要望をまとめる必要とは逆になる。"}, {"text": "帰宅", "is_correct": false, "explanation": "「帰宅しないと」は要望に続かず、話を進める行為とも合わない。"}, {"text": "配列", "is_correct": false, "explanation": "並べる意味で、要望を一つにまとめる流れと合わない。"}], "explanations": {"集約": "「集約しないと」と続き、要望をまとめる必要があることを示す。", "拡散": "広がる意味で、要望をまとめる必要とは逆になる。", "帰宅": "「帰宅しないと」は要望に続かず、話を進める行為とも合わない。", "配列": "並べる意味で、要望を一つにまとめる流れと合わない。"}, "sentence_index": 6, "correct_answer": "集約"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "朝ごはんを集約するのに、一時間かかった。", "explanation": "ここは〈調理する〉の意味。〈集約〉は別々の要素を一つの全体にまとめる語で、料理の手順には使わない。"}, {"text": "眠気を集約して、目が覚めた。", "explanation": "ここは〈散らす・消す〉の意味。〈集約〉は一つにまとめる語で、眠気を消す意味にはならない。"}, {"text": "会議の時間を集約すると、話が長くなる。", "explanation": "時間の長さを伸ばす意味ではない。「集約」は別々の要素を一つにまとめる語で、時間を延ばす意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616496e4-4d0a-47ad-b093-14a19d5697f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35662, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "バラバラの回答を集約に、答えを一つにまとめた。", "corrected_sentence": "バラバラの回答を集約して、答えを一つにまとめた。", "error_description": "正しくは「集約して」。「集約」は「する」を付けて動詞として使うので、「に」では文が続かない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616496e4-4d0a-47ad-b093-14a19d5697f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35662, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会議の資料を集約ないと、話が進まない。", "corrected_sentence": "会議の資料を集約しないと、話が進まない。", "error_description": "正しくは「集約しないと」。「集約」は「する」を付けて動詞にするため、否定は「集約しない」の形が必要。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616496e4-4d0a-47ad-b093-14a19d5697f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
