INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35663, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "個別に存在するものを一つの全体にまとめること。", "primary_collocate": null, "pronunciation": "しゅうやく", "ipa": "ɕɯːjakɯ", "syllable_count": 4, "sentences": [{"text": "各支店の情報を本社に集約する仕組みを作った。", "target_word": "集約", "complexity_tier": "T3", "furigana": "各支店[かくしてん]の情報[じょうほう]を本社[ほんしゃ]に集約[しゅうやく]する仕組[しく]みを作[つく]った。", "sentence_source": "generated"}, {"text": "小さな工場の生産を一か所に集約して、効率が上がった。", "target_word": "集約", "complexity_tier": "T3", "furigana": "小[ちい]さな工場[こうじょう]の生産[せいさん]を一[いっ]か所[しょ]に集約[しゅうやく]して、効率[こうりつ]が上[あ]がった。", "sentence_source": "generated"}, {"text": "地域ごとの意見の集約は、担当の課が行っている。", "target_word": "集約", "complexity_tier": "T3", "furigana": "地域[ちいき]ごとの意見[いけん]の集約[しゅうやく]は、担当[たんとう]の課[か]が行[おこな]っている。", "sentence_source": "generated"}, {"text": "複数のシステムを一つに集約したので、管理が楽になった。", "target_word": "集約", "complexity_tier": "T3", "furigana": "複数[ふくすう]のシステムを一[ひと]つに集約[しゅうやく]したので、管理[かんり]が楽[らく]になった。", "sentence_source": "generated"}, {"text": "個々の研究を集約すると、新しい傾向が見えてくる。", "target_word": "集約", "complexity_tier": "T3", "furigana": "個々[ここ]の研究[けんきゅう]を集約[しゅうやく]すると、新[あたら]しい傾向[けいこう]が見[み]えてくる。", "sentence_source": "generated"}, {"text": "会計の窓口を一階に集約したため、客の迷いが減った。", "target_word": "集約", "complexity_tier": "T3", "furigana": "会計[かいけい]の窓口[まどぐち]を一階[いっかい]に集約[しゅうやく]したため、客[きゃく]の迷[まよ]いが減[へ]った。", "sentence_source": "generated"}, {"text": "各自のレポートは集約して、一冊の報告書にした。", "target_word": "集約", "complexity_tier": "T3", "furigana": "各自[かくじ]のレポートは集約[しゅうやく]して、一冊[いっさつ]の報告書[ほうこくしょ]にした。", "sentence_source": "generated"}, {"text": "権限が社長に集約されているので、決定が早い。", "target_word": "集約", "complexity_tier": "T3", "furigana": "権限[けんげん]が社長[しゃちょう]に集約[しゅうやく]されているので、決定[けってい]が早[はや]い。", "sentence_source": "generated"}, {"text": "散らばった図書館の本を、新しい建物に集約した。", "target_word": "集約", "complexity_tier": "T3", "furigana": "散[ち]らばった図書館[としょかん]の本[ほん]を、新[あたら]しい建物[たてもの]に集約[しゅうやく]した。", "sentence_source": "generated"}, {"text": "情報の集約が進むほど、見落としも起こりにくい。", "target_word": "集約", "complexity_tier": "T3", "furigana": "情報[じょうほう]の集約[しゅうやく]が進[すす]むほど、見落[みお]としも起[お]こりにくい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "集約", "label": "基本形"}, {"form": "集約する", "label": "辞書形"}, {"form": "集約した", "label": "過去形"}, {"form": "集約されて", "label": "受身のて形"}, {"form": "集約しない", "label": "否定形"}], "register": "neutral to formal", "sense_fingerprint": "集約: consolidating separate units (branches, factories, systems, powers) into one whole or one place (拠点・機能・権限を一つに集約する)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e19b2205-6e13-41a2-a86e-2a42bff0feea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35663, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "集約", "is_correct": true, "explanation": "「集約する仕組み」の形で、各支店の情報を本社にまとめる仕組みを表す。"}, {"text": "解体", "is_correct": false, "explanation": "組織をばらす意味で、情報を本社に寄せる仕組みとは逆になる。"}, {"text": "撤去", "is_correct": false, "explanation": "取り除く意味で、情報を本社に寄せる仕組みとは合わない。"}, {"text": "切断", "is_correct": false, "explanation": "切り離す意味で、情報を本社に送る仕組みとは合わない。"}], "explanations": {"集約": "「集約する仕組み」の形で、各支店の情報を本社にまとめる仕組みを表す。", "解体": "組織をばらす意味で、情報を本社に寄せる仕組みとは逆になる。", "撤去": "取り除く意味で、情報を本社に寄せる仕組みとは合わない。", "切断": "切り離す意味で、情報を本社に送る仕組みとは合わない。"}, "sentence_index": 0, "correct_answer": "集約"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "重いパンの生地を集約して、ふくらませた。", "explanation": "ここは生地をふくらませる意味。「集約」は別々のものを一つにまとめる語で、膨張させる意味にはならない。"}, {"text": "その絵の具を集約して、新しい色を作った。", "explanation": "ここは絵の具を混ぜる意味。「集約」は個別のものを一つの全体にまとめる語で、混色の手順を指さない。"}, {"text": "眠い子どもの泣き声を集約して、部屋を静かにした。", "explanation": "ここは音を消す意味。「集約」は別々のものを一つにまとめる語で、音を小さくする意味ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616496e4-4d0a-47ad-b093-14a19d5697f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35663, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "集約", "is_correct": true, "explanation": "「集約して」と続き、個別のレポートを一つにまとめることを表す。"}, {"text": "拡散", "is_correct": false, "explanation": "広がる意味で、レポートを一冊にまとめる流れと合わない。"}, {"text": "放置", "is_correct": false, "explanation": "そのままにする意味で、一冊の報告書にまとめる内容と合わない。"}, {"text": "配列", "is_correct": false, "explanation": "並べる意味で、一冊の報告書にまとめる内容に合わない。"}], "explanations": {"集約": "「集約して」と続き、個別のレポートを一つにまとめることを表す。", "拡散": "広がる意味で、レポートを一冊にまとめる流れと合わない。", "放置": "そのままにする意味で、一冊の報告書にまとめる内容と合わない。", "配列": "並べる意味で、一冊の報告書にまとめる内容に合わない。"}, "sentence_index": 6, "correct_answer": "集約"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会議の時間を集約すると、話が長くなる。", "explanation": "時間の長さを伸ばす意味ではない。「集約」は別々の要素を一つにまとめる語で、時間を延ばす意味にはならない。"}, {"text": "夕焼けの色を集約すると、空が暗くなった。", "explanation": "空の色を暗くする意味ではない。「集約」は個別の要素を一つの全体にまとめる語で、色の濃さを変える意味にはならない。"}, {"text": "家の中の音を集約して、眠りにくくなった。", "explanation": "音を増やす意味ではない。「集約」は別々の要素を一つにまとめる語で、音の大きさを変える意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616496e4-4d0a-47ad-b093-14a19d5697f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35663, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "各店の在庫を一か所に集約に仕組みを作った。", "corrected_sentence": "各店の在庫を一か所に集約する仕組みを作った。", "error_description": "正しくは「集約する」。「集約」は「する」を付けて動詞として使うので、「に」を続けると文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616496e4-4d0a-47ad-b093-14a19d5697f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35663, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "各自の感想は集約に、一冊の本にまとめた。", "corrected_sentence": "各自の感想は集約して、一冊の本にまとめた。", "error_description": "正しくは「集約して」。「集約」は「する」を付けて動詞として使うので、「に」では文が続かない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616496e4-4d0a-47ad-b093-14a19d5697f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
