INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35664, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「形態は」で主題を示し、後の「エビとは…ちがっている」と対比する。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すので、「ちがっている」の主題の説明には合わない。"}, {"text": "の", "is_correct": false, "explanation": "「形態の」は名詞を修飾する形で、後ろに述語が続かず文が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「形態を、エビとは…ちがっている」は目的語を取らない「ちがう」に合わず不自然。"}], "correct_answer": "は", "explanations": {"は": "「形態は」で主題を示し、後の「エビとは…ちがっている」と対比する。", "へ": "「へ」は方向を表すので、「ちがっている」の主題の説明には合わない。", "の": "「形態の」は名詞を修飾する形で、後ろに述語が続かず文が成り立たない。", "を": "「形態を、エビとは…ちがっている」は目的語を取らない「ちがう」に合わず不自然。"}, "error_tags": {"へ": "方向", "の": "連体修飾", "を": "目的格"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33441540-5e68-48c9-ab4d-7372add938d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35664, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ものの形や状態のこと。", "primary_collocate": null, "pronunciation": "けいたい", "ipa": "keːtai", "syllable_count": 4, "sentences": [{"text": "この虫は成長すると、体の形態が大きく変わる。", "target_word": "形態", "complexity_tier": "T3", "furigana": "この虫[むし]は成長[せいちょう]すると、体[からだ]の形態[けいたい]が大[おお]きく変[か]わる。", "sentence_source": "generated"}, {"text": "水は温度によって、氷や水蒸気などちがう形態になる。", "target_word": "形態", "complexity_tier": "T3", "furigana": "水[みず]は温度[おんど]によって、氷[こおり]や水蒸気[すいじょうき]などちがう形態[けいたい]になる。", "sentence_source": "generated"}, {"text": "雲にはいろいろな形態があり、空を見ると面白い。", "target_word": "形態", "complexity_tier": "T3", "furigana": "雲[くも]にはいろいろな形態[けいたい]があり、空[そら]を見[み]ると面白[おもしろ]い。", "sentence_source": "generated"}, {"text": "この岩の形態は、まるで動物の顔のように見える。", "target_word": "形態", "complexity_tier": "T3", "furigana": "この岩[いわ]の形態[けいたい]は、まるで動物[どうぶつ]の顔[かお]のように見[み]える。", "sentence_source": "generated"}, {"text": "生き物の形態を調べて、種類を見分ける。", "target_word": "形態", "complexity_tier": "T3", "furigana": "生[い]き物[もの]の形態[けいたい]を調[しら]べて、種類[しゅるい]を見分[みわ]ける。", "sentence_source": "generated"}, {"text": "雪の結晶は、温度によって形態がちがう。", "target_word": "形態", "complexity_tier": "T3", "furigana": "雪[ゆき]の結晶[けっしょう]は、温度[おんど]によって形態[けいたい]がちがう。", "sentence_source": "generated"}, {"text": "同じ植物でも、育つ場所で葉の形態がちがう。", "target_word": "形態", "complexity_tier": "T3", "furigana": "同[おな]じ植物[しょくぶつ]でも、育[そだ]つ場所[ばしょ]で葉[は]の形態[けいたい]がちがう。", "sentence_source": "generated"}, {"text": "カニの体の形態は、エビとはかなりちがっている。", "target_word": "形態", "complexity_tier": "T3", "furigana": "カニの体[からだ]の形態[けいたい]は、エビとはかなりちがっている。", "sentence_source": "generated"}, {"text": "博物館では、恐竜の骨の形態をくわしく比べている。", "target_word": "形態", "complexity_tier": "T3", "furigana": "博物館[はくぶつかん]では、恐竜[きょうりゅう]の骨[ほね]の形態[けいたい]をくわしく比[くら]べている。", "sentence_source": "generated"}, {"text": "この貝は、成長するにつれて殻の形態が変化する。", "target_word": "形態", "complexity_tier": "T3", "furigana": "この貝[かい]は、成長[せいちょう]するにつれて殻[から]の形態[けいたい]が変化[へんか]する。", "sentence_source": "generated"}], "morphological_forms": [{"form": "形態", "label": "基本形"}], "register": "formal", "sense_fingerprint": "生き物や物質などの見た目の形や状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07e99574-5a76-414c-a8d8-98dc1fc98f23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35664, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "形態", "is_correct": true, "explanation": "「体の形態が大きく変わる」で、体の見た目の形を指すので正解。"}, {"text": "日程", "is_correct": false, "explanation": "「体の日程が大きく変わる」は意味が通らない。体の形を表す語が入る。"}, {"text": "予算", "is_correct": false, "explanation": "「体の予算が大きく変わる」は意味が通らない。"}, {"text": "天気", "is_correct": false, "explanation": "「体の天気が大きく変わる」は意味が通らない。"}], "explanations": {"形態": "「体の形態が大きく変わる」で、体の見た目の形を指すので正解。", "日程": "「体の日程が大きく変わる」は意味が通らない。体の形を表す語が入る。", "予算": "「体の予算が大きく変わる」は意味が通らない。", "天気": "「体の天気が大きく変わる」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "形態"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この料理は形態が辛くて、食べると汗が出る。", "explanation": "ここは〈味〉の意味。辛さは味の話で、形態は物の形や状態を指すので合わない。"}, {"text": "このピアノは形態が低くて、どの音も遠く聞こえる。", "explanation": "ここは〈音程〉の意味。音の高低は形態ではなく音程で言うので、この文には合わない。"}, {"text": "この靴は形態が高くて、なかなか買えない。", "explanation": "ここは〈値段〉の意味。値段の高さを形態で表すことはなく、値段で言う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33441540-5e68-48c9-ab4d-7372add938d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35664, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "形態", "is_correct": true, "explanation": "「葉の形態がちがう」で、葉の見た目の形の違いを指すので正解。"}, {"text": "時刻", "is_correct": false, "explanation": "「葉の時刻がちがう」は意味が通らない。"}, {"text": "料金", "is_correct": false, "explanation": "「葉の料金がちがう」は意味が通らない。"}, {"text": "人数", "is_correct": false, "explanation": "「葉の人数がちがう」は意味が通らない。"}], "explanations": {"形態": "「葉の形態がちがう」で、葉の見た目の形の違いを指すので正解。", "時刻": "「葉の時刻がちがう」は意味が通らない。", "料金": "「葉の料金がちがう」は意味が通らない。", "人数": "「葉の人数がちがう」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "形態"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この車は形態が速くて、高速道路でよく目立つ。", "explanation": "ここは〈速さ〉の意味。車の速さを形態で表すことはなく、速度で言う。"}, {"text": "彼女の形態は、天気のようにすぐ変わる。", "explanation": "ここは〈気持ち〉の意味。感情の移り変わりを形態で表すことはない。"}, {"text": "この犬は形態が若く、まだ子どもだ。", "explanation": "ここは〈年齢〉の意味。動物の若さや年の頃は形態ではなく年齢で言う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33441540-5e68-48c9-ab4d-7372add938d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35664, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この虫は、暑い夏に体の形態が変える。", "corrected_sentence": "この虫は、暑い夏に体の形態を変える。", "error_description": "「変える」は他動詞なので目的語に「を」を取る。「形態が」は誤りで、正しくは「形態を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33441540-5e68-48c9-ab4d-7372add938d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35664, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "研究者は、化石の形態が比べて、昔の生き物の仲間を探す。", "corrected_sentence": "研究者は、化石の形態を比べて、昔の生き物の仲間を探す。", "error_description": "「比べる」は「AとBを比べる」の形で目的語に「を」を取る。「形態が」は誤りで、正しくは「形態を」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33441540-5e68-48c9-ab4d-7372add938d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35665, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33441540-5e68-48c9-ab4d-7372add938d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35665, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「形態が」は主語で、「大きくちがう」の主語として自然に成り立つ。"}, {"text": "を", "is_correct": false, "explanation": "「形態を大きくちがう」は目的語を取らない「ちがう」には合わず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、「ちがう」の主体にはならない。"}, {"text": "の", "is_correct": false, "explanation": "「形態の」は連体修飾で、後ろに述語が続かず文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「形態が」は主語で、「大きくちがう」の主語として自然に成り立つ。", "を": "「形態を大きくちがう」は目的語を取らない「ちがう」には合わず不自然。", "へ": "「へ」は方向を表し、「ちがう」の主体にはならない。", "の": "「形態の」は連体修飾で、後ろに述語が続かず文が成り立たない。"}, "error_tags": {"を": "目的格（ちがう）", "へ": "方向", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33441540-5e68-48c9-ab4d-7372add938d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35665, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の存在や現れ方の様式。", "primary_collocate": null, "pronunciation": "けいたい", "ipa": "keːtai", "syllable_count": 4, "sentences": [{"text": "最近は、働き方の形態がとても多くなった。", "target_word": "形態", "complexity_tier": "T3", "furigana": "最近[さいきん]は、働[はたら]き方[かた]の形態[けいたい]がとても多[おお]くなった。", "sentence_source": "generated"}, {"text": "この店はネットだけで売る、新しい営業の形態だ。", "target_word": "形態", "complexity_tier": "T3", "furigana": "この店[みせ]はネットだけで売[う]る、新[あたら]しい営業[えいぎょう]の形態[けいたい]だ。", "sentence_source": "generated"}, {"text": "家族の形態は、時代とともに変わってきた。", "target_word": "形態", "complexity_tier": "T3", "furigana": "家族[かぞく]の形態[けいたい]は、時代[じだい]とともに変[か]わってきた。", "sentence_source": "generated"}, {"text": "会社の組織の形態によって、意思の決め方もちがう。", "target_word": "形態", "complexity_tier": "T3", "furigana": "会社[かいしゃ]の組織[そしき]の形態[けいたい]によって、意思[いし]の決[き]め方[かた]もちがう。", "sentence_source": "generated"}, {"text": "契約の形態には、正社員のほか、派遣や契約社員もある。", "target_word": "形態", "complexity_tier": "T3", "furigana": "契約[けいやく]の形態[けいたい]には、正社員[せいしゃいん]のほか、派遣[はけん]や契約社員[けいやくしゃいん]もある。", "sentence_source": "generated"}, {"text": "テレワークという勤務の形態が広がっている。", "target_word": "形態", "complexity_tier": "T3", "furigana": "テレワークという勤務[きんむ]の形態[けいたい]が広[ひろ]がっている。", "sentence_source": "generated"}, {"text": "この団体は、会員が自由に参加する形態で運営している。", "target_word": "形態", "complexity_tier": "T3", "furigana": "この団体[だんたい]は、会員[かいいん]が自由[じゆう]に参加[さんか]する形態[けいたい]で運営[うんえい]している。", "sentence_source": "generated"}, {"text": "昔の農業と今の農業では、経営の形態が大きくちがう。", "target_word": "形態", "complexity_tier": "T3", "furigana": "昔[むかし]の農業[のうぎょう]と今[いま]の農業[のうぎょう]では、経営[けいえい]の形態[けいたい]が大[おお]きくちがう。", "sentence_source": "generated"}, {"text": "学校の授業の形態は、教室だけではなくなった。", "target_word": "形態", "complexity_tier": "T3", "furigana": "学校[がっこう]の授業[じゅぎょう]の形態[けいたい]は、教室[きょうしつ]だけではなくなった。", "sentence_source": "generated"}, {"text": "観光の形態が変わり、団体旅行より個人旅行が増えた。", "target_word": "形態", "complexity_tier": "T3", "furigana": "観光[かんこう]の形態[けいたい]が変[か]わり、団体旅行[だんたいりょこう]より個人旅行[こじんりょこう]が増[ふ]えた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "形態", "label": "基本形"}], "register": "formal", "sense_fingerprint": "仕事・組織・制度などのあり方や様式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07e99574-5a76-414c-a8d8-98dc1fc98f23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35665, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "形態", "is_correct": true, "explanation": "「働き方の形態が多くなった」で、働き方のあり方の種類を指すので正解。"}, {"text": "年齢", "is_correct": false, "explanation": "「働き方の年齢が多くなった」は意味が通らない。"}, {"text": "気温", "is_correct": false, "explanation": "「働き方の気温が多くなった」は意味が通らない。"}, {"text": "料金", "is_correct": false, "explanation": "「働き方の料金が多くなった」は意味が通らない。"}], "explanations": {"形態": "「働き方の形態が多くなった」で、働き方のあり方の種類を指すので正解。", "年齢": "「働き方の年齢が多くなった」は意味が通らない。", "気温": "「働き方の気温が多くなった」は意味が通らない。", "料金": "「働き方の料金が多くなった」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "形態"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この服は、形態が白と黒の二色で、大人っぽい。", "explanation": "ここは〈配色〉の意味。服の色の組み合わせは形態ではなく配色で表す。"}, {"text": "この電車は形態が遅れて、会議に間に合わなかった。", "explanation": "ここは〈遅延〉の意味。電車が遅れる度合いを形態で言うことはなく、遅延で表す。"}, {"text": "彼女は形態が明るくて、みんなに好かれる。", "explanation": "ここは〈性格〉の意味。人の性格の説明には形態は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33441540-5e68-48c9-ab4d-7372add938d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35665, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "形態", "is_correct": true, "explanation": "「会員が自由に参加する形態で運営している」で、組織の運営のあり方を指すので正解。"}, {"text": "色", "is_correct": false, "explanation": "「会員が自由に参加する色で運営している」は意味が通らない。"}, {"text": "天気", "is_correct": false, "explanation": "「天気で運営している」は意味が通らない。"}, {"text": "体重", "is_correct": false, "explanation": "「体重で運営している」は意味が通らない。"}], "explanations": {"形態": "「会員が自由に参加する形態で運営している」で、組織の運営のあり方を指すので正解。", "色": "「会員が自由に参加する色で運営している」は意味が通らない。", "天気": "「天気で運営している」は意味が通らない。", "体重": "「体重で運営している」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "形態"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この金属は、熱に強いという形態がある。", "explanation": "ここは〈性質〉の意味。熱への強さは形態ではなく性質で表す。"}, {"text": "このスープは、形態が濃くて体が温まる。", "explanation": "ここは〈味〉の意味。味の濃さを形態で表すことはない。"}, {"text": "ピアノの形態が部屋いっぱいに広がった。", "explanation": "ここは〈音〉の意味。音の広がりは形態ではなく音で表す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33441540-5e68-48c9-ab4d-7372add938d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35665, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会社は、社員が働く形態に自由に選べるようにした。", "corrected_sentence": "会社は、社員が働く形態を自由に選べるようにした。", "error_description": "「選べる」の目的語は「を」で示す。「形態に」は誤りで、正しくは「形態を」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33441540-5e68-48c9-ab4d-7372add938d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35665, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校は、授業の形態が生徒に合わせて変えている。", "corrected_sentence": "学校は、授業の形態を生徒に合わせて変えている。", "error_description": "「変える」は他動詞で目的語に「を」を取る。「形態が」は誤りで、正しくは「形態を」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33441540-5e68-48c9-ab4d-7372add938d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
