INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35666, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "たくさんの人が、あることを一番よく使うこと。", "primary_collocate": null, "pronunciation": "しゅりゅう", "ipa": "ɕɯɾʲɯː", "syllable_count": 3, "sentences": [{"text": "買い物の支払いは、スマートフォンが主流になってきた。", "target_word": "主流", "complexity_tier": "T3", "furigana": "買[か]い物[もの]の支払[しはら]いは、スマートフォンが主流[しゅりゅう]になってきた。", "sentence_source": "generated"}, {"text": "十年前は、ゲームといえばカードを使う方法が主流だった。", "target_word": "主流", "complexity_tier": "T3", "furigana": "十年前[じゅうねんまえ]は、ゲームといえばカードを使[つか]う方法[ほうほう]が主流[しゅりゅう]だった。", "sentence_source": "generated"}, {"text": "この地域では、田植えを機械でするのが主流です。", "target_word": "主流", "complexity_tier": "T3", "furigana": "この地域[ちいき]では、田植[たう]えを機械[きかい]でするのが主流[しゅりゅう]です。", "sentence_source": "generated"}, {"text": "連絡の方法は、電話よりメッセージアプリが主流だ。", "target_word": "主流", "complexity_tier": "T3", "furigana": "連絡[れんらく]の方法[ほうほう]は、電話[でんわ]よりメッセージアプリが主流[しゅりゅう]だ。", "sentence_source": "generated"}, {"text": "若い人の間では、紙の本より電子書籍が主流だという。", "target_word": "主流", "complexity_tier": "T3", "furigana": "若[わか]い人[ひと]の間[あいだ]では、紙[かみ]の本[ほん]より電子書籍[でんししょせき]が主流[しゅりゅう]だという。", "sentence_source": "generated"}, {"text": "以前は有線のイヤホンが多かったが、今は無線が主流だ。", "target_word": "主流", "complexity_tier": "T3", "furigana": "以前[いぜん]は有線[ゆうせん]のイヤホンが多[おお]かったが、今[いま]は無線[むせん]が主流[しゅりゅう]だ。", "sentence_source": "generated"}, {"text": "音楽を聞く方法は、CDから配信が主流に変わった。", "target_word": "主流", "complexity_tier": "T3", "furigana": "音楽[おんがく]を聞[き]く方法[ほうほう]は、CDから配信[はいしん]が主流[しゅりゅう]に変[か]わった。", "sentence_source": "generated"}, {"text": "会議は、集まるより画面越しにするのが主流になった。", "target_word": "主流", "complexity_tier": "T3", "furigana": "会議[かいぎ]は、集[あつ]まるより画面越[がめんご]しにするのが主流[しゅりゅう]になった。", "sentence_source": "generated"}, {"text": "この店では、現金よりカードの支払いが主流だ。", "target_word": "主流", "complexity_tier": "T3", "furigana": "この店[みせ]では、現金[げんきん]よりカードの支払[しはら]いが主流[しゅりゅう]だ。", "sentence_source": "generated"}, {"text": "写真はフィルムに代わって、デジタルが主流となった。", "target_word": "主流", "complexity_tier": "T3", "furigana": "写真[しゃしん]はフィルムに代[か]わって、デジタルが主流[しゅりゅう]となった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "主流", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "道具や方法として最も多くの人に使われているもの", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07e99574-5a76-414c-a8d8-98dc1fc98f23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35666, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "主流", "is_correct": true, "explanation": "「スマートフォンが主流になってきた」で、多くの人が使う状態を指すので正解。"}, {"text": "季節", "is_correct": false, "explanation": "「スマートフォンが季節になってきた」は意味が通らない。"}, {"text": "天気", "is_correct": false, "explanation": "「スマートフォンが天気になってきた」は意味が通らない。"}, {"text": "料金", "is_correct": false, "explanation": "「スマートフォンが料金になってきた」は意味が通らない。"}], "explanations": {"主流": "「スマートフォンが主流になってきた」で、多くの人が使う状態を指すので正解。", "季節": "「スマートフォンが季節になってきた」は意味が通らない。", "天気": "「スマートフォンが天気になってきた」は意味が通らない。", "料金": "「スマートフォンが料金になってきた」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "主流"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このアイドルは若者の間で主流が高く、テレビによく出る。", "explanation": "ここは〈人気〉の意味。人の人気を表す語で、主流は使わない。"}, {"text": "このカメラは主流が手頃で、初心者にもおすすめだ。", "explanation": "ここは〈値段〉の意味。価格の話に主流は使わない。"}, {"text": "この祭りは主流が春で、毎年多くの人が来る。", "explanation": "ここは〈時期〉の意味。祭りが開かれる時期を主流で言うことはない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33441540-5e68-48c9-ab4d-7372add938d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35666, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "主流", "is_correct": true, "explanation": "「配信が主流に変わった」で、広く使われる方法になったことを表すので正解。"}, {"text": "時給", "is_correct": false, "explanation": "「配信が時給に変わった」は意味が通らない。"}, {"text": "体重", "is_correct": false, "explanation": "「配信が体重に変わった」は意味が通らない。"}, {"text": "行列", "is_correct": false, "explanation": "「配信が行列に変わった」は方法の変化を表せず、不自然。"}], "explanations": {"主流": "「配信が主流に変わった」で、広く使われる方法になったことを表すので正解。", "時給": "「配信が時給に変わった」は意味が通らない。", "体重": "「配信が体重に変わった」は意味が通らない。", "行列": "「配信が行列に変わった」は方法の変化を表せず、不自然。"}, "sentence_index": 6, "correct_answer": "主流"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この店は、味も値段も主流だと評判だ。", "explanation": "ここは〈最高〉の意味。品質を高く評価する場面では主流は合わない。"}, {"text": "夏の気温が主流で、冷房がよく売れる。", "explanation": "ここは〈暑さ〉の意味。夏の暑さの度合いを主流で表すことはない。"}, {"text": "このパソコンは、性能が主流で、動画編集にも向いている。", "explanation": "ここは〈処理能力〉の意味。パソコンの処理の力を主流で表すことはない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33441540-5e68-48c9-ab4d-7372add938d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35666, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新しい機器は、今や若者の間で主流がなっている。", "corrected_sentence": "新しい機器は、今や若者の間で主流となっている。", "error_description": "「〜となる」の形を取るので、正しくは「主流と」。「主流が」は「なる」と合わず不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33441540-5e68-48c9-ab4d-7372add938d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35666, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新しい技術は、数年で主流がなった。", "corrected_sentence": "新しい技術は、数年で主流となった。", "error_description": "「〜となる」の形を取るので、正しくは「主流と」。「主流が」は「なる」と合わず不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33441540-5e68-48c9-ab4d-7372add938d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35667, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "「主流は」で主題を示し、「毎年少しずつ変わる」と結びつく。"}, {"text": "を", "is_correct": false, "explanation": "「主流を毎年少しずつ変わる」は目的語を取らない動詞に合わず不自然。"}, {"text": "の", "is_correct": false, "explanation": "「主流の、毎年少しずつ変わる」は連体修飾で、主述が成立しない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表すが、「主流へ毎年少しずつ変わる」は行き先が示されず不自然。"}], "correct_answer": "は", "explanations": {"は": "「主流は」で主題を示し、「毎年少しずつ変わる」と結びつく。", "を": "「主流を毎年少しずつ変わる」は目的語を取らない動詞に合わず不自然。", "の": "「主流の、毎年少しずつ変わる」は連体修飾で、主述が成立しない。", "へ": "「へ」は方向を表すが、「主流へ毎年少しずつ変わる」は行き先が示されず不自然。"}, "error_tags": {"を": "目的格", "の": "連体修飾", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33441540-5e68-48c9-ab4d-7372add938d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35667, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「占める」は目的語に「を」を取るので、「主流を占める」が正しい。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を表し、「占める」の目的語にはならない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表し、「主流から占める」は成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表し、「占める」の目的語にはならない。"}], "correct_answer": "を", "explanations": {"を": "「占める」は目的語に「を」を取るので、「主流を占める」が正しい。", "へ": "「へ」は方向を表し、「占める」の目的語にはならない。", "から": "「から」は起点を表し、「主流から占める」は成り立たない。", "より": "「より」は比較を表し、「占める」の目的語にはならない。"}, "error_tags": {"へ": "方向", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33441540-5e68-48c9-ab4d-7372add938d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35667, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "多くの人に広く用いられ、中心となっていること。", "primary_collocate": null, "pronunciation": "しゅりゅう", "ipa": "ɕɯɾʲɯː", "syllable_count": 3, "sentences": [{"text": "その考え方は、今の学界で主流になっている。", "target_word": "主流", "complexity_tier": "T3", "furigana": "その考[かんが]え方[かた]は、今[いま]の学界[がっかい]で主流[しゅりゅう]になっている。", "sentence_source": "generated"}, {"text": "ファッションの主流は、毎年少しずつ変わる。", "target_word": "主流", "complexity_tier": "T3", "furigana": "ファッションの主流[しゅりゅう]は、毎年[まいとし]少[すこ]しずつ変[か]わる。", "sentence_source": "generated"}, {"text": "彼の意見は、会社の主流とは少しちがっていた。", "target_word": "主流", "complexity_tier": "T3", "furigana": "彼[かれ]の意見[いけん]は、会社[かいしゃ]の主流[しゅりゅう]とは少[すこ]しちがっていた。", "sentence_source": "generated"}, {"text": "この説は、かつては主流だったが、今はほとんど支持されない。", "target_word": "主流", "complexity_tier": "T3", "furigana": "この説[せつ]は、かつては主流[しゅりゅう]だったが、今[いま]はほとんど支持[しじ]されない。", "sentence_source": "generated"}, {"text": "エネルギーの主流が、石油から再生可能なものへ移りつつある。", "target_word": "主流", "complexity_tier": "T3", "furigana": "エネルギーの主流[しゅりゅう]が、石油[せきゆ]から再生可能[さいせいかのう]なものへ移[うつ]りつつある。", "sentence_source": "generated"}, {"text": "音楽の主流に合わせず、自分のスタイルを守る歌手もいる。", "target_word": "主流", "complexity_tier": "T3", "furigana": "音楽[おんがく]の主流[しゅりゅう]に合[あ]わせず、自分[じぶん]のスタイルを守[まも]る歌手[かしゅ]もいる。", "sentence_source": "generated"}, {"text": "この料理法は、地方ではまだ主流とはいえない。", "target_word": "主流", "complexity_tier": "T3", "furigana": "この料理法[りょうりほう]は、地方[ちほう]ではまだ主流[しゅりゅう]とはいえない。", "sentence_source": "generated"}, {"text": "映画界では、長い間ハリウッドの作品が主流を占めてきた。", "target_word": "主流", "complexity_tier": "T3", "furigana": "映画界[えいがかい]では、長[なが]い間[あいだ]ハリウッドの作品[さくひん]が主流[しゅりゅう]を占[し]めてきた。", "sentence_source": "generated"}, {"text": "新しい技術が出ても、すぐに主流になるとは限らない。", "target_word": "主流", "complexity_tier": "T3", "furigana": "新[あたら]しい技術[ぎじゅつ]が出[で]ても、すぐに主流[しゅりゅう]になるとは限[かぎ]らない。", "sentence_source": "generated"}, {"text": "大学の研究では、この方法が主流の考え方だ。", "target_word": "主流", "complexity_tier": "T3", "furigana": "大学[だいがく]の研究[けんきゅう]では、この方法[ほうほう]が主流[しゅりゅう]の考[かんが]え方[かた]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "主流", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "考え方や流行などの中心となる大きな流れ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07e99574-5a76-414c-a8d8-98dc1fc98f23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35667, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "主流", "is_correct": true, "explanation": "「学界で主流になっている」で、学界の中心となる考え方を指すので正解。"}, {"text": "期限", "is_correct": false, "explanation": "「学界で期限になっている」は意味が通らない。"}, {"text": "予算", "is_correct": false, "explanation": "「学界で予算になっている」は意味が通らない。"}, {"text": "料金", "is_correct": false, "explanation": "「学界で料金になっている」は意味が通らない。"}], "explanations": {"主流": "「学界で主流になっている」で、学界の中心となる考え方を指すので正解。", "期限": "「学界で期限になっている」は意味が通らない。", "予算": "「学界で予算になっている」は意味が通らない。", "料金": "「学界で料金になっている」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "主流"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この荷物は主流が重くて、運ぶのが大変だ。", "explanation": "ここは〈重さ〉の意味。物の重さを主流で表すことはない。"}, {"text": "会議の主流が長くて、昼ご飯の時間がなくなった。", "explanation": "ここは〈長さ〉の意味。会議の長さを主流で言うことはない。"}, {"text": "彼は、テストの主流が毎回上がっている。", "explanation": "ここは〈順位〉の意味。成績の順位に主流は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33441540-5e68-48c9-ab4d-7372add938d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35667, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "主流", "is_correct": true, "explanation": "「地方ではまだ主流とはいえない」で、広く使われる中心の状態を指すので正解。"}, {"text": "印刷", "is_correct": false, "explanation": "「地方ではまだ印刷とはいえない」は意味が通らない。"}, {"text": "時刻", "is_correct": false, "explanation": "「地方ではまだ時刻とはいえない」は意味が通らない。"}, {"text": "人数", "is_correct": false, "explanation": "「地方ではまだ人数とはいえない」は意味が通らない。"}], "explanations": {"主流": "「地方ではまだ主流とはいえない」で、広く使われる中心の状態を指すので正解。", "印刷": "「地方ではまだ印刷とはいえない」は意味が通らない。", "時刻": "「地方ではまだ時刻とはいえない」は意味が通らない。", "人数": "「地方ではまだ人数とはいえない」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "主流"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この店は、味の主流が濃くて、ご飯が進む。", "explanation": "ここは〈濃さ〉の意味。料理の濃い薄いを主流で表すことはない。"}, {"text": "明日の天候は、一日中主流の見込みだ。", "explanation": "ここは〈天気〉の意味。天気の見通しを主流とはいわない。"}, {"text": "彼は体力の主流が強く、毎朝走っている。", "explanation": "ここは〈持久力〉の意味。体の持ちこたえる力を主流で表すことはない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33441540-5e68-48c9-ab4d-7372add938d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35667, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その治療法は、今の医学界で主流がなりつつある。", "corrected_sentence": "その治療法は、今の医学界で主流になりつつある。", "error_description": "「〜になる」の形を取るので、正しくは「主流に」。「主流が」は「なる」の格として誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33441540-5e68-48c9-ab4d-7372add938d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35667, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この研究室の考えは、数年前から主流を扱われている。", "corrected_sentence": "この研究室の考えは、数年前から主流として扱われている。", "error_description": "「〜として扱う」の形を取るので、正しくは「主流として」。「主流を扱われている」は文として成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33441540-5e68-48c9-ab4d-7372add938d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
