INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35672, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "食べ物に、小さな生き物がはたらいて、味やにおいがかわること。", "primary_collocate": null, "pronunciation": "はっこう", "ipa": "hakkoː", "syllable_count": 4, "sentences": [{"text": "牛乳を発酵させると、酸味のあるヨーグルトができる。", "target_word": "発酵", "complexity_tier": "T3", "furigana": "牛乳[ぎゅうにゅう]を発酵[はっこう]させると、酸味[さんみ]のあるヨーグルトができる。", "sentence_source": "generated"}, {"text": "味噌は、豆が発酵して独特の香りが出る食べ物だ。", "target_word": "発酵", "complexity_tier": "T3", "furigana": "味噌[みそ]は、豆[まめ]が発酵[はっこう]して独特[どくとく]の香[かお]りが出[で]る食[た]べ物[もの]だ。", "sentence_source": "generated"}, {"text": "暖かい部屋に置いたので、パン生地の発酵が早く進んだ。", "target_word": "発酵", "complexity_tier": "T3", "furigana": "暖[あたた]かい部屋[へや]に置[お]いたので、パン生地[きじ]の発酵[はっこう]が早[はや]く進[すす]んだ。", "sentence_source": "generated"}, {"text": "発酵が進みすぎて、漬物がとても酸っぱくなってしまった。", "target_word": "発酵", "complexity_tier": "T3", "furigana": "発酵[はっこう]が進[すす]みすぎて、漬物[つけもの]がとても酸[す]っぱくなってしまった。", "sentence_source": "generated"}, {"text": "納豆は、豆を発酵させて作るため、強いにおいがある。", "target_word": "発酵", "complexity_tier": "T3", "furigana": "納豆[なっとう]は、豆[まめ]を発酵[はっこう]させて作[つく]るため、強[つよ]いにおいがある。", "sentence_source": "generated"}, {"text": "低い温度では発酵がゆっくりなので、ワインの味がまろやかになる。", "target_word": "発酵", "complexity_tier": "T3", "furigana": "低[ひく]い温度[おんど]では発酵[はっこう]がゆっくりなので、ワインの味[あじ]がまろやかになる。", "sentence_source": "generated"}, {"text": "発酵が止まってしまい、ビールはいつまでも甘いままだった。", "target_word": "発酵", "complexity_tier": "T3", "furigana": "発酵[はっこう]が止[と]まってしまい、ビールはいつまでも甘[あま]いままだった。", "sentence_source": "generated"}, {"text": "祖母は米麹と塩を混ぜて、一か月ほど発酵させる。", "target_word": "発酵", "complexity_tier": "T3", "furigana": "祖母[そぼ]は米麹[こめこうじ]と塩[しお]を混[ま]ぜて、一[いっ]か月[げつ]ほど発酵[はっこう]させる。", "sentence_source": "generated"}, {"text": "蓋を開けると、発酵したにおいが台所いっぱいに広がった。", "target_word": "発酵", "complexity_tier": "T3", "furigana": "蓋[ふた]を開[あ]けると、発酵[はっこう]したにおいが台所[だいどころ]いっぱいに広[ひろ]がった。", "sentence_source": "generated"}, {"text": "発酵のおかげで、大豆は消化しやすく、味も深くなる。", "target_word": "発酵", "complexity_tier": "T3", "furigana": "発酵[はっこう]のおかげで、大豆[だいず]は消化[しょうか]しやすく、味[あじ]も深[ふか]くなる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "発酵する", "label": "基本形(サ変動詞)"}, {"form": "発酵した", "label": "過去形"}, {"form": "発酵して", "label": "テ形"}, {"form": "発酵させる", "label": "使役形"}], "register": "neutral", "sense_fingerprint": "微生物のはたらきで食べ物の味やにおいが変わること(味噌・納豆・パン生地など)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fadd210-a29d-4c27-8f72-cc6debb7762d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35672, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "発酵", "is_correct": true, "explanation": "微生物のはたらきで牛乳が変化してヨーグルトになる、という文脈に合う。"}, {"text": "冷凍", "is_correct": false, "explanation": "牛乳を凍らせる意味で、ヨーグルトができる文とは合わない。"}, {"text": "沸騰", "is_correct": false, "explanation": "液体を煮立てる意味で、微生物の働きでヨーグルトができるという文脈とは合わない。"}, {"text": "研磨", "is_correct": false, "explanation": "こすって磨く意味で、牛乳には使えないので文が成り立たない。"}], "explanations": {"発酵": "微生物のはたらきで牛乳が変化してヨーグルトになる、という文脈に合う。", "冷凍": "牛乳を凍らせる意味で、ヨーグルトができる文とは合わない。", "沸騰": "液体を煮立てる意味で、微生物の働きでヨーグルトができるという文脈とは合わない。", "研磨": "こすって磨く意味で、牛乳には使えないので文が成り立たない。"}, "sentence_index": 0, "correct_answer": "発酵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新しい法律は来月から発酵する。", "explanation": "ここは〈発効〉の意味（法律などの効力が生じること）。〈発酵〉は微生物による食品の変化を指すので合わない。"}, {"text": "古い遺跡で、昔の土器を発酵した。", "explanation": "ここは〈発掘〉の意味。土の中から物を掘り出すことを指し、食べ物が微生物の働きで変わる〈発酵〉とは合わない。"}, {"text": "この酵素は脂肪を発酵する。", "explanation": "ここは〈分解〉の意味。酵素が物質を細かく分けることを指し、脂肪に対して〈発酵〉は使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c83277a-0ac9-4383-8090-f98d2f035f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35672, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "発酵", "is_correct": true, "explanation": "発酵が止まるとビールが甘いまま残る、という文脈に合う。"}, {"text": "凍結", "is_correct": false, "explanation": "水などが凍って固まる意味で、ビールの甘さが残る話とつながらない。"}, {"text": "膨張", "is_correct": false, "explanation": "ふくらむ意味で、止まったことでビールが甘いままという文脈に合わない。"}, {"text": "点火", "is_correct": false, "explanation": "火をつける意味で、ビールの甘さの話には合わない。"}], "explanations": {"発酵": "発酵が止まるとビールが甘いまま残る、という文脈に合う。", "凍結": "水などが凍って固まる意味で、ビールの甘さが残る話とつながらない。", "膨張": "ふくらむ意味で、止まったことでビールが甘いままという文脈に合わない。", "点火": "火をつける意味で、ビールの甘さの話には合わない。"}, "sentence_index": 6, "correct_answer": "発酵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "唾液は食べ物をよく発酵する。", "explanation": "ここは〈消化〉の意味。唾液が食べ物を分解することを指し、微生物の働きを表す〈発酵〉は合わない。"}, {"text": "塩は水によく発酵する。", "explanation": "ここは〈溶解〉の意味。物質が液体に溶けることを指し、食品の変化を表す〈発酵〉とは合わない。"}, {"text": "器具は熱湯で発酵してから使う。", "explanation": "ここは〈殺菌〉の意味。熱で菌を殺すことを指し、菌の働きで変化させる〈発酵〉とは逆で合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c83277a-0ac9-4383-8090-f98d2f035f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35672, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "室温が高いと、ぬか床の発酵を早く進む。", "corrected_sentence": "室温が高いと、ぬか床の発酵が早く進む。", "error_description": "「進む」は自動詞なので、動作の主体は「発酵が」の形で表す。「発酵を」は目的語の形で、ここでは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c83277a-0ac9-4383-8090-f98d2f035f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35672, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "パン生地を室温で一時間発酵せると、ふっくら仕上がる。", "corrected_sentence": "パン生地を室温で一時間発酵させると、ふっくら仕上がる。", "error_description": "「発酵させる」の使役の形が正しい。「発酵せる」は「させる」の活用の誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c83277a-0ac9-4383-8090-f98d2f035f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35674, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c83277a-0ac9-4383-8090-f98d2f035f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35674, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「乾燥に時間がかかる」で、時間がかかる対象を表す。"}, {"text": "が", "is_correct": false, "explanation": "「乾燥が時間がかかる」と主語にすると、「かかる」の対象の関係が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「乾燥を時間がかかる」と目的語にすると、動詞「かかる」と合わない。"}, {"text": "と", "is_correct": false, "explanation": "「乾燥と時間がかかる」と並べる形にすると、文の意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "「乾燥に時間がかかる」で、時間がかかる対象を表す。", "が": "「乾燥が時間がかかる」と主語にすると、「かかる」の対象の関係が成り立たない。", "を": "「乾燥を時間がかかる」と目的語にすると、動詞「かかる」と合わない。", "と": "「乾燥と時間がかかる」と並べる形にすると、文の意味が通らない。"}, "error_tags": {"が": "主語", "を": "目的語", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c83277a-0ac9-4383-8090-f98d2f035f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35674, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "水がなくなること。", "primary_collocate": null, "pronunciation": "かんそう", "ipa": "kaɴsoː", "syllable_count": 4, "sentences": [{"text": "洗濯物は風が強い日のほうが乾燥が早い。", "target_word": "乾燥", "complexity_tier": "T3", "furigana": "洗濯物[せんたくもの]は風[かぜ]が強[つよ]い日[ひ]のほうが乾燥[かんそう]が早[はや]い。", "sentence_source": "generated"}, {"text": "干したキノコは、乾燥させると長く保存できる。", "target_word": "乾燥", "complexity_tier": "T3", "furigana": "干[ほ]したキノコは、乾燥[かんそう]させると長[なが]く保存[ほぞん]できる。", "sentence_source": "generated"}, {"text": "雨が降らず、畑の土が乾燥してひび割れた。", "target_word": "乾燥", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]らず、畑[はたけ]の土[つち]が乾燥[かんそう]してひび割[わ]れた。", "sentence_source": "generated"}, {"text": "果物を乾燥させて、おやつのドライフルーツを作った。", "target_word": "乾燥", "complexity_tier": "T3", "furigana": "果物[くだもの]を乾燥[かんそう]させて、おやつのドライフルーツを作[つく]った。", "sentence_source": "generated"}, {"text": "木材は十分に乾燥しないと、あとで曲がることがある。", "target_word": "乾燥", "complexity_tier": "T3", "furigana": "木材[もくざい]は十分[じゅうぶん]に乾燥[かんそう]しないと、あとで曲[ま]がることがある。", "sentence_source": "generated"}, {"text": "日なたに置いたので、絵の具の乾燥は思ったより早かった。", "target_word": "乾燥", "complexity_tier": "T3", "furigana": "日[ひ]なたに置[お]いたので、絵[え]の具[ぐ]の乾燥[かんそう]は思[おも]ったより早[はや]かった。", "sentence_source": "generated"}, {"text": "魚を一晩乾燥させたら、身が固くなり味が濃くなった。", "target_word": "乾燥", "complexity_tier": "T3", "furigana": "魚[さかな]を一晩[ひとばん]乾燥[かんそう]させたら、身[み]が固[かた]くなり味[あじ]が濃[こ]くなった。", "sentence_source": "generated"}, {"text": "ペンキは乾燥に時間がかかるので、塗ったあとは一日待つ。", "target_word": "乾燥", "complexity_tier": "T3", "furigana": "ペンキは乾燥[かんそう]に時間[じかん]がかかるので、塗[ぬ]ったあとは一日[いちにち]待[ま]つ。", "sentence_source": "generated"}, {"text": "川の水が少なくなり、池の底まで乾燥してしまった。", "target_word": "乾燥", "complexity_tier": "T3", "furigana": "川[かわ]の水[みず]が少[すく]なくなり、池[いけ]の底[そこ]まで乾燥[かんそう]してしまった。", "sentence_source": "generated"}, {"text": "この粘土は、形を作ったあと一日乾燥させてから焼く。", "target_word": "乾燥", "complexity_tier": "T3", "furigana": "この粘土[ねんど]は、形[かたち]を作[つく]ったあと一日[いちにち]乾燥[かんそう]させてから焼[や]く。", "sentence_source": "generated"}], "morphological_forms": [{"form": "乾燥する", "label": "基本形(サ変動詞)"}, {"form": "乾燥した", "label": "過去形"}, {"form": "乾燥して", "label": "テ形"}, {"form": "乾燥させる", "label": "使役形"}], "register": "neutral", "sense_fingerprint": "ものから水が抜けて乾く過程(洗濯物・食材・土・木材などが乾くこと)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fadd210-a29d-4c27-8f72-cc6debb7762d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35674, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "乾燥", "is_correct": true, "explanation": "水分が抜けて乾いていく過程を表し、洗濯物が早く乾くという文脈に合う。"}, {"text": "凍結", "is_correct": false, "explanation": "水が固まる意味で、洗濯物が乾く話にはならない。"}, {"text": "沸騰", "is_correct": false, "explanation": "液体が沸く意味で、洗濯物には使えないので文が成り立たない。"}, {"text": "膨張", "is_correct": false, "explanation": "ふくらむ意味で、洗濯物の乾きの速さとは関係がない。"}], "explanations": {"乾燥": "水分が抜けて乾いていく過程を表し、洗濯物が早く乾くという文脈に合う。", "凍結": "水が固まる意味で、洗濯物が乾く話にはならない。", "沸騰": "液体が沸く意味で、洗濯物には使えないので文が成り立たない。", "膨張": "ふくらむ意味で、洗濯物の乾きの速さとは関係がない。"}, "sentence_index": 0, "correct_answer": "乾燥"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "やかんで水を乾燥させて、お茶をいれた。", "explanation": "ここは〈沸騰させる〉の意味。水を熱して湯にすることを指し、水分がなくなる過程の〈乾燥〉とは違うので合わない。"}, {"text": "熱いお茶を乾燥させて、冷ました。", "explanation": "ここは〈冷却〉の意味。熱を取って温度を下げることを指し、水分がなくなる〈乾燥〉とは違う。"}, {"text": "皿を乾燥させて、汚れを洗い流した。", "explanation": "ここは〈洗浄〉の意味。水などで汚れを落とすことを指し、水分を抜く〈乾燥〉では汚れは落ちない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c83277a-0ac9-4383-8090-f98d2f035f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35674, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "乾燥", "is_correct": true, "explanation": "水分を抜いて乾かす過程を表し、魚を一晩おいて身が固くなる文脈に合う。"}, {"text": "研磨", "is_correct": false, "explanation": "こすって磨く意味で、魚を一晩おく話には合わない。"}, {"text": "点火", "is_correct": false, "explanation": "火をつける意味で、魚の身が固くなる話には使えない。"}, {"text": "採掘", "is_correct": false, "explanation": "掘り出す意味で、魚には使えないので文が成り立たない。"}], "explanations": {"乾燥": "水分を抜いて乾かす過程を表し、魚を一晩おいて身が固くなる文脈に合う。", "研磨": "こすって磨く意味で、魚を一晩おく話には合わない。", "点火": "火をつける意味で、魚の身が固くなる話には使えない。", "採掘": "掘り出す意味で、魚には使えないので文が成り立たない。"}, "sentence_index": 6, "correct_answer": "乾燥"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "風船を乾燥させて、さらに大きくふくらませた。", "explanation": "ここは〈膨張〉の意味。ふくらませることを指し、水分を抜く〈乾燥〉とは違う。"}, {"text": "寒い朝、ドアの鍵が乾燥して開かなかった。", "explanation": "ここは〈凍結〉の意味。水が固まって動かなくなることを指し、水分が抜けていく〈乾燥〉とは違う。"}, {"text": "金属を乾燥させて、表面をなめらかにする。", "explanation": "ここは〈研磨〉の意味。こすって表面を磨く作業を指し、水分を抜くことは意味しない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c83277a-0ac9-4383-8090-f98d2f035f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35674, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "風が強いと洗濯物を乾燥が早く進む。", "corrected_sentence": "風が強いと洗濯物の乾燥が早く進む。", "error_description": "「乾燥」は「洗濯物の」と修飾して使う。「洗濯物を」は目的語の形で、ここでは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c83277a-0ac9-4383-8090-f98d2f035f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35674, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "木材は十分に乾燥せると、曲がりにくくなる。", "corrected_sentence": "木材は十分に乾燥させると、曲がりにくくなる。", "error_description": "「乾燥させる」の使役の形が正しい。「乾燥せる」は「させる」の活用の誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c83277a-0ac9-4383-8090-f98d2f035f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
