INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35675, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "水分がなくなり、かわいた状態になること。", "primary_collocate": null, "pronunciation": "かんそう", "ipa": "kaɴsoː", "syllable_count": 4, "sentences": [{"text": "冬は空気が乾燥するので、加湿器を使っている。", "target_word": "乾燥", "complexity_tier": "T3", "furigana": "冬[ふゆ]は空気[くうき]が乾燥[かんそう]するので、加湿器[かしつき]を使[つか]っている。", "sentence_source": "generated"}, {"text": "乾燥した季節には、のどが痛くなりやすい。", "target_word": "乾燥", "complexity_tier": "T3", "furigana": "乾燥[かんそう]した季節[きせつ]には、のどが痛[いた]くなりやすい。", "sentence_source": "generated"}, {"text": "部屋の乾燥がひどく、朝起きると唇が割れていた。", "target_word": "乾燥", "complexity_tier": "T3", "furigana": "部屋[へや]の乾燥[かんそう]がひどく、朝[あさ]起[お]きると唇[くちびる]が割[わ]れていた。", "sentence_source": "generated"}, {"text": "砂漠は雨が少なく、一年中乾燥した気候が続く。", "target_word": "乾燥", "complexity_tier": "T3", "furigana": "砂漠[さばく]は雨[あめ]が少[すく]なく、一年中[いちねんじゅう]乾燥[かんそう]した気候[きこう]が続[つづ]く。", "sentence_source": "generated"}, {"text": "乾燥した空気のせいで、火事が広がりやすくなった。", "target_word": "乾燥", "complexity_tier": "T3", "furigana": "乾燥[かんそう]した空気[くうき]のせいで、火事[かじ]が広[ひろ]がりやすくなった。", "sentence_source": "generated"}, {"text": "肌の乾燥を防ぐために、お風呂のあとにクリームをぬる。", "target_word": "乾燥", "complexity_tier": "T3", "furigana": "肌[はだ]の乾燥[かんそう]を防[ふせ]ぐために、お風呂[ふろ]のあとにクリームをぬる。", "sentence_source": "generated"}, {"text": "乾燥した日には、ドアにさわると静電気が起きる。", "target_word": "乾燥", "complexity_tier": "T3", "furigana": "乾燥[かんそう]した日[ひ]には、ドアにさわると静電気[せいでんき]が起[お]きる。", "sentence_source": "generated"}, {"text": "暖房をつけっぱなしにすると、部屋が乾燥しすぎて目が痛くなる。", "target_word": "乾燥", "complexity_tier": "T3", "furigana": "暖房[だんぼう]をつけっぱなしにすると、部屋[へや]が乾燥[かんそう]しすぎて目[め]が痛[いた]くなる。", "sentence_source": "generated"}, {"text": "この地方は夏でも乾燥していて、洗濯物がすぐに乾く。", "target_word": "乾燥", "complexity_tier": "T3", "furigana": "この地方[ちほう]は夏[なつ]でも乾燥[かんそう]していて、洗濯物[せんたくもの]がすぐに乾[かわ]く。", "sentence_source": "generated"}, {"text": "乾燥が続いたので、山の草木が枯れはじめた。", "target_word": "乾燥", "complexity_tier": "T3", "furigana": "乾燥[かんそう]が続[つづ]いたので、山[やま]の草木[くさき]が枯[か]れはじめた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "乾燥する", "label": "基本形(サ変動詞)"}, {"form": "乾燥した", "label": "過去形・連体形"}, {"form": "乾燥して", "label": "テ形"}, {"form": "乾燥しすぎ", "label": "過度の状態を表す形"}], "register": "neutral", "sense_fingerprint": "空気・肌・気候などの水分が少なく、かわいた状態になること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fadd210-a29d-4c27-8f72-cc6debb7762d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35675, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "乾燥", "is_correct": true, "explanation": "空気の水分が少なく、かわいた状態を表し、加湿器を使う文脈に合う。"}, {"text": "凍結", "is_correct": false, "explanation": "水などが固まる意味で、空気には使わず加湿器の話ともつながらない。"}, {"text": "点火", "is_correct": false, "explanation": "火をつける意味で、空気の状態を表せない。"}, {"text": "沈殿", "is_correct": false, "explanation": "粒子が底に沈む意味で、空気の状態を表す文には合わない。"}], "explanations": {"乾燥": "空気の水分が少なく、かわいた状態を表し、加湿器を使う文脈に合う。", "凍結": "水などが固まる意味で、空気には使わず加湿器の話ともつながらない。", "点火": "火をつける意味で、空気の状態を表せない。", "沈殿": "粒子が底に沈む意味で、空気の状態を表す文には合わない。"}, "sentence_index": 0, "correct_answer": "乾燥"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "台風が来て、町の畑が乾燥した。", "explanation": "ここは〈浸水〉の意味。水に覆われることを指し、水分が少なくなってかわく〈乾燥〉とは逆で合わない。"}, {"text": "梅雨は乾燥が多く、洗濯物が乾きにくい。", "explanation": "ここは〈湿気〉の意味。湿気が多いから洗濯物が乾きにくいという文で、〈乾燥〉を入れると意味が逆になる。"}, {"text": "書類を乾燥させて、順番に並べた。", "explanation": "ここは〈整理〉の意味。書類を順番に並べることを指し、水分を抜く〈乾燥〉とは違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c83277a-0ac9-4383-8090-f98d2f035f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35675, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "乾燥", "is_correct": true, "explanation": "空気や肌の水分が少ない状態を表し、ドアにさわると静電気が起きる文脈に合う。"}, {"text": "沸騰", "is_correct": false, "explanation": "液体が煮立つ意味で、乾いた日の話には合わない。"}, {"text": "膨張", "is_correct": false, "explanation": "ふくらむ意味で、静電気が起きる文脈に合わない。"}, {"text": "研磨", "is_correct": false, "explanation": "こすって磨く意味で、乾いた日の状態を表せない。"}], "explanations": {"乾燥": "空気や肌の水分が少ない状態を表し、ドアにさわると静電気が起きる文脈に合う。", "沸騰": "液体が煮立つ意味で、乾いた日の話には合わない。", "膨張": "ふくらむ意味で、静電気が起きる文脈に合わない。", "研磨": "こすって磨く意味で、乾いた日の状態を表せない。"}, "sentence_index": 6, "correct_answer": "乾燥"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雨で鉄の橋が乾燥した。", "explanation": "ここは〈腐食〉の意味。金属が化学変化で傷むことを指し、水分が少ない状態の〈乾燥〉とは違う。"}, {"text": "寒さで池が乾燥して、スケートができた。", "explanation": "ここは〈凍結〉の意味。水が固まって滑れる状態を指し、水分がなくなる〈乾燥〉とは違う。"}, {"text": "春になって雪が乾燥し、道が濡れた。", "explanation": "ここは〈融解〉の意味。雪が解けて水になることを指し、かわいた状態を表す〈乾燥〉とは逆で合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c83277a-0ac9-4383-8090-f98d2f035f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35675, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "加湿器をつけたので、部屋を乾燥がやわらいだ。", "corrected_sentence": "加湿器をつけたので、部屋の乾燥がやわらいだ。", "error_description": "「乾燥」は「部屋の」と修飾して使う。「部屋を」は目的語の形で、ここでは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c83277a-0ac9-4383-8090-f98d2f035f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35675, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "冬は空気が乾燥いるので、のどを守る。", "corrected_sentence": "冬は空気が乾燥しているので、のどを守る。", "error_description": "状態を表すには「乾燥している」と動詞の形が必要。「乾燥いる」は活用の形として誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c83277a-0ac9-4383-8090-f98d2f035f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35676, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「一連の動作」で、続く動作の一まとまりを修飾する。"}, {"text": "が", "is_correct": false, "explanation": "「一連が動作を」と主語にすると、文の構造が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「一連を動作を」と目的語にすると、動作を二重に示す形になり不自然。"}, {"text": "に", "is_correct": false, "explanation": "「一連に動作を」と方向の形にすると、動作を修飾できない。"}], "correct_answer": "の", "explanations": {"の": "「一連の動作」で、続く動作の一まとまりを修飾する。", "が": "「一連が動作を」と主語にすると、文の構造が成り立たない。", "を": "「一連を動作を」と目的語にすると、動作を二重に示す形になり不自然。", "に": "「一連に動作を」と方向の形にすると、動作を修飾できない。"}, "error_tags": {"が": "主語", "を": "目的語", "に": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c83277a-0ac9-4383-8090-f98d2f035f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35676, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「一連の出来事」で、続く出来事のまとまりを修飾する。"}, {"text": "へ", "is_correct": false, "explanation": "「一連へ出来事を」と方向の形にすると、出来事を修飾できない。"}, {"text": "で", "is_correct": false, "explanation": "「一連で出来事を」と手段の形にすると、出来事との関係が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「一連より出来事を」と比較の形にすると、文の意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「一連の出来事」で、続く出来事のまとまりを修飾する。", "へ": "「一連へ出来事を」と方向の形にすると、出来事を修飾できない。", "で": "「一連で出来事を」と手段の形にすると、出来事との関係が成り立たない。", "より": "「一連より出来事を」と比較の形にすると、文の意味が通らない。"}, "error_tags": {"へ": "方向", "で": "手段", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c83277a-0ac9-4383-8090-f98d2f035f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35676, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "いくつかのことが、続けて起こることをいう。", "primary_collocate": null, "pronunciation": "いちれん", "ipa": "itɕiɾeɴ", "syllable_count": 4, "sentences": [{"text": "工場で一連の事故が起き、会社は工場を止めることにした。", "target_word": "一連", "complexity_tier": "T3", "furigana": "工場[こうじょう]で一連[いちれん]の事故[じこ]が起[お]き、会社[かいしゃ]は工場[こうじょう]を止[と]めることにした。", "sentence_source": "generated"}, {"text": "彼は一連の動作を、迷わずに素早く終えた。", "target_word": "一連", "complexity_tier": "T3", "furigana": "彼[かれ]は一連[いちれん]の動作[どうさ]を、迷[まよ]わずに素早[すばや]く終[お]えた。", "sentence_source": "generated"}, {"text": "警察は一連の事件を、同じ犯人によるものと考えている。", "target_word": "一連", "complexity_tier": "T3", "furigana": "警察[けいさつ]は一連[いちれん]の事件[じけん]を、同[おな]じ犯人[はんにん]によるものと考[かんが]えている。", "sentence_source": "generated"}, {"text": "一連の流れを覚えれば、手続きは難しくない。", "target_word": "一連", "complexity_tier": "T3", "furigana": "一連[いちれん]の流[なが]れを覚[おぼ]えれば、手続[てつづ]きは難[むずか]しくない。", "sentence_source": "generated"}, {"text": "政府は一連の問題について、記者会見で説明した。", "target_word": "一連", "complexity_tier": "T3", "furigana": "政府[せいふ]は一連[いちれん]の問題[もんだい]について、記者会見[きしゃかいけん]で説明[せつめい]した。", "sentence_source": "generated"}, {"text": "選手は一連の練習を終えて、ようやく休んだ。", "target_word": "一連", "complexity_tier": "T3", "furigana": "選手[せんしゅ]は一連[いちれん]の練習[れんしゅう]を終[お]えて、ようやく休[やす]んだ。", "sentence_source": "generated"}, {"text": "先生は実験の一連の手順を、黒板に順番に書いた。", "target_word": "一連", "complexity_tier": "T3", "furigana": "先生[せんせい]は実験[じっけん]の一連[いちれん]の手順[てじゅん]を、黒板[こくばん]に順番[じゅんばん]に書[か]いた。", "sentence_source": "generated"}, {"text": "一連の出来事を思い出すと、今でも胸が苦しくなる。", "target_word": "一連", "complexity_tier": "T3", "furigana": "一連[いちれん]の出来事[できごと]を思[おも]い出[だ]すと、今[いま]でも胸[むね]が苦[くる]しくなる。", "sentence_source": "generated"}, {"text": "町では夏の一連の行事が終わり、広場は静かになった。", "target_word": "一連", "complexity_tier": "T3", "furigana": "町[まち]では夏[なつ]の一連[いちれん]の行事[ぎょうじ]が終[お]わり、広場[ひろば]は静[しず]かになった。", "sentence_source": "generated"}, {"text": "社長は一連の失敗の責任を取って、会社をやめた。", "target_word": "一連", "complexity_tier": "T3", "furigana": "社長[しゃちょう]は一連[いちれん]の失敗[しっぱい]の責任[せきにん]を取[と]って、会社[かいしゃ]をやめた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "一連", "label": "基本形"}, {"form": "一連の", "label": "連体修飾形"}], "register": "neutral", "sense_fingerprint": "互いに関連して続けて起こる、いくつかの出来事や動作のまとまり(「一連の〜」)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fadd210-a29d-4c27-8f72-cc6debb7762d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35676, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一連", "is_correct": true, "explanation": "続けて起こった出来事のまとまりを表し、一連の事故という文脈に合う。"}, {"text": "一括", "is_correct": false, "explanation": "まとめて一度に行う意味で、続けて起こる事故には使わない。"}, {"text": "一閃", "is_correct": false, "explanation": "ぴかりと光る一瞬を表し、事故の文脈には合わない。"}, {"text": "一辺", "is_correct": false, "explanation": "図形の一つの辺の意味で、事故の文には使えない。"}], "explanations": {"一連": "続けて起こった出来事のまとまりを表し、一連の事故という文脈に合う。", "一括": "まとめて一度に行う意味で、続けて起こる事故には使わない。", "一閃": "ぴかりと光る一瞬を表し、事故の文脈には合わない。", "一辺": "図形の一つの辺の意味で、事故の文には使えない。"}, "sentence_index": 0, "correct_answer": "一連"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "生徒たちは一連に手を挙げた。", "explanation": "ここは〈一斉〉の意味。同時に全員が動くことを指し、続いて起こることを表す〈一連〉とは合わない。"}, {"text": "商品の一連を見る。", "explanation": "ここは〈一覧〉の意味。項目を並べた表を見る話で、〈一連〉は出来事の続きを表すので合わない。"}, {"text": "雨が三日一連で降った。", "explanation": "ここは〈連続〉の意味。途切れず続くことを言うが、〈一連〉は続けて起こる出来事のまとまりで、雨の日数には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c83277a-0ac9-4383-8090-f98d2f035f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35676, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一連", "is_correct": true, "explanation": "続いて並ぶ手順のまとまりを表し、順番に書いた手順という文脈に合う。"}, {"text": "一瞬", "is_correct": false, "explanation": "ほんの短い時間の意味で、手順には合わない。"}, {"text": "一面", "is_correct": false, "explanation": "表面全体の意味で、手順を書く文には合わない。"}, {"text": "一抹", "is_correct": false, "explanation": "わずかなという意味で、手順の話とは合わない。"}], "explanations": {"一連": "続いて並ぶ手順のまとまりを表し、順番に書いた手順という文脈に合う。", "一瞬": "ほんの短い時間の意味で、手順には合わない。", "一面": "表面全体の意味で、手順を書く文には合わない。", "一抹": "わずかなという意味で、手順の話とは合わない。"}, "sentence_index": 6, "correct_answer": "一連"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "一連の客が一度に店に入ってきた。", "explanation": "ここは〈一斉〉の意味。同時に入ることを指し、続けて起こる〈一連〉とは合わない。"}, {"text": "店で靴下を一連買った。", "explanation": "ここは〈一対〉の意味。二つで一組になる物を言い、〈一連〉は靴下の数え方には使えない。"}, {"text": "父は一連の車を買った。", "explanation": "ここは〈一台〉の意味。車を数える言い方で、〈一連〉は続く出来事を表すので車には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c83277a-0ac9-4383-8090-f98d2f035f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35676, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新製品の発売に伴い、一連を不具合が報告された。", "corrected_sentence": "新製品の発売に伴い、一連の不具合が報告された。", "error_description": "「一連」は「の」で後ろの「不具合」を修飾する。「一連を」は目的語の形で、ここでは誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c83277a-0ac9-4383-8090-f98d2f035f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35676, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工事の一連な作業が終わり、道路が開通した。", "corrected_sentence": "工事の一連の作業が終わり、道路が開通した。", "error_description": "「一連」は名詞なので、続く名詞を「の」でつなぐ。「な」は形容動詞の語尾なので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c83277a-0ac9-4383-8090-f98d2f035f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35678, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c83277a-0ac9-4383-8090-f98d2f035f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35678, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「熱湯で処理する」の「で」は手段を表し、熱湯を使って処理する意味になる。"}, {"text": "に", "is_correct": false, "explanation": "「に」は対象や行き先を示すため、「熱湯に処理する」は不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すため、処理の手段を表せず合わない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すため、熱湯を使う手段の意味にならず合わない。"}], "correct_answer": "で", "explanations": {"で": "「熱湯で処理する」の「で」は手段を表し、熱湯を使って処理する意味になる。", "に": "「に」は対象や行き先を示すため、「熱湯に処理する」は不自然。", "へ": "「へ」は方向を示すため、処理の手段を表せず合わない。", "から": "「から」は起点を示すため、熱湯を使う手段の意味にならず合わない。"}, "error_tags": {"に": "対象・着点", "へ": "方向", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c83277a-0ac9-4383-8090-f98d2f035f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35678, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何かをするために、ものを変えたり、整えたりすること。", "primary_collocate": null, "pronunciation": "しょり", "ipa": "ɕoɾi", "syllable_count": 2, "sentences": [{"text": "魚は料理の前に、うろこと内臓の処理をしておく。", "target_word": "処理", "complexity_tier": "T3", "furigana": "魚[さかな]は料理[りょうり]の前[まえ]に、うろこと内臓[ないぞう]の処理[しょり]をしておく。", "sentence_source": "generated"}, {"text": "古くなった薬品は、専門の業者が安全に処理する。", "target_word": "処理", "complexity_tier": "T3", "furigana": "古[ふる]くなった薬品[やくひん]は、専門[せんもん]の業者[ぎょうしゃ]が安全[あんぜん]に処理[しょり]する。", "sentence_source": "generated"}, {"text": "金属の表面を薬品で処理すると、さびにくくなる。", "target_word": "処理", "complexity_tier": "T3", "furigana": "金属[きんぞく]の表面[ひょうめん]を薬品[やくひん]で処理[しょり]すると、さびにくくなる。", "sentence_source": "generated"}, {"text": "傷の処理が遅れたため、ばい菌が入ってしまった。", "target_word": "処理", "complexity_tier": "T3", "furigana": "傷[きず]の処理[しょり]が遅[おく]れたため、ばい菌[きん]が入[はい]ってしまった。", "sentence_source": "generated"}, {"text": "台風のあとは、倒れた木の処理が大変だった。", "target_word": "処理", "complexity_tier": "T3", "furigana": "台風[たいふう]のあとは、倒[たお]れた木[き]の処理[しょり]が大変[たいへん]だった。", "sentence_source": "generated"}, {"text": "生ごみは、においが出る前に処理したほうがいい。", "target_word": "処理", "complexity_tier": "T3", "furigana": "生[なま]ごみは、においが出[で]る前[まえ]に処理[しょり]したほうがいい。", "sentence_source": "generated"}, {"text": "この布は、防水の処理がしてあるので雨に強い。", "target_word": "処理", "complexity_tier": "T3", "furigana": "布[ぬの]は、防水[ぼうすい]の処理[しょり]がしてあるので雨[あめ]に強[つよ]い。", "sentence_source": "generated"}, {"text": "野菜を冷凍する前に、熱湯で処理しておくと色がきれいに残る。", "target_word": "処理", "complexity_tier": "T3", "furigana": "野菜[やさい]を冷凍[れいとう]する前[まえ]に、熱湯[ねっとう]で処理[しょり]しておくと色[いろ]がきれいに残[のこ]る。", "sentence_source": "generated"}, {"text": "古いペンキをはがす処理に、丸一日かかった。", "target_word": "処理", "complexity_tier": "T3", "furigana": "古[ふる]いペンキをはがす処理[しょり]に、丸一日[まるいちにち]かかった。", "sentence_source": "generated"}, {"text": "工場では、出た水を処理してから川に流している。", "target_word": "処理", "complexity_tier": "T3", "furigana": "工場[こうじょう]では、出[で]た水[みず]を処理[しょり]してから川[かわ]に流[なが]している。", "sentence_source": "generated"}], "morphological_forms": [{"form": "処理する", "label": "基本形(サ変動詞)"}, {"form": "処理した", "label": "過去形"}, {"form": "処理して", "label": "テ形"}, {"form": "処理される", "label": "受身形"}], "register": "neutral", "sense_fingerprint": "ごみ・書類・傷・材料など具体的なものに手を加えて片付けたり整えたりすること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 3 above tier T2: contains vocabulary far above tier T2: ばい菌 (Zipf 2.46)']::text[], '0fadd210-a29d-4c27-8f72-cc6debb7762d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35678, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "処理", "is_correct": true, "explanation": "ここは魚のうろこや内臓を取り除いて整える作業の意味で、「処理をする」と言う。"}, {"text": "盛り付け", "is_correct": false, "explanation": "盛り付けは料理を器に並べることなので、うろこや内臓を取り除く下準備には合わない。"}, {"text": "配達", "is_correct": false, "explanation": "配達は品物を届けることなので、魚の下ごしらえの段階には当てはまらない。"}, {"text": "計量", "is_correct": false, "explanation": "計量は分量をはかることなので、うろこや内臓を取り除く作業とは意味が合わない。"}], "explanations": {"処理": "ここは魚のうろこや内臓を取り除いて整える作業の意味で、「処理をする」と言う。", "盛り付け": "盛り付けは料理を器に並べることなので、うろこや内臓を取り除く下準備には合わない。", "配達": "配達は品物を届けることなので、魚の下ごしらえの段階には当てはまらない。", "計量": "計量は分量をはかることなので、うろこや内臓を取り除く作業とは意味が合わない。"}, "sentence_index": 0, "correct_answer": "処理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "食事の代金を処理して、店を出た。", "explanation": "ここは〈支払い〉の意味。代金を払うことには〈支払い〉を使い、〈処理〉は物に手を加えて整える意味なので合わない。"}, {"text": "車を処理しながら、道を教えた。", "explanation": "ここは〈運転〉の意味。車を動かすことには〈運転〉を使い、〈処理〉は手を加えて片付けたり整えたりすることなので合わない。"}, {"text": "風邪の処理をするため、病院へ行った。", "explanation": "ここは〈治療〉の意味。病気を治すことには〈治療〉を使い、〈処理〉は物に手を加えて整える場合に使うので、病気には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c83277a-0ac9-4383-8090-f98d2f035f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35678, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "処理", "is_correct": true, "explanation": "ここは布に防水の手を加えてあるという意味。「処理してある」で加工や施しを表す。"}, {"text": "柄", "is_correct": false, "explanation": "柄は布の模様のことで、防水の性質を表さないので合わない。"}, {"text": "色", "is_correct": false, "explanation": "色は布の色味のことで、防水の手入れとは結びつかない。"}, {"text": "糸", "is_correct": false, "explanation": "糸は布を織る材料で、防水の加工をした状態を表さないので合わない。"}], "explanations": {"処理": "ここは布に防水の手を加えてあるという意味。「処理してある」で加工や施しを表す。", "柄": "柄は布の模様のことで、防水の性質を表さないので合わない。", "色": "色は布の色味のことで、防水の手入れとは結びつかない。", "糸": "糸は布を織る材料で、防水の加工をした状態を表さないので合わない。"}, "sentence_index": 6, "correct_answer": "処理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "母は毎日、家族のために夕食の処理を作っている。", "explanation": "ここは〈料理〉の意味。食事を作ることには〈料理〉を使い、〈処理〉は物を片付けたり整えたりすることなので、夕食を作る文には合わない。"}, {"text": "雨で大事な試合を処理することになった。", "explanation": "ここは〈中止〉の意味。試合を取りやめるときは〈中止〉を使い、〈処理〉は物や書類を片付けることなので合わない。"}, {"text": "店で飲み物を処理して、席で待った。", "explanation": "ここは〈注文〉の意味。飲み物を頼むことには〈注文〉を使い、〈処理〉は手を加えて片付けたり整えたりすることなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c83277a-0ac9-4383-8090-f98d2f035f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35678, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "古いペンキをはがす処理を、半日もかかった。", "corrected_sentence": "古いペンキをはがす処理に、半日もかかった。", "error_description": "正しくは「処理に半日もかかった」。「かかる」は時間や手間を表す「に」を取るので、「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c83277a-0ac9-4383-8090-f98d2f035f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35678, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ほうれん草を冷凍する前に、熱湯に処理しておくと色がきれいに残る。", "corrected_sentence": "ほうれん草を冷凍する前に、熱湯で処理しておくと色がきれいに残る。", "error_description": "正しくは「熱湯で処理する」。手段を表す「で」が必要で、「熱湯に処理する」は「に」が合わず不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c83277a-0ac9-4383-8090-f98d2f035f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35679, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「処理に時間がかかる」の「に」は、処理にかかる時間の対象を表す。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すので、「処理を時間がかかる」は不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、処理と時間の関係を表せず合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や相手を示すので、「処理と時間がかかる」は意味が通らない。"}], "correct_answer": "に", "explanations": {"に": "「処理に時間がかかる」の「に」は、処理にかかる時間の対象を表す。", "を": "「を」は目的語を示すので、「処理を時間がかかる」は不自然。", "へ": "「へ」は方向を示すので、処理と時間の関係を表せず合わない。", "と": "「と」は並列や相手を示すので、「処理と時間がかかる」は意味が通らない。"}, "error_tags": {"を": "目的語", "へ": "方向", "と": "並列・相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c83277a-0ac9-4383-8090-f98d2f035f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35679, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「処理の途中」の「の」は、処理と途中をつなぐ所属を表す。"}, {"text": "に", "is_correct": false, "explanation": "「に」は時点や対象を示すので、「処理に途中で電源が切れ」は不自然。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列を示すので、「処理と途中で」は意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「処理へ途中で」は合わない。"}], "correct_answer": "の", "explanations": {"の": "「処理の途中」の「の」は、処理と途中をつなぐ所属を表す。", "に": "「に」は時点や対象を示すので、「処理に途中で電源が切れ」は不自然。", "と": "「と」は並列を示すので、「処理と途中で」は意味が通らない。", "へ": "「へ」は方向を示すので、「処理へ途中で」は合わない。"}, "error_tags": {"に": "時点・対象", "と": "並列", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c83277a-0ac9-4383-8090-f98d2f035f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35679, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "物事を目的に沿って操作したり、変化させたりすること。また、そのための一連の手順や作業。", "primary_collocate": null, "pronunciation": "しょり", "ipa": "ɕoɾi", "syllable_count": 2, "sentences": [{"text": "このソフトは、大きな画像でも速く処理できる。", "target_word": "処理", "complexity_tier": "T3", "furigana": "このソフトは、大[おお]きな画像[がぞう]でも速[はや]く処理[しょり]できる。", "sentence_source": "generated"}, {"text": "古いパソコンは、データの処理に時間がかかる。", "target_word": "処理", "complexity_tier": "T3", "furigana": "古[ふる]いパソコンは、データの処理[しょり]に時間[じかん]がかかる。", "sentence_source": "generated"}, {"text": "入力された情報は、サーバーで自動的に処理される。", "target_word": "処理", "complexity_tier": "T3", "furigana": "入力[にゅうりょく]された情報[じょうほう]は、サーバーで自動的[じどうてき]に処理[しょり]される。", "sentence_source": "generated"}, {"text": "処理の手順を間違えて、計算の結果が変わってしまった。", "target_word": "処理", "complexity_tier": "T3", "furigana": "処理[しょり]の手順[てじゅん]を間違[まちが]えて、計算[けいさん]の結果[けっか]が変[か]わってしまった。", "sentence_source": "generated"}, {"text": "注文が多すぎて、システムの処理が追いつかなかった。", "target_word": "処理", "complexity_tier": "T3", "furigana": "注文[ちゅうもん]が多[おお]すぎて、システムの処理[しょり]が追[お]いつかなかった。", "sentence_source": "generated"}, {"text": "新しい機械は、一秒間に何万件もの処理を行う。", "target_word": "処理", "complexity_tier": "T3", "furigana": "新[あたら]しい機械[きかい]は、一秒間[いちびょうかん]に何万件[なんまんけん]もの処理[しょり]を行[おこな]う。", "sentence_source": "generated"}, {"text": "カメラは、撮った写真を内部で処理してから保存する。", "target_word": "処理", "complexity_tier": "T3", "furigana": "カメラは、撮[と]った写真[しゃしん]を内部[ないぶ]で処理[しょり]してから保存[ほぞん]する。", "sentence_source": "generated"}, {"text": "処理の途中で電源が切れ、作業が最初からやり直しになった。", "target_word": "処理", "complexity_tier": "T3", "furigana": "処理[しょり]の途中[とちゅう]で電源[でんげん]が切[き]れ、作業[さぎょう]が最初[さいしょ]からやり直[なお]しになった。", "sentence_source": "generated"}, {"text": "音声をテキストにする処理は、いくつかの段階に分かれている。", "target_word": "処理", "complexity_tier": "T3", "furigana": "音声[おんせい]をテキストにする処理[しょり]は、いくつかの段階[だんかい]に分[わ]かれている。", "sentence_source": "generated"}, {"text": "プログラムの処理が終わるまで、画面を閉じてはいけない。", "target_word": "処理", "complexity_tier": "T3", "furigana": "プログラムの処理[しょり]が終[お]わるまで、画面[がめん]を閉[と]じてはいけない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "処理する", "label": "基本形(サ変動詞)"}, {"form": "処理した", "label": "過去形"}, {"form": "処理される", "label": "受身形"}, {"form": "処理できる", "label": "可能形"}], "register": "neutral", "sense_fingerprint": "コンピューターやシステムがデータ・情報を決まった手順で扱うこと、またその手順や作業", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fadd210-a29d-4c27-8f72-cc6debb7762d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35679, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "処理", "is_correct": true, "explanation": "ここはソフトが画像を扱って作業を進める意味で、「速く処理できる」と言う。"}, {"text": "画面", "is_correct": false, "explanation": "画面は表示される面のことで、「速く〜できる」の形で作業を表す名詞として合わない。"}, {"text": "データ", "is_correct": false, "explanation": "データは情報のまとまりで、「速くデータできる」とは作業を表せないので合わない。"}, {"text": "画像", "is_correct": false, "explanation": "画像は絵や写真のことで、「速く画像できる」と作業を表せないので合わない。"}], "explanations": {"処理": "ここはソフトが画像を扱って作業を進める意味で、「速く処理できる」と言う。", "画面": "画面は表示される面のことで、「速く〜できる」の形で作業を表す名詞として合わない。", "データ": "データは情報のまとまりで、「速くデータできる」とは作業を表せないので合わない。", "画像": "画像は絵や写真のことで、「速く画像できる」と作業を表せないので合わない。"}, "sentence_index": 0, "correct_answer": "処理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "毎朝、庭の花を処理して、成長を記録した。", "explanation": "ここは〈観察〉の意味。花の様子を見て記録することには〈観察〉を使い、〈処理〉は目的に沿って物事を操作することなので合わない。"}, {"text": "店で飲み物を処理して、席で待った。", "explanation": "ここは〈注文〉の意味。飲み物を頼むことには〈注文〉を使い、〈処理〉は情報を決まった手順で扱うことなので合わない。"}, {"text": "ピアノを処理して、曲を弾いた。", "explanation": "ここは〈演奏〉の意味。楽器で曲を弾くことには〈演奏〉を使い、〈処理〉は目的に沿って物事を操作することなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c83277a-0ac9-4383-8090-f98d2f035f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35679, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "処理", "is_correct": true, "explanation": "ここはカメラが写真を内部で処理してから保存するという、情報を扱う作業の意味。"}, {"text": "撤去", "is_correct": false, "explanation": "撤去は設置したものを取り除くことなので、写真を内部で扱う作業には合わない。"}, {"text": "点灯", "is_correct": false, "explanation": "点灯は明かりをつけることなので、写真を扱う作業とは結びつかない。"}, {"text": "睡眠", "is_correct": false, "explanation": "睡眠は眠ることなので、写真を内部で扱う作業には当たらない。"}], "explanations": {"処理": "ここはカメラが写真を内部で処理してから保存するという、情報を扱う作業の意味。", "撤去": "撤去は設置したものを取り除くことなので、写真を内部で扱う作業には合わない。", "点灯": "点灯は明かりをつけることなので、写真を扱う作業とは結びつかない。", "睡眠": "睡眠は眠ることなので、写真を内部で扱う作業には当たらない。"}, "sentence_index": 6, "correct_answer": "処理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "母は毎日、家族のために夕食の処理を作っている。", "explanation": "ここは〈料理〉の意味。食事を作ることには〈料理〉を使い、〈処理〉は情報や手順を扱う場合に使うので、夕食の文には合わない。"}, {"text": "雨で大事な試合を処理することになり、残念だった。", "explanation": "ここは〈中止〉の意味。試合を取りやめるときは〈中止〉を使い、〈処理〉は情報を決まった手順で扱うことなので合わない。"}, {"text": "休みの日は、軽く処理して汗を流す。", "explanation": "ここは〈運動〉の意味。体を動かすことには〈運動〉を使い、〈処理〉は目的に沿って物事を操作することなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c83277a-0ac9-4383-8090-f98d2f035f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35679, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "古いスマホは、写真の処理を時間がかかる。", "corrected_sentence": "古いスマホは、写真の処理に時間がかかる。", "error_description": "正しくは「処理に時間がかかる」。「時間がかかる」には「に」が必要で、「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c83277a-0ac9-4383-8090-f98d2f035f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35679, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "データの処理を終わってから、結果を保存する。", "corrected_sentence": "データの処理が終わってから、結果を保存する。", "error_description": "正しくは「処理が終わる」。「終わる」は自動詞なので主語に「が」を使う。「処理を終わる」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c83277a-0ac9-4383-8090-f98d2f035f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
