INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35682, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "加熱や加工をせず、手を加えないそのままの状態であること。", "primary_collocate": null, "pronunciation": "なま", "ipa": "nama", "syllable_count": 2, "sentences": [{"text": "新鮮な魚なので、生で食べても安心です。", "target_word": "生", "complexity_tier": "T3", "furigana": "新鮮[しんせん]な魚[さかな]なので、生[なま]で食[た]べても安心[あんしん]です。", "sentence_source": "generated"}, {"text": "この野菜は生のままでも甘いので、サラダにしました。", "target_word": "生", "complexity_tier": "T3", "furigana": "この野菜[やさい]は生[なま]のままでも甘[あま]いので、サラダにしました。", "sentence_source": "generated"}, {"text": "母は生の貝を食べるとお腹をこわすので、いつも焼いて食べます。", "target_word": "生", "complexity_tier": "T3", "furigana": "母[はは]は生[なま]の貝[かい]を食[た]べるとお腹[なか]をこわすので、いつも焼[や]いて食[た]べます。", "sentence_source": "generated"}, {"text": "生の果物は、缶詰より香りが強いです。", "target_word": "生", "complexity_tier": "T3", "furigana": "生[なま]の果物[くだもの]は、缶詰[かんづめ]より香[かお]りが強[つよ]いです。", "sentence_source": "generated"}, {"text": "卵を生のままごはんにかけて食べるのが好きです。", "target_word": "生", "complexity_tier": "T3", "furigana": "卵[たまご]を生[なま]のままごはんにかけて食[た]べるのが好[す]きです。", "sentence_source": "generated"}, {"text": "肉は生だと危ないので、中までしっかり焼きましょう。", "target_word": "生", "complexity_tier": "T3", "furigana": "肉[にく]は生[なま]だと危[あぶ]ないので、中[なか]までしっかり焼[や]きましょう。", "sentence_source": "generated"}, {"text": "ウニは生が一番おいしいと、漁師さんが教えてくれた。", "target_word": "生", "complexity_tier": "T3", "furigana": "ウニは生[なま]が一番[いちばん]おいしいと、漁師[りょうし]さんが教[おし]えてくれた。", "sentence_source": "generated"}, {"text": "干したきのこより、生のきのこのほうが水分が多い。", "target_word": "生", "complexity_tier": "T3", "furigana": "干[ほ]したきのこより、生[なま]のきのこのほうが水分[すいぶん]が多[おお]い。", "sentence_source": "generated"}, {"text": "生のにんじんは固いが、すりおろせば食べやすい。", "target_word": "生", "complexity_tier": "T3", "furigana": "生[なま]のにんじんは固[かた]いが、すりおろせば食[た]べやすい。", "sentence_source": "generated"}, {"text": "この店のカキは、生でも焼いてもおいしい。", "target_word": "生", "complexity_tier": "T3", "furigana": "この店[みせ]のカキは、生[なま]でも焼[や]いてもおいしい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "生", "label": "base"}], "register": "neutral", "sense_fingerprint": "生で・生のまま。手を加えない、生きたままの新鮮な状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T1: 3 words above tier T1 (max 2): 干し (Zipf 3.8), きのこ (Zipf 3.87), きのこ (Zipf 3.87)','sentence 8 above tier T1: 4 words above tier T1 (max 2): にんじん (Zipf 3.33), 固い (Zipf 3.76), すり (Zipf 3.92), おろせ (Zipf 2.55)']::text[], '0fadd210-a29d-4c27-8f72-cc6debb7762d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35682, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生", "is_correct": true, "explanation": "ここは魚を加熱せず、そのままの状態で食べるという意味。「生で食べる」と言う。"}, {"text": "焼き", "is_correct": false, "explanation": "焼きは火を通した状態を指すので、「焼きで食べる」とは言わず合わない。"}, {"text": "干し", "is_correct": false, "explanation": "干しは乾燥させた食品を指すので、「干しで食べる」とは言えず合わない。"}, {"text": "重さ", "is_correct": false, "explanation": "重さは目方のことなので、「重さで食べる」とは言えず合わない。"}], "explanations": {"生": "ここは魚を加熱せず、そのままの状態で食べるという意味。「生で食べる」と言う。", "焼き": "焼きは火を通した状態を指すので、「焼きで食べる」とは言わず合わない。", "干し": "干しは乾燥させた食品を指すので、「干しで食べる」とは言えず合わない。", "重さ": "重さは目方のことなので、「重さで食べる」とは言えず合わない。"}, "sentence_index": 0, "correct_answer": "生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この魚は生の季節なので、おいしい。", "explanation": "ここは〈旬〉の意味。食べ物がいちばんおいしい時期には〈旬〉を使い、〈生〉は加熱していない状態を表すので合わない。"}, {"text": "この店は生の店員が多いので、初めての人も安心です。", "explanation": "ここは〈新人〉の意味。勤めて間もない店員には〈新人〉を使い、〈生〉は食べ物や直接の状態を表すので合わない。"}, {"text": "生の服を買ってきたので、洗ってから着る。", "explanation": "ここは〈新品〉の意味。服の状態には〈新品〉を使い、〈生〉は食べ物や生きものなど、手を加えていない状態を表すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c83277a-0ac9-4383-8090-f98d2f035f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35682, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生", "is_correct": true, "explanation": "ここはウニを加熱せず、そのままの状態で食べるのが一番おいしいという意味。"}, {"text": "殻", "is_correct": false, "explanation": "殻はウニの外側を覆うものなので、食べ方のおいしさを表す語としては合わない。"}, {"text": "色", "is_correct": false, "explanation": "色は見た目のことなので、食べて一番おいしい状態の説明には合わない。"}, {"text": "形", "is_correct": false, "explanation": "形は姿のことなので、おいしさを比べる文には合わない。"}], "explanations": {"生": "ここはウニを加熱せず、そのままの状態で食べるのが一番おいしいという意味。", "殻": "殻はウニの外側を覆うものなので、食べ方のおいしさを表す語としては合わない。", "色": "色は見た目のことなので、食べて一番おいしい状態の説明には合わない。", "形": "形は姿のことなので、おいしさを比べる文には合わない。"}, "sentence_index": 6, "correct_answer": "生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この店は、お客さんの生を聞いてメニューを変えている。", "explanation": "ここは〈声〉の意味。意見を聞くことには〈声〉を使い、〈生〉を単独で使うと意味が通らないので合わない。"}, {"text": "父の生は、一九六〇年です。", "explanation": "ここは〈生年〉の意味。生まれた年を表すには〈生年〉を使い、〈生〉を単独で年の意味にはできないので合わない。"}, {"text": "この店のカキは、生ごみにはせず、焼いてもおいしい。", "explanation": "ここは「生ごみ」という別の語の一部で、この義項の「生」ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c83277a-0ac9-4383-8090-f98d2f035f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35682, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この鶏肉は生を食べられないので、必ず加熱してください。", "corrected_sentence": "この鶏肉は生で食べられないので、必ず加熱してください。", "error_description": "正しくは「生で食べられない」。食べる手段や状態を表す「で」が必要で、「を」は目的語として不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c83277a-0ac9-4383-8090-f98d2f035f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35682, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この魚は、生にも焼いてもおいしい。", "corrected_sentence": "この魚は、生でも焼いてもおいしい。", "error_description": "正しくは「生でも」。そのまま食べる方法を表す「で」が必要で、「に」は不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c83277a-0ac9-4383-8090-f98d2f035f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
