INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35683, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "録音や録画などを通さず、その場で直接行われていること。", "primary_collocate": null, "pronunciation": "なま", "ipa": "nama", "syllable_count": 2, "sentences": [{"text": "生の演奏を聞くと、CDとは迫力が全然違います。", "target_word": "生", "complexity_tier": "T3", "furigana": "生[なま]の演奏[えんそう]を聞[き]くと、CDとは迫力[はくりょく]が全然[ぜんぜん]違[ちが]います。", "sentence_source": "generated"}, {"text": "テレビより、生で見る試合のほうが盛り上がる。", "target_word": "生", "complexity_tier": "T3", "furigana": "テレビより、生[なま]で見[み]る試合[しあい]のほうが盛[も]り上[あ]がる。", "sentence_source": "generated"}, {"text": "歌手の生の声は、録音よりずっと力強かった。", "target_word": "生", "complexity_tier": "T3", "furigana": "歌手[かしゅ]の生[なま]の声[こえ]は、録音[ろくおん]よりずっと力強[ちからづよ]かった。", "sentence_source": "generated"}, {"text": "チケットが取れたので、好きなバンドを生で見られます。", "target_word": "生", "complexity_tier": "T3", "furigana": "チケットが取[と]れたので、好[す]きなバンドを生[なま]で見[み]られます。", "sentence_source": "generated"}, {"text": "現場の生の意見を聞くために、工場を訪ねた。", "target_word": "生", "complexity_tier": "T3", "furigana": "現場[げんば]の生[なま]の意見[いけん]を聞[き]くために、工場[こうじょう]を訪[たず]ねた。", "sentence_source": "generated"}, {"text": "生の音は、スピーカーを通した音とは違う。", "target_word": "生", "complexity_tier": "T3", "furigana": "生[なま]の音[おと]は、スピーカーを通[とお]した音[おと]とは違[ちが]う。", "sentence_source": "generated"}, {"text": "生の舞台は、失敗してもやり直せないから緊張する。", "target_word": "生", "complexity_tier": "T3", "furigana": "生[なま]の舞台[ぶたい]は、失敗[しっぱい]してもやり直[なお]せないから緊張[きんちょう]する。", "sentence_source": "generated"}, {"text": "一度は生で見たいと思っていた花火大会に、やっと行けた。", "target_word": "生", "complexity_tier": "T3", "furigana": "一度[いちど]は生[なま]で見[み]たいと思[おも]っていた花火大会[はなびたいかい]に、やっと行[い]けた。", "sentence_source": "generated"}, {"text": "生のトークは、台本がないので何が起こるかわからない。", "target_word": "生", "complexity_tier": "T3", "furigana": "生[なま]のトークは、台本[だいほん]がないので何[なに]が起[お]こるかわからない。", "sentence_source": "generated"}, {"text": "録音ではなく、生で歌ってほしいとお客さんが頼んだ。", "target_word": "生", "complexity_tier": "T3", "furigana": "録音[ろくおん]ではなく、生[なま]で歌[うた]ってほしいとお客[きゃく]さんが頼[たの]んだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "生", "label": "base"}], "register": "neutral", "sense_fingerprint": "生で見る・生の声。録音や加工を通さず、直接そこにある生きた状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T1: contains vocabulary far above tier T1: 力強かっ (Zipf 1.68)']::text[], '0fadd210-a29d-4c27-8f72-cc6debb7762d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35683, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生", "is_correct": true, "explanation": "ここは録音や加工を通さず、その場で行われる演奏という意味。"}, {"text": "中古", "is_correct": false, "explanation": "中古は一度使われた品を指すので、演奏の性質を表す語としては合わない。"}, {"text": "新品", "is_correct": false, "explanation": "新品は新しい品物を指すので、演奏の性質を表す語としては合わない。"}, {"text": "白黒", "is_correct": false, "explanation": "白黒は色の区別を表す語なので、演奏を表す語としては合わない。"}], "explanations": {"生": "ここは録音や加工を通さず、その場で行われる演奏という意味。", "中古": "中古は一度使われた品を指すので、演奏の性質を表す語としては合わない。", "新品": "新品は新しい品物を指すので、演奏の性質を表す語としては合わない。", "白黒": "白黒は色の区別を表す語なので、演奏を表す語としては合わない。"}, "sentence_index": 0, "correct_answer": "生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏は生ビールを飲みながら、野球を見る。", "explanation": "ここは「生ビール」の「生」で、この義項の「生」ではない。"}, {"text": "祖父の生は、一九三〇年です。", "explanation": "ここは〈生年〉の意味。生まれた年を表す語で、この義項の「生」（その場の演奏など）ではない。"}, {"text": "生ごみは、夜に出すのがルールだ。", "explanation": "ここは「生ごみ」という別の語の一部で、この義項の「生」ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c83277a-0ac9-4383-8090-f98d2f035f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35683, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生", "is_correct": true, "explanation": "ここは録音を通さず、その場で行われる舞台という意味。"}, {"text": "冷凍", "is_correct": false, "explanation": "冷凍は食品を凍らせることなので、舞台の性質を表す語としては合わない。"}, {"text": "塩", "is_correct": false, "explanation": "塩は調味料なので、舞台の種類を表す語としては合わない。"}, {"text": "紙", "is_correct": false, "explanation": "紙は材料の一つなので、舞台の性質を表す語としては合わない。"}], "explanations": {"生": "ここは録音を通さず、その場で行われる舞台という意味。", "冷凍": "冷凍は食品を凍らせることなので、舞台の性質を表す語としては合わない。", "塩": "塩は調味料なので、舞台の種類を表す語としては合わない。", "紙": "紙は材料の一つなので、舞台の性質を表す語としては合わない。"}, "sentence_index": 6, "correct_answer": "生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "父の生は、一九六〇年です。", "explanation": "ここは〈生年〉の意味。生まれた年を表すには〈生年〉を使い、〈生〉を単独で年の意味にはできないので合わない。"}, {"text": "この舞台は生ごみにして、来週から始まる。", "explanation": "ここは〈上演〉の意味。舞台を開くことには〈上演〉を使い、〈生〉を単独で舞台の意味にはできないので合わない。"}, {"text": "生の服を買ってきたので、洗ってから着る。", "explanation": "ここは〈新品〉の意味。服の状態には〈新品〉を使い、〈生〉は命や直接の状態を表すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c83277a-0ac9-4383-8090-f98d2f035f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35683, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ライブ映像より、生に見るコンサートのほうが盛り上がる。", "corrected_sentence": "ライブ映像より、生で見るコンサートのほうが盛り上がる。", "error_description": "正しくは「生で見る」。見る方法を表す「で」が必要で、「に」は不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c83277a-0ac9-4383-8090-f98d2f035f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35683, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ライブ会場で、生を歌声を聞くと鳥肌が立つ。", "corrected_sentence": "ライブ会場で、生の歌声を聞くと鳥肌が立つ。", "error_description": "正しくは「生の歌声」。「生」と「歌声」をつなぐ「の」が必要で、「を」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c83277a-0ac9-4383-8090-f98d2f035f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
