INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35684, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "みどりいろのことです。", "primary_collocate": null, "pronunciation": "ぐりーん", "ipa": "ɡɯɾiːɴ", "syllable_count": 4, "sentences": [{"text": "私は今日、グリーンのセーターを着ています。", "target_word": "グリーン", "complexity_tier": "T3", "furigana": "私[わたし]は今日[きょう]、グリーンのセーターを着[き]ています。", "sentence_source": "generated"}, {"text": "この部屋のカーテンは、明るいグリーンです。", "target_word": "グリーン", "complexity_tier": "T3", "furigana": "この部屋[へや]のカーテンは、明[あか]るいグリーンです。", "sentence_source": "generated"}, {"text": "好きな色を聞かれて、わたしはグリーンと答えました。", "target_word": "グリーン", "complexity_tier": "T3", "furigana": "好[す]きな色[いろ]を聞[き]かれて、わたしはグリーンと答[こた]えました。", "sentence_source": "generated"}, {"text": "白いシャツには、濃いグリーンのネクタイが合います。", "target_word": "グリーン", "complexity_tier": "T3", "furigana": "白[しろ]いシャツには、濃[こ]いグリーンのネクタイが合[あ]います。", "sentence_source": "generated"}, {"text": "庭の木の葉が、きれいなグリーンに変わりました。", "target_word": "グリーン", "complexity_tier": "T3", "furigana": "庭[にわ]の木[き]の葉[は]が、きれいなグリーンに変[か]わりました。", "sentence_source": "generated"}, {"text": "弟は青よりもグリーンのかばんがほしいと言いました。", "target_word": "グリーン", "complexity_tier": "T3", "furigana": "弟[おとうと]は青[あお]よりもグリーンのかばんがほしいと言[い]いました。", "sentence_source": "generated"}, {"text": "妹の部屋は壁がグリーンなので、森の中にいるようです。", "target_word": "グリーン", "complexity_tier": "T3", "furigana": "妹[いもうと]の部屋[へや]は壁[かべ]がグリーンなので、森[もり]の中[なか]にいるようです。", "sentence_source": "generated"}, {"text": "赤とグリーンを使って、クリスマスのカードを作りました。", "target_word": "グリーン", "complexity_tier": "T3", "furigana": "赤[あか]とグリーンを使[つか]って、クリスマスのカードを作[つく]りました。", "sentence_source": "generated"}, {"text": "このペンはインクがグリーンで、ノートによく目立ちます。", "target_word": "グリーン", "complexity_tier": "T3", "furigana": "このペンはインクがグリーンで、ノートによく目立[めだ]ちます。", "sentence_source": "generated"}, {"text": "買ったばかりの自転車は、深いグリーンでとても気に入っています。", "target_word": "グリーン", "complexity_tier": "T3", "furigana": "買[か]ったばかりの自転車[じてんしゃ]は、深[ふか]いグリーンでとても気[き]に入[はい]っています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "グリーン", "label": "基本形"}], "register": "丁寧（です・ます体）", "sense_fingerprint": "グリーン|色の緑|名詞|外来語", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '241fa7e4-e5ef-46f7-8ead-7bb2111dc929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35684, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "グリーン", "is_correct": true, "explanation": "色の緑を表す語で、「私は今日、___のセーターを着ています」に入ると意味が通る。"}, {"text": "ズボン", "is_correct": false, "explanation": "服の種類で色を表さないため、「ズボンのセーター」は意味をなさず空欄に入らない。"}, {"text": "スカート", "is_correct": false, "explanation": "服の種類で色を表さないため、「スカートのセーター」は空欄に入らない。"}, {"text": "マフラー", "is_correct": false, "explanation": "身につける物の名前で色を表さないため、「マフラーのセーター」は空欄に入らない。"}], "explanations": {"グリーン": "色の緑を表す語で、「私は今日、___のセーターを着ています」に入ると意味が通る。", "ズボン": "服の種類で色を表さないため、「ズボンのセーター」は意味をなさず空欄に入らない。", "スカート": "服の種類で色を表さないため、「スカートのセーター」は空欄に入らない。", "マフラー": "身につける物の名前で色を表さないため、「マフラーのセーター」は空欄に入らない。"}, "sentence_index": 0, "correct_answer": "グリーン"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏の空は、どこまでも澄んだグリーンが広がっています。", "explanation": "ここは〈青〉の意味。空の色は「青」と言い、「グリーン」とは言わない。"}, {"text": "桜の花が、よく晴れた日にグリーンに咲きました。", "explanation": "ここは〈ピンク（薄紅）〉の意味。桜の花の色は「ピンク」と言い、「グリーン」は合わない。"}, {"text": "藤の花が、やわらかいグリーンに垂れ下がっています。", "explanation": "ここは〈紫〉の意味。藤の花の色は「紫」と言い、「グリーン」は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f80da53-5a3d-4e39-a9da-336841e85e22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35684, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "グリーン", "is_correct": true, "explanation": "色の緑を表し、「妹の部屋は壁がグリーンなので」と壁の色として意味が通る。"}, {"text": "ベッド", "is_correct": false, "explanation": "家具の名前で色ではないため、「壁がベッドなので」は意味をなさない。"}, {"text": "カーテン", "is_correct": false, "explanation": "窓の布で色を表さないため、壁の状態としては空欄に入らない。"}, {"text": "ラジオ", "is_correct": false, "explanation": "電化製品の名前で色ではないため、「壁がラジオなので」は意味をなさない。"}], "explanations": {"グリーン": "色の緑を表し、「妹の部屋は壁がグリーンなので」と壁の色として意味が通る。", "ベッド": "家具の名前で色ではないため、「壁がベッドなので」は意味をなさない。", "カーテン": "窓の布で色を表さないため、壁の状態としては空欄に入らない。", "ラジオ": "電化製品の名前で色ではないため、「壁がラジオなので」は意味をなさない。"}, "sentence_index": 6, "correct_answer": "グリーン"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雪が降り積もって、庭一面がきれいなグリーンになりました。", "explanation": "ここは〈白〉の意味。雪景色の色は「白」と言い、「グリーン」は合わない。"}, {"text": "墨で書いた文字が、濃いグリーンになって読みにくくなりました。", "explanation": "ここは〈黒〉の意味。墨の色は「黒」と言い、「グリーン」は合わない。"}, {"text": "よく熟したトマトが、グリーンになりました。", "explanation": "ここは〈赤〉の意味。熟したトマトの色は「赤」と言い、「グリーン」は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f80da53-5a3d-4e39-a9da-336841e85e22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35684, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "庭の木は、きれいなグリーンで見えます。", "corrected_sentence": "庭の木は、きれいなグリーンに見えます。", "error_description": "「見える」は〈そのように見える〉という結果の状態を表し、「に」を取る。「で」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f80da53-5a3d-4e39-a9da-336841e85e22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35684, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨日、カーテンの色は落ち着いたグリーンへ決めました。", "corrected_sentence": "昨日、カーテンの色は落ち着いたグリーンに決めました。", "error_description": "「決める」は「Aを Bに決める」と結果の「に」を取る。方向を表す「へ」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f80da53-5a3d-4e39-a9da-336841e85e22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
