INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35685, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "植物の葉などの色で、なかまには「みどり」という言い方もあります。", "primary_collocate": null, "pronunciation": "ぐりーん", "ipa": "ɡɯɾiːɴ", "syllable_count": 4, "sentences": [{"text": "春になると、木の葉がやわらかいグリーンになる。", "target_word": "グリーン", "complexity_tier": "T3", "furigana": "春[はる]になると、木[き]の葉[は]がやわらかいグリーンになる。", "sentence_source": "generated"}, {"text": "雨のあと、庭の草が濃いグリーンに見えた。", "target_word": "グリーン", "complexity_tier": "T3", "furigana": "雨[あめ]のあと、庭[にわ]の草[くさ]が濃[こ]いグリーンに見[み]えた。", "sentence_source": "generated"}, {"text": "秋に葉は赤くなるが、夏は深いグリーンだ。", "target_word": "グリーン", "complexity_tier": "T3", "furigana": "秋[あき]に葉[は]は赤[あか]くなるが、夏[なつ]は深[ふか]いグリーンだ。", "sentence_source": "generated"}, {"text": "畑のレタスは、葉のグリーンがとても鮮やかだ。", "target_word": "グリーン", "complexity_tier": "T3", "furigana": "畑[はたけ]のレタスは、葉[は]のグリーンがとても鮮[あざ]やかだ。", "sentence_source": "generated"}, {"text": "山いっぱいのグリーンを見ると、心が落ち着く。", "target_word": "グリーン", "complexity_tier": "T3", "furigana": "山[やま]いっぱいのグリーンを見[み]ると、心[こころ]が落[お]ち着[つ]く。", "sentence_source": "generated"}, {"text": "この観葉植物は、葉のグリーンが特に鮮やかだ。", "target_word": "グリーン", "complexity_tier": "T3", "furigana": "この観葉植物[かんようしょくぶつ]は、葉[は]のグリーンが特[とく]に鮮[あざ]やかだ。", "sentence_source": "generated"}, {"text": "新しい葉は明るいグリーンで、古い葉は暗い色をしている。", "target_word": "グリーン", "complexity_tier": "T3", "furigana": "新[あたら]しい葉[は]は明[あか]るいグリーンで、古[ふる]い葉[は]は暗[くら]い色[いろ]をしている。", "sentence_source": "generated"}, {"text": "水が足りないと、葉のグリーンがうすくなる。", "target_word": "グリーン", "complexity_tier": "T3", "furigana": "水[みず]が足[た]りないと、葉[は]のグリーンがうすくなる。", "sentence_source": "generated"}, {"text": "公園の木々は、夏の光を受けて濃いグリーンに光っていた。", "target_word": "グリーン", "complexity_tier": "T3", "furigana": "公園[こうえん]の木々[きぎ]は、夏[なつ]の光[ひかり]を受[う]けて濃[こ]いグリーンに光[ひか]っていた。", "sentence_source": "generated"}, {"text": "畑の苗は、根づいて葉がグリーンになってきた。", "target_word": "グリーン", "complexity_tier": "T3", "furigana": "畑[はたけ]の苗[なえ]は、根[ね]づいて葉[は]がグリーンになってきた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "グリーン", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "植物の葉などに見られる緑の色", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T2: contains vocabulary far above tier T2: うすく (Zipf 2.37)','sentence 9 above tier T2: contains vocabulary far above tier T2: 根づい (Zipf 2.03)']::text[], '8e41a0f0-a380-46ef-b279-79ccdfb5e191') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35685, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "グリーン", "is_correct": true, "explanation": "葉の色を表し、「やわらかい＿になる」で葉の色の変化を自然に表す。"}, {"text": "冬", "is_correct": false, "explanation": "冬は季節で、「やわらかい冬になる」は意味が通らない。"}, {"text": "石", "is_correct": false, "explanation": "石は硬い物で、「やわらかい石になる」は不自然。"}, {"text": "電車", "is_correct": false, "explanation": "電車は乗り物で、葉の様子を表せない。"}], "explanations": {"グリーン": "葉の色を表し、「やわらかい＿になる」で葉の色の変化を自然に表す。", "冬": "冬は季節で、「やわらかい冬になる」は意味が通らない。", "石": "石は硬い物で、「やわらかい石になる」は不自然。", "電車": "電車は乗り物で、葉の様子を表せない。"}, "sentence_index": 0, "correct_answer": "グリーン"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "庭には、グリーンが積もっていた。", "explanation": "ここは〈枯れ葉〉の意味。積もるのは枯れ葉で、緑の色を表すグリーンでは言わないので合わない。"}, {"text": "砂糖を入れず、グリーンで飲んだ。", "explanation": "ここは〈ブラック〉（砂糖やミルクを入れないコーヒー）の意味。飲み方はブラックと言い、色名のグリーンでは言わないので合わない。"}, {"text": "庭のグリーンが伸びて、ボーボーになった。", "explanation": "ここは〈植物〉の意味。「グリーン」は植物全体を指すこともあるが、色の義項の文脈ではこの文は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27b02584-4570-4192-a68a-670bb414bf49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35685, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "グリーン", "is_correct": true, "explanation": "葉の色を表し、「明るい＿で」と色の様子を示すのに合う。"}, {"text": "試験", "is_correct": false, "explanation": "試験は出来事で、「明るい試験で」は意味が通らない。"}, {"text": "朝食", "is_correct": false, "explanation": "朝食は食事で、葉の色を表さないので入らない。"}, {"text": "熱", "is_correct": false, "explanation": "熱は温度や病気の状態で、葉の色として「明るい熱で」は合わない。"}], "explanations": {"グリーン": "葉の色を表し、「明るい＿で」と色の様子を示すのに合う。", "試験": "試験は出来事で、「明るい試験で」は意味が通らない。", "朝食": "朝食は食事で、葉の色を表さないので入らない。", "熱": "熱は温度や病気の状態で、葉の色として「明るい熱で」は合わない。"}, "sentence_index": 6, "correct_answer": "グリーン"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "お祝いに、グリーンで乾杯した。", "explanation": "ここは〈シャンパン〉（乾杯に使うお酒）の意味。乾杯の飲み物はシャンパンなどと言い、色名のグリーンでは言わないので合わない。"}, {"text": "連休のグリーンウィークに旅行した。", "explanation": "ここは〈ゴールデンウィーク〉（大型連休）の意味。連休はゴールデンウィークと言い、グリーンウィークとは言わないので合わない。"}, {"text": "試合で、審判がグリーンカードを掲げた。", "explanation": "ここは〈レッドカード〉（退場の合図）の意味。グリーンカードは退場を示す語ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27b02584-4570-4192-a68a-670bb414bf49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35685, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夏の朝、葉のグリーンを一段と濃く見えた。", "corrected_sentence": "夏の朝、葉のグリーンが一段と濃く見えた。", "error_description": "「見える」の主語は「が」で示す。「葉のグリーンを」は誤りで、「葉のグリーンが」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27b02584-4570-4192-a68a-670bb414bf49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35685, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "春の木の葉は、少しずつグリーンな色合いを増していく。", "corrected_sentence": "春の木の葉は、少しずつグリーンの色合いを増していく。", "error_description": "色を表す名詞が名詞を修飾するときは「の」を使う。「グリーンな色合い」は誤りで、「グリーンの色合い」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27b02584-4570-4192-a68a-670bb414bf49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
