INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35686, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "まめの こと。", "primary_collocate": null, "pronunciation": "びーん", "ipa": "biːɴ", "syllable_count": 3, "sentences": [{"text": "英語で「まめ」のことをビーンと言います。", "target_word": "ビーン", "complexity_tier": "T3", "furigana": "英語[えいご]で「まめ」のことをビーンと言[い]います。", "sentence_source": "generated"}, {"text": "このスープには、赤いビーンがたくさん入っています。", "target_word": "ビーン", "complexity_tier": "T3", "furigana": "このスープには、赤[あか]いビーンがたくさん入[はい]っています。", "sentence_source": "generated"}, {"text": "ビーンは、よく洗ってから煮ると食べやすくなります。", "target_word": "ビーン", "complexity_tier": "T3", "furigana": "[ビーン|びーん]は、よく洗ってから煮ると食べやすくなります。", "sentence_source": "generated"}, {"text": "ビーンは小さいですが、体にいい食べ物です。", "target_word": "ビーン", "complexity_tier": "T3", "furigana": "ビーンは小[ちい]さいですが、体[からだ]にいい食[た]べ物[もの]です。", "sentence_source": "generated"}, {"text": "外国の絵本で、ビーンを植えると大きな木が生える話を読みました。", "target_word": "ビーン", "complexity_tier": "T3", "furigana": "外国の絵本で、[ビーン|びーん]を植えると大きな木が生える話を読みました。", "sentence_source": "generated"}, {"text": "友だちは、ビーンの料理が好きで、よく作ります。", "target_word": "ビーン", "complexity_tier": "T3", "furigana": "友[とも]だちは、ビーンの料理[りょうり]が好[す]きで、よく作[つく]ります。", "sentence_source": "generated"}, {"text": "ビーンを水に入れて、一晩おきました。", "target_word": "ビーン", "complexity_tier": "T3", "furigana": "ビーンを水[みず]に入[い]れて、一晩[ひとばん]おきました。", "sentence_source": "generated"}, {"text": "店でビーンを買って、カレーに入れました。", "target_word": "ビーン", "complexity_tier": "T3", "furigana": "店[みせ]でビーンを買[か]って、カレーに入[い]れました。", "sentence_source": "generated"}, {"text": "「ビーン」と「ビール」は、音が似ているので間違えやすいです。", "target_word": "ビーン", "complexity_tier": "T3", "furigana": "「ビーン」と「ビール」は、音[おと]が似[に]ているので間違[まちが]えやすいです。", "sentence_source": "generated"}, {"text": "ビーンは、日本語では「豆」といいます。", "target_word": "ビーン", "complexity_tier": "T3", "furigana": "ビーンは、日本語[にほんご]では「豆[まめ]」といいます。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ビーン", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "豆を表す外来語", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e94d6e2d-9444-4318-ae52-f2bb09e93812') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35686, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ビーン", "is_correct": true, "explanation": "英語で「まめ」を表す語なので正解。"}, {"text": "ビール", "is_correct": false, "explanation": "お酒の名前で、まめの英語ではないので合わない。"}, {"text": "ピザ", "is_correct": false, "explanation": "料理の名前で、まめの英語ではないので合わない。"}, {"text": "ケーキ", "is_correct": false, "explanation": "菓子の名前で、まめの英語ではないので合わない。"}], "explanations": {"ビーン": "英語で「まめ」を表す語なので正解。", "ビール": "お酒の名前で、まめの英語ではないので合わない。", "ピザ": "料理の名前で、まめの英語ではないので合わない。", "ケーキ": "菓子の名前で、まめの英語ではないので合わない。"}, "sentence_index": 0, "correct_answer": "ビーン"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "仕事のあとに、ビーンを一杯飲みます。", "explanation": "ここは〈ビール〉の意味。ビーンは豆で飲み物ではないので、飲む対象にならない。"}, {"text": "ビーンの肉は、柔らかくて脂がのっています。", "explanation": "ここは〈ビーフ〉（牛肉）の意味。ビーンは豆で肉ではないので合わない。"}, {"text": "りんごのビーンを庭に植えて、芽が出るのを待ちました。", "explanation": "ここは〈種〉の意味。ビーンは豆のことで、りんごの種には使わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ebcc47-ec9a-4162-b5a9-df7c48f0951d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35686, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ビーン", "is_correct": true, "explanation": "豆を一晩水に漬けるのは普通の下ごしらえで、この文に合う。"}, {"text": "チーズ", "is_correct": false, "explanation": "水に一晩入れて戻すものではないので、文が不自然になる。"}, {"text": "ソーセージ", "is_correct": false, "explanation": "水に一晩漬ける料理ではないので、文が不自然になる。"}, {"text": "ラーメン", "is_correct": false, "explanation": "麺を一晩水に入れる調理ではないので、文が不自然になる。"}], "explanations": {"ビーン": "豆を一晩水に漬けるのは普通の下ごしらえで、この文に合う。", "チーズ": "水に一晩入れて戻すものではないので、文が不自然になる。", "ソーセージ": "水に一晩漬ける料理ではないので、文が不自然になる。", "ラーメン": "麺を一晩水に入れる調理ではないので、文が不自然になる。"}, "sentence_index": 6, "correct_answer": "ビーン"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ビーンを押すと、ドアが開きます。", "explanation": "ここは〈ボタン〉の意味。ビーンは豆で、押して操作するものではないので合わない。"}, {"text": "ビーンを鳴らすと、お客さんが呼ばれて来ます。", "explanation": "ここは〈ベル〉の意味。ビーンは豆で、鳴らして人を呼ぶものではないので合わない。"}, {"text": "ビーンを畳んで、棚にしまいました。", "explanation": "ここは〈タオル〉の意味。ビーンは豆で、畳める物ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ebcc47-ec9a-4162-b5a9-df7c48f0951d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35686, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "このスープには、白いビーンをたくさん入っています。", "corrected_sentence": "このスープには、白いビーンがたくさん入っています。", "error_description": "『入る』は自動詞なので、主語のビーンには『が』を使う。『を』は誤りで、正しくは『が』。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ebcc47-ec9a-4162-b5a9-df7c48f0951d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35686, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "毎朝、ビーンが水に入れて、柔らかくします。", "corrected_sentence": "毎朝、ビーンを水に入れて、柔らかくします。", "error_description": "『入れる』は他動詞なので、目的語のビーンには『を』を使う。『が』は誤りで、正しくは『を』。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ebcc47-ec9a-4162-b5a9-df7c48f0951d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35687, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "『コーヒー』と『味』をつなぐ連体修飾の『の』なので正解。"}, {"text": "が", "is_correct": false, "explanation": "『が』は主語を示すが、『コーヒー』と『味』をつなぐ『の』の代わりにはならない。"}, {"text": "を", "is_correct": false, "explanation": "『を』は目的語を示し、『コーヒー』と『味』をつなげられない。"}, {"text": "へ", "is_correct": false, "explanation": "『へ』は方向を示し、『コーヒー』と『味』をつなげられない。"}], "correct_answer": "の", "explanations": {"の": "『コーヒー』と『味』をつなぐ連体修飾の『の』なので正解。", "が": "『が』は主語を示すが、『コーヒー』と『味』をつなぐ『の』の代わりにはならない。", "を": "『を』は目的語を示し、『コーヒー』と『味』をつなげられない。", "へ": "『へ』は方向を示し、『コーヒー』と『味』をつなげられない。"}, "error_tags": {"が": "『が』は主語を示すが、『コーヒー』と『味』をつなぐ『の』の代わりにはならない。", "を": "『を』は目的語を示し、『コーヒー』と『味』をつなげられない。", "へ": "『へ』は方向を示し、『コーヒー』と『味』をつなげられない。"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ebcc47-ec9a-4162-b5a9-df7c48f0951d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35687, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『教える』の内容になるビーンを示すので『を』が正解。"}, {"text": "に", "is_correct": false, "explanation": "『に』は教える相手を示すので、教える内容には使えない。"}, {"text": "で", "is_correct": false, "explanation": "『で』は場所や手段を示し、教える内容には合わない。"}, {"text": "より", "is_correct": false, "explanation": "『より』は比較を示し、ここでは文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "『教える』の内容になるビーンを示すので『を』が正解。", "に": "『に』は教える相手を示すので、教える内容には使えない。", "で": "『で』は場所や手段を示し、教える内容には合わない。", "より": "『より』は比較を示し、ここでは文が成り立たない。"}, "error_tags": {"に": "『に』は教える相手を示すので、教える内容には使えない。", "で": "『で』は場所や手段を示し、教える内容には合わない。", "より": "『より』は比較を示し、ここでは文が成り立たない。"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ebcc47-ec9a-4162-b5a9-df7c48f0951d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
